                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_invariant_diag_avg
               local_ot_env(1)%schur_projector_physical_trace_invariant_free_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_invariant_free_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_invariant_free_avg
               local_ot_env(1)%schur_projector_physical_weight_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_weight_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  local_ot_env(1)%schur_projector_physical_weight*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_metric_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_metric_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_metric_ratio*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_compensation_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_compensation_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  projector_physical_compensation_ratio*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_correction_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_correction_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  projector_physical_correction_ratio*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_negative_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_negative_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  local_ot_env(1)%schur_projector_physical_negative*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_direct_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_direct_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_direct_ratio*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_selected_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_selected_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_selected_ratio*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_shift_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_shift_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_shift_ratio*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_trace_actual_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_actual_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  projector_physical_trace_actual_avg*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_trace_raw_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_raw_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  projector_physical_trace_raw_avg*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_trace_active_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_active_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  projector_physical_trace_active_avg*projector_physical_quality_ratio
               local_ot_env(1)%schur_projector_physical_trace_actual_diag_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_actual_diag_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_actual_diag_quality
               local_ot_env(1)%schur_projector_physical_trace_actual_free_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_actual_free_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_actual_free_quality
               local_ot_env(1)%schur_projector_physical_trace_raw_diag_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_raw_diag_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_raw_diag_quality
               local_ot_env(1)%schur_projector_physical_trace_raw_free_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_raw_free_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_raw_free_quality
               local_ot_env(1)%schur_projector_physical_trace_active_diag_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_active_diag_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_active_diag_quality
               local_ot_env(1)%schur_projector_physical_trace_active_free_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_active_free_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_active_free_quality
               local_ot_env(1)%schur_projector_physical_trace_invariant_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_invariant_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_invariant_quality
               local_ot_env(1)%schur_projector_physical_trace_invariant_diag_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_invariant_diag_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_invariant_diag_quality
               local_ot_env(1)%schur_projector_physical_trace_invariant_free_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_trace_invariant_free_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_trace_invariant_free_quality
            END IF
            local_ot_env(1)%schur_projector_physical_drop_sum = &
               local_ot_env(1)%schur_projector_physical_drop_sum + projector_physical_predicted_drop
            local_ot_env(1)%schur_projector_physical_measured_sum = &
               local_ot_env(1)%schur_projector_physical_measured_sum + measured_drop
         END IF
         projector_physical_direct_predicted_drop = local_ot_env(1)%schur_projector_physical_direct
         projector_physical_direct_quality_ratio = 0.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_projector_physical_pending .AND. &
             projector_physical_direct_predicted_drop > &
             EPSILON(projector_physical_direct_predicted_drop) .AND. measured_drop > 0.0_dp) THEN
            projector_physical_direct_quality_ratio = &
               measured_drop/projector_physical_direct_predicted_drop
            local_ot_env(1)%schur_projector_physical_direct_quality = &
               projector_physical_direct_quality_ratio
            samples = MIN(local_ot_env(1)%schur_projector_physical_direct_quality_samples + 1, &
                          HUGE(samples) - 1)
            local_ot_env(1)%schur_projector_physical_direct_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_projector_physical_direct_quality_shadow_ema = &
                  projector_physical_direct_quality_ratio
            ELSE
               local_ot_env(1)%schur_projector_physical_direct_quality_shadow_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_direct_quality_shadow_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_physical_direct_quality_ratio
            END IF
            local_ot_env(1)%schur_projector_physical_direct_drop_sum = &
               local_ot_env(1)%schur_projector_physical_direct_drop_sum + &
               projector_physical_direct_predicted_drop
            local_ot_env(1)%schur_projector_physical_direct_measured_sum = &
               local_ot_env(1)%schur_projector_physical_direct_measured_sum + measured_drop
         END IF
         projector_physical_direct_selected_predicted_drop = &
            local_ot_env(1)%schur_projector_physical_direct_selected
         projector_physical_direct_selected_quality_ratio = 0.0_dp
         IF (mermin_search .AND. projector_physical_direct_selected_predicted_drop > &
             EPSILON(projector_physical_direct_selected_predicted_drop) .AND. &
             measured_drop > 0.0_dp) THEN
            projector_physical_direct_selected_quality_ratio = &
               measured_drop/projector_physical_direct_selected_predicted_drop
            local_ot_env(1)%schur_projector_physical_direct_selected_quality = &
               projector_physical_direct_selected_quality_ratio
            samples = MIN( &
                      local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples + 1, &
                      HUGE(samples) - 1)
            local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema = &
                  projector_physical_direct_selected_quality_ratio
               local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema = &
                  residual_quality_ratio
            ELSE
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  projector_physical_direct_selected_quality_ratio
               local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*residual_quality_ratio
            END IF
            local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality = &
               residual_quality_ratio
            local_ot_env(1)%schur_projector_physical_direct_selected_drop_sum = &
               local_ot_env(1)%schur_projector_physical_direct_selected_drop_sum + &
               projector_physical_direct_selected_predicted_drop
            local_ot_env(1)%schur_projector_physical_direct_selected_measured_sum = &
               local_ot_env(1)%schur_projector_physical_direct_selected_measured_sum + measured_drop
         END IF
         projector_physical_direct_density_selected_predicted_drop = &
            local_ot_env(1)%schur_projector_phys_direct_density_sel
         projector_physical_direct_density_selected_quality_ratio = 0.0_dp
         IF (mermin_search .AND. projector_physical_direct_density_selected_predicted_drop > &
             EPSILON(projector_physical_direct_density_selected_predicted_drop) .AND. &
             measured_drop > 0.0_dp) THEN
            projector_physical_direct_density_selected_quality_ratio = &
               measured_drop/projector_physical_direct_density_selected_predicted_drop
            local_ot_env(1)%schur_projector_phys_direct_density_sel_quality = &
               projector_physical_direct_density_selected_quality_ratio
            samples = MIN( &
                      local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples + 1, &
                      HUGE(samples) - 1)
            local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_ema = &
                  projector_physical_direct_density_selected_quality_ratio
               local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema = &
                  residual_quality_ratio
            ELSE
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_ema + &
                  ot_kp_schur_quality_ema_alpha* &
                  projector_physical_direct_density_selected_quality_ratio
               local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*residual_quality_ratio
            END IF
            local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality = &
               residual_quality_ratio
            local_ot_env(1)%schur_projector_phys_direct_density_sel_drop_sum = &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_drop_sum + &
               projector_physical_direct_density_selected_predicted_drop
            local_ot_env(1)%schur_projector_phys_direct_density_sel_measured_sum = &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_measured_sum + measured_drop
         END IF
         projector_mixed_direct_predicted_drop = local_ot_env(1)%schur_projector_mixed_direct_drop
         projector_mixed_direct_quality_ratio = 0.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_projector_mixed_direct_pending .AND. &
             projector_mixed_direct_predicted_drop > EPSILON(projector_mixed_direct_predicted_drop) .AND. &
             measured_drop > 0.0_dp) THEN
            projector_mixed_direct_quality_ratio = measured_drop/projector_mixed_direct_predicted_drop
            local_ot_env(1)%schur_projector_mixed_direct_quality = projector_mixed_direct_quality_ratio
            samples = MIN(local_ot_env(1)%schur_projector_mixed_direct_quality_samples + 1, HUGE(samples) - 1)
            local_ot_env(1)%schur_projector_mixed_direct_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_projector_mixed_direct_quality_ema = projector_mixed_direct_quality_ratio
               local_ot_env(1)%schur_projector_mixed_direct_weight_ema = &
                  local_ot_env(1)%schur_projector_mixed_direct_weight
            ELSE
               local_ot_env(1)%schur_projector_mixed_direct_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_mixed_direct_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_mixed_direct_quality_ratio
               local_ot_env(1)%schur_projector_mixed_direct_weight_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_mixed_direct_weight_ema + &
                  ot_kp_schur_quality_ema_alpha*local_ot_env(1)%schur_projector_mixed_direct_weight
            END IF
            local_ot_env(1)%schur_projector_mixed_direct_drop_sum = &
               local_ot_env(1)%schur_projector_mixed_direct_drop_sum + &
               projector_mixed_direct_predicted_drop
            local_ot_env(1)%schur_projector_mixed_direct_measured_sum = &
               local_ot_env(1)%schur_projector_mixed_direct_measured_sum + measured_drop
         END IF
         projector_spectral_predicted_drop = local_ot_env(1)%schur_projector_spectral_drop
         projector_spectral_quality_ratio = 0.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_projector_spectral_pending .AND. &
             projector_spectral_predicted_drop > EPSILON(projector_spectral_predicted_drop) .AND. &
             measured_drop > 0.0_dp) THEN
            projector_spectral_quality_ratio = measured_drop/projector_spectral_predicted_drop
            local_ot_env(1)%schur_projector_spectral_quality = projector_spectral_quality_ratio
            samples = MIN(local_ot_env(1)%schur_projector_spectral_quality_samples + 1, HUGE(samples) - 1)
            local_ot_env(1)%schur_projector_spectral_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_projector_spectral_quality_ema = projector_spectral_quality_ratio
               local_ot_env(1)%schur_projector_spectral_dot_ema = &
                  local_ot_env(1)%schur_projector_spectral_dot
               local_ot_env(1)%schur_projector_spectral_norm_ema = &
                  local_ot_env(1)%schur_projector_spectral_norm
               local_ot_env(1)%schur_projector_spectral_floor_ema = &
                  local_ot_env(1)%schur_projector_spectral_floor
               local_ot_env(1)%schur_projector_spectral_emin_ema = &
                  local_ot_env(1)%schur_projector_spectral_emin
            ELSE
               local_ot_env(1)%schur_projector_spectral_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_spectral_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*projector_spectral_quality_ratio
               local_ot_env(1)%schur_projector_spectral_dot_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_spectral_dot_ema + &
                  ot_kp_schur_quality_ema_alpha*local_ot_env(1)%schur_projector_spectral_dot
               local_ot_env(1)%schur_projector_spectral_norm_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_spectral_norm_ema + &
                  ot_kp_schur_quality_ema_alpha*local_ot_env(1)%schur_projector_spectral_norm
               local_ot_env(1)%schur_projector_spectral_floor_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_spectral_floor_ema + &
                  ot_kp_schur_quality_ema_alpha*local_ot_env(1)%schur_projector_spectral_floor
               local_ot_env(1)%schur_projector_spectral_emin_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_projector_spectral_emin_ema + &
                  ot_kp_schur_quality_ema_alpha*local_ot_env(1)%schur_projector_spectral_emin
            END IF
            local_ot_env(1)%schur_projector_spectral_drop_sum = &
               local_ot_env(1)%schur_projector_spectral_drop_sum + projector_spectral_predicted_drop
            local_ot_env(1)%schur_projector_spectral_measured_sum = &
               local_ot_env(1)%schur_projector_spectral_measured_sum + measured_drop
         END IF
         projector_spectral_selected_predicted_drop = 0.0_dp
         projector_spectral_selected_quality_ratio = 0.0_dp
         IF (local_ot_env(1)%schur_model_flavor == 36) THEN
            projector_spectral_selected_predicted_drop = calibrated_predicted_drop
            IF (projector_spectral_selected_predicted_drop <= &
                EPSILON(projector_spectral_selected_predicted_drop)) &
               projector_spectral_selected_predicted_drop = predicted_drop
         END IF
         IF (mermin_search .AND. local_ot_env(1)%schur_model_flavor == 36 .AND. &
             projector_spectral_selected_predicted_drop > &
             EPSILON(projector_spectral_selected_predicted_drop)) THEN
            IF (measured_drop > 0.0_dp) THEN
               projector_spectral_selected_quality_ratio = &
                  measured_drop/projector_spectral_selected_predicted_drop
               local_ot_env(1)%schur_projector_spectral_selected_quality = &
                  projector_spectral_selected_quality_ratio
               local_ot_env(1)%schur_projector_spectral_selected_residual_quality = &
                  residual_quality_ratio
               samples = MIN(local_ot_env(1)%schur_projector_spectral_selected_quality_samples + 1, &
                             HUGE(samples) - 1)
               local_ot_env(1)%schur_projector_spectral_selected_quality_samples = samples
               IF (samples == 1) THEN
                  local_ot_env(1)%schur_projector_spectral_selected_quality_ema = &
                     projector_spectral_selected_quality_ratio
                  local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema = &
                     residual_quality_ratio
               ELSE
                  local_ot_env(1)%schur_projector_spectral_selected_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_projector_spectral_selected_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*projector_spectral_selected_quality_ratio
                  local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*residual_quality_ratio
               END IF
               local_ot_env(1)%schur_projector_spectral_selected_drop_sum = &
                  local_ot_env(1)%schur_projector_spectral_selected_drop_sum + &
                  projector_spectral_selected_predicted_drop
               local_ot_env(1)%schur_projector_spectral_selected_measured_sum = &
                  local_ot_env(1)%schur_projector_spectral_selected_measured_sum + measured_drop
               ! A positive but badly overpredicted spectral probe is only
               ! damaging in the tail if it also fails to reduce the physical
               ! residual. Keep residual-good directions alive even when the
               ! local Mermin drop model is temporarily pessimistic.
               IF (projector_spectral_selected_quality_ratio < &
                   0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
                   residual_quality_ratio < ot_kp_schur_projector_response_quality_min_ratio) &
                  local_ot_env(1)%schur_projector_spectral_selected_failure_samples = &
                  MIN(local_ot_env(1)%schur_projector_spectral_selected_failure_samples + 1, &
                      HUGE(samples) - 1)
            ELSE
               local_ot_env(1)%schur_projector_spectral_selected_failure_samples = &
                  MIN(local_ot_env(1)%schur_projector_spectral_selected_failure_samples + 1, &
                      HUGE(samples) - 1)
               local_ot_env(1)%schur_projector_spectral_selected_quality = 0.0_dp
               local_ot_env(1)%schur_projector_spectral_selected_quality_ema = 0.0_dp
               local_ot_env(1)%schur_projector_spectral_selected_residual_quality = 0.0_dp
               local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema = 0.0_dp
            END IF
         END IF
         ! A too-large physical quality ratio means the shadow model is
         ! conservative, not unstable; selection still uses the clamped
         ! expected-drop quality below.
         local_ot_env(1)%schur_projector_physical_candidate_enabled = &
            local_ot_env(1)%schur_projector_physical_quality_samples >= &
            ot_kp_schur_projector_response_min_samples .AND. &
            local_ot_env(1)%schur_projector_physical_quality_ema >= &
            ot_kp_schur_projector_response_quality_min_ratio .AND. &
            local_ot_env(1)%schur_projector_physical_quality >= &
            0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
         ! Let robust spectral shadow history promote the candidate early,
         ! but do not make one positive, overpredicted probe a permanent veto.
         spectral_selected_ema_ok = &
            local_ot_env(1)%schur_projector_spectral_selected_quality_ema >= &
            ot_kp_schur_projector_response_quality_min_ratio .OR. &
            local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema >= &
            ot_kp_schur_projector_response_quality_min_ratio
         spectral_selected_recent_ok = &
            local_ot_env(1)%schur_projector_spectral_selected_quality >= &
            0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .OR. &
            local_ot_env(1)%schur_projector_spectral_selected_residual_quality >= &
            ot_kp_schur_projector_response_quality_min_ratio
         local_ot_env(1)%schur_projector_spectral_candidate_enabled = &
            local_ot_env(1)%schur_projector_spectral_selected_failure_samples < &
            ot_kp_schur_projector_spectral_probe_max_failures .AND. &
            local_ot_env(1)%schur_projector_spectral_dot_ema > 0.0_dp .AND. &
            local_ot_env(1)%schur_projector_spectral_norm_ema > 0.0_dp .AND. &
            ((local_ot_env(1)%schur_projector_spectral_selected_quality_samples >= &
              ot_kp_schur_projector_response_min_samples .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_selected_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_measured_sum > 0.0_dp .AND. &
              spectral_selected_ema_ok .AND. spectral_selected_recent_ok) .OR. &
             (local_ot_env(1)%schur_projector_spectral_selected_quality_samples >= &
              ot_kp_schur_projector_spectral_selected_min_samples .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_selected_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_measured_sum > 0.0_dp .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema >= &
              ot_kp_schur_projector_response_quality_min_ratio .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_residual_quality >= &
              ot_kp_schur_projector_response_quality_min_ratio .AND. &
              spectral_selected_ema_ok .AND. spectral_selected_recent_ok) .OR. &
             (local_ot_env(1)%schur_projector_spectral_selected_quality_samples > 0 .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_selected_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_measured_sum > 0.0_dp .AND. &
              spectral_selected_ema_ok .AND. spectral_selected_recent_ok .AND. &
              local_ot_env(1)%schur_projector_spectral_quality_samples >= &
              ot_kp_schur_projector_response_min_samples .AND. &
              local_ot_env(1)%schur_projector_spectral_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_measured_sum > 0.0_dp .AND. &
              local_ot_env(1)%schur_projector_spectral_floor_ema > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_floor_ema) .AND. &
              local_ot_env(1)%schur_projector_spectral_quality_ema >= &
              ot_kp_schur_projector_spectral_probe_quality_min .AND. &
              local_ot_env(1)%schur_projector_spectral_quality >= &
              0.5_dp*ot_kp_schur_projector_spectral_probe_quality_min))

         local_ot_env(1)%schur_split_candidate_enabled = local_ot_env(1)%schur_model_quality_ready
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples) &
            local_ot_env(1)%schur_split_candidate_enabled = local_ot_env(1)%schur_split_candidate_enabled .AND. &
                                                            local_ot_env(1)%schur_split_calibrated_quality_ema >= &
                                                            ot_kp_schur_calibrated_quality_min_ratio .AND. &
                                                            local_ot_env(1)%schur_split_calibrated_quality >= &
                                                            0.5_dp*ot_kp_schur_calibrated_quality_min_ratio
         local_ot_env(1)%schur_constrained_candidate_enabled = &
            local_ot_env(1)%schur_split_candidate_enabled .AND. &
            local_ot_env(1)%schur_constrained_quality_samples >= ot_kp_schur_constrained_min_samples .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality_ema >= &
            ot_kp_schur_constrained_advantage_ratio* &
            MAX(ot_kp_schur_calibrated_quality_min_ratio, local_ot_env(1)%schur_split_calibrated_quality_ema) .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality_ema <= &
            ot_kp_schur_calibrated_quality_max_ratio .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality >= &
            0.5_dp*ot_kp_schur_calibrated_quality_min_ratio .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality <= &
            2.0_dp*ot_kp_schur_calibrated_quality_max_ratio
         local_ot_env(1)%schur_model_pending = .FALSE.
         local_ot_env(1)%schur_constrained_pending = .FALSE.
         local_ot_env(1)%schur_split_shadow_pending = .FALSE.
         local_ot_env(1)%schur_occgap_shadow_pending = .FALSE.
         local_ot_env(1)%schur_projector_mode_pending = .FALSE.
         local_ot_env(1)%schur_projector_offdiag_pending = .FALSE.
         local_ot_env(1)%schur_projector_inactive_offdiag_pending = .FALSE.
         local_ot_env(1)%schur_projector_response_pending = .FALSE.
         local_ot_env(1)%schur_projector_plateau_gap_pending = .FALSE.
         local_ot_env(1)%schur_projector_physical_pending = .FALSE.
         local_ot_env(1)%schur_projector_mixed_direct_pending = .FALSE.
         local_ot_env(1)%schur_projector_spectral_pending = .FALSE.
         local_ot_env(1)%schur_projector_diagref_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_audit_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_descent_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_full_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_full_direct_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_full_global_pending = .FALSE.
         local_ot_env(1)%schur_model_flavor = 0

         logger => cp_get_default_logger()
         projector_physical_weight_quality = 0.0_dp
         projector_physical_metric_quality = 0.0_dp
         projector_physical_compensation_quality = 0.0_dp
         projector_physical_correction_quality = 0.0_dp
         projector_physical_negative_quality = 0.0_dp
         projector_physical_direct_quality = 0.0_dp
         projector_physical_selected_quality = 0.0_dp
         projector_physical_shift_quality = 0.0_dp
         IF (local_ot_env(1)%schur_projector_physical_weight_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_weight_ema)) &
            projector_physical_weight_quality = &
            local_ot_env(1)%schur_projector_physical_weight_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_weight_ema
         IF (local_ot_env(1)%schur_projector_physical_metric_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_metric_ema)) &
            projector_physical_metric_quality = &
            local_ot_env(1)%schur_projector_physical_metric_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_metric_ema
         IF (local_ot_env(1)%schur_projector_physical_compensation_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_compensation_ema)) &
            projector_physical_compensation_quality = &
            local_ot_env(1)%schur_projector_physical_compensation_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_compensation_ema
         IF (local_ot_env(1)%schur_projector_physical_correction_ratio_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_correction_ratio_ema)) &
            projector_physical_correction_quality = &
            local_ot_env(1)%schur_projector_physical_correction_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_correction_ratio_ema
         IF (local_ot_env(1)%schur_projector_physical_negative_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_negative_ema)) &
            projector_physical_negative_quality = &
            local_ot_env(1)%schur_projector_physical_negative_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_negative_ema
         IF (local_ot_env(1)%schur_projector_physical_direct_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_direct_ema)) &
            projector_physical_direct_quality = &
            local_ot_env(1)%schur_projector_physical_direct_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_direct_ema
         IF (local_ot_env(1)%schur_projector_physical_selected_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_selected_ema)) &
            projector_physical_selected_quality = &
            local_ot_env(1)%schur_projector_physical_selected_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_selected_ema
         IF (local_ot_env(1)%schur_projector_physical_shift_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_shift_ema)) &
            projector_physical_shift_quality = &
            local_ot_env(1)%schur_projector_physical_shift_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_shift_ema
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) THEN
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,9(1X,ES16.8),1X,I6,2(1X,L1))') &
               " OT Schur LS quality attempt raw_pred cal_pred meas raw_ratio raw_ema cal_ratio cal_ema "// &
               "gap_ratio delta samples ready enabled:", &
               local_ot_env(1)%schur_model_attempt, &
               predicted_drop, calibrated_predicted_drop, measured_drop, quality_ratio, &
               local_ot_env(1)%schur_model_quality_ema, calibrated_quality_ratio, &
               local_ot_env(1)%schur_model_calibrated_quality_ema, &
               local_ot_env(1)%schur_model_gap_ratio, local_ot_env(1)%delta, &
               local_ot_env(1)%schur_model_quality_samples, &
               local_ot_env(1)%schur_model_quality_ready, local_ot_env(1)%schur_split_candidate_enabled
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),17(1X,ES16.8))') &
               " OT Schur LS history split_n coupled_n split_ratio split_ema split_cal split_cal_ema "// &
               "split_resid split_resid_ema split_pred split_meas coupled_ratio coupled_ema "// &
               "coupled_cal coupled_cal_ema coupled_resid coupled_resid_ema coupled_pred cpred coupled_meas:", &
               local_ot_env(1)%schur_split_quality_samples, local_ot_env(1)%schur_coupled_quality_samples, &
               local_ot_env(1)%schur_split_quality, local_ot_env(1)%schur_split_quality_ema, &
               local_ot_env(1)%schur_split_calibrated_quality, &
               local_ot_env(1)%schur_split_calibrated_quality_ema, &
               local_ot_env(1)%schur_split_residual_quality, &
               local_ot_env(1)%schur_split_residual_quality_ema, &
               local_ot_env(1)%schur_split_drop_sum, local_ot_env(1)%schur_split_measured_sum, &
               local_ot_env(1)%schur_coupled_quality, local_ot_env(1)%schur_coupled_quality_ema, &
               local_ot_env(1)%schur_coupled_calibrated_quality, &
               local_ot_env(1)%schur_coupled_calibrated_quality_ema, &
               local_ot_env(1)%schur_coupled_residual_quality, &
               local_ot_env(1)%schur_coupled_residual_quality_ema, &
               local_ot_env(1)%schur_coupled_drop_sum, &
               local_ot_env(1)%schur_coupled_calibrated_drop_sum, &
               local_ot_env(1)%schur_coupled_measured_sum
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,9(1X,ES16.8))') &
               " OT Schur LS split shadow n ratio ema cal cal_ema pred cpred meas latest_cal:", &
               local_ot_env(1)%schur_split_shadow_quality_samples, &
               local_ot_env(1)%schur_split_shadow_quality, local_ot_env(1)%schur_split_shadow_quality_ema, &
               local_ot_env(1)%schur_split_shadow_calibrated_quality, &
               local_ot_env(1)%schur_split_shadow_calibrated_quality_ema, &
               local_ot_env(1)%schur_split_shadow_drop_sum, &
               local_ot_env(1)%schur_split_shadow_calibrated_drop_sum, &
               local_ot_env(1)%schur_split_shadow_measured_sum, &
               split_shadow_calibrated_quality_ratio
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,6(1X,ES16.8))') &
               " OT Schur LS occ-gap shadow n ratio ema pred meas gap latest:", &
               local_ot_env(1)%schur_occgap_shadow_quality_samples, &
               local_ot_env(1)%schur_occgap_shadow_quality, &
               local_ot_env(1)%schur_occgap_shadow_quality_ema, &
               local_ot_env(1)%schur_occgap_shadow_drop_sum, &
               local_ot_env(1)%schur_occgap_shadow_measured_sum, &
               local_ot_env(1)%schur_occgap_shadow_gap_ratio, &
               occgap_shadow_predicted_drop
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,10(1X,ES16.8),1X,L1)') &
               " OT Schur LS constrained n ratio ema cal cal_ema pred cpred meas gap split_cal_ema split_cpred enabled:", &
               local_ot_env(1)%schur_constrained_quality_samples, &
               local_ot_env(1)%schur_constrained_quality, local_ot_env(1)%schur_constrained_quality_ema, &
               local_ot_env(1)%schur_constrained_calibrated_quality, &
               local_ot_env(1)%schur_constrained_calibrated_quality_ema, &
               local_ot_env(1)%schur_constrained_drop_sum, &
               local_ot_env(1)%schur_constrained_calibrated_drop_sum, &
               local_ot_env(1)%schur_constrained_measured_sum, local_ot_env(1)%schur_constrained_gap_ratio, &
               local_ot_env(1)%schur_split_calibrated_quality_ema, &
               local_ot_env(1)%schur_split_calibrated_drop_sum, &
               local_ot_env(1)%schur_constrained_candidate_enabled
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,11(1X,ES16.8))') &
               " OT Schur LS projector modes n ratio ema pred meas rdrop rratio step rneg trust tema latest:", &
               local_ot_env(1)%schur_projector_mode_quality_samples, &
               local_ot_env(1)%schur_projector_mode_quality, &
               local_ot_env(1)%schur_projector_mode_quality_ema, &
               local_ot_env(1)%schur_projector_mode_drop_sum, &
               local_ot_env(1)%schur_projector_mode_measured_sum, &
               local_ot_env(1)%schur_projector_mode_response_drop_sum, &
               projector_mode_response_drop_ratio, projector_mode_step_negative, &
               projector_mode_response_negative, projector_mode_trust, &
               local_ot_env(1)%schur_projector_mode_trust_ema, &
               local_ot_env(1)%schur_projector_mode_response_drop
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,12(1X,ES16.8))') &
               " OT Schur LS projector offdiag-dP modes n ratio ema pred meas signed sema abs aema neg nema step sema:", &
               local_ot_env(1)%schur_projector_offdiag_quality_samples, &
               local_ot_env(1)%schur_projector_offdiag_quality, &
               local_ot_env(1)%schur_projector_offdiag_quality_ema, &
               local_ot_env(1)%schur_projector_offdiag_drop_sum, &
               local_ot_env(1)%schur_projector_offdiag_measured_sum, &
               projector_offdiag_signed_ratio, &
               local_ot_env(1)%schur_projector_offdiag_signed_ratio_ema, &
               projector_offdiag_abs_ratio, &
               local_ot_env(1)%schur_projector_offdiag_abs_ratio_ema, &
               projector_offdiag_negative, &
               local_ot_env(1)%schur_projector_offdiag_negative_ema, &
               projector_offdiag_step_negative, &
               local_ot_env(1)%schur_projector_offdiag_step_negative_ema
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,12(1X,ES16.8))') &
               " OT Schur LS projector inactive-offdiag-dP modes n ratio ema pred meas signed sema abs "// &
               "aema neg nema step sema:", &
               local_ot_env(1)%schur_projector_inactive_offdiag_quality_samples, &
               local_ot_env(1)%schur_projector_inactive_offdiag_quality, &
               local_ot_env(1)%schur_projector_inactive_offdiag_quality_ema, &
               local_ot_env(1)%schur_projector_inactive_offdiag_drop_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_measured_sum, &
               projector_inactive_offdiag_signed_ratio, &
               local_ot_env(1)%schur_projector_inactive_offdiag_signed_ratio_ema, &
               projector_inactive_offdiag_abs_ratio, &
               local_ot_env(1)%schur_projector_inactive_offdiag_abs_ratio_ema, &
               projector_inactive_offdiag_negative, &
               local_ot_env(1)%schur_projector_inactive_offdiag_negative_ema, &
               projector_inactive_offdiag_step_negative, &
               local_ot_env(1)%schur_projector_inactive_offdiag_step_negative_ema
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,7(1X,ES16.8))') &
               " OT Schur LS projector inactive-offdiag selected history n ratio ema resid rema pred meas latest:", &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality_samples, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality_ema, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_residual_quality, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_residual_quality_ema, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_drop_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_measured_sum, &
               projector_inactive_offdiag_selected_predicted_drop
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,7(1X,ES16.8),1X,L1)') &
               " OT Schur LS projector response n ratio ema pred meas weight wema neg enabled:", &
               local_ot_env(1)%schur_projector_response_quality_samples, &
               local_ot_env(1)%schur_projector_response_quality, &
               local_ot_env(1)%schur_projector_response_quality_ema, &
               local_ot_env(1)%schur_projector_response_drop_sum, &
               local_ot_env(1)%schur_projector_response_measured_sum, &
               local_ot_env(1)%schur_projector_response_weight, &
               local_ot_env(1)%schur_projector_response_weight_ema, &
               local_ot_env(1)%schur_projector_response_negative_ema, &
               local_ot_env(1)%schur_projector_response_candidate_enabled
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,7(1X,ES16.8))') &
               " OT Schur LS projector response selected history n ratio ema resid rema pred meas latest:", &
               local_ot_env(1)%schur_projector_response_selected_quality_samples, &
               local_ot_env(1)%schur_projector_response_selected_quality, &
               local_ot_env(1)%schur_projector_response_selected_quality_ema, &
               local_ot_env(1)%schur_projector_response_selected_residual_quality, &
               local_ot_env(1)%schur_projector_response_selected_residual_quality_ema, &
               local_ot_env(1)%schur_projector_response_selected_drop_sum, &
               local_ot_env(1)%schur_projector_response_selected_measured_sum, &
               projector_response_selected_predicted_drop
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,11(1X,ES16.8))') &
               " OT Schur LS projector plateau-gap n ratio ema pred meas latest weight wema neg nema step sema:", &
               local_ot_env(1)%schur_projector_plateau_gap_quality_samples, &
               local_ot_env(1)%schur_projector_plateau_gap_quality, &
               local_ot_env(1)%schur_projector_plateau_gap_quality_ema, &
               local_ot_env(1)%schur_projector_plateau_gap_drop_sum, &
               local_ot_env(1)%schur_projector_plateau_gap_measured_sum, &
               projector_plateau_gap_predicted_drop, &
               local_ot_env(1)%schur_projector_plateau_gap_weight, &
               local_ot_env(1)%schur_projector_plateau_gap_weight_ema, &
               local_ot_env(1)%schur_projector_plateau_gap_negative, &
               local_ot_env(1)%schur_projector_plateau_gap_negative_ema, &
               local_ot_env(1)%schur_projector_plateau_gap_step, &
               local_ot_env(1)%schur_projector_plateau_gap_step_ema
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,9(1X,ES16.8),1X,L1)') &
               " OT Schur LS projector diag-ref n ratio ema pred meas weight wema corr cema neg enabled:", &
               local_ot_env(1)%schur_projector_diagref_quality_samples, &
               local_ot_env(1)%schur_projector_diagref_quality, &
               local_ot_env(1)%schur_projector_diagref_quality_ema, &
               local_ot_env(1)%schur_projector_diagref_drop_sum, &
               local_ot_env(1)%schur_projector_diagref_measured_sum, &
               local_ot_env(1)%schur_projector_diagref_weight, &
               local_ot_env(1)%schur_projector_diagref_weight_ema, &
               local_ot_env(1)%schur_projector_diagref_correction_drop, &
               local_ot_env(1)%schur_projector_diagref_correction_ratio_ema, &
               local_ot_env(1)%schur_projector_diagref_negative_ema, &
               local_ot_env(1)%schur_projector_diagref_candidate_enabled
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,8(1X,ES16.8))') &
               " OT Schur LS projector density n ratio ema pred meas latest lowcurv lcema lcqema:", &
               local_ot_env(1)%schur_projector_density_quality_samples, &
