                                                    added_mos_auto_tail_enabled, &
                                                    added_mos_auto_tail_residual_limit, &
                                                    eps_scf_channel, response_raw_delta)
      INTEGER, INTENT(IN)                                :: target_group
      LOGICAL, INTENT(OUT)                               :: group_done
      LOGICAL, INTENT(IN)                                :: added_mos_auto_tail_enabled
      REAL(KIND=dp), INTENT(IN) :: added_mos_auto_tail_residual_limit, eps_scf_channel, response_raw_delta

      INTEGER, PARAMETER :: max_schur_rot = 800, reject_dgesv = 1, reject_model_gap = 6, &
         reject_model_mismatch = 8, reject_nondescent = 2, reject_norm = 3, &
         reject_quality_gate = 7, reject_response = 4, reject_scale = 5
      REAL(KIND=dp), PARAMETER :: max_norm_ratio = 1.0E6_dp, &
         schur_frontier_curvature_floor = 5.0E-1_dp, schur_gauge_curvature_floor = 1.5_dp, &
         schur_gauge_occ_gap_max = 5.0E-2_dp, schur_min_coupled_scale = 5.0E-1_dp, &
         schur_model_gap_factor = 5.0E-1_dp, schur_response_penalty_scale = 1.0_dp, &
         schur_response_trust_factor = 2.5E-1_dp

      INTEGER :: channel_var_start, constrained_reject_reason, coupled_reject_reason, &
         dense_reject_reason, group, ie, ikpoint, imo, info, ispin, ivar, jmo, local_channel, &
         local_kpoint, nchannels, ne, nmo, nrot, nrot_active, nrot_full, &
         projector_fd_cluster_derivatives, projector_fd_cluster_replacements, r, reject_reason, s, &
         schur_attempt, schur_used_attempt, selected_attempt, selected_flavor, &
         split_selected_attempt
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: channel_nmo, e_offset, ipiv, &
                                                            ipiv_energy, var_channel, var_ei, &
                                                            var_ej, var_i, var_j, var_kind
      LOGICAL :: active_pair, attempt_failed, constrained_candidate_enabled, &
