         projector_physical_direct_density_selected_mermin_quality = 0.0_dp
         projector_physical_direct_density_shadow_quality_for_selection = 0.0_dp
         density_descent_bootstrap_maturity = 0.0_dp
         density_descent_bootstrap_quality = 0.0_dp
         density_descent_bootstrap_ready = .FALSE.
         density_descent_quality_for_selection = 0.0_dp
         projector_physical_trace_split_quality = 0.0_dp
         projector_physical_direct_density_audit_quality = 1.0_dp
         projector_physical_direct_floor_density_maturity = 0.0_dp
         projector_physical_direct_floor_density_bootstrap_weight = 0.0_dp
         projector_physical_direct_floor_density_quality = 0.0_dp
         projector_physical_direct_floor_density_trust_quality = 1.0_dp
         projector_physical_direct_floor_density_weight = 0.0_dp
         projector_physical_response_abs_step = 0.0_dp
         projector_physical_response_abs_trust_ratio = 0.0_dp
         projector_physical_response_weighted_step = 0.0_dp
         projector_physical_response_weighted_trust_ratio = 0.0_dp
         projector_physical_scale_quality = 0.0_dp
         projector_physical_trust_quality = 1.0_dp
         projector_physical_trust_scale = 1.0_dp
         projector_physical_unit_abs_step = 0.0_dp
         projector_physical_unit_weighted_step = 0.0_dp
         projector_physical_response_audit_base_weight = 0.0_dp
         projector_physical_response_audit_eval_abs_avg = 0.0_dp
         projector_physical_response_audit_negative_weight_sum = 0.0_dp
         projector_physical_response_audit_positive_weight_sum = 0.0_dp
         projector_physical_response_audit_response_total_sum = 0.0_dp
         projector_physical_response_audit_step_weight_sum = 0.0_dp
         projector_physical_response_correction_drop = 0.0_dp
         projector_physical_response_correction_negative = 0.0_dp
         projector_physical_response_negative_coeff = 0.0_dp
         projector_physical_response_positive_coeff = 0.0_dp
         projector_physical_response_cross_drop = 0.0_dp
         projector_physical_response_negative_drop = 0.0_dp
         projector_physical_response_positive_drop = 0.0_dp
         projector_physical_response_raw_negative_fraction = 0.0_dp
         projector_physical_response_weight = 0.0_dp
         projector_response_direction_scale = 0.0_dp
         projector_response_expected_drop = 0.0_dp
         projector_response_gdot_energy = 0.0_dp
         projector_response_gdot_rotation = 0.0_dp
         projector_response_gdotp = 0.0_dp
         projector_response_model_calibrated_drop = 0.0_dp
         projector_response_model_drop = 0.0_dp
         projector_response_model_gap = 0.0_dp
         projector_response_model_gap_drop = 0.0_dp
         projector_response_model_gap_ratio = 0.0_dp
         projector_response_model_gap_trust = HUGE(1.0_dp)
         projector_response_metric_norm_energy = 0.0_dp
         projector_response_metric_norm_rotation = 0.0_dp
         projector_response_metric_normp = 0.0_dp
         projector_response_norm_energy = 0.0_dp
         projector_response_norm_rotation = 0.0_dp
         projector_response_normp = 0.0_dp
         projector_response_norm_ratio = 0.0_dp
         projector_response_quality_for_selection = 0.0_dp
         projector_response_response_abs_step = 0.0_dp
         projector_response_response_abs_trust_ratio = 0.0_dp
         projector_response_response_weighted_step = 0.0_dp
         projector_response_response_weighted_trust_ratio = 0.0_dp
         projector_response_scale_quality = 0.0_dp
         projector_response_trust_quality = 1.0_dp
         projector_response_trust_scale = 1.0_dp
         projector_response_unit_abs_step = 0.0_dp
         projector_response_unit_weighted_step = 0.0_dp
         projector_mode_response_audit_base_weight = 0.0_dp
         projector_mode_response_audit_eval_abs_avg = 0.0_dp
         projector_mode_response_audit_negative_weight_sum = 0.0_dp
         projector_mode_response_audit_positive_weight_sum = 0.0_dp
         projector_mode_response_audit_response_total_sum = 0.0_dp
         projector_mode_response_audit_step_weight_sum = 0.0_dp
         projector_mode_response_correction_drop = 0.0_dp
         projector_mode_response_correction_negative = 0.0_dp
         projector_mode_response_negative_coeff = 0.0_dp
         projector_mode_response_positive_coeff = 0.0_dp
         projector_mode_response_cross_drop = 0.0_dp
         projector_mode_response_negative_drop = 0.0_dp
         projector_mode_response_positive_drop = 0.0_dp
         projector_mode_response_drop = 0.0_dp
         projector_mode_response_drop_ratio = 0.0_dp
         projector_mode_response_negative_fraction = 0.0_dp
         projector_mode_response_raw_negative_fraction = 0.0_dp
         projector_mode_step_negative_fraction = 0.0_dp
         projector_mode_trust_quality = 1.0_dp
         projector_mode_response_weight = 0.0_dp
         mermin_branch_loss_gain = 0.0_dp
         mermin_branch_loss_weight = kpoint_ot_mermin_branch_loss_weight( &
                                     local_ot_env(1)%mermin_ls_accepted_quality_ema, &
                                     local_ot_env(1)%mermin_ls_accepted_gap_ema, &
                                     local_ot_env(1)%mermin_ls_accepted_quality_samples)
         model_gap = 0.0_dp
         model_gap_drop = 0.0_dp
         model_gap_ratio = 0.0_dp
         model_gap_trust = HUGE(1.0_dp)
         model_calibrated_drop = 0.0_dp
         row_floor_shift_drop = 0.0_dp
         occgap_shadow_abs_step = 0.0_dp
         occgap_shadow_drop = 0.0_dp
         occgap_shadow_gap_ratio = 0.0_dp
         occgap_shadow_quality = 1.0_dp
         occgap_shadow_step = 0.0_dp
         split_curvature_scale = 1.0_dp
         split_direction_scale = 0.0_dp
         split_dense_expected_ratio = 0.0_dp
         split_expected_drop = 0.0_dp
         split_gdotp = 0.0_dp
         split_gdot_energy = 0.0_dp
         split_gdot_rotation = 0.0_dp
         split_model_calibrated_drop = 0.0_dp
         split_model_drop = 0.0_dp
         split_model_gap_ratio = 0.0_dp
         split_occgap_shadow_drop = 0.0_dp
         split_occgap_shadow_gap_ratio = 0.0_dp
         split_norm_energy = 0.0_dp
         split_norm_rotation = 0.0_dp
         split_normp = 0.0_dp
         split_norm_ratio = 0.0_dp
         split_scale_quality = 0.0_dp
         split_response_abs_step = 0.0_dp
         split_response_abs_trust_ratio = 0.0_dp
         split_response_step = 0.0_dp
         split_response_weighted_step = 0.0_dp
         split_response_weighted_trust_ratio = 0.0_dp
         split_quality_for_calibration = 1.0_dp
         split_quality_for_selection = ot_kp_schur_calibrated_quality_min_ratio
         split_residual_quality = 1.0_dp
         split_residual_competitive = .TRUE.
         step_gauge_quality = 1.0_dp
         IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
            step_gauge_quality = &
               kpoint_ot_schur_step_gauge_quality(local_ot_env(1)%schur_step_gauge_ratio, &
                                                  local_ot_env(1)%schur_step_gauge_ratio_ema, &
                                                  local_ot_env(1)%schur_step_gauge_residual_quality, &
                                                  local_ot_env(1)%schur_step_gauge_residual_quality_ema, &
                                                  local_ot_env(1)%schur_step_gauge_quality_samples)
         END IF
         constrained_quality_for_selection = ot_kp_schur_calibrated_quality_min_ratio
         split_trust_quality = 1.0_dp
         split_density_projector_fraction = 0.0_dp
         split_diag_shift_max = 0.0_dp
         split_diag_shift_sum = 0.0_dp
         split_residual_delta = 0.0_dp
         split_response_abs_trust = HUGE(1.0_dp)
         split_response_trust = HUGE(1.0_dp)
         split_response_trust_factor = 1.0_dp
         split_rot_floor_min = rotation_curvature_floor
         split_schur_diag_min = HUGE(1.0_dp)
         exact_density_plateau_response_ready = .FALSE.
         exact_density_response_ready = .FALSE.
         exact_density_direct_response_ready = .FALSE.
         exact_density_full_audit_ready = .FALSE.
         exact_density_floor_audit_ready = .FALSE.
         exact_density_full_response_ready = .FALSE.
         density_full_candidate_ready = .FALSE.
         density_full_candidate_selected = .FALSE.
         density_full_direct_candidate_ready = .FALSE.
         density_full_direct_candidate_selected = .FALSE.
         density_full_direct_tail_probe_ready = .FALSE.
         density_full_global_bootstrap_ready = .FALSE.
         density_full_global_candidate_ready = .FALSE.
         density_full_global_candidate_selected = .FALSE.
         density_full_global_tail_prefer = .FALSE.
         density_full_global_tail_probe_ready = .FALSE.
         density_full_tail_probe_ready = .FALSE.
         density_descent_candidate_ready = .FALSE.
         density_descent_candidate_selected = .FALSE.
         density_descent_tail_probe_ready = .FALSE.
         exact_physical_response_ready = .FALSE.
         failed = .FALSE.
         constrained_candidate_ready = .FALSE.
         constrained_candidate_selected = .FALSE.
         projector_physical_candidate_ready = .FALSE.
         projector_physical_candidate_selected = .FALSE.
         projector_physical_direct_candidate_ready = .FALSE.
         projector_physical_direct_candidate_selected = .FALSE.
         projector_physical_direct_candidate_used = .FALSE.
         projector_physical_direct_density_candidate_ready = .FALSE.
         projector_physical_direct_density_candidate_selected = .FALSE.
         projector_physical_direct_density_quality_ready = .FALSE.
         projector_physical_direct_density_residual_bad = .FALSE.
         projector_physical_direct_density_selected_probe_ready = .FALSE.
         projector_physical_direct_density_tail_probe_ready = .FALSE.
         projector_physical_direct_spectral_candidate_ready = .FALSE.
         projector_physical_direct_spectral_candidate_selected = .FALSE.
         projector_physical_direct_spectral_probe_ready = .FALSE.
         projector_physical_direct_spectral_probe_selected = .FALSE.
         projector_offdiag_candidate_ready = .FALSE.
         projector_offdiag_candidate_selected = .FALSE.
         projector_offdiag_candidate_inactive = .FALSE.
         projector_inactive_offdiag_candidate_ready = .FALSE.
         projector_response_candidate_ready = .FALSE.
         projector_response_candidate_selected = .FALSE.
         split_candidate_ready = .FALSE.
         split_candidate_selected = .FALSE.
         projector_fd_cluster_derivatives = 0
         projector_fd_cluster_replacements = 0
         split_selected_attempt = 0
         ivar = 0
         constrained_sol(:) = 0.0_dp
         constrained_z_e(:) = 0.0_dp
         projector_physical_direct_sol(:) = 0.0_dp
         projector_physical_direct_z_e(:) = 0.0_dp
         projector_physical_direct_density_sol(:) = 0.0_dp
         projector_physical_sol(:) = 0.0_dp
         projector_physical_z_e(:) = 0.0_dp
         split_sol(:) = 0.0_dp
         split_z_e(:) = 0.0_dp

         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (group /= target_group) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               channel_projector_weight = kpoint_ot_canonical_projector_weight(local_ot_env(local_channel)%delta, &
                                                                               ot_kp_canonical_projector_max_weight)
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               ALLOCATE (h_re(nmo, nmo), h_im(nmo, nmo), grad_re(nmo, nmo), grad_im(nmo, nmo))
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_chc, h_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_chc_im, h_im)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx, grad_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx_im, grad_im)
               CALL local_ot_env(local_channel)%para_env%sum(h_re)
               CALL local_ot_env(local_channel)%para_env%sum(h_im)
               CALL local_ot_env(local_channel)%para_env%sum(grad_re)
               CALL local_ot_env(local_channel)%para_env%sum(grad_im)

               tether_strength = 0.0_dp
               IF (local_ot_env(local_channel)%settings%canonical_tether) THEN
                  rayleigh_edge_gap = 0.0_dp
                  DO imo = 1, nmo
                     tether_response = kpoint_ot_canonical_tether_response(trial_occupation(imo, ikpoint, ispin), &
                                                                           trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                                                           sigma, maxocc)
                     IF (tether_response > 0.0_dp) &
                        rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                                ABS(h_re(imo, imo) - local_ot_env(local_channel)%ener_x(imo)))
                  END DO
                  tether_strength = kpoint_ot_canonical_tether_strength(local_ot_env(local_channel), &
                                                                        rayleigh_edge_gap, sigma)
               END IF

               DO imo = 1, nmo
                  ie = e_offset(local_channel) + imo - 1
                  gvalue = kpoint_ot_smearing_g(trial_occupation(imo, ikpoint, ispin), &
                                                trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                                sigma, maxocc, smear%method)
                  tether_weight = kpoint_ot_canonical_tether_weight(trial_occupation(imo, ikpoint, ispin), &
                                                                    trial_eigenvalues(imo, ikpoint, ispin), &
                                                                    mu, sigma, &
                                                                    maxocc, wkp(ikpoint), tether_strength)
                  occ_curv(ie) = wkp(ikpoint)*gvalue
                  tether_curv(ie) = tether_weight
                  curv(ie) = occ_curv(ie) + tether_curv(ie)
                  grad_e(ie) = local_ot_env(local_channel)%ener_gx(imo)
               END DO
               channel_occ_curv_max = MAXVAL(occ_curv(e_offset(local_channel): &
                                                      e_offset(local_channel) + nmo - 1))

               channel_var_start = ivar + 1
               DO imo = 1, nmo - 1
                  DO jmo = imo + 1, nmo
                     IF (schur_active_subspace) THEN
                        occ_tail_i = MAX(0.0_dp, MIN(trial_occupation(imo, ikpoint, ispin), &
                                                     maxocc - trial_occupation(imo, ikpoint, ispin)))
                        occ_tail_j = MAX(0.0_dp, MIN(trial_occupation(jmo, ikpoint, ispin), &
                                                     maxocc - trial_occupation(jmo, ikpoint, ispin)))
                        active_pair = MAX(occ_tail_i, occ_tail_j) >= schur_active_occ_min .OR. &
                                      ABS(trial_eigenvalues(imo, ikpoint, ispin) - trial_mu(ispin)) <= &
                                      schur_energy_window .OR. &
                                      ABS(trial_eigenvalues(jmo, ikpoint, ispin) - trial_mu(ispin)) <= &
                                      schur_energy_window
                        IF (.NOT. active_pair) CYCLE
                     END IF
                     ivar = ivar + 1
                     var_channel(ivar) = local_channel
                     var_i(ivar) = imo
                     var_j(ivar) = jmo
                     var_kind(ivar) = 1
                     var_ei(ivar) = e_offset(local_channel) + imo - 1
                     var_ej(ivar) = e_offset(local_channel) + jmo - 1
                     pair_projector_weight = kpoint_ot_pair_projector_weight(channel_projector_weight, &
                                                                             occ_curv(var_ei(ivar)), &
                                                                             occ_curv(var_ej(ivar)), &
                                                                             channel_occ_curv_max)
                     pair_occ_gap = MIN(1.0_dp, &
                                        ABS(trial_occupation(imo, ikpoint, ispin) - &
                                            trial_occupation(jmo, ikpoint, ispin))/ &
                                        MAX(maxocc, EPSILON(maxocc)))
                     var_projector_active_weight(ivar) = pair_projector_weight
                     var_projector_weight(ivar) = channel_projector_weight
                     var_occ_gap_weight(ivar) = pair_occ_gap
                     grad_rot(ivar) = 2.0_dp*grad_re(imo, jmo)
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) > EPSILON(1.0_dp)) &
                        rot_floor(ivar) = schur_frontier_curvature_floor
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) <= EPSILON(1.0_dp) .AND. &
                         pair_occ_gap <= schur_gauge_occ_gap_max) &
                        rot_floor(ivar) = schur_gauge_curvature_floor

                     ivar = ivar + 1
                     var_channel(ivar) = local_channel
                     var_i(ivar) = imo
                     var_j(ivar) = jmo
                     var_kind(ivar) = 2
                     var_ei(ivar) = e_offset(local_channel) + imo - 1
                     var_ej(ivar) = e_offset(local_channel) + jmo - 1
                     var_projector_active_weight(ivar) = pair_projector_weight
                     var_projector_weight(ivar) = channel_projector_weight
                     var_occ_gap_weight(ivar) = pair_occ_gap
                     grad_rot(ivar) = 2.0_dp*grad_im(imo, jmo)
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) > EPSILON(1.0_dp)) &
                        rot_floor(ivar) = schur_frontier_curvature_floor
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) <= EPSILON(1.0_dp) .AND. &
                         pair_occ_gap <= schur_gauge_occ_gap_max) &
                        rot_floor(ivar) = schur_gauge_curvature_floor
                  END DO
               END DO
               CALL build_finite_ref_rotation_model(local_channel, nmo, channel_var_start, ivar, &
                                                    e_offset(local_channel), h_re, h_im, &
                                                    trial_occupation(1:nmo, ikpoint, ispin), wkp(ikpoint), &
                                                    projector_occupation_window_gap, &
                                                    occ_curv(e_offset(local_channel):e_offset(local_channel) + nmo - 1), &
                                                    var_i, var_j, var_kind, &
                                                    projector_physical_shadow_enabled, &
                                                    projector_density_full_audit_enabled, &
                                                    projector_plateau_gap_model_enabled, &
                                                    step_gauge_quality, &
                                                    rot_hessian, rot_hessian_coupled, rot_hessian_projector, &
                                                    rot_hessian_projector_physical, &
                                                    rot_hessian_projector_physical_offdiag, &
                                                    rot_hessian_projector_physical_offdiag_plateau, response, &
                                                    response_occ, response_occ_physical, response_density_physical, &
                                                    response_density_floor_audit, response_density_full, &
                                                    response_density_full_audit, &
                                                    response_density_plateau, &
                                                    projector_fd_cluster_derivatives, &
                                                    projector_fd_cluster_replacements, failed)
               DEALLOCATE (h_re, h_im, grad_re, grad_im)
            END DO
         END DO

         CPASSERT(ivar == nrot)
         rot_grad_active_re = 0.0_dp
         rot_grad_active_im = 0.0_dp
         rot_grad_inactive_re = 0.0_dp
         rot_grad_inactive_im = 0.0_dp
         rot_grad_gap_re = 0.0_dp
         rot_grad_gap_im = 0.0_dp
         rot_grad_gauge_re = 0.0_dp
         rot_grad_gauge_im = 0.0_dp
         rot_grad_active_weight_sum = 0.0_dp
         rot_grad_inactive_weight_sum = 0.0_dp
         rot_grad_gap_weight = 0.0_dp
         rot_grad_gauge_weight = 0.0_dp
         rot_grad_active_fraction_max = 0.0_dp
         DO r = 1, nrot
            rot_grad_pair_fraction = 0.0_dp
            IF (var_projector_weight(r) > EPSILON(var_projector_weight(r))) &
               rot_grad_pair_fraction = var_projector_active_weight(r)/var_projector_weight(r)
            rot_grad_pair_fraction = MIN(1.0_dp, MAX(0.0_dp, rot_grad_pair_fraction))
            rot_grad_rest_fraction = 1.0_dp - rot_grad_pair_fraction
            rot_grad_fermi_weight = rot_grad_pair_fraction
            rot_grad_gap_fraction = kpoint_ot_residual_occ_gap_weight(var_occ_gap_weight(r))
            rot_grad_sq = grad_rot(r)*grad_rot(r)
            rot_grad_gap_weight = rot_grad_gap_weight + &
                                  rot_grad_rest_fraction*rot_grad_gap_fraction
            rot_grad_gauge_weight = rot_grad_gauge_weight + &
                                    rot_grad_rest_fraction*(1.0_dp - rot_grad_gap_fraction)
            IF (var_kind(r) == 1) THEN
               rot_grad_active_re = rot_grad_active_re + rot_grad_pair_fraction*rot_grad_sq
               rot_grad_inactive_re = rot_grad_inactive_re + rot_grad_rest_fraction*rot_grad_sq
               rot_grad_gap_re = rot_grad_gap_re + &
                                  rot_grad_rest_fraction*rot_grad_gap_fraction*rot_grad_sq
               rot_grad_gauge_re = rot_grad_gauge_re + &
                                   rot_grad_rest_fraction*(1.0_dp - rot_grad_gap_fraction)*rot_grad_sq
            ELSE
               rot_grad_active_im = rot_grad_active_im + rot_grad_pair_fraction*rot_grad_sq
               rot_grad_inactive_im = rot_grad_inactive_im + rot_grad_rest_fraction*rot_grad_sq
               rot_grad_gap_im = rot_grad_gap_im + &
                                  rot_grad_rest_fraction*rot_grad_gap_fraction*rot_grad_sq
               rot_grad_gauge_im = rot_grad_gauge_im + &
                                   rot_grad_rest_fraction*(1.0_dp - rot_grad_gap_fraction)*rot_grad_sq
            END IF
            rot_grad_active_weight_sum = rot_grad_active_weight_sum + rot_grad_fermi_weight
            rot_grad_inactive_weight_sum = rot_grad_inactive_weight_sum + rot_grad_rest_fraction
            rot_grad_active_fraction_max = MAX(rot_grad_active_fraction_max, rot_grad_pair_fraction)
         END DO
         CALL para_env_inter_kp%sum(rot_grad_active_re)
         CALL para_env_inter_kp%sum(rot_grad_active_im)
         CALL para_env_inter_kp%sum(rot_grad_inactive_re)
         CALL para_env_inter_kp%sum(rot_grad_inactive_im)
         CALL para_env_inter_kp%sum(rot_grad_gap_re)
         CALL para_env_inter_kp%sum(rot_grad_gap_im)
         CALL para_env_inter_kp%sum(rot_grad_gauge_re)
         CALL para_env_inter_kp%sum(rot_grad_gauge_im)
         CALL para_env_inter_kp%sum(rot_grad_active_weight_sum)
         CALL para_env_inter_kp%sum(rot_grad_inactive_weight_sum)
         CALL para_env_inter_kp%sum(rot_grad_gap_weight)
         CALL para_env_inter_kp%sum(rot_grad_gauge_weight)
         CALL para_env_inter_kp%max(rot_grad_active_fraction_max)
         rot_grad_active_fraction_avg = 0.0_dp
         IF (rot_grad_active_weight_sum + rot_grad_inactive_weight_sum > EPSILON(1.0_dp)) &
            rot_grad_active_fraction_avg = rot_grad_active_weight_sum/ &
                                           (rot_grad_active_weight_sum + rot_grad_inactive_weight_sum)
         rot_grad_physical_norm = rot_grad_active_re + rot_grad_active_im + &
                                  rot_grad_gap_re + rot_grad_gap_im
         rot_grad_gauge_norm = rot_grad_gauge_re + rot_grad_gauge_im
         rot_grad_energy_norm = DOT_PRODUCT(grad_e, grad_e)
         CALL para_env_inter_kp%sum(rot_grad_energy_norm)
         rot_grad_total_physical_norm = rot_grad_physical_norm + rot_grad_energy_norm
         ! With a complete rotation audit the raw physical gradient is a safer
         ! convergence metric than the preconditioned Schur search direction.
         physical_delta_raw_tail_ready = eps_scf_channel > 0.0_dp .AND. &
                                         response_raw_delta > 0.0_dp .AND. &
                                         response_raw_delta <= &
                                         ot_kp_schur_physical_tail_eps_factor*eps_scf_channel
         physical_delta_norm = 0.0_dp
         IF (nrot + ne > 0) &
            physical_delta_norm = SQRT(MAX(0.0_dp, rot_grad_total_physical_norm)/ &
                                       REAL(nrot + ne, KIND=dp))
         physical_delta_norm_limit = &
            ot_kp_schur_physical_norm_tail_factor*ot_kp_schur_physical_tail_eps_factor* &
            eps_scf_channel
         physical_delta_norm_ready = eps_scf_channel > 0.0_dp .AND. &
                                     physical_delta_norm <= physical_delta_norm_limit .AND. &
                                     local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                     ot_kp_schur_calibration_min_samples .AND. &
                                     local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp .AND. &
                                     local_ot_env(1)%mermin_ls_accepted_gap_ema <= &
                                     ot_kp_schur_residual_tail_plateau_slack
         physical_delta_plateau_ready = residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                        physical_delta_norm <= physical_delta_norm_limit .AND. &
                                        rot_grad_total_physical_norm <= &
                                        MAX(rot_grad_gauge_norm, residual_delta*residual_delta) .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                        ot_kp_schur_calibration_min_samples .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_gap_ema <= &
                                        ot_kp_schur_residual_tail_plateau_slack
         physical_delta_group_ready = residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                      (.NOT. schur_active_subspace .OR. &
                                       rot_grad_gauge_norm > &
                                       MAX(rot_grad_total_physical_norm, EPSILON(1.0_dp)) .OR. &
                                       physical_delta_norm_ready .OR. &
                                       physical_delta_plateau_ready)
         local_ot_env(1)%kpoint_physical_delta_groups = &
            local_ot_env(1)%kpoint_physical_delta_groups + 1
         local_ot_env(1)%kpoint_physical_gnorm = &
            local_ot_env(1)%kpoint_physical_gnorm + rot_grad_total_physical_norm
         local_ot_env(1)%kpoint_physical_rot_gnorm = &
            local_ot_env(1)%kpoint_physical_rot_gnorm + rot_grad_physical_norm
         local_ot_env(1)%kpoint_physical_energy_gnorm = &
            local_ot_env(1)%kpoint_physical_energy_gnorm + rot_grad_energy_norm
         local_ot_env(1)%kpoint_gauge_gnorm = &
            local_ot_env(1)%kpoint_gauge_gnorm + rot_grad_gauge_norm
         local_ot_env(1)%kpoint_physical_delta_ready = &
            local_ot_env(1)%kpoint_physical_delta_ready .AND. physical_delta_group_ready
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,8(1X,ES16.8))') &
            " OT Schur rotation gradient active audit group re im inactive_re inactive_im favg fmax wact winact:", &
            target_group, rot_grad_active_re, rot_grad_active_im, rot_grad_inactive_re, &
            rot_grad_inactive_im, rot_grad_active_fraction_avg, rot_grad_active_fraction_max, &
            rot_grad_active_weight_sum, rot_grad_inactive_weight_sum
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,8(1X,ES16.8))') &
            " OT Schur rotgrad occ audit grp gap_re gap_im gauge_re gauge_im wgap wgauge fermi_re fermi_im:", &
            target_group, rot_grad_gap_re, rot_grad_gap_im, rot_grad_gauge_re, &
            rot_grad_gauge_im, rot_grad_gap_weight, rot_grad_gauge_weight, &
            rot_grad_active_re, rot_grad_active_im
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,1X,L1,5(1X,ES16.8))') &
            " OT Schur physical residual audit group ready energy rot gauge total raw_delta:", &
            target_group, physical_delta_group_ready, rot_grad_energy_norm, rot_grad_physical_norm, &
            rot_grad_gauge_norm, rot_grad_total_physical_norm, residual_delta
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,L1),8(1X,ES16.8),1X,I6)') &
            " OT Schur physical residual plateau audit group ready plateau norm rawtail qema gema "// &
            "phys pdelta raw resp neps eps samples:", &
            target_group, physical_delta_group_ready, physical_delta_plateau_ready, &
            physical_delta_norm_ready, physical_delta_raw_tail_ready, &
            local_ot_env(1)%mermin_ls_accepted_quality_ema, &
            local_ot_env(1)%mermin_ls_accepted_gap_ema, &
            rot_grad_total_physical_norm, physical_delta_norm, residual_delta, response_raw_delta, &
            physical_delta_norm_limit, &
            ot_kp_schur_physical_tail_eps_factor*eps_scf_channel, &
            local_ot_env(1)%mermin_ls_accepted_quality_samples
         IF (failed) THEN
            DEALLOCATE (curv, grad_e, occ_curv, tether_curv, z_e, accepted_z_e, z_density_plateau_trial, &
                        z_density_floor_audit_trial, z_density_full_audit_trial, &
                        z_density_full_global_trial, &
                        z_density_full_trial, z_density_trial, &
                        z_exact_physical_trial, z_exact_raw_trial, &
                        z_exact_trial, z_trial, rx_e, rx_model, constrained_z_e, &
                        projector_physical_direct_curv_eval, projector_physical_direct_model_e, &
                        projector_physical_direct_response_rx_e, &
                        projector_physical_direct_diagref_rx_e, &
                        projector_physical_direct_density_rx_e, &
                        projector_physical_direct_density_z_e, &
                        density_descent_rx_e, &
                        density_descent_z_e, &
                        density_full_rx_e, &
                        density_full_global_rx_e, &
                        density_full_global_sol, &
                        density_full_sol, &
                        density_full_z_e, &
                        density_gap_projected_e, &
                        density_gap_rx_e, &
                        density_plateau_rx_e, density_plateau_z_e, &
                        projector_physical_direct_rx_e, &
                        projector_physical_direct_schur_eval, &
                        projector_physical_direct_z_e, projector_physical_model_e, &
                        projector_offdiag_rx_e, projector_offdiag_z_e, &
                        projector_inactive_offdiag_rx_e, &
                        projector_inactive_offdiag_z_e, &
                        projector_physical_rx_e, projector_physical_z_e, &
                        projector_response_rx_e, projector_response_z_e, split_z_e)
            DEALLOCATE (grad_rot, rhs, rtd, sol, accepted_sol, constrained_sol, &
                        projector_physical_direct_sol, &
                        projector_physical_sol, projector_offdiag_sol, &
                        projector_inactive_offdiag_sol, projector_response_sol, split_sol, &
                        var_occ_gap_weight, var_projector_active_weight, var_projector_weight)
            DEALLOCATE (var_channel, var_ei, var_ej, var_i, var_j, var_kind)
            DEALLOCATE (rot_floor, row_floor_shift, projector_physical_direct_active_lcomp, &
                        energy_cross, energy_cross_density, &
                        energy_cross_density_floor_audit, energy_cross_density_full, &
                        energy_cross_density_full_audit, energy_cross_density_full_global, &
                        energy_cross_density_plateau, &
                        energy_cross_physical, energy_cross_raw, &
                        energy_hessian, response, response_coupled, response_density_exact, &
                        response_density_floor_audit, response_density_floor_audit_exact, &
                        response_density_full, response_density_full_audit, &
                        response_density_full_audit_exact, response_density_full_exact, &
                        response_density_full_global, response_density_full_global_exact, response_density_physical, &
                        response_density_plateau, response_density_plateau_exact, &
                        response_exact, response_exact_physical, &
                        response_exact_raw, response_occ, response_occ_physical, response_split, rot_hessian, &
                        projector_physical_direct_base_delta, projector_physical_direct_curv_vec, &
                        projector_physical_direct_delta, &
                        rot_hessian_coupled, rot_hessian_projector, &
                        projector_physical_direct_schur_mat, projector_physical_direct_schur_vec, &
                        rot_hessian_projector_physical, &
                        rot_hessian_projector_physical_active, rot_hessian_projector_physical_diagref, &
                        rot_hessian_projector_physical_offdiag_active, &
                        rot_hessian_projector_physical_offdiag, &
                        rot_hessian_projector_physical_offdiag_plateau, &
                        rot_hessian_projector_physical_offdiag_plateau_active, &
                        schur, schur_metric, ipiv, ipiv_energy, channel_nmo, e_offset)
            RETURN
         END IF

         occ_curv_diag_sum = SUM(occ_curv(:))
         tether_curv_diag_sum = SUM(tether_curv(:))
         total_curv_diag_sum = SUM(curv(:))
         occ_curv_diag_max = MAXVAL(occ_curv(:))
         tether_curv_diag_max = MAXVAL(tether_curv(:))
         total_curv_diag_max = MAXVAL(curv(:))
         CALL para_env_inter_kp%sum(occ_curv_diag_sum)
         CALL para_env_inter_kp%sum(tether_curv_diag_sum)
         CALL para_env_inter_kp%sum(total_curv_diag_sum)
         CALL para_env_inter_kp%max(occ_curv_diag_max)
         CALL para_env_inter_kp%max(tether_curv_diag_max)
         CALL para_env_inter_kp%max(total_curv_diag_max)
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) THEN
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,6(1X,ES16.8))') &
               " OT Schur occupation preconditioner group occ_sum occ_max tether_sum tether_max total_sum total_max:", &
               target_group, occ_curv_diag_sum, occ_curv_diag_max, tether_curv_diag_sum, &
               tether_curv_diag_max, total_curv_diag_sum, total_curv_diag_max
         END IF

         z_shift = 0.0_dp
         z_weight = 0.0_dp
         energy_floor_count = 0.0_dp
         energy_floor_curv_sum = 0.0_dp
         curv_projection_sum = SUM(curv)
         CALL para_env_inter_kp%sum(curv_projection_sum)
         occ_curv_projection_sum = SUM(occ_curv)
         CALL para_env_inter_kp%sum(occ_curv_projection_sum)
         DO ie = 1, ne
            IF (curv(ie) > EPSILON(curv(ie))) THEN
               IF (curv(ie) < energy_curvature_floor) THEN
                  energy_floor_count = energy_floor_count + 1.0_dp
                  energy_floor_curv_sum = energy_floor_curv_sum + curv(ie)
               END IF
               z_e(ie) = grad_e(ie)/MAX(curv(ie), energy_curvature_floor)
               z_shift = z_shift + curv(ie)*z_e(ie)
               z_weight = z_weight + curv(ie)
            END IF
         END DO
         CALL para_env_inter_kp%sum(z_shift)
         CALL para_env_inter_kp%sum(z_weight)
         CALL para_env_inter_kp%sum(energy_floor_count)
         CALL para_env_inter_kp%sum(energy_floor_curv_sum)
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,ES16.8))') &
            " OT Schur occupation preconditioner energy-floor group count curv_sum floor:", &
            target_group, energy_floor_count, energy_floor_curv_sum, energy_curvature_floor
         IF (z_weight > EPSILON(z_weight)) z_e(:) = z_e(:) - z_shift/z_weight
         CALL project_kpoint_ot_schur_response(z_e, occ_curv, tether_curv, &
                                               occ_curv_projection_sum, channel_nmo, e_offset)

         z_trial(:) = z_e(:)
         rot_hessian(:, :) = 0.5_dp*(rot_hessian(:, :) + TRANSPOSE(rot_hessian(:, :)))
         rot_hessian_coupled(:, :) = 0.5_dp*(rot_hessian_coupled(:, :) + &
                                             TRANSPOSE(rot_hessian_coupled(:, :)))
         rot_hessian_projector(:, :) = 0.5_dp*(rot_hessian_projector(:, :) + &
                                               TRANSPOSE(rot_hessian_projector(:, :)))
         rot_hessian_projector_physical(:, :) = 0.5_dp*(rot_hessian_projector_physical(:, :) + &
                                                        TRANSPOSE(rot_hessian_projector_physical(:, :)))
         rot_hessian_projector_physical_offdiag(:, :) = 0.5_dp* &
                                                        (rot_hessian_projector_physical_offdiag(:, :) + &
                                                         TRANSPOSE(rot_hessian_projector_physical_offdiag(:, :)))
         rot_hessian_projector_physical_offdiag_plateau(:, :) = 0.5_dp* &
                                                                (rot_hessian_projector_physical_offdiag_plateau(:, :) + &
                                                                 TRANSPOSE(rot_hessian_projector_physical_offdiag_plateau(:, :)))
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.0_dp
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.0_dp
         DO s = 1, nrot
            DO r = 1, nrot
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_offdiag_active_weight = 0.0_dp
               IF (var_projector_weight(r) + var_projector_weight(s) > &
                   EPSILON(projector_offdiag_active_weight)) THEN
                  projector_offdiag_active_weight = &
                     (var_projector_active_weight(r) + var_projector_active_weight(s))/ &
                     MAX(var_projector_weight(r) + var_projector_weight(s), EPSILON(1.0_dp))
                  projector_offdiag_active_weight = &
                     MIN(1.0_dp, MAX(0.0_dp, projector_offdiag_active_weight))
               END IF
               rot_hessian_projector_physical_offdiag_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag(r, s)
               rot_hessian_projector_physical_offdiag_plateau_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag_plateau(r, s)
            END DO
         END DO
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.5_dp* &
                                                               (rot_hessian_projector_physical_offdiag_active(:, :) + &
                                                                TRANSPOSE(rot_hessian_projector_physical_offdiag_active(:, :)))
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.5_dp* &
                                                                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) + &
                                                             TRANSPOSE(rot_hessian_projector_physical_offdiag_plateau_active(:, :)))
         projector_physical_offdiag_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_inactive_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_inactive_abs_avg = &
            SUM(ABS((rot_hessian_projector_physical_offdiag_plateau(:, :) - &
                     rot_hessian_projector_physical_offdiag(:, :)) - &
                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                     rot_hessian_projector_physical_offdiag_active(:, :))))
         rot_hessian_projector_physical_diagref(:, :) = 0.0_dp
         DO s = 1, nrot
            DO r = 1, nrot
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_diagref_weight = 0.5_dp*(var_projector_weight(r) + var_projector_weight(s))
               rot_hessian_projector_physical_diagref(r, s) = &
                  (1.0_dp - projector_diagref_weight)*rot_hessian_coupled(r, s)
            END DO
         END DO
         rot_hessian_projector_physical_diagref(:, :) = 0.5_dp* &
                                                        (rot_hessian_projector_physical_diagref(:, :) + &
                                                         TRANSPOSE(rot_hessian_projector_physical_diagref(:, :)))
         projector_density_floor_audit_abs_avg = SUM(ABS(response_density_floor_audit(:, :)))
         projector_density_floor_audit_gap_abs_avg = &
            SUM(ABS(response_density_floor_audit(:, :) - response_density_physical(:, :)))
         projector_physical_density_full_abs_avg = SUM(ABS(response_density_full(:, :)))
         projector_density_full_audit_abs_avg = SUM(ABS(response_density_full_audit(:, :)))
         IF (local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
               density_full_global_selected_residual_quality = &
                  kpoint_ot_selected_tail_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
               density_full_global_selected_mix_residual_quality = &
                  kpoint_ot_selected_tail_mix_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
               density_full_global_selected_response_scale = 0.25_dp + 0.75_dp* &
                  SQRT(MAX(0.0_dp, MIN(1.0_dp, density_full_global_selected_mix_residual_quality)))
            END IF
         END IF
         projector_density_full_global_floor_mix_weight = &
            kpoint_ot_density_full_global_floor_source_weight( &
            residual_delta, local_ot_env(1)%schur_projector_density_full_global_sel_quality, &
            local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
            local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
            local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema, &
            local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples)
         ! Use the active-window, gauge-safe physical density response for the
         ! global fixed-N candidate.  Once selected global-history repeatedly
         ! underpredicts accepted Mermin drops, admit a tiny piece of the
         ! floor-limited finite-projector source before the fixed-N projection.
         response_density_full_global(:, :) = response_density_physical(:, :)
         IF (projector_density_full_global_floor_mix_weight > &
             EPSILON(projector_density_full_global_floor_mix_weight)) &
            response_density_full_global(:, :) = &
            response_density_full_global(:, :) + projector_density_full_global_floor_mix_weight* &
            (response_density_floor_audit(:, :) - response_density_physical(:, :))
         DO s = 1, nrot
            CALL project_kpoint_ot_schur_response(response_density_full_global(:, s), occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
         END DO
         projector_response_signal_max = 0.0_dp
         projector_response_signal_sum = 0.0_dp
         projector_response_signal_count = 0.0_dp
         var_projector_response_weight(:) = 0.0_dp
         DO r = 1, nrot
            projector_response_signal = 0.0_dp
            DO ie = 1, ne
               projector_response_signal = projector_response_signal + &
                                           MAX(0.0_dp, occ_curv(ie))*response_density_full_global(ie, r)**2
            END DO
            projector_response_signal_weight = &
               kpoint_ot_projector_response_signal_weight(projector_response_signal)
            IF (projector_response_signal_weight > 0.0_dp) THEN
               var_projector_response_weight(r) = projector_response_signal_weight
               projector_response_signal_max = MAX(projector_response_signal_max, &
                                                   var_projector_response_weight(r))
               projector_response_signal_sum = projector_response_signal_sum + &
                                               var_projector_response_weight(r)
               projector_response_signal_count = projector_response_signal_count + 1.0_dp
            END IF
         END DO
         IF (projector_response_signal_max > EPSILON(projector_response_signal_max)) THEN
            projector_response_signal_mean = projector_response_signal_sum/ &
                                             MAX(1.0_dp, projector_response_signal_count)
            projector_response_signal_ref = &
               kpoint_ot_projector_response_character_scale(projector_response_signal_max, &
                                                            projector_response_signal_mean)
            var_projector_response_weight(:) = &
               MIN(1.0_dp, MAX(0.0_dp, var_projector_response_weight(:)/projector_response_signal_ref))
         END IF
         projector_response_character_abs_avg = SUM(var_projector_response_weight(:))
         projector_response_character_max = MAXVAL(var_projector_response_weight(:))
         projector_response_character_fraction = &
            REAL(COUNT(var_projector_response_weight(:) > EPSILON(1.0_dp)), KIND=dp)
         projector_density_full_global_abs_avg = SUM(ABS(response_density_full_global(:, :)))
         projector_physical_density_active_abs_avg = SUM(ABS(response_density_physical(:, :)))
         projector_physical_density_gap_abs_avg = &
            SUM(ABS(response_density_full(:, :) - response_density_physical(:, :)))
         projector_physical_density_gap_abs_max = &
            MAXVAL(ABS(response_density_full(:, :) - response_density_physical(:, :)))
         CALL para_env_inter_kp%sum(projector_density_floor_audit_abs_avg)
         CALL para_env_inter_kp%sum(projector_density_floor_audit_gap_abs_avg)
         CALL para_env_inter_kp%sum(projector_physical_density_full_abs_avg)
         CALL para_env_inter_kp%sum(projector_density_full_audit_abs_avg)
         CALL para_env_inter_kp%sum(projector_density_full_global_abs_avg)
         CALL para_env_inter_kp%sum(projector_physical_density_active_abs_avg)
         CALL para_env_inter_kp%sum(projector_physical_density_gap_abs_avg)
         CALL para_env_inter_kp%sum(projector_response_character_abs_avg)
         CALL para_env_inter_kp%sum(projector_response_character_fraction)
         CALL para_env_inter_kp%max(projector_response_character_max)
         CALL para_env_inter_kp%max(projector_physical_density_gap_abs_max)
         projector_density_floor_audit_abs_avg = projector_density_floor_audit_abs_avg/ &
                                                 REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_floor_audit_gap_abs_avg = projector_density_floor_audit_gap_abs_avg/ &
                                                     REAL(MAX(1, ne*nrot), KIND=dp)
         projector_physical_density_full_abs_avg = projector_physical_density_full_abs_avg/ &
                                                   REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_full_audit_abs_avg = projector_density_full_audit_abs_avg/ &
                                                REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_full_global_abs_avg = projector_density_full_global_abs_avg/ &
                                                 REAL(MAX(1, ne*nrot), KIND=dp)
         projector_physical_density_active_abs_avg = projector_physical_density_active_abs_avg/ &
                                                     REAL(MAX(1, ne*nrot), KIND=dp)
         projector_physical_density_gap_abs_avg = projector_physical_density_gap_abs_avg/ &
                                                  REAL(MAX(1, ne*nrot), KIND=dp)
         projector_response_character_abs_avg = projector_response_character_abs_avg/ &
                                                REAL(MAX(1, nrot), KIND=dp)
         projector_response_character_fraction = projector_response_character_fraction/ &
                                                 REAL(MAX(1, nrot), KIND=dp)
         IF (projector_physical_density_full_abs_avg > &
             EPSILON(projector_physical_density_full_abs_avg)) &
            projector_physical_density_active_fraction = &
            projector_physical_density_active_abs_avg/projector_physical_density_full_abs_avg
         exact_density_response_ready = .FALSE.
         IF (projector_physical_shadow_enabled) THEN
            ! The density source for the exact Mermin response must live in the
            ! same fixed-N/tether gauge as the solved energy response.
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                       0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_density, response_density_exact, &
                                                       z_density_trial, ipiv_energy, exact_density_response_ready, &
                                                       energy_gauge_weight)
            IF (exact_density_response_ready) THEN
               projector_physical_density_rhs_abs_avg = &
                  SUM(ABS(energy_cross_density(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
               projector_physical_density_rhs_abs_max = MAXVAL(ABS(energy_cross_density(:, :)))
               projector_physical_density_response_abs_avg = &
                  SUM(ABS(response_density_exact(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
               projector_physical_density_response_abs_max = MAXVAL(ABS(response_density_exact(:, :)))
               DO s = 1, nrot
                  DO r = 1, nrot
                     projected_term = 0.5_dp* &
                                      (DOT_PRODUCT(energy_cross_density(:, r), response_density_exact(:, s)) + &
                                       DOT_PRODUCT(energy_cross_density(:, s), response_density_exact(:, r)))
                     rot_hessian_projector_physical(r, s) = rot_hessian_projector_physical(r, s) + &
                                                            projected_term
                     rot_hessian_projector_physical_diagref(r, s) = &
                        rot_hessian_projector_physical_diagref(r, s) + projected_term
                     projector_physical_density_abs_avg = projector_physical_density_abs_avg + ABS(projected_term)
                     projector_physical_density_delta_max = MAX(projector_physical_density_delta_max, &
                                                                ABS(projected_term))
                     IF (r == s) THEN
                        projector_physical_density_diag_avg = &
                           projector_physical_density_diag_avg + projected_term
                        DO ie = 1, ne
                           dense_term = energy_cross_density(ie, r)*response_density_exact(ie, r)
                           projector_physical_density_diag_abs_sum = &
                              projector_physical_density_diag_abs_sum + ABS(dense_term)
                           IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                              projector_physical_density_low_curv_sum = &
                              projector_physical_density_low_curv_sum + ABS(dense_term)
                        END DO
                     END IF
                  END DO
               END DO
               projector_physical_density_abs_avg = projector_physical_density_abs_avg/ &
                                                    REAL(MAX(1, nrot*nrot), KIND=dp)
               projector_physical_density_diag_avg = projector_physical_density_diag_avg/ &
                                                     REAL(MAX(1, nrot), KIND=dp)
               IF (projector_physical_density_diag_abs_sum > &
                   EPSILON(projector_physical_density_diag_abs_sum)) &
                  projector_physical_density_low_curv_fraction = &
                  projector_physical_density_low_curv_sum/projector_physical_density_diag_abs_sum
            END IF
            exact_density_plateau_response_ready = .FALSE.
            IF (projector_plateau_gap_model_enabled) &
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_plateau, &
                                                          0.0_dp*response_density_plateau, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density_plateau, response_density_plateau_exact, &
                                                          z_density_plateau_trial, ipiv_energy, &
                                                          exact_density_plateau_response_ready, energy_gauge_weight)
         END IF
         exact_density_full_audit_ready = .FALSE.
         exact_density_floor_audit_ready = .FALSE.
         exact_density_full_response_ready = .FALSE.
         projector_density_floor_audit_exact_abs_avg = 0.0_dp
         projector_density_floor_audit_low_curv_fraction = 0.0_dp
         projector_density_floor_audit_diag_abs_sum = 0.0_dp
         projector_density_floor_audit_low_curv_sum = 0.0_dp
         IF (projector_density_full_audit_enabled .AND. projector_density_floor_audit_abs_avg > &
             EPSILON(projector_density_floor_audit_abs_avg)) THEN
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_floor_audit, &
                                                       0.0_dp*response_density_floor_audit, 0.0_dp*grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_density_floor_audit, &
                                                       response_density_floor_audit_exact, &
                                                       z_density_floor_audit_trial, ipiv_energy, &
                                                       exact_density_floor_audit_ready, energy_gauge_weight)
            IF (exact_density_floor_audit_ready) THEN
               projector_density_floor_audit_exact_abs_avg = &
                  SUM(ABS(response_density_floor_audit_exact(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
               DO r = 1, nrot
                  DO ie = 1, ne
                     dense_term = energy_cross_density_floor_audit(ie, r)* &
                                  response_density_floor_audit_exact(ie, r)
                     projector_density_floor_audit_diag_abs_sum = &
                        projector_density_floor_audit_diag_abs_sum + ABS(dense_term)
                     IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                        projector_density_floor_audit_low_curv_sum = &
                        projector_density_floor_audit_low_curv_sum + ABS(dense_term)
                  END DO
               END DO
               IF (projector_density_floor_audit_diag_abs_sum > &
                   EPSILON(projector_density_floor_audit_diag_abs_sum)) &
                  projector_density_floor_audit_low_curv_fraction = &
                  projector_density_floor_audit_low_curv_sum/projector_density_floor_audit_diag_abs_sum
            END IF
         END IF
         IF (projector_physical_shadow_enabled .AND. projector_physical_density_full_abs_avg > &
             EPSILON(projector_physical_density_full_abs_avg)) THEN
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full, &
                                                       0.0_dp*response_density_full, 0.0_dp*grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_density_full, response_density_full_exact, &
                                                       z_density_full_trial, ipiv_energy, &
                                                       exact_density_full_response_ready, energy_gauge_weight)
         END IF
         IF (projector_density_full_audit_enabled .AND. projector_density_full_global_abs_avg > &
             EPSILON(projector_density_full_global_abs_avg)) THEN
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                       0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_density_full_global, &
                                                       response_density_full_global_exact, &
                                                       z_density_full_global_trial, ipiv_energy, &
                                                       exact_density_full_audit_ready, energy_gauge_weight)
            IF (exact_density_full_audit_ready) THEN
               energy_cross_density_full_audit(:, :) = energy_cross_density_full_global(:, :)
               response_density_full_audit_exact(:, :) = response_density_full_global_exact(:, :)
               z_density_full_audit_trial(:) = z_density_full_global_trial(:)
            END IF
         END IF
         density_full_global_history_trust_quality = 1.0_dp
         density_full_global_quality_for_selection = 0.0_dp
         projector_physical_direct_floor_density_quality = 0.0_dp
         projector_physical_direct_floor_density_trust_quality = 1.0_dp
         IF (local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            density_full_global_selected_mermin_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_density_full_global_sel_drop_sum, &
               local_ot_env(1)%schur_projector_density_full_global_sel_measured_sum, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               0.0_dp, 0.0_dp, ot_kp_schur_projector_response_quality_max_ratio)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
               density_full_global_selected_residual_quality = &
                  kpoint_ot_selected_tail_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
               density_full_global_selected_mix_residual_quality = &
                  kpoint_ot_selected_tail_mix_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
               density_full_global_selected_response_scale = 0.25_dp + 0.75_dp* &
                  SQRT(MAX(0.0_dp, MIN(1.0_dp, density_full_global_selected_mix_residual_quality)))
            END IF
         END IF
         exact_density_direct_response_ready = exact_density_response_ready
         energy_cross_density_direct(:, :) = energy_cross_density(:, :)
         response_density_direct_exact(:, :) = response_density_exact(:, :)
         ! Once the accepted full-density response history is mature and good,
         ! keep the Direct model blend history controlled.  Individual trial
         ! line-search probes can miss the local Direct response and should
         ! not switch this correction on/off between probes in the same tail.
         IF ((exact_density_floor_audit_ready .OR. exact_density_full_audit_ready) .AND. &
             local_ot_env(1)%schur_projector_density_full_global_quality_samples > 0 .AND. &
             local_ot_env(1)%schur_projector_density_full_global_drop_sum > &
             ot_kp_schur_projector_density_full_min_drop .AND. &
             local_ot_env(1)%schur_projector_density_full_global_measured_sum > 0.0_dp .AND. &
             local_ot_env(1)%schur_projector_density_full_global_quality_ema >= &
             0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
            density_full_global_history_trust_quality = &
               kpoint_ot_schur_metric_trust_quality( &
               local_ot_env(1)%schur_projector_density_full_global_weighted_trust_ema, 0.0_dp)
            density_full_global_quality_for_selection = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_density_full_global_drop_sum, &
               local_ot_env(1)%schur_projector_density_full_global_measured_sum, &
               local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
               ot_kp_schur_projector_response_min_samples, &
               local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            density_full_global_quality_for_selection = &
               kpoint_ot_floor_bootstrap_history_quality( &
               density_full_global_quality_for_selection, &
               local_ot_env(1)%schur_projector_density_full_global_quality, &
               local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
               ot_kp_schur_projector_response_min_samples)
            projector_physical_direct_floor_density_quality = &
               density_full_global_quality_for_selection
            projector_physical_direct_floor_density_trust_quality = &
               density_full_global_history_trust_quality
            IF (local_ot_env(1)%schur_projector_density_full_global_quality_samples >= &
                ot_kp_schur_projector_response_min_samples) THEN
               projector_physical_direct_floor_density_maturity = &
                  REAL(local_ot_env(1)%schur_projector_density_full_global_quality_samples - &
                       ot_kp_schur_projector_response_min_samples + 1, KIND=dp)/ &
                  REAL(MAX(1, ot_kp_schur_projector_response_min_samples), KIND=dp)
            ELSE
               projector_physical_direct_floor_density_maturity = &
                  0.25_dp*REAL(local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                               KIND=dp)/ &
                  REAL(MAX(1, ot_kp_schur_projector_response_min_samples), KIND=dp)
            END IF
            projector_physical_direct_floor_density_maturity = &
               MIN(1.0_dp, MAX(0.0_dp, projector_physical_direct_floor_density_maturity))
            projector_physical_direct_floor_density_weight = &
               projector_physical_direct_floor_density_maturity* &
               MIN(0.5_dp*ot_kp_schur_projector_trace_active_max_weight, &
                   MAX(0.0_dp, MIN(1.0_dp, density_full_global_quality_for_selection))* &
                   MAX(0.0_dp, MIN(1.0_dp, density_full_global_history_trust_quality)))
            IF (projector_physical_direct_floor_density_weight > &
                EPSILON(projector_physical_direct_floor_density_weight)) THEN
               exact_density_direct_response_ready = .TRUE.
               IF (exact_density_response_ready) THEN
                  energy_cross_density_direct(:, :) = &
                     (1.0_dp - projector_physical_direct_floor_density_weight)* &
                     energy_cross_density(:, :) + &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(energy_cross_density_floor_audit(:, :), &
                           energy_cross_density_full_audit(:, :), &
                           exact_density_floor_audit_ready)
                  response_density_direct_exact(:, :) = &
                     (1.0_dp - projector_physical_direct_floor_density_weight)* &
                     response_density_exact(:, :) + &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(response_density_floor_audit_exact(:, :), &
                           response_density_full_audit_exact(:, :), &
                           exact_density_floor_audit_ready)
               ELSE
                  energy_cross_density_direct(:, :) = &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(energy_cross_density_floor_audit(:, :), &
                           energy_cross_density_full_audit(:, :), &
                           exact_density_floor_audit_ready)
                  response_density_direct_exact(:, :) = &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(response_density_floor_audit_exact(:, :), &
                           response_density_full_audit_exact(:, :), &
                           exact_density_floor_audit_ready)
               END IF
            END IF
         END IF
         IF (projector_physical_direct_floor_density_weight <= &
             EPSILON(projector_physical_direct_floor_density_weight) .AND. &
             exact_density_floor_audit_ready) THEN
            projector_physical_direct_floor_density_bootstrap_weight = &
               kpoint_ot_direct_floor_density_bootstrap_weight( &
               residual_delta, local_ot_env(1)%mermin_ls_accepted_quality_ema, &
               local_ot_env(1)%mermin_ls_accepted_quality_samples, &
               projector_density_floor_audit_abs_avg, projector_density_floor_audit_exact_abs_avg, &
               projector_density_floor_audit_low_curv_fraction, projector_density_full_global_abs_avg)
            IF (projector_physical_direct_floor_density_bootstrap_weight > &
                EPSILON(projector_physical_direct_floor_density_bootstrap_weight)) THEN
               projector_physical_direct_floor_density_quality = &
                  MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                      MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                          local_ot_env(1)%mermin_ls_accepted_quality_ema))
               projector_physical_direct_floor_density_trust_quality = 1.0_dp
               projector_physical_direct_floor_density_maturity = 0.0_dp
               projector_physical_direct_floor_density_weight = &
                  projector_physical_direct_floor_density_bootstrap_weight
            END IF
         END IF
         IF (local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_physical_direct_density_selected_mermin_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_drop_sum, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_measured_sum, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_ema, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               0.0_dp, 0.0_dp, &
               ot_kp_schur_projector_response_quality_max_ratio)
            projector_physical_direct_density_selected_history_quality = &
               projector_physical_direct_density_selected_mermin_quality
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
               projector_physical_direct_density_recent_residual_quality = &
                  kpoint_ot_selected_tail_residual_quality( &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema)
               projector_physical_direct_density_mix_residual_quality = &
                  kpoint_ot_selected_tail_mix_residual_quality( &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema)
               projector_physical_direct_density_selected_history_quality = &
                  projector_physical_direct_density_selected_history_quality* &
                  projector_physical_direct_density_recent_residual_quality
               projector_density_selected_history_weight = &
                  kpoint_ot_direct_density_selected_mix_weight( &
                  residual_delta, projector_physical_direct_density_selected_mermin_quality, &
                  projector_physical_direct_density_mix_residual_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples)
            END IF
         END IF
         IF (local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_density_selected_history_weight = &
               MAX(projector_density_selected_history_weight, &
                   kpoint_ot_direct_density_selected_mix_weight( &
                   residual_delta, density_full_global_selected_mermin_quality, &
                   density_full_global_selected_mix_residual_quality, &
                   local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples))
            projector_physical_direct_density_selected_mermin_quality = &
               MAX(projector_physical_direct_density_selected_mermin_quality, &
                   density_full_global_selected_mermin_quality)
            projector_physical_direct_density_recent_residual_quality = &
               MAX(projector_physical_direct_density_recent_residual_quality, &
                   density_full_global_selected_residual_quality)
            projector_physical_direct_density_mix_residual_quality = &
               MAX(projector_physical_direct_density_mix_residual_quality, &
                   density_full_global_selected_mix_residual_quality)
         END IF
         IF (projector_density_selected_history_weight > &
             EPSILON(projector_density_selected_history_weight)) THEN
            projector_physical_direct_floor_density_weight = &
               MAX(projector_physical_direct_floor_density_weight, &
                   projector_density_selected_history_weight)
            projector_physical_direct_floor_density_quality = &
               MAX(projector_physical_direct_floor_density_quality, &
                   MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                       projector_physical_direct_density_selected_mermin_quality))
            projector_physical_direct_floor_density_trust_quality = &
               MAX(projector_physical_direct_floor_density_trust_quality, &
                   MIN(1.0_dp, MAX(0.0_dp, &
                                   projector_physical_direct_density_mix_residual_quality)))
         END IF
         IF (projector_physical_direct_floor_density_weight > &
             EPSILON(projector_physical_direct_floor_density_weight) .AND. &
             (exact_density_floor_audit_ready .OR. exact_density_full_audit_ready)) THEN
            exact_density_direct_response_ready = .TRUE.
            IF (exact_density_response_ready) THEN
               energy_cross_density_direct(:, :) = &
                  (1.0_dp - projector_physical_direct_floor_density_weight)* &
                  energy_cross_density(:, :) + &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(energy_cross_density_floor_audit(:, :), &
                        energy_cross_density_full_audit(:, :), &
                        exact_density_floor_audit_ready)
               response_density_direct_exact(:, :) = &
                  (1.0_dp - projector_physical_direct_floor_density_weight)* &
                  response_density_exact(:, :) + &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(response_density_floor_audit_exact(:, :), &
                        response_density_full_audit_exact(:, :), &
                        exact_density_floor_audit_ready)
            ELSE
               energy_cross_density_direct(:, :) = &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(energy_cross_density_floor_audit(:, :), &
                        energy_cross_density_full_audit(:, :), &
                        exact_density_floor_audit_ready)
               response_density_direct_exact(:, :) = &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(response_density_floor_audit_exact(:, :), &
                        response_density_full_audit_exact(:, :), &
                        exact_density_floor_audit_ready)
            END IF
         END IF
         IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,16(1X,ES16.8),2(1X,I8))') &
            " OT Schur projector phys direct density mix group weight boot mature qhist tqhist absavg "// &
            "selw selq selrq selmixrq gselq gselrq gscale rchavg rchmax rchfrac samples sels:", &
            target_group, projector_physical_direct_floor_density_weight, &
            projector_physical_direct_floor_density_bootstrap_weight, &
            projector_physical_direct_floor_density_maturity, &
            projector_physical_direct_floor_density_quality, &
            projector_physical_direct_floor_density_trust_quality, &
            projector_density_full_global_abs_avg, &
            projector_density_selected_history_weight, &
            projector_physical_direct_density_selected_mermin_quality, &
            projector_physical_direct_density_recent_residual_quality, &
            projector_physical_direct_density_mix_residual_quality, &
            density_full_global_selected_mermin_quality, &
            density_full_global_selected_residual_quality, &
            density_full_global_selected_response_scale, &
            projector_response_character_abs_avg, &
            projector_response_character_max, &
            projector_response_character_fraction, &
            local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
            local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples
         IF (exact_density_direct_response_ready) THEN
            DO s = 1, nrot
               DO r = 1, nrot
                  projected_term = 0.5_dp* &
                                   (DOT_PRODUCT(energy_cross_density_direct(:, r), &
                                                response_density_direct_exact(:, s)) + &
                                    DOT_PRODUCT(energy_cross_density_direct(:, s), &
                                                response_density_direct_exact(:, r)))
                  IF (exact_density_response_ready) &
                     projected_term = projected_term - 0.5_dp* &
                                      (DOT_PRODUCT(energy_cross_density(:, r), response_density_exact(:, s)) + &
                                       DOT_PRODUCT(energy_cross_density(:, s), response_density_exact(:, r)))
                  rot_hessian_projector_physical(r, s) = &
                     rot_hessian_projector_physical(r, s) + projected_term
                  rot_hessian_projector_physical_diagref(r, s) = &
                     rot_hessian_projector_physical_diagref(r, s) + projected_term
               END DO
            END DO
         END IF
         ! Rebuild the off-diagonal projector-response active block with the
         ! same history-qualified physical pair weights used by the Direct
         ! Schur model below.  The early Fermi-window split is a conservative
         ! bootstrap; once density-response history is mature, occupied/virtual
         ! occupation-gap pairs carry physical response and should not remain
         ! lumped into the inactive projector-gauge bucket.
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.0_dp
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.0_dp
         DO s = 1, nrot
            DO r = 1, nrot
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_physical_active_weight_r = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                           var_projector_active_weight(r), &
                                                           var_occ_gap_weight(r), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(r))
               projector_physical_active_weight_s = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(s), &
                                                           var_projector_active_weight(s), &
                                                           var_occ_gap_weight(s), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(s))
               projector_offdiag_active_weight = 0.0_dp
               IF (var_projector_weight(r) + var_projector_weight(s) > &
                   EPSILON(projector_offdiag_active_weight)) THEN
                  projector_offdiag_active_weight = &
                     (projector_physical_active_weight_r + projector_physical_active_weight_s)/ &
                     MAX(var_projector_weight(r) + var_projector_weight(s), EPSILON(1.0_dp))
                  projector_offdiag_active_weight = &
                     MIN(1.0_dp, MAX(0.0_dp, projector_offdiag_active_weight))
               END IF
               rot_hessian_projector_physical_offdiag_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag(r, s)
               rot_hessian_projector_physical_offdiag_plateau_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag_plateau(r, s)
            END DO
         END DO
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.5_dp* &
                                                               (rot_hessian_projector_physical_offdiag_active(:, :) + &
                                                                TRANSPOSE(rot_hessian_projector_physical_offdiag_active(:, :)))
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.5_dp* &
                                                                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) + &
                                                             TRANSPOSE(rot_hessian_projector_physical_offdiag_plateau_active(:, :)))
         projector_physical_offdiag_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_inactive_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_inactive_abs_avg = &
            SUM(ABS((rot_hessian_projector_physical_offdiag_plateau(:, :) - &
                     rot_hessian_projector_physical_offdiag(:, :)) - &
                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                     rot_hessian_projector_physical_offdiag_active(:, :))))
         ! Keep the validated full physical trace backbone for cross-channel
         ! fixed-N terms, but filter the same-channel non-covariant residual
         ! with the active occupation-window pair weight.  This keeps genuine
         ! Fermi-window curvature while avoiding hardening local gauge-noise
         ! modes in the Direct finite-response correction.
         rot_hessian_projector_physical_active(:, :) = rot_hessian_projector_physical(:, :)
         DO s = 1, nrot
            DO r = 1, nrot
               projector_physical_active_weight_r = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                           var_projector_active_weight(r), &
                                                           var_occ_gap_weight(r), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(r))
               projector_physical_active_weight_s = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(s), &
                                                           var_projector_active_weight(s), &
                                                           var_occ_gap_weight(s), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(s))
               projector_physical_covariant_delta = &
                  -0.5_dp*(var_projector_weight(r) + var_projector_weight(s))*rot_hessian(r, s)
               projector_physical_active_covariant_delta = &
                  -0.5_dp*(projector_physical_active_weight_r + &
                           projector_physical_active_weight_s)*rot_hessian(r, s)
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_offdiag_active_weight = 0.0_dp
               IF (var_projector_weight(r) + var_projector_weight(s) > &
                   EPSILON(projector_offdiag_active_weight)) THEN
                  projector_offdiag_active_weight = &
                     (projector_physical_active_weight_r + projector_physical_active_weight_s)/ &
                     MAX(var_projector_weight(r) + var_projector_weight(s), EPSILON(1.0_dp))
                  projector_offdiag_active_weight = &
                     MIN(1.0_dp, MAX(0.0_dp, projector_offdiag_active_weight))
               END IF
               projector_physical_residual_delta = &
                  rot_hessian_projector_physical(r, s) - rot_hessian(r, s) - &
                  projector_physical_covariant_delta
               rot_hessian_projector_physical_active(r, s) = &
                  rot_hessian(r, s) + projector_physical_active_covariant_delta + &
                  projector_offdiag_active_weight*projector_physical_residual_delta
            END DO
         END DO
         DO r = 1, nrot
            projector_hessian_diag_avg = projector_hessian_diag_avg + rot_hessian_projector(r, r)
            projector_hessian_delta_diag_avg = projector_hessian_delta_diag_avg + &
                                               rot_hessian_projector(r, r) - rot_hessian(r, r)
            projector_physical_diag_avg = projector_physical_diag_avg + rot_hessian_projector_physical(r, r)
            projector_physical_delta_diag_avg = projector_physical_delta_diag_avg + &
                                                rot_hessian_projector_physical(r, r) - rot_hessian(r, r)
            projector_physical_offdiag_diag_avg = projector_physical_offdiag_diag_avg + &
                                                  rot_hessian_projector_physical_offdiag(r, r)
            projector_physical_offdiag_plateau_diag_avg = projector_physical_offdiag_plateau_diag_avg + &
                                                          rot_hessian_projector_physical_offdiag_plateau(r, r)
            projector_physical_offdiag_plateau_gap_diag_avg = &
               projector_physical_offdiag_plateau_gap_diag_avg + &
               rot_hessian_projector_physical_offdiag_plateau(r, r) - &
               rot_hessian_projector_physical_offdiag(r, r)
            projector_physical_diagref_diag_avg = projector_physical_diagref_diag_avg + &
                                                  rot_hessian_projector_physical_diagref(r, r)
            projector_physical_diagref_delta_diag_avg = projector_physical_diagref_delta_diag_avg + &
                                                        rot_hessian_projector_physical_diagref(r, r) - rot_hessian(r, r)
            projector_physical_diagref_gap_diag_avg = projector_physical_diagref_gap_diag_avg + &
                                                 rot_hessian_projector_physical_diagref(r, r) - rot_hessian_projector_physical(r, r)
            projector_physical_active_weight_r = &
               kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                        var_projector_active_weight(r), &
                                                        var_occ_gap_weight(r), &
                                                        projector_physical_direct_floor_density_weight, &
                                                        var_projector_response_weight(r))
            projector_physical_covariant_delta = -var_projector_weight(r)*rot_hessian(r, r)
            projector_physical_active_covariant_delta = -projector_physical_active_weight_r*rot_hessian(r, r)
            projector_physical_residual_delta = rot_hessian_projector_physical(r, r) - rot_hessian(r, r) - &
                                                projector_physical_covariant_delta
            projector_physical_covariant_diag_avg = projector_physical_covariant_diag_avg + &
                                                    projector_physical_covariant_delta
            projector_physical_active_covariant_diag_avg = projector_physical_active_covariant_diag_avg + &
                                                           projector_physical_active_covariant_delta
            projector_physical_residual_diag_avg = projector_physical_residual_diag_avg + &
                                                   projector_physical_residual_delta
            IF (var_projector_weight(r) > EPSILON(var_projector_weight(r))) THEN
               projector_physical_active_weight_avg = projector_physical_active_weight_avg + &
                                                      projector_physical_active_weight_r/var_projector_weight(r)
               projector_physical_active_weight_max = MAX(projector_physical_active_weight_max, &
                                                          projector_physical_active_weight_r/var_projector_weight(r))
               IF (projector_physical_active_weight_r > EPSILON(projector_physical_active_weight_r)) &
                  projector_physical_active_weight_fraction = projector_physical_active_weight_fraction + 1.0_dp
            END IF
            DO s = 1, nrot
               projector_physical_active_weight_r = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                           var_projector_active_weight(r), &
                                                           var_occ_gap_weight(r), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(r))
               projector_physical_active_weight_s = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(s), &
                                                           var_projector_active_weight(s), &
                                                           var_occ_gap_weight(s), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(s))
               projector_physical_covariant_delta = -0.5_dp*(var_projector_weight(r) + &
                                                             var_projector_weight(s))*rot_hessian(r, s)
               projector_physical_active_covariant_delta = &
                  -0.5_dp*(projector_physical_active_weight_r + &
                           projector_physical_active_weight_s)*rot_hessian(r, s)
               projector_physical_residual_delta = rot_hessian_projector_physical(r, s) - rot_hessian(r, s) - &
                                                   projector_physical_covariant_delta
               projector_hessian_abs_avg = projector_hessian_abs_avg + &
                                           ABS(rot_hessian_projector(r, s) - rot_hessian(r, s))
               projector_hessian_delta_max = MAX(projector_hessian_delta_max, &
                                                 ABS(rot_hessian_projector(r, s) - rot_hessian(r, s)))
               projector_physical_abs_avg = projector_physical_abs_avg + &
                                            ABS(rot_hessian_projector_physical(r, s) - rot_hessian(r, s))
               projector_physical_delta_max = MAX(projector_physical_delta_max, &
                                                  ABS(rot_hessian_projector_physical(r, s) - rot_hessian(r, s)))
               projector_physical_offdiag_abs_avg = projector_physical_offdiag_abs_avg + &
                                                    ABS(rot_hessian_projector_physical_offdiag(r, s))
               projector_physical_offdiag_delta_max = MAX(projector_physical_offdiag_delta_max, &
                                                          ABS(rot_hessian_projector_physical_offdiag(r, s)))
               projector_physical_offdiag_plateau_abs_avg = &
                  projector_physical_offdiag_plateau_abs_avg + &
                  ABS(rot_hessian_projector_physical_offdiag_plateau(r, s))
               projector_physical_offdiag_plateau_delta_max = &
                  MAX(projector_physical_offdiag_plateau_delta_max, &
                      ABS(rot_hessian_projector_physical_offdiag_plateau(r, s)))
               projector_physical_offdiag_plateau_gap_abs_avg = &
                  projector_physical_offdiag_plateau_gap_abs_avg + &
                  ABS(rot_hessian_projector_physical_offdiag_plateau(r, s) - &
                      rot_hessian_projector_physical_offdiag(r, s))
               projector_physical_offdiag_plateau_gap_delta_max = &
                  MAX(projector_physical_offdiag_plateau_gap_delta_max, &
                      ABS(rot_hessian_projector_physical_offdiag_plateau(r, s) - &
                          rot_hessian_projector_physical_offdiag(r, s)))
               projector_physical_diagref_abs_avg = projector_physical_diagref_abs_avg + &
                                                    ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian(r, s))
               projector_physical_diagref_delta_max = MAX(projector_physical_diagref_delta_max, &
                                                          ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian(r, s)))
               projector_physical_diagref_gap_abs_avg = projector_physical_diagref_gap_abs_avg + &
                                            ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian_projector_physical(r, s))
               projector_physical_diagref_gap_delta_max = MAX(projector_physical_diagref_gap_delta_max, &
                                           ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian_projector_physical(r, s)))
               projector_physical_covariant_abs_avg = projector_physical_covariant_abs_avg + &
                                                      ABS(projector_physical_covariant_delta)
               projector_physical_covariant_delta_max = MAX(projector_physical_covariant_delta_max, &
                                                            ABS(projector_physical_covariant_delta))
               projector_physical_active_covariant_abs_avg = projector_physical_active_covariant_abs_avg + &
                                                             ABS(projector_physical_active_covariant_delta)
               projector_physical_active_covariant_delta_max = &
                  MAX(projector_physical_active_covariant_delta_max, &
                      ABS(projector_physical_active_covariant_delta))
               projector_physical_residual_abs_avg = projector_physical_residual_abs_avg + &
                                                     ABS(projector_physical_residual_delta)
               projector_physical_residual_delta_max = MAX(projector_physical_residual_delta_max, &
                                                           ABS(projector_physical_residual_delta))
               projector_gauge_abs_avg = projector_gauge_abs_avg + &
                                         ABS(rot_hessian_projector(r, s) - rot_hessian_projector_physical(r, s))
               projector_gauge_delta_max = MAX(projector_gauge_delta_max, &
                                               ABS(rot_hessian_projector(r, s) - rot_hessian_projector_physical(r, s)))
            END DO
         END DO
         projector_hessian_diag_avg = projector_hessian_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_hessian_delta_diag_avg = projector_hessian_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_hessian_abs_avg = projector_hessian_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_diag_avg = projector_physical_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_delta_diag_avg = projector_physical_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_abs_avg = projector_physical_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_diag_avg = &
            projector_physical_offdiag_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_offdiag_abs_avg = &
            projector_physical_offdiag_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_active_abs_avg = &
            projector_physical_offdiag_active_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_inactive_abs_avg = &
            projector_physical_offdiag_inactive_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_diag_avg = &
            projector_physical_offdiag_plateau_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_offdiag_plateau_abs_avg = &
            projector_physical_offdiag_plateau_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_diag_avg = &
            projector_physical_offdiag_plateau_gap_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_abs_avg = &
            projector_physical_offdiag_plateau_gap_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_active_abs_avg = &
            projector_physical_offdiag_plateau_gap_active_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_inactive_abs_avg = &
            projector_physical_offdiag_plateau_gap_inactive_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         IF (projector_physical_abs_avg > EPSILON(projector_physical_abs_avg)) &
            projector_physical_offdiag_abs_ratio = &
            projector_physical_offdiag_abs_avg/projector_physical_abs_avg
         projector_physical_diagref_diag_avg = &
            projector_physical_diagref_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_diagref_delta_diag_avg = &
            projector_physical_diagref_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_diagref_gap_diag_avg = &
            projector_physical_diagref_gap_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_diagref_abs_avg = &
            projector_physical_diagref_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_diagref_gap_abs_avg = &
            projector_physical_diagref_gap_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_diagref_trace_balance = MAX(0.0_dp, -projector_physical_diagref_delta_diag_avg)
         projector_physical_covariant_diag_avg = &
            projector_physical_covariant_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_covariant_abs_avg = &
            projector_physical_covariant_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_active_covariant_diag_avg = &
            projector_physical_active_covariant_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_active_covariant_abs_avg = &
            projector_physical_active_covariant_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_active_trace_balance = MAX(0.0_dp, -projector_physical_active_covariant_diag_avg)
         projector_physical_active_weight_avg = &
            projector_physical_active_weight_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_active_weight_fraction = &
            projector_physical_active_weight_fraction/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_residual_diag_avg = &
            projector_physical_residual_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_residual_abs_avg = &
            projector_physical_residual_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_trace_balance = MAX(0.0_dp, -projector_physical_delta_diag_avg)
         projector_physical_direct_diag_balance = projector_physical_delta_diag_avg - &
                                                  projector_physical_covariant_diag_avg - &
                                                  projector_physical_residual_diag_avg
         projector_gauge_abs_avg = projector_gauge_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         curv_projection_sum = SUM(curv)
         CALL para_env_inter_kp%sum(curv_projection_sum)
         occ_curv_projection_sum = SUM(occ_curv)
         CALL para_env_inter_kp%sum(occ_curv_projection_sum)
         ! The split candidate follows the same diagonal/spectral projector blend as
         ! the finite complex rotation gradient: occupation curvature sees the
         ! finite projector response, while the channel-local tether still sees the
         ! full Rayleigh diagonal it anchors.
         response_coupled(:, :) = response(:, :)
         response_split(:, :) = 0.0_dp
         DO r = 1, nrot
            DO ie = 1, ne
               IF (curv(ie) > EPSILON(curv(ie))) &
                  response_split(ie, r) = (occ_curv(ie)*response_occ(ie, r) + &
                                           tether_curv(ie)*response(ie, r))/curv(ie)
            END DO
         END DO
         DO r = 1, nrot
            response_shift = DOT_PRODUCT(curv, response_coupled(:, r))
            CALL para_env_inter_kp%sum(response_shift)
            IF (curv_projection_sum > EPSILON(curv_projection_sum)) &
               response_coupled(:, r) = response_coupled(:, r) - response_shift/curv_projection_sum
            DO ie = 1, ne
               IF (curv(ie) <= EPSILON(curv(ie))) response_coupled(ie, r) = 0.0_dp
            END DO
            CALL project_kpoint_ot_schur_response(response_split(:, r), occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
         END DO
         projector_response_gap_avg = 0.0_dp
         projector_response_gap_max = 0.0_dp
         physical_response_gap_avg = 0.0_dp
         physical_response_gap_max = 0.0_dp
         DO r = 1, nrot
            projector_response_gap_norm = DOT_PRODUCT(occ_curv(:)*(response_occ(:, r) - response(:, r)), &
                                                      response_occ(:, r) - response(:, r))
            CALL para_env_inter_kp%sum(projector_response_gap_norm)
            IF (occ_curv_projection_sum > EPSILON(occ_curv_projection_sum)) &
               projector_response_gap_avg = projector_response_gap_avg + &
                                            SQRT(MAX(0.0_dp, projector_response_gap_norm/occ_curv_projection_sum))
            projector_response_gap_max = MAX(projector_response_gap_max, &
                                             MAXVAL(ABS(response_occ(:, r) - response(:, r))))
            physical_response_gap_norm = DOT_PRODUCT(occ_curv(:)*(response_occ_physical(:, r) - response_occ(:, r)), &
                                                     response_occ_physical(:, r) - response_occ(:, r))
            CALL para_env_inter_kp%sum(physical_response_gap_norm)
            IF (occ_curv_projection_sum > EPSILON(occ_curv_projection_sum)) &
               physical_response_gap_avg = physical_response_gap_avg + &
                                           SQRT(MAX(0.0_dp, physical_response_gap_norm/occ_curv_projection_sum))
            physical_response_gap_max = MAX(physical_response_gap_max, &
                                            MAXVAL(ABS(response_occ_physical(:, r) - response_occ(:, r))))
         END DO
         projector_response_gap_avg = projector_response_gap_avg/REAL(MAX(1, nrot), KIND=dp)
         physical_response_gap_avg = physical_response_gap_avg/REAL(MAX(1, nrot), KIND=dp)
         CALL para_env_inter_kp%max(projector_response_gap_max)
         CALL para_env_inter_kp%max(physical_response_gap_max)
         density_plateau_exact_gap_avg = 0.0_dp
         density_plateau_exact_gap_max = 0.0_dp
         density_plateau_raw_gap_avg = 0.0_dp
         density_plateau_raw_gap_max = 0.0_dp
         IF (exact_density_response_ready .AND. exact_density_full_response_ready) THEN
            DO r = 1, nrot
               physical_response_gap_norm = &
                  DOT_PRODUCT(occ_curv(:)*(response_density_full(:, r) - response_density_physical(:, r)), &
                              response_density_full(:, r) - response_density_physical(:, r))
               CALL para_env_inter_kp%sum(physical_response_gap_norm)
               IF (occ_curv_projection_sum > EPSILON(occ_curv_projection_sum)) &
                  density_plateau_raw_gap_avg = density_plateau_raw_gap_avg + &
                                                SQRT(MAX(0.0_dp, physical_response_gap_norm/occ_curv_projection_sum))
               density_plateau_raw_gap_max = MAX(density_plateau_raw_gap_max, &
                                                 MAXVAL(ABS(response_density_full(:, r) - &
                                                            response_density_physical(:, r))))
               physical_response_gap_norm = &
                  DOT_PRODUCT(curv(:)*(response_density_full_exact(:, r) - response_density_exact(:, r)), &
                              response_density_full_exact(:, r) - response_density_exact(:, r))
               CALL para_env_inter_kp%sum(physical_response_gap_norm)
               IF (curv_projection_sum > EPSILON(curv_projection_sum)) &
                  density_plateau_exact_gap_avg = density_plateau_exact_gap_avg + &
                                                  SQRT(MAX(0.0_dp, physical_response_gap_norm/curv_projection_sum))
               density_plateau_exact_gap_max = MAX(density_plateau_exact_gap_max, &
                                                   MAXVAL(ABS(response_density_full_exact(:, r) - &
                                                              response_density_exact(:, r))))
            END DO
            density_plateau_raw_gap_avg = density_plateau_raw_gap_avg/REAL(MAX(1, nrot), KIND=dp)
            density_plateau_exact_gap_avg = density_plateau_exact_gap_avg/REAL(MAX(1, nrot), KIND=dp)
            CALL para_env_inter_kp%max(density_plateau_raw_gap_max)
            CALL para_env_inter_kp%max(density_plateau_exact_gap_max)
         END IF
         CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_occ, response, grad_e, &
                                                    channel_nmo, e_offset, energy_hessian, energy_cross, &
                                                    response_exact, z_exact_trial, ipiv_energy, &
                                                    exact_energy_model_ready, energy_gauge_weight)
         exact_physical_response_ready = .FALSE.
         IF (exact_energy_model_ready .AND. projector_physical_shadow_enabled) &
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_occ_physical, response, &
                                                       grad_e, channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_physical, response_exact_physical, &
                                                       z_exact_physical_trial, ipiv_energy, &
                                                       exact_physical_response_ready, energy_gauge_weight)
         IF (exact_physical_response_ready) &
            CALL project_kpoint_ot_schur_response(z_exact_physical_trial, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
         IF (exact_energy_model_ready) &
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response, response, grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, energy_cross_raw, &
                                                       response_exact_raw, z_exact_raw_trial, ipiv_energy, &
                                                       exact_energy_model_ready, energy_gauge_weight)
         IF (exact_energy_model_ready) THEN
            CALL project_kpoint_ot_schur_response(z_exact_trial, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
            CALL project_kpoint_ot_schur_response(z_exact_raw_trial, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
            DO r = 1, nrot
               exact_response_diag_avg = exact_response_diag_avg + &
                                         DOT_PRODUCT(energy_cross(:, r), response_exact(:, r))
               response_mixed_diag_avg = response_mixed_diag_avg + &
                                         0.5_dp*(DOT_PRODUCT(energy_cross(:, r), response_exact_raw(:, r)) + &
                                                 DOT_PRODUCT(energy_cross_raw(:, r), response_exact(:, r)))
            END DO
            exact_response_diag_avg = exact_response_diag_avg/REAL(MAX(1, nrot), KIND=dp)
            response_mixed_diag_avg = response_mixed_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         END IF

         IF (sigma > EPSILON(sigma)) THEN
            response_trust_base = schur_response_trust_factor*kpoint_ot_fermi_window_anchor(sigma)
            response_abs_trust = ot_kp_fermi_window_outer_factor*sigma
            DO local_channel = 1, nchannels
               IF (channel_nmo(local_channel) <= 0) CYCLE
               IF (local_ot_env(local_channel)%ener_x_trust_radius <= 0.0_dp) CYCLE
               density_projector_trust_scale = &
                  MIN(density_projector_trust_scale, local_ot_env(local_channel)%ener_x_trust_scale)
            END DO
            density_projector_trust_scale = MIN(1.0_dp, MAX(0.0_dp, density_projector_trust_scale))
            IF (density_projector_control_delta > 0.0_dp .AND. &
                ot_kp_canonical_density_max_weight > 0.0_dp) THEN
               density_projector_fraction = &
                  kpoint_ot_canonical_density_projector_weight(density_projector_control_delta)/ &
                  ot_kp_canonical_density_max_weight
               density_projector_fraction = density_projector_trust_scale* &
                                            MIN(1.0_dp, MAX(0.0_dp, density_projector_fraction))
               density_projector_response_trust_fraction = density_projector_fraction
               ! The density blend may be active early; only let it tighten the
               ! Schur response trust when the residual has reached the coupled tail.
               IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) &
                  density_projector_response_trust_fraction = density_projector_response_trust_fraction* &
                                                             MIN(1.0_dp, &
                                                                 ot_kp_schur_projector_coupled_tail_delta/ &
                                                                 MAX(residual_delta, EPSILON(1.0_dp)))
               response_trust_factor = MAX(ot_kp_schur_response_trust_min_factor, &
                                           1.0_dp - density_projector_response_trust_fraction)
            END IF
            response_trust = response_trust_base*response_trust_factor
         END IF
         solved = .FALSE.
         trust_rejected = .FALSE.
         schur_used_attempt = 0
         selected_flavor = 0
         ! Evaluate the split fixed-N/tether Schur model under HIGH audit, or
         ! after accepted Mermin line-search drops validate the model quality.
         split_candidate_enabled = new_search_point .AND. local_ot_env(1)%schur_split_candidate_enabled
         constrained_candidate_enabled = new_search_point .AND. &
                                         local_ot_env(1)%schur_constrained_candidate_enabled
         split_candidate_diagnostic = split_candidate_enabled .OR. constrained_candidate_enabled
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            split_quality_for_calibration = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_split_drop_sum, &
                                               local_ot_env(1)%schur_split_measured_sum, &
                                               local_ot_env(1)%schur_split_quality_ema, &
                                               local_ot_env(1)%schur_split_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, &
                                               local_ot_env(1)%schur_split_quality_ema, &
                                               ot_kp_schur_calibration_floor, 1.0_dp)
            split_quality_for_calibration = MAX(split_quality_for_calibration, &
                                                MAX(ot_kp_schur_calibration_floor, &
                                                    MIN(1.0_dp, local_ot_env(1)%schur_split_quality_ema)))
         ELSE IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            ! Bootstrap Split curvature from the accepted dense/coupled Mermin
            ! model quality.  Otherwise Split candidates that are already known
            ! to be over-optimistic can be rejected by the OT z.z=g.z scale gate
            ! before they ever collect their own calibration samples.
            split_quality_for_calibration = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_coupled_calibrated_drop_sum, &
                                               local_ot_env(1)%schur_coupled_measured_sum, &
                                               local_ot_env(1)%schur_coupled_calibrated_quality_ema, &
                                               local_ot_env(1)%schur_coupled_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, &
                                               local_ot_env(1)%schur_coupled_calibrated_quality_ema, &
                                               ot_kp_schur_calibration_floor, 1.0_dp)
            split_quality_for_calibration = MAX(split_quality_for_calibration, &
                                                MAX(ot_kp_schur_calibration_floor, &
                                                    MIN(1.0_dp, &
                                                        local_ot_env(1)%schur_coupled_calibrated_quality_ema)))
         END IF
         IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            dense_quality_for_selection = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_coupled_calibrated_drop_sum, &
                                               local_ot_env(1)%schur_coupled_measured_sum, &
                                               local_ot_env(1)%schur_coupled_calibrated_quality_ema, &
                                               local_ot_env(1)%schur_coupled_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, 1.0_dp, &
                                               ot_kp_schur_calibrated_quality_min_ratio, &
                                               ot_kp_schur_calibrated_quality_max_ratio)
            dense_quality_for_selection = MAX(dense_quality_for_selection, &
                                              MAX(ot_kp_schur_calibrated_quality_min_ratio, &
                                                  MIN(ot_kp_schur_calibrated_quality_max_ratio, &
                                                      local_ot_env(1)%schur_coupled_calibrated_quality_ema)))
         END IF
         projector_mode_history_quality = dense_quality_for_selection
         IF (local_ot_env(1)%schur_projector_mode_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            projector_mode_history_quality = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_mode_drop_sum, &
                                               local_ot_env(1)%schur_projector_mode_measured_sum, &
                                               local_ot_env(1)%schur_projector_mode_quality_ema, &
                                               local_ot_env(1)%schur_projector_mode_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, &
                                               dense_quality_for_selection, &
                                               ot_kp_schur_calibrated_quality_min_ratio, &
                                               ot_kp_schur_calibrated_quality_max_ratio)
         END IF
         IF (local_ot_env(1)%schur_projector_mode_drop_sum > &
             EPSILON(local_ot_env(1)%schur_projector_mode_drop_sum)) &
            projector_mode_history_response_ratio = &
            local_ot_env(1)%schur_projector_mode_response_drop_sum/ &
            local_ot_env(1)%schur_projector_mode_drop_sum
         projector_mode_history_response_negative = &
            local_ot_env(1)%schur_projector_mode_response_negative_ema
         projector_physical_direct_spectral_quality_for_selection = &
            kpoint_ot_schur_history_quality( &
            local_ot_env(1)%schur_projector_spectral_selected_drop_sum, &
            local_ot_env(1)%schur_projector_spectral_selected_measured_sum, &
            local_ot_env(1)%schur_projector_spectral_selected_quality_ema, &
            local_ot_env(1)%schur_projector_spectral_selected_quality_samples, &
            ot_kp_schur_projector_response_min_samples, &
            0.0_dp, &
            ot_kp_schur_projector_response_quality_min_ratio, &
            ot_kp_schur_projector_response_quality_max_ratio)
         projector_physical_direct_spectral_shadow_quality_for_probe = &
            kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_spectral_drop_sum, &
                                            local_ot_env(1)%schur_projector_spectral_measured_sum, &
                                            local_ot_env(1)%schur_projector_spectral_quality_ema, &
                                            local_ot_env(1)%schur_projector_spectral_quality_samples, &
                                            ot_kp_schur_projector_response_min_samples, &
                                            0.0_dp, &
                                            ot_kp_schur_projector_response_quality_min_ratio, &
                                            ot_kp_schur_projector_response_quality_max_ratio)
         projector_response_quality_for_selection = &
            kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_response_drop_sum, &
                                            local_ot_env(1)%schur_projector_response_measured_sum, &
                                            local_ot_env(1)%schur_projector_response_quality_ema, &
                                            local_ot_env(1)%schur_projector_response_quality_samples, &
                                            ot_kp_schur_projector_response_min_samples, &
                                            0.0_dp, &
                                            ot_kp_schur_projector_response_quality_min_ratio, &
                                            ot_kp_schur_projector_response_underpredict_max_ratio)
         IF (local_ot_env(1)%schur_projector_response_selected_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_response_quality_for_selection = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_response_selected_drop_sum, &
               local_ot_env(1)%schur_projector_response_selected_measured_sum, &
               local_ot_env(1)%schur_projector_response_selected_quality_ema, &
               local_ot_env(1)%schur_projector_response_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               projector_response_quality_for_selection, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_underpredict_max_ratio)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
               projector_response_quality_for_selection = projector_response_quality_for_selection* &
                                                          MAX(0.0_dp, MIN(1.0_dp, &
                                                            local_ot_env(1)%schur_projector_response_selected_residual_quality_ema))
         END IF
         projector_diagref_quality_for_selection = &
            kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_diagref_drop_sum, &
                                            local_ot_env(1)%schur_projector_diagref_measured_sum, &
                                            local_ot_env(1)%schur_projector_diagref_quality_ema, &
                                            local_ot_env(1)%schur_projector_diagref_quality_samples, &
                                            ot_kp_schur_projector_response_min_samples, &
                                            0.0_dp, &
                                            ot_kp_schur_projector_response_quality_min_ratio, &
                                            ot_kp_schur_projector_response_quality_max_ratio)
         projector_physical_quality_for_selection = &
            kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_physical_drop_sum, &
                                            local_ot_env(1)%schur_projector_physical_measured_sum, &
                                            local_ot_env(1)%schur_projector_physical_quality_ema, &
                                            local_ot_env(1)%schur_projector_physical_quality_samples, &
                                            ot_kp_schur_projector_response_min_samples, &
                                            0.0_dp, &
                                            ot_kp_schur_projector_response_quality_min_ratio, &
                                            ot_kp_schur_projector_response_quality_max_ratio)
         projector_physical_trace_split_quality = &
            kpoint_ot_trace_split_history_quality( &
            local_ot_env(1)%schur_projector_physical_trace_actual_diag_ema, &
            local_ot_env(1)%schur_projector_physical_trace_actual_free_ema, &
            local_ot_env(1)%schur_projector_physical_trace_actual_diag_quality_ema, &
            local_ot_env(1)%schur_projector_physical_trace_actual_free_quality_ema, &
            local_ot_env(1)%schur_projector_physical_quality_samples, &
            projector_physical_quality_for_selection)
         projector_physical_trace_invariant_quality_for_selection = &
            kpoint_ot_trace_invariant_history_quality( &
            local_ot_env(1)%schur_projector_physical_trace_invariant_ema, &
            local_ot_env(1)%schur_projector_physical_trace_invariant_quality_ema, &
            local_ot_env(1)%schur_projector_physical_trace_invariant_diag_ema, &
            local_ot_env(1)%schur_projector_physical_trace_invariant_free_ema, &
            local_ot_env(1)%schur_projector_physical_trace_invariant_diag_quality_ema, &
            local_ot_env(1)%schur_projector_physical_trace_invariant_free_quality_ema, &
            local_ot_env(1)%schur_projector_physical_quality_samples, &
            projector_physical_trace_split_quality)
         projector_plateau_gap_quality_for_selection = 1.0_dp
         IF (local_ot_env(1)%schur_projector_plateau_gap_quality_samples >= &
             ot_kp_schur_projector_response_min_samples) &
            projector_plateau_gap_quality_for_selection = &
            kpoint_ot_schur_history_quality( &
            local_ot_env(1)%schur_projector_plateau_gap_drop_sum, &
            local_ot_env(1)%schur_projector_plateau_gap_measured_sum, &
            local_ot_env(1)%schur_projector_plateau_gap_quality_ema, &
            local_ot_env(1)%schur_projector_plateau_gap_quality_samples, &
            ot_kp_schur_projector_response_min_samples, &
            1.0_dp, &
            ot_kp_schur_projector_response_quality_min_ratio, &
            ot_kp_schur_projector_response_quality_max_ratio)
         projector_physical_direct_quality_for_selection = projector_physical_trace_invariant_quality_for_selection
         projector_physical_direct_history_quality = 1.0_dp
         projector_physical_direct_history_scale = 1.0_dp
         projector_physical_direct_history_growth_scale = 1.0_dp
         IF (local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_physical_direct_tail_history_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_physical_direct_selected_drop_sum, &
               local_ot_env(1)%schur_projector_physical_direct_selected_measured_sum, &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema, &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               0.0_dp, 0.0_dp, &
               ot_kp_schur_projector_response_quality_max_ratio)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
               projector_physical_direct_tail_residual_quality = &
               kpoint_ot_selected_tail_residual_quality( &
               local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality, &
               local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
               projector_physical_direct_tail_history_quality = &
               projector_physical_direct_tail_history_quality* &
               projector_physical_direct_tail_residual_quality
            projector_physical_direct_tail_history_scale = &
               SQRT(MIN(1.0_dp, projector_physical_direct_tail_history_quality))
            projector_physical_direct_quality_for_selection = &
               kpoint_ot_direct_selected_probe_quality( &
               projector_physical_trace_invariant_quality_for_selection, &
               projector_physical_direct_tail_history_quality, &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples)
            projector_physical_direct_history_quality = &
               kpoint_ot_direct_history_quality( &
               local_ot_env(1)%schur_projector_physical_direct_selected_drop_sum, &
               local_ot_env(1)%schur_projector_physical_direct_selected_measured_sum, &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema, &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
               projector_physical_direct_history_quality = &
               projector_physical_direct_history_quality* &
               MAX(0.0_dp, MIN(1.0_dp, &
                               local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema))
            projector_physical_direct_history_scale = &
               kpoint_ot_direct_history_step_scale( &
               projector_physical_direct_history_quality, &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples)
            projector_physical_direct_history_growth_scale = &
               kpoint_ot_direct_history_growth_scale( &
               projector_physical_direct_history_quality, &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples)
            projector_physical_direct_history_scale = &
               projector_physical_direct_history_scale* &
               projector_physical_direct_history_growth_scale
         END IF
         IF (projector_physical_direct_shadow_quality_for_promotion > &
             EPSILON(projector_physical_direct_shadow_quality_for_promotion)) THEN
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples >= &
                ot_kp_schur_calibration_min_samples) &
               projector_physical_direct_shadow_quality_for_promotion = &
               projector_physical_direct_shadow_quality_for_promotion* &
               projector_physical_direct_tail_residual_quality
            projector_physical_direct_quality_for_selection = &
               MAX(projector_physical_direct_quality_for_selection, &
                   MIN(1.0_dp, MAX(0.0_dp, projector_physical_direct_shadow_quality_for_promotion)))
            projector_physical_direct_history_quality = &
               MAX(projector_physical_direct_history_quality, &
                   projector_physical_direct_shadow_quality_for_promotion)
         END IF
         projector_physical_direct_quality_for_selection = &
            MIN(projector_physical_direct_quality_for_selection, &
                MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                    projector_physical_trace_invariant_quality_for_selection))
         projector_physical_direct_density_audit_quality = &
            kpoint_ot_density_audit_trust_quality( &
            local_ot_env(1)%schur_projector_density_audit_lowcurv_ema, &
            local_ot_env(1)%schur_projector_density_audit_lowcurv_quality_ema, &
            local_ot_env(1)%schur_projector_density_audit_amplification_ema, &
            local_ot_env(1)%schur_projector_density_audit_amplification_quality_ema, &
            local_ot_env(1)%schur_projector_density_audit_samples)
         projector_physical_direct_density_quality_for_selection = &
            kpoint_ot_schur_history_quality( &
            local_ot_env(1)%schur_projector_density_drop_sum, &
            local_ot_env(1)%schur_projector_density_measured_sum, &
            local_ot_env(1)%schur_projector_density_quality_ema, &
            local_ot_env(1)%schur_projector_density_quality_samples, &
            ot_kp_schur_projector_response_min_samples, &
            0.0_dp, &
            ot_kp_schur_projector_response_quality_min_ratio, &
            ot_kp_schur_projector_response_quality_max_ratio)
         projector_physical_direct_density_selected_probe_ready = .FALSE.
         IF (local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_physical_direct_density_quality_for_selection = &
               kpoint_ot_direct_selected_probe_quality( &
               projector_physical_direct_density_quality_for_selection, &
               projector_physical_direct_density_selected_history_quality, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples, &
               ot_kp_schur_calibration_min_samples)
            projector_physical_direct_density_selected_probe_ready = &
               projector_physical_direct_density_selected_history_quality >= &
               ot_kp_schur_projector_response_quality_min_ratio .AND. &
               projector_physical_direct_density_recent_residual_quality >= &
               0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
         END IF
         projector_physical_direct_density_shadow_quality_for_selection = &
            projector_physical_direct_density_quality_for_selection
         projector_density_history_quality = 1.0_dp
         projector_density_history_weight = 0.0_dp
         IF (projector_physical_shadow_enabled .AND. &
             residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
            IF (local_ot_env(1)%schur_projector_density_full_direct_quality_samples >= &
                ot_kp_schur_projector_response_min_samples .AND. &
                local_ot_env(1)%schur_projector_density_full_direct_drop_sum > &
                ot_kp_schur_projector_density_full_min_drop .AND. &
                local_ot_env(1)%schur_projector_density_full_direct_measured_sum > 0.0_dp .AND. &
                local_ot_env(1)%schur_projector_density_full_direct_quality_ema >= &
                0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
               projector_density_history_quality = &
                  kpoint_ot_direct_history_quality( &
                  local_ot_env(1)%schur_projector_density_full_direct_drop_sum, &
                  local_ot_env(1)%schur_projector_density_full_direct_measured_sum, &
                  local_ot_env(1)%schur_projector_density_full_direct_quality_ema, &
                  local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                  ot_kp_schur_projector_response_min_samples)
               projector_density_history_quality = projector_density_history_quality* &
                                                   MAX(0.0_dp, MIN(1.0_dp, &
                                                                   local_ot_env(1)% &
                                                                   schur_projector_density_full_direct_trust_ema))
               projector_density_history_weight = &
                  MAX(projector_density_history_weight, &
                      kpoint_ot_projector_coupled_weight( &
                      residual_delta, projector_density_history_quality, &
                      local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                      density_projector_fraction, projector_hessian_diag_avg, &
                      projector_hessian_delta_diag_avg))
            END IF
            IF (local_ot_env(1)%schur_projector_density_full_quality_samples >= &
                ot_kp_schur_projector_response_min_samples .AND. &
                local_ot_env(1)%schur_projector_density_full_drop_sum > &
                ot_kp_schur_projector_density_full_min_drop .AND. &
                local_ot_env(1)%schur_projector_density_full_measured_sum > 0.0_dp .AND. &
                local_ot_env(1)%schur_projector_density_full_quality_ema >= &
                0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
               projector_density_history_quality = &
                  kpoint_ot_direct_history_quality( &
                  local_ot_env(1)%schur_projector_density_full_drop_sum, &
                  local_ot_env(1)%schur_projector_density_full_measured_sum, &
                  local_ot_env(1)%schur_projector_density_full_quality_ema, &
                  local_ot_env(1)%schur_projector_density_full_quality_samples, &
                  ot_kp_schur_projector_response_min_samples)
               projector_density_history_quality = projector_density_history_quality* &
                                                   MAX(0.0_dp, MIN(1.0_dp, &
                                                                   local_ot_env(1)%schur_projector_density_full_trust_ema))
               projector_density_history_weight = &
                  MAX(projector_density_history_weight, &
                      kpoint_ot_projector_coupled_weight( &
                      residual_delta, projector_density_history_quality, &
                      local_ot_env(1)%schur_projector_density_full_quality_samples, &
                      density_projector_fraction, projector_hessian_diag_avg, &
                      projector_hessian_delta_diag_avg))
            END IF
            IF (local_ot_env(1)%schur_projector_density_full_global_quality_samples >= &
                ot_kp_schur_projector_response_min_samples .AND. &
                local_ot_env(1)%schur_projector_density_full_global_drop_sum > &
                ot_kp_schur_projector_density_full_min_drop .AND. &
                local_ot_env(1)%schur_projector_density_full_global_measured_sum > 0.0_dp .AND. &
                local_ot_env(1)%schur_projector_density_full_global_quality_ema >= &
                0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
               projector_density_history_quality = &
                  kpoint_ot_direct_history_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_drop_sum, &
                  local_ot_env(1)%schur_projector_density_full_global_measured_sum, &
                  local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
                  local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                  ot_kp_schur_projector_response_min_samples)
               projector_density_history_quality = projector_density_history_quality* &
                                                   MAX(0.0_dp, MIN(1.0_dp, &
                                                                   local_ot_env(1)% &
                                                                   schur_projector_density_full_global_trust_ema))
               projector_density_history_weight = &
                  MAX(projector_density_history_weight, &
                      kpoint_ot_projector_coupled_weight( &
                      residual_delta, projector_density_history_quality, &
                      local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                      density_projector_fraction, projector_hessian_diag_avg, &
                      projector_hessian_delta_diag_avg))
            END IF
            projector_density_history_weight = &
               MAX(projector_density_history_weight, &
                   projector_physical_direct_floor_density_weight)
         END IF
         projector_density_active_mix_weight = &
            MAX(projector_density_history_weight, projector_density_selected_history_weight)
         density_descent_quality_for_selection = &
            kpoint_ot_schur_history_quality( &
            local_ot_env(1)%schur_projector_density_descent_drop_sum, &
            local_ot_env(1)%schur_projector_density_descent_measured_sum, &
            local_ot_env(1)%schur_projector_density_descent_quality_ema, &
            local_ot_env(1)%schur_projector_density_descent_quality_samples, &
            ot_kp_schur_projector_response_min_samples, &
            0.0_dp, &
            ot_kp_schur_projector_response_quality_min_ratio, &
            ot_kp_schur_projector_response_quality_max_ratio)
         IF (local_ot_env(1)%schur_projector_density_descent_quality_samples > 0 .AND. &
             local_ot_env(1)%schur_projector_density_descent_support_ema >= &
             ot_kp_schur_projector_response_quality_min_ratio .AND. &
             local_ot_env(1)%schur_projector_density_descent_support >= &
             0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
             local_ot_env(1)%schur_projector_density_descent_quality_ema >= &
             ot_kp_schur_projector_response_quality_min_ratio .AND. &
             local_ot_env(1)%schur_projector_density_descent_quality >= &
             0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
            density_descent_bootstrap_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_density_descent_drop_sum, &
               local_ot_env(1)%schur_projector_density_descent_measured_sum, &
               local_ot_env(1)%schur_projector_density_descent_quality_ema, &
               local_ot_env(1)%schur_projector_density_descent_quality_samples, &
               1, 0.0_dp, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            density_descent_bootstrap_maturity = &
               REAL(MIN(local_ot_env(1)%schur_projector_density_descent_quality_samples, &
                        ot_kp_schur_projector_response_min_samples), KIND=dp)/ &
               REAL(MAX(1, ot_kp_schur_projector_response_min_samples), KIND=dp)
            density_descent_quality_for_selection = &
               MAX(density_descent_quality_for_selection, &
                   density_descent_bootstrap_maturity*density_descent_bootstrap_quality)
            density_descent_bootstrap_ready = &
               local_ot_env(1)%schur_projector_density_descent_quality_samples >= 2 .AND. &
               density_descent_quality_for_selection >= &
               ot_kp_schur_projector_response_quality_min_ratio
         END IF
         IF (local_ot_env(1)%schur_projector_density_descent_selected_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            density_descent_quality_for_selection = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_density_descent_selected_drop_sum, &
               local_ot_env(1)%schur_projector_density_descent_selected_measured_sum, &
               local_ot_env(1)%schur_projector_density_descent_selected_quality_ema, &
               local_ot_env(1)%schur_projector_density_descent_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               density_descent_quality_for_selection, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
               density_descent_quality_for_selection = &
               density_descent_quality_for_selection* &
               MAX(0.0_dp, MIN(1.0_dp, &
                               local_ot_env(1)%schur_projector_density_descent_selected_residual_quality_ema))
         END IF
         IF (local_ot_env(1)%schur_projector_offdiag_quality_samples >= &
             ot_kp_schur_projector_response_min_samples) THEN
            projector_offdiag_history_quality = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_offdiag_drop_sum, &
                                               local_ot_env(1)%schur_projector_offdiag_measured_sum, &
                                               local_ot_env(1)%schur_projector_offdiag_quality_ema, &
                                               local_ot_env(1)%schur_projector_offdiag_quality_samples, &
                                               ot_kp_schur_projector_response_min_samples, &
                                               0.0_dp, &
                                               ot_kp_schur_projector_response_quality_min_ratio, &
                                               ot_kp_schur_projector_response_quality_max_ratio)
            IF (local_ot_env(1)%schur_projector_offdiag_abs_ratio_ema > &
                EPSILON(local_ot_env(1)%schur_projector_offdiag_abs_ratio_ema)) &
               projector_offdiag_history_trust = &
               MAX(0.0_dp, -local_ot_env(1)%schur_projector_offdiag_signed_ratio_ema/ &
                   local_ot_env(1)%schur_projector_offdiag_abs_ratio_ema)
            projector_offdiag_history_trust = &
               MIN(1.0_dp, projector_offdiag_history_trust)* &
               MIN(1.0_dp, MAX(0.0_dp, local_ot_env(1)%schur_projector_offdiag_step_negative_ema))
            projector_offdiag_history_response_ratio = &
               MAX(0.0_dp, 1.0_dp - &
                   MIN(1.0_dp, &
                       MAX(0.0_dp, &
                           local_ot_env(1)%schur_projector_offdiag_step_negative_ema)))* &
               ot_kp_schur_projector_response_ratio_gate
            projector_offdiag_quality_for_selection = &
               projector_offdiag_history_quality*projector_offdiag_history_trust
            projector_offdiag_quality_for_selection = &
               kpoint_ot_offdiag_tail_residual_quality( &
               projector_offdiag_quality_for_selection, &
               local_ot_env(1)%schur_coupled_residual_quality, &
               local_ot_env(1)%schur_coupled_residual_quality_ema, &
               local_ot_env(1)%schur_coupled_quality_samples, residual_delta)
         END IF
         IF (local_ot_env(1)%schur_projector_inactive_offdiag_quality_samples >= &
             ot_kp_schur_projector_response_min_samples) THEN
            projector_inactive_offdiag_history_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_inactive_offdiag_drop_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_measured_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_quality_ema, &
               local_ot_env(1)%schur_projector_inactive_offdiag_quality_samples, &
               ot_kp_schur_projector_response_min_samples, &
               0.0_dp, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            IF (local_ot_env(1)%schur_projector_inactive_offdiag_abs_ratio_ema > &
                EPSILON(local_ot_env(1)%schur_projector_inactive_offdiag_abs_ratio_ema)) &
               projector_inactive_offdiag_history_trust = &
               MAX(0.0_dp, &
                   -local_ot_env(1)%schur_projector_inactive_offdiag_signed_ratio_ema/ &
                   local_ot_env(1)%schur_projector_inactive_offdiag_abs_ratio_ema)
            projector_inactive_offdiag_history_trust = &
               MIN(1.0_dp, projector_inactive_offdiag_history_trust)* &
               MIN(1.0_dp, MAX(0.0_dp, &
                               local_ot_env(1)%schur_projector_inactive_offdiag_step_negative_ema))
            projector_inactive_offdiag_history_response_ratio = &
               MAX(0.0_dp, &
                   1.0_dp - &
                   MIN(1.0_dp, &
                       MAX(0.0_dp, &
                           local_ot_env(1)%schur_projector_inactive_offdiag_step_negative_ema)))* &
               ot_kp_schur_projector_response_ratio_gate
            projector_inactive_offdiag_quality_for_selection = &
               projector_inactive_offdiag_history_quality* &
               projector_inactive_offdiag_history_trust
            projector_inactive_offdiag_quality_for_selection = &
               kpoint_ot_offdiag_tail_residual_quality( &
               projector_inactive_offdiag_quality_for_selection, &
               local_ot_env(1)%schur_coupled_residual_quality, &
               local_ot_env(1)%schur_coupled_residual_quality_ema, &
               local_ot_env(1)%schur_coupled_quality_samples, residual_delta)
         END IF
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples .OR. &
             local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) &
            residual_reference_quality = ot_kp_schur_quality_min_ratio
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples) &
            residual_reference_quality = MAX(residual_reference_quality, &
                                             local_ot_env(1)%schur_split_residual_quality_ema)
         IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) &
            residual_reference_quality = MAX(residual_reference_quality, &
                                             local_ot_env(1)%schur_coupled_residual_quality_ema)
         IF (local_ot_env(1)%schur_projector_offdiag_selected_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_offdiag_selected_quality_for_selection = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_offdiag_selected_drop_sum, &
               local_ot_env(1)%schur_projector_offdiag_selected_measured_sum, &
               local_ot_env(1)%schur_projector_offdiag_selected_quality_ema, &
               local_ot_env(1)%schur_projector_offdiag_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               projector_offdiag_quality_for_selection, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            projector_offdiag_selected_quality_for_selection = &
               kpoint_ot_inactive_offdiag_selected_tail_quality( &
               projector_offdiag_selected_quality_for_selection, &
               local_ot_env(1)%schur_projector_offdiag_selected_quality_ema, &
               local_ot_env(1)%schur_projector_offdiag_selected_drop_sum, &
               local_ot_env(1)%schur_projector_offdiag_selected_measured_sum, &
               local_ot_env(1)%schur_projector_offdiag_selected_residual_quality, &
               local_ot_env(1)%schur_projector_offdiag_selected_residual_quality_ema, &
               residual_reference_quality, &
               local_ot_env(1)%schur_projector_offdiag_selected_quality_samples, &
               residual_delta)
            projector_offdiag_quality_for_selection = &
               MAX(projector_offdiag_quality_for_selection, &
                   projector_offdiag_selected_quality_for_selection)
            projector_offdiag_selected_residual_quality = &
               kpoint_ot_selected_tail_mix_residual_quality( &
               local_ot_env(1)%schur_projector_offdiag_selected_residual_quality, &
               local_ot_env(1)%schur_projector_offdiag_selected_residual_quality_ema)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                projector_offdiag_selected_quality_for_selection >= &
                ot_kp_schur_projector_response_quality_min_ratio .AND. &
                projector_offdiag_history_trust >= &
                0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
               IF (projector_offdiag_selected_residual_quality >= &
                   MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)) THEN
                  projector_offdiag_model_advantage_ratio = 1.0_dp
               ELSE IF (projector_offdiag_selected_residual_quality >= &
                        0.75_dp*MAX(dense_residual_quality, &
                                    ot_kp_schur_calibrated_quality_min_ratio)) THEN
                  projector_offdiag_model_advantage_ratio = &
                     MIN(projector_offdiag_model_advantage_ratio, 1.05_dp)
               END IF
            END IF
         END IF
         IF (local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_inactive_offdiag_selected_quality_for_selection = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_drop_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_measured_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality_ema, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               1.0_dp, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            projector_inactive_offdiag_selected_quality_for_selection = &
               kpoint_ot_inactive_offdiag_selected_tail_quality( &
               projector_inactive_offdiag_selected_quality_for_selection, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality_ema, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_drop_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_measured_sum, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_residual_quality, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_residual_quality_ema, &
               residual_reference_quality, &
               local_ot_env(1)%schur_projector_inactive_offdiag_selected_quality_samples, &
               residual_delta)
         END IF
         projector_inactive_offdiag_selected_scale = &
            MIN(1.0_dp, MAX(0.0_dp, projector_inactive_offdiag_selected_quality_for_selection))
         split_quality_for_selection = &
            kpoint_ot_schur_history_quality(local_ot_env(1)%schur_split_calibrated_drop_sum, &
                                            local_ot_env(1)%schur_split_measured_sum, &
                                            local_ot_env(1)%schur_split_calibrated_quality_ema, &
                                            local_ot_env(1)%schur_split_quality_samples, &
                                            ot_kp_schur_calibration_min_samples, &
                                            local_ot_env(1)%schur_split_calibrated_quality_ema, &
                                            ot_kp_schur_calibrated_quality_min_ratio, &
                                            ot_kp_schur_calibrated_quality_max_ratio)
         constrained_quality_for_selection = &
            kpoint_ot_schur_history_quality(local_ot_env(1)%schur_constrained_calibrated_drop_sum, &
                                            local_ot_env(1)%schur_constrained_measured_sum, &
                                            local_ot_env(1)%schur_constrained_calibrated_quality_ema, &
                                            local_ot_env(1)%schur_constrained_quality_samples, &
                                            ot_kp_schur_constrained_min_samples, &
                                            local_ot_env(1)%schur_constrained_calibrated_quality_ema, &
                                            ot_kp_schur_calibrated_quality_min_ratio, &
                                            ot_kp_schur_calibrated_quality_max_ratio)
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples .OR. &
             local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) &
            residual_reference_quality = ot_kp_schur_quality_min_ratio
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples) &
            residual_reference_quality = MAX(residual_reference_quality, &
                                             local_ot_env(1)%schur_split_residual_quality_ema)
         IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) &
            residual_reference_quality = MAX(residual_reference_quality, &
                                             local_ot_env(1)%schur_coupled_residual_quality_ema)
         IF (residual_reference_quality > EPSILON(residual_reference_quality)) THEN
            IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples) &
               split_residual_quality = &
               MAX(ot_kp_schur_calibrated_quality_min_ratio, &
                   MIN(1.0_dp, local_ot_env(1)%schur_split_residual_quality_ema/residual_reference_quality))
            IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
               dense_residual_quality_strict = &
                  MIN(1.0_dp, MAX(0.0_dp, &
                                  local_ot_env(1)%schur_coupled_residual_quality_ema/ &
                                  residual_reference_quality))
               dense_residual_quality = &
                  MAX(ot_kp_schur_calibrated_quality_min_ratio, dense_residual_quality_strict)
            END IF
            split_quality_for_selection = split_quality_for_selection*split_residual_quality
            dense_quality_for_selection = dense_quality_for_selection*dense_residual_quality
         END IF
         dense_coupled_gate_quality = local_ot_env(1)%schur_coupled_quality
         dense_coupled_gate_quality_ema = local_ot_env(1)%schur_coupled_quality_ema
         IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            dense_coupled_gate_quality = &
               MAX(dense_coupled_gate_quality, &
                   MIN(ot_kp_schur_calibrated_quality_max_ratio, &
                       local_ot_env(1)%schur_coupled_calibrated_quality))
            dense_coupled_gate_quality_ema = &
               MAX(dense_coupled_gate_quality_ema, &
                   MIN(ot_kp_schur_calibrated_quality_max_ratio, &
                       local_ot_env(1)%schur_coupled_calibrated_quality_ema))
         END IF
         IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
             local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_physical_direct_density_residual_bad = &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality < &
               0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
               MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)
         END IF
         dense_exact_scale_ready = residual_delta > ot_kp_schur_projector_coupled_tail_delta
         IF (.NOT. dense_exact_scale_ready .AND. &
             local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            dense_exact_scale_ready = &
               dense_coupled_gate_quality_ema >= ot_kp_schur_quality_min_ratio .AND. &
               dense_coupled_gate_quality >= 0.5_dp*ot_kp_schur_quality_min_ratio .AND. &
               dense_residual_quality_strict >= ot_kp_schur_calibrated_quality_min_ratio
         END IF
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples .OR. &
             local_ot_env(1)%schur_model_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            split_curvature_scale = MIN(ot_kp_schur_calibration_max_scale, &
                                        1.0_dp/SQRT(split_quality_for_calibration))
         END IF
         ! Attempt order: response-constrained split shadow, raw split,
         ! dense fixed-N coupled response, and the conservative raw fallback.
         DO schur_attempt = 1, 4
            attempt_failed = .FALSE.
            reject_reason = 0
            direction_scale = 0.0_dp
            scale_quality = 0.0_dp
            gdotp = 0.0_dp
            gdot_energy = 0.0_dp
            gdot_rotation = 0.0_dp
            gnorm = 0.0_dp
            norm_energy = 0.0_dp
            norm_rotation = 0.0_dp
            norm_ratio = 0.0_dp
            normp = 0.0_dp
            exact_attempt_response = exact_energy_model_ready .AND. schur_attempt <= 3
            response_model_available = schur_attempt <= 2 .OR. &
                                       (schur_attempt == 3 .AND. exact_attempt_response)
            projector_coupled_weight = 0.0_dp
            projector_diag_compensation = 0.0_dp
            projector_mode_damped_abs_avg = 0.0_dp
