               CYCLE
            END IF
            IF (schur_attempt <= 2 .AND. .NOT. split_candidate_diagnostic) THEN
               IF (schur_attempt == 1) THEN
                  constrained_reject_reason = reject_quality_gate
               ELSE
                  coupled_reject_reason = reject_quality_gate
               END IF
               CYCLE
            END IF
            projector_tail_active_delta_diag_avg = 0.0_dp
            projector_tail_active_delta_weight = 0.0_dp
            projector_plateau_gap_delta_diag_avg = 0.0_dp
            projector_plateau_gap_delta_weight = 0.0_dp
            projector_tail_delta_diag_avg = projector_hessian_delta_diag_avg
            IF (schur_attempt <= 2) THEN
               schur(:, :) = rot_hessian_coupled(:, :) + rot_hessian_projector(:, :) - rot_hessian(:, :)
            ELSE IF (schur_attempt == 3) THEN
               IF (exact_attempt_response) &
                  projector_coupled_weight = kpoint_ot_projector_coupled_weight(residual_delta, &
                                                       dense_quality_for_selection, local_ot_env(1)%schur_coupled_quality_samples, &
                                           density_projector_fraction, projector_hessian_diag_avg, projector_hessian_delta_diag_avg)
               IF (exact_attempt_response) &
                  projector_coupled_weight = MAX(projector_coupled_weight, &
                                                 projector_density_history_weight)
               schur(:, :) = rot_hessian_coupled(:, :) + &
                             projector_coupled_weight*(rot_hessian_projector(:, :) - rot_hessian(:, :))
               IF (exact_attempt_response .AND. exact_physical_response_ready .AND. &
                   residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                   projector_density_active_mix_weight > EPSILON(projector_density_active_mix_weight)) THEN
                  projector_tail_active_delta_weight = &
                     kpoint_ot_projector_tail_active_delta_weight(projector_coupled_weight, &
                                                                 projector_density_active_mix_weight)
                  IF (projector_tail_active_delta_weight > EPSILON(projector_tail_active_delta_weight)) THEN
                     schur(:, :) = schur(:, :) + projector_coupled_weight* &
                                   projector_tail_active_delta_weight* &
                                   (rot_hessian_projector_physical_active(:, :) - &
                                    rot_hessian_projector(:, :))
                     projector_tail_active_delta_diag_avg = 0.0_dp
                     DO r = 1, nrot
                        projector_tail_active_delta_diag_avg = projector_tail_active_delta_diag_avg + &
                           rot_hessian_projector_physical_active(r, r) - rot_hessian(r, r)
                     END DO
                     projector_tail_active_delta_diag_avg = &
                        projector_tail_active_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                     projector_tail_delta_diag_avg = &
                        (1.0_dp - projector_tail_active_delta_weight)*projector_hessian_delta_diag_avg + &
                        projector_tail_active_delta_weight*projector_tail_active_delta_diag_avg
                  END IF
               END IF
               IF (exact_attempt_response .AND. projector_plateau_gap_model_enabled .AND. &
                   residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
                  projector_plateau_gap_delta_weight = &
                     kpoint_ot_projector_plateau_gap_mix_weight( &
                     residual_delta, projector_plateau_gap_quality_for_selection, &
                     local_ot_env(1)%schur_projector_plateau_gap_quality_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_weight_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_negative_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_step_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_quality_samples)
                  IF (projector_plateau_gap_delta_weight > &
                      EPSILON(projector_plateau_gap_delta_weight)) THEN
                     schur(:, :) = schur(:, :) + projector_plateau_gap_delta_weight* &
                        (rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                         rot_hessian_projector_physical_offdiag_active(:, :))
                     projector_plateau_gap_delta_diag_avg = 0.0_dp
                     DO r = 1, nrot
                        projector_plateau_gap_delta_diag_avg = &
                           projector_plateau_gap_delta_diag_avg + &
                           rot_hessian_projector_physical_offdiag_plateau_active(r, r) - &
                           rot_hessian_projector_physical_offdiag_active(r, r)
                     END DO
                     projector_plateau_gap_delta_diag_avg = &
                        projector_plateau_gap_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  END IF
               END IF
               IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
                  projector_diag_compensation = &
                  MAX(0.0_dp, -projector_coupled_weight*projector_tail_delta_diag_avg)
            ELSE
               schur(:, :) = rot_hessian(:, :)
               IF (exact_physical_response_ready .AND. &
                   residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                   projector_physical_direct_floor_density_weight > &
                   EPSILON(projector_physical_direct_floor_density_weight)) &
                  schur(:, :) = schur(:, :) + rot_hessian_projector_physical_offdiag_active(:, :)
            END IF
            DO r = 1, nrot
               IF (schur_attempt <= 2) THEN
                  IF (exact_energy_model_ready) THEN
                     rhs(r) = grad_rot(r) + DOT_PRODUCT(response_exact(:, r), grad_e)
                  ELSE
                     rhs(r) = grad_rot(r) + DOT_PRODUCT(response_split(:, r), grad_e)
                  END IF
               ELSE IF (schur_attempt == 3) THEN
                  IF (exact_attempt_response) THEN
                     rhs(r) = grad_rot(r) + DOT_PRODUCT(response_exact(:, r), grad_e)
                  ELSE
                     rtd(r) = DOT_PRODUCT(curv, response_coupled(:, r))
                     rhs(r) = grad_rot(r) + DOT_PRODUCT(response_coupled(:, r), grad_e)
                  END IF
               ELSE
                  rtd(r) = DOT_PRODUCT(curv, response(:, r))
                  rhs(r) = grad_rot(r) + DOT_PRODUCT(response(:, r), grad_e)
               END IF
            END DO
            diag_shift_sum = 0.0_dp
            diag_shift_max = 0.0_dp
            row_floor_shift(:) = 0.0_dp
            diag_prefloor_avg = 0.0_dp
            diag_prefloor_min = HUGE(1.0_dp)
            diag_prefloor_max = -HUGE(1.0_dp)
            diag_shift_fraction = 0.0_dp
            row_floor_avg = 0.0_dp
            row_floor_max = 0.0_dp
            response_abs_step = 0.0_dp
            response_abs_trust_ratio = 0.0_dp
            response_step_max = 0.0_dp
            response_weighted_step = 0.0_dp
            response_weighted_trust_ratio = 0.0_dp
            model_drop = 0.0_dp
            model_calibrated_drop = 0.0_dp
            model_gap = 0.0_dp
            model_gap_drop = 0.0_dp
            model_gap_ratio = 0.0_dp
            model_gap_trust = HUGE(1.0_dp)
            occgap_shadow_abs_step = 0.0_dp
            occgap_shadow_drop = 0.0_dp
            occgap_shadow_gap_ratio = 0.0_dp
            occgap_shadow_quality = 1.0_dp
            occgap_shadow_step = 0.0_dp
            occ_response_diag_sum = 0.0_dp
            response_penalty_diag_sum = 0.0_dp
            rot_diag_sum = 0.0_dp
            tether_response_diag_sum = 0.0_dp
            rot_floor_min = rotation_curvature_floor
            schur_diag_min = HUGE(1.0_dp)

            DO s = 1, nrot
               DO r = 1, nrot
                  response_penalty_term = 0.0_dp
                  IF (schur_attempt <= 2) THEN
                     CALL kpoint_ot_mixed_projected_cross_term(response_occ(:, r), response_occ(:, s), &
                                                               response(:, r), response(:, s), &
                                                               occ_curv, tether_curv, occ_curv_projection_sum, &
                                                               channel_nmo, e_offset, projected_term, &
                                                               occ_projected_term, tether_projected_term)
                     IF (exact_energy_model_ready) &
                        projected_term = 0.5_dp*(DOT_PRODUCT(energy_cross(:, r), response_exact_raw(:, s)) + &
                                                 DOT_PRODUCT(energy_cross_raw(:, r), response_exact(:, s)))
                     IF (schur_attempt == 1) response_penalty_term = &
                        schur_response_penalty_scale*projected_term
                     IF (r == s) THEN
                        rot_diag_sum = rot_diag_sum + schur(r, r)
                        occ_response_diag_sum = occ_response_diag_sum + occ_projected_term
                        tether_response_diag_sum = tether_response_diag_sum + tether_projected_term
                        response_penalty_diag_sum = response_penalty_diag_sum + response_penalty_term
                     END IF
                  ELSE IF (schur_attempt == 3) THEN
                     IF (exact_attempt_response) THEN
                        projected_term = 0.5_dp*(DOT_PRODUCT(energy_cross(:, r), response_exact_raw(:, s)) + &
                                                 DOT_PRODUCT(energy_cross_raw(:, r), response_exact(:, s)))
                     ELSE
                        dense_term = DOT_PRODUCT(curv(:)*response_coupled(:, r), response_coupled(:, s))
                        projected_term = dense_term
                        IF (curv_projection_sum > EPSILON(curv_projection_sum)) &
                           projected_term = projected_term - rtd(r)*rtd(s)/curv_projection_sum
                     END IF
                  ELSE
                     dense_term = DOT_PRODUCT(curv(:)*response(:, r), response(:, s))
                     projected_term = dense_term
                     IF (curv_projection_sum > EPSILON(curv_projection_sum)) &
                        projected_term = projected_term - rtd(r)*rtd(s)/curv_projection_sum
                  END IF
                  schur(r, s) = schur(r, s) - projected_term + response_penalty_term
               END DO
            END DO
            IF (schur_attempt <= 2) schur(:, :) = split_curvature_scale*schur(:, :)
            DO r = 1, nrot
               IF (projector_diag_compensation > 0.0_dp) schur(r, r) = schur(r, r) + projector_diag_compensation
               row_floor = rotation_curvature_floor
               IF (schur_attempt <= 3) THEN
                  row_floor = rot_floor(r)
                  IF (exact_attempt_response .AND. &
                      residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
                     ! In the metallic tail the exact-response Schur block should
                     ! keep the Fermi-window curvature floor even when the optional
                     ! physical projector shadow is not available for this step.
                     IF (exact_physical_response_ready) THEN
                        row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                                      rot_hessian_projector_physical(r, r), &
                                                                      rot_floor(r))
                     ELSE
                        row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                                      schur(r, r), rot_floor(r))
                     END IF
                     row_floor = kpoint_ot_residual_gauge_rotation_floor( &
                                 row_floor, schur_gauge_curvature_floor, &
                                 var_occ_gap_weight(r), step_gauge_quality)
                  END IF
               ELSE
                  row_floor = kpoint_ot_raw_tail_rotation_floor(row_floor, rot_floor(r), residual_delta)
               END IF
               rot_floor_min = MIN(rot_floor_min, row_floor)
               diag_prefloor_avg = diag_prefloor_avg + schur(r, r)
               diag_prefloor_min = MIN(diag_prefloor_min, schur(r, r))
               diag_prefloor_max = MAX(diag_prefloor_max, schur(r, r))
               row_floor_avg = row_floor_avg + row_floor
               row_floor_max = MAX(row_floor_max, row_floor)
               IF (schur_attempt <= 3) THEN
                  ! First try the coupled finite-rotation Schur block itself.  The
                  ! line-search safeguards below reject non-descent or overlarge
                  ! response directions; the Gershgorin model remains the fallback.
                  diag_shift = MAX(0.0_dp, row_floor - schur(r, r))
               ELSE
                  row_abs = SUM(ABS(schur(r, :))) - ABS(schur(r, r))
                  diag_shift = MAX(0.0_dp, row_abs + row_floor - schur(r, r))
               END IF
               IF (diag_shift > 0.0_dp) THEN
                  row_floor_shift(r) = diag_shift
                  schur(r, r) = schur(r, r) + diag_shift
                  diag_shift_sum = diag_shift_sum + diag_shift
                  diag_shift_max = MAX(diag_shift_max, diag_shift)
                  diag_shift_fraction = diag_shift_fraction + 1.0_dp
               END IF
               schur_diag_min = MIN(schur_diag_min, schur(r, r))
            END DO
            diag_prefloor_avg = diag_prefloor_avg/REAL(MAX(1, nrot), KIND=dp)
            row_floor_avg = row_floor_avg/REAL(MAX(1, nrot), KIND=dp)
            diag_shift_fraction = diag_shift_fraction/REAL(MAX(1, nrot), KIND=dp)
            schur_metric(:, :) = 0.5_dp*(schur(:, :) + TRANSPOSE(schur(:, :)))
            IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,I6),8(1X,ES16.8))') &
               " OT Schur hypothetical row-floor audit group ne nrot att preavg premin premax "// &
               "flooravg floormax sfrac dsum dmax:", &
               target_group, ne, nrot, schur_attempt, diag_prefloor_avg, diag_prefloor_min, diag_prefloor_max, &
               row_floor_avg, row_floor_max, diag_shift_fraction, diag_shift_sum, diag_shift_max

            sol(:) = rhs(:)
            CALL dgesv(nrot, 1, schur, nrot, ipiv, sol, nrot, info)
            IF (info /= 0) THEN
               attempt_failed = .TRUE.
               reject_reason = reject_dgesv
            END IF

            IF (.NOT. attempt_failed) THEN
               row_floor_shift_quad = 0.0_dp
               row_floor_shifted_step = 0.0_dp
               row_floor_step_norm = DOT_PRODUCT(sol, sol)
               DO r = 1, nrot
                  row_floor_shift_quad = row_floor_shift_quad + row_floor_shift(r)*sol(r)*sol(r)
                  IF (row_floor_shift(r) > 0.0_dp) &
                     row_floor_shifted_step = row_floor_shifted_step + sol(r)*sol(r)
               END DO
               row_floor_step_fraction = 0.0_dp
               IF (row_floor_step_norm > EPSILON(row_floor_step_norm)) &
                  row_floor_step_fraction = row_floor_shifted_step/row_floor_step_norm
               IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),5(1X,ES16.8))') &
                  " OT Schur row-floor step audit group att shifted_frac shift_quad step_norm dsum dmax:", &
                  target_group, schur_attempt, row_floor_step_fraction, row_floor_shift_quad, &
                  row_floor_step_norm, diag_shift_sum, diag_shift_max
               IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source() .AND. &
                   schur_attempt == 3 .AND. exact_attempt_response) &
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),5(1X,ES16.8))') &
                  " OT Schur projector tail active-delta mix group att weight absw rawdiag actdiag mixdiag:", &
                  target_group, schur_attempt, projector_tail_active_delta_weight, &
                  projector_coupled_weight*projector_tail_active_delta_weight, &
                  projector_hessian_delta_diag_avg, projector_tail_active_delta_diag_avg, &
                  projector_tail_delta_diag_avg
               IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source() .AND. &
                   schur_attempt == 3 .AND. exact_attempt_response) &
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),2(1X,ES16.8))') &
                  " OT Schur projector plateau-gap coupled-delta mix group att weight diag:", &
                  target_group, schur_attempt, projector_plateau_gap_delta_weight, &
                  projector_plateau_gap_delta_diag_avg
               IF (schur_attempt <= 2) THEN
                  IF (exact_energy_model_ready) THEN
                     rx_e(:) = MATMUL(response_exact_raw, sol)
                     rx_model(:) = MATMUL(response_exact, sol)
                  ELSE
                     rx_e(:) = MATMUL(response_split, sol)
                     rx_model(:) = MATMUL(response_coupled, sol)
                  END IF
               ELSE IF (schur_attempt == 3) THEN
                  IF (exact_attempt_response) THEN
                     rx_e(:) = MATMUL(response_exact_raw, sol)
                     rx_model(:) = MATMUL(response_exact, sol)
                  ELSE
                     rx_e(:) = MATMUL(response_coupled, sol)
                     rx_model(:) = rx_e(:)
                  END IF
               ELSE
                  rx_e(:) = MATMUL(response, sol)
                  rx_model(:) = rx_e(:)
               END IF
               CALL project_kpoint_ot_schur_response(rx_e, occ_curv, tether_curv, &
                                                     occ_curv_projection_sum, channel_nmo, e_offset)
               IF (response_model_available) THEN
                  CALL project_kpoint_ot_schur_response(rx_model, occ_curv, tether_curv, &
                                                        occ_curv_projection_sum, channel_nmo, e_offset)
               END IF
               gnorm = DOT_PRODUCT(grad_e, grad_e) + DOT_PRODUCT(grad_rot, grad_rot)
               IF (schur_attempt == 3 .AND. exact_attempt_response .AND. &
                   projector_coupled_weight > EPSILON(projector_coupled_weight) .AND. &
                   (local_ot_env(1)%schur_projector_mode_quality_samples >= &
                    ot_kp_schur_calibration_min_samples .OR. &
                    projector_density_history_weight > EPSILON(projector_density_history_weight))) THEN
                  CALL audit_kpoint_ot_projector_response_modes(rot_hessian, rot_hessian_projector, sol, &
                                                                response_exact_raw, response_exact, curv, &
                                                                occ_curv, tether_curv, occ_curv_projection_sum, &
                                                                channel_nmo, e_offset, .TRUE., &
                                                                projector_coupled_weight, residual_delta, &
                                                                projector_mode_history_quality, &
                                                                local_ot_env(1)%schur_projector_mode_trust_ema, &
                                                                projector_mode_history_response_ratio, grad_e, &
                                                                z_e + rx_e, rx_e, &
                                                                projector_response_rx_e, projector_mode_response_weight, &
                                                                projector_mode_response_correction_drop, &
                                                                projector_mode_response_correction_negative, &
                                                                projector_mode_response_raw_negative_fraction, &
                                                                projector_mode_response_positive_drop, &
                                                                projector_mode_response_negative_drop, &
                                                                projector_mode_response_cross_drop, &
                                                                projector_mode_response_positive_coeff, &
                                                                projector_mode_response_negative_coeff, &
                                                                diag_base_weight= &
                                                                projector_mode_response_audit_base_weight, &
                                                                diag_response_total_sum= &
                                                                projector_mode_response_audit_response_total_sum, &
                                                                diag_step_weight_sum= &
                                                                projector_mode_response_audit_step_weight_sum, &
                                                                diag_eval_abs_avg= &
                                                                projector_mode_response_audit_eval_abs_avg, &
                                                                diag_positive_weight_sum= &
                                                                projector_mode_response_audit_positive_weight_sum, &
                                                                diag_negative_weight_sum= &
                                                                projector_mode_response_audit_negative_weight_sum, &
                                                                raw_residual_delta=response_raw_delta)
                  IF (projector_mode_response_weight > EPSILON(projector_mode_response_weight)) THEN
                     projector_response_z_e(:) = z_e(:) + projector_response_rx_e(:)
                     projector_response_gdot_energy = DOT_PRODUCT(grad_e, projector_response_z_e)
                     projector_response_gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                     projector_response_norm_energy = DOT_PRODUCT(projector_response_z_e, projector_response_z_e)
                     projector_response_norm_rotation = DOT_PRODUCT(sol, sol)
                     CALL kpoint_ot_mixed_projected_term(projector_response_z_e, projector_response_z_e, &
                                                         occ_curv, tether_curv, occ_curv_projection_sum, &
                                                         channel_nmo, e_offset, &
                                                         projector_response_metric_norm_energy)
                     projector_response_metric_norm_energy = &
                        MAX(0.0_dp, projector_response_metric_norm_energy)
                     projector_response_metric_norm_rotation = ABS(kpoint_ot_symmetric_quad(schur_metric, sol))
                     IF (projector_response_metric_norm_rotation <= &
                         EPSILON(projector_response_metric_norm_rotation)) &
                        projector_response_metric_norm_rotation = kpoint_ot_symmetric_abs_quad(schur_metric, sol)
                     projector_response_gdotp = projector_response_gdot_energy + projector_response_gdot_rotation
                     projector_response_normp = projector_response_norm_energy + projector_response_norm_rotation
                     projector_response_metric_normp = projector_response_metric_norm_energy + &
                                                       projector_response_metric_norm_rotation
                     projector_response_norm_ratio = projector_response_normp/MAX(gnorm, EPSILON(1.0_dp))
                     IF (projector_response_gdotp > 0.0_dp .AND. &
                         projector_response_normp > EPSILON(projector_response_normp) .AND. &
                         projector_response_metric_normp > EPSILON(projector_response_metric_normp) .AND. &
                         projector_response_norm_ratio <= max_norm_ratio) THEN
                        projector_response_unit_abs_step = MAXVAL(ABS(projector_response_rx_e))
                        CALL para_env_inter_kp%max(projector_response_unit_abs_step)
                        projector_response_unit_weighted_step = &
                           kpoint_ot_weighted_response_step(projector_response_rx_e, curv, curv_projection_sum)
                        projector_response_trust_scale = 1.0_dp
                        IF (response_trust > EPSILON(response_trust) .AND. &
                            projector_response_unit_weighted_step > &
                            EPSILON(projector_response_unit_weighted_step)) &
                           projector_response_trust_scale = &
                           MIN(projector_response_trust_scale, &
                               0.8_dp*response_trust/projector_response_unit_weighted_step)
                        IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                            projector_response_unit_abs_step > EPSILON(projector_response_unit_abs_step)) &
                           projector_response_trust_scale = &
                           MIN(projector_response_trust_scale, &
                               0.8_dp*response_abs_trust/projector_response_unit_abs_step)
                        projector_response_direction_scale = &
                           MIN(1.0_dp, projector_response_trust_scale, &
                               projector_response_gdotp/ &
                               MAX(projector_response_metric_normp, &
                                   EPSILON(projector_response_metric_normp)))
                        projector_response_scale_quality = &
                           kpoint_ot_schur_scale_quality(projector_response_direction_scale, schur_min_coupled_scale)
                        projector_response_z_e(:) = projector_response_direction_scale*projector_response_z_e(:)
                        projector_response_sol(:) = projector_response_direction_scale*sol(:)
                        projector_response_model_drop = projector_response_direction_scale* &
                                                        projector_response_gdotp - &
                                                        0.5_dp*projector_response_direction_scale* &
                                                        projector_response_direction_scale* &
                                                        projector_response_metric_normp
                        projector_response_response_abs_step = &
                           projector_response_direction_scale*projector_response_unit_abs_step
                        projector_response_response_weighted_step = &
                           projector_response_direction_scale*projector_response_unit_weighted_step
                        projector_response_model_gap = &
                           projector_response_direction_scale*MAXVAL(ABS(rx_model - projector_response_rx_e))
                        projector_response_model_gap_drop = &
                           kpoint_ot_response_mismatch_drop(projector_response_rx_e, rx_model, curv, &
                                                            projector_response_direction_scale)
                        projector_response_model_calibrated_drop = &
                           MAX(0.0_dp, projector_response_model_drop - projector_response_model_gap_drop)
                        projector_response_model_gap_trust = schur_model_gap_factor*response_trust
                        projector_response_model_gap_ratio = 0.0_dp
                        IF (projector_response_model_gap_trust > EPSILON(projector_response_model_gap_trust)) &
                           projector_response_model_gap_ratio = projector_response_model_gap/ &
                                                                projector_response_model_gap_trust
                        projector_response_response_weighted_trust_ratio = 0.0_dp
                        IF (response_trust > EPSILON(response_trust)) &
                           projector_response_response_weighted_trust_ratio = &
                           projector_response_response_weighted_step/response_trust
                        projector_response_response_abs_trust_ratio = 0.0_dp
                        IF (response_abs_trust > EPSILON(response_abs_trust)) &
                           projector_response_response_abs_trust_ratio = &
                           projector_response_response_abs_step/response_abs_trust
                        projector_response_trust_quality = &
                           kpoint_ot_schur_trust_quality(projector_response_response_weighted_trust_ratio, &
                                                         projector_response_response_abs_trust_ratio, &
                                                         projector_response_model_gap_ratio)
                        IF (projector_response_direction_scale < schur_min_coupled_scale) &
                           projector_response_model_calibrated_drop = &
                           projector_response_scale_quality*projector_response_model_calibrated_drop
                        projector_response_expected_drop = &
                           kpoint_ot_schur_expected_drop(projector_response_model_calibrated_drop, &
                                                         projector_response_quality_for_selection, &
                                                         projector_response_trust_quality)
                        projector_response_candidate_ready = &
                           projector_response_model_calibrated_drop > EPSILON(projector_response_model_drop) .AND. &
                           projector_response_response_weighted_step <= response_trust .AND. &
                           projector_response_response_abs_step <= response_abs_trust
                     END IF
                  END IF
               END IF
               IF (schur_attempt == 3 .AND. exact_attempt_response .AND. exact_physical_response_ready .AND. &
                   projector_physical_shadow_enabled .AND. &
                   projector_coupled_weight > EPSILON(projector_coupled_weight) .AND. &
                   (local_ot_env(1)%schur_projector_mode_quality_samples >= &
                    ot_kp_schur_calibration_min_samples .OR. &
                    projector_density_history_weight > EPSILON(projector_density_history_weight))) THEN
                  response_physical_model(:, :) = response_exact_physical(:, :)
                  IF (exact_density_full_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_full_exact(:, :)
                  ELSE IF (exact_density_direct_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_direct_exact(:, :)
                  ELSE IF (exact_density_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_exact(:, :)
                  END IF
                  projector_physical_model_e(:) = MATMUL(response_physical_model, sol)
                  CALL project_kpoint_ot_schur_response(projector_physical_model_e, occ_curv, tether_curv, &
                                                        occ_curv_projection_sum, channel_nmo, e_offset)
                  ! The physical shadow must see the active occupation-response
                  ! curvature and the fixed-N density response, not only the
                  ! tiny projector-basis gauge remainder.  The diagonal density
                  ! response is represented in response_physical_model below;
                  ! add the gauge-filtered off-diagonal projector Hessian to
                  ! the rotational metric used for the modal response audit.
                  projector_physical_direct_inactive_offdiag_weight = 0.0_dp
                  IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
                     IF (projector_inactive_offdiag_quality_for_selection* &
                         projector_inactive_offdiag_selected_scale > &
                         EPSILON(projector_inactive_offdiag_quality_for_selection)) THEN
                        projector_physical_direct_inactive_offdiag_balance = &
                           kpoint_ot_projector_negative_step_balance( &
                           projector_inactive_offdiag_history_quality* &
                           projector_inactive_offdiag_selected_scale, &
                           projector_inactive_offdiag_history_trust, &
                           projector_inactive_offdiag_history_response_ratio, &
                           local_ot_env(1)%schur_projector_inactive_offdiag_step_negative_ema)
                        projector_physical_direct_inactive_offdiag_weight = &
                           projector_coupled_weight* &
                           projector_inactive_offdiag_selected_scale* &
                           projector_physical_direct_inactive_offdiag_balance
                     ELSE
                        projector_physical_direct_inactive_offdiag_balance = &
                           kpoint_ot_projector_negative_step_balance( &
                           projector_mode_history_quality, &
                           local_ot_env(1)%schur_projector_mode_trust_ema, &
                           projector_mode_history_response_ratio, &
                           local_ot_env(1)%schur_projector_mode_step_negative_ema)
                        projector_physical_direct_inactive_offdiag_weight = &
                           projector_coupled_weight* &
                           projector_physical_direct_inactive_offdiag_balance
                     END IF
                  END IF
                  projector_physical_direct_delta(:, :) = &
                     rot_hessian_projector_physical(:, :) + &
                     rot_hessian_projector_physical_offdiag_active(:, :) + &
                     projector_physical_direct_inactive_offdiag_weight* &
                     (rot_hessian_projector_physical_offdiag(:, :) - &
                      rot_hessian_projector_physical_offdiag_active(:, :))
                  projector_physical_direct_delta(:, :) = &
                     0.5_dp*(projector_physical_direct_delta(:, :) + &
                             TRANSPOSE(projector_physical_direct_delta(:, :)))
                  CALL audit_kpoint_ot_projector_response_modes(rot_hessian, &
                                                                projector_physical_direct_delta, sol, &
                                                                response_exact_raw, response_physical_model, curv, &
                                                                occ_curv, tether_curv, occ_curv_projection_sum, &
                                                                channel_nmo, e_offset, .TRUE., &
                                                                projector_coupled_weight, residual_delta, &
                                                                projector_mode_history_quality, &
                                                                local_ot_env(1)%schur_projector_mode_trust_ema, &
                                                                projector_mode_history_response_ratio, grad_e, &
                                                                z_e + rx_e, rx_e, &
                                                                projector_physical_rx_e, projector_physical_response_weight, &
                                                                projector_physical_response_correction_drop, &
                                                                projector_physical_response_correction_negative, &
                                                                projector_physical_response_raw_negative_fraction, &
                                                                projector_physical_response_positive_drop, &
                                                                projector_physical_response_negative_drop, &
                                                                projector_physical_response_cross_drop, &
                                                                projector_physical_response_positive_coeff, &
                                                                projector_physical_response_negative_coeff, &
                                                                diag_base_weight= &
                                                                projector_physical_response_audit_base_weight, &
                                                                diag_response_total_sum= &
                                                                projector_physical_response_audit_response_total_sum, &
                                                                diag_step_weight_sum= &
                                                                projector_physical_response_audit_step_weight_sum, &
                                                                diag_eval_abs_avg= &
                                                                projector_physical_response_audit_eval_abs_avg, &
                                                                diag_positive_weight_sum= &
                                                                projector_physical_response_audit_positive_weight_sum, &
                                                                diag_negative_weight_sum= &
                                                                projector_physical_response_audit_negative_weight_sum, &
                                                                raw_residual_delta=response_raw_delta)
                  IF (projector_physical_response_weight > EPSILON(projector_physical_response_weight)) THEN
                     projector_physical_z_e(:) = z_e(:) + projector_physical_rx_e(:)
                     projector_physical_gdot_energy = DOT_PRODUCT(grad_e, projector_physical_z_e)
                     projector_physical_gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                     projector_physical_norm_energy = DOT_PRODUCT(projector_physical_z_e, projector_physical_z_e)
                     projector_physical_norm_rotation = DOT_PRODUCT(sol, sol)
                     projector_physical_gdotp = projector_physical_gdot_energy + projector_physical_gdot_rotation
                     projector_physical_normp = projector_physical_norm_energy + projector_physical_norm_rotation
                     projector_physical_norm_ratio = projector_physical_normp/MAX(gnorm, EPSILON(1.0_dp))
                     IF (projector_physical_gdotp > 0.0_dp .AND. &
                         projector_physical_normp > EPSILON(projector_physical_normp) .AND. &
                         projector_physical_norm_ratio <= max_norm_ratio) THEN
                        projector_physical_unit_abs_step = MAXVAL(ABS(projector_physical_rx_e))
                        CALL para_env_inter_kp%max(projector_physical_unit_abs_step)
                        projector_physical_unit_weighted_step = &
                           kpoint_ot_weighted_response_step(projector_physical_rx_e, curv, curv_projection_sum)
                        projector_physical_trust_scale = 1.0_dp
                        IF (response_trust > EPSILON(response_trust) .AND. &
                            projector_physical_unit_weighted_step > &
                            EPSILON(projector_physical_unit_weighted_step)) &
                           projector_physical_trust_scale = &
                           MIN(projector_physical_trust_scale, &
                               0.8_dp*response_trust/projector_physical_unit_weighted_step)
                        IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                            projector_physical_unit_abs_step > EPSILON(projector_physical_unit_abs_step)) &
                           projector_physical_trust_scale = &
                           MIN(projector_physical_trust_scale, &
                               0.8_dp*response_abs_trust/projector_physical_unit_abs_step)
                        projector_physical_direction_scale = &
                           MIN(1.0_dp, projector_physical_trust_scale, &
                               projector_physical_gdotp/ &
                               MAX(projector_physical_normp, EPSILON(projector_physical_normp)))
                        projector_physical_scale_quality = &
                           kpoint_ot_schur_scale_quality(projector_physical_direction_scale, schur_min_coupled_scale)
                        projector_physical_z_e(:) = projector_physical_direction_scale*projector_physical_z_e(:)
                        projector_physical_sol(:) = projector_physical_direction_scale*sol(:)
                        projector_physical_model_drop = projector_physical_direction_scale* &
                                                        projector_physical_gdotp - &
                                                        0.5_dp*projector_physical_direction_scale* &
                                                        projector_physical_direction_scale* &
                                                        projector_physical_normp
                        projector_physical_response_abs_step = &
                           projector_physical_direction_scale*projector_physical_unit_abs_step
                        projector_physical_response_weighted_step = &
                           projector_physical_direction_scale*projector_physical_unit_weighted_step
                        projector_physical_model_gap = &
                           projector_physical_direction_scale* &
                           MAXVAL(ABS(projector_physical_model_e - projector_physical_rx_e))
                        projector_physical_model_gap_drop = &
                           kpoint_ot_response_mismatch_drop(projector_physical_rx_e, projector_physical_model_e, curv, &
                                                            projector_physical_direction_scale)
                        projector_physical_model_calibrated_drop = &
                           MAX(0.0_dp, projector_physical_model_drop - projector_physical_model_gap_drop)
                        projector_physical_model_gap_trust = schur_model_gap_factor*response_trust
                        projector_physical_model_gap_ratio = 0.0_dp
                        IF (projector_physical_model_gap_trust > EPSILON(projector_physical_model_gap_trust)) &
                           projector_physical_model_gap_ratio = projector_physical_model_gap/ &
                                                                projector_physical_model_gap_trust
                        projector_physical_response_weighted_trust_ratio = 0.0_dp
                        IF (response_trust > EPSILON(response_trust)) &
                           projector_physical_response_weighted_trust_ratio = &
                           projector_physical_response_weighted_step/response_trust
                        projector_physical_response_abs_trust_ratio = 0.0_dp
                        IF (response_abs_trust > EPSILON(response_abs_trust)) &
                           projector_physical_response_abs_trust_ratio = &
                           projector_physical_response_abs_step/response_abs_trust
                        projector_physical_trust_quality = &
                           kpoint_ot_schur_trust_quality(projector_physical_response_weighted_trust_ratio, &
                                                         projector_physical_response_abs_trust_ratio, &
                                                         projector_physical_model_gap_ratio)
                        IF (projector_physical_direction_scale < schur_min_coupled_scale) &
                           projector_physical_model_calibrated_drop = &
                           projector_physical_scale_quality*projector_physical_model_calibrated_drop
                        projector_physical_expected_drop = &
                           kpoint_ot_schur_expected_drop(projector_physical_model_calibrated_drop, &
                                                         projector_physical_quality_for_selection, &
                                                         projector_physical_trust_quality)
                        projector_physical_candidate_ready = &
                           projector_physical_model_calibrated_drop > &
                           EPSILON(projector_physical_model_drop) .AND. &
                           projector_physical_response_weighted_step <= response_trust .AND. &
                           projector_physical_response_abs_step <= response_abs_trust
                     END IF
                  END IF
               END IF
               IF (schur_attempt == 3 .AND. exact_attempt_response .AND. &
                   exact_physical_response_ready .AND. &
                   projector_physical_direct_shadow_enabled .AND. &
                   projector_coupled_weight > EPSILON(projector_coupled_weight) .AND. &
                   projector_inactive_offdiag_quality_for_selection* &
                   projector_inactive_offdiag_selected_scale >= &
                   ot_kp_schur_projector_response_quality_min_ratio .AND. &
                   projector_inactive_offdiag_history_trust > &
                   EPSILON(projector_inactive_offdiag_history_trust)) THEN
                  projector_physical_direct_delta(:, :) = rot_hessian(:, :) + &
                                                          rot_hessian_projector_physical_offdiag(:, :) - &
                                                          rot_hessian_projector_physical_offdiag_active(:, :)
                  response_physical_model(:, :) = response_exact_physical(:, :)
                  IF (exact_density_full_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_full_exact(:, :)
                  ELSE IF (exact_density_direct_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_direct_exact(:, :)
                  ELSE IF (exact_density_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_exact(:, :)
                  END IF
                  projector_physical_model_e(:) = MATMUL(response_physical_model, sol)
                  CALL project_kpoint_ot_schur_response(projector_physical_model_e, &
                                                        occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                  CALL audit_kpoint_ot_projector_response_modes(rot_hessian, &
                                                                projector_physical_direct_delta, sol, response_exact_raw, &
                                                                response_physical_model, curv, occ_curv, tether_curv, &
                                                                occ_curv_projection_sum, channel_nmo, e_offset, .TRUE., &
                                                                projector_coupled_weight, residual_delta, &
                                                                projector_inactive_offdiag_history_quality, &
                                                                projector_inactive_offdiag_history_trust, &
                                                                projector_inactive_offdiag_history_response_ratio, grad_e, &
                                                                z_e + rx_e, rx_e, projector_inactive_offdiag_rx_e, &
                                                                projector_inactive_offdiag_response_weight, &
                                                                projector_inactive_offdiag_response_correction_drop, &
                                                                projector_inactive_offdiag_response_correction_negative, &
                                                                projector_inactive_offdiag_response_raw_negative_fraction, &
                                                                projector_inactive_offdiag_response_positive_drop, &
                                                                projector_inactive_offdiag_response_negative_drop, &
                                                                projector_inactive_offdiag_response_cross_drop, &
                                                                projector_inactive_offdiag_response_positive_coeff, &
                                                                projector_inactive_offdiag_response_negative_coeff, &
                                                                raw_residual_delta=response_raw_delta)
                  IF (projector_inactive_offdiag_response_weight > &
                      EPSILON(projector_inactive_offdiag_response_weight)) THEN
                     projector_inactive_offdiag_z_e(:) = &
                        z_e(:) + projector_inactive_offdiag_rx_e(:)
                     projector_inactive_offdiag_gdot_energy = &
                        DOT_PRODUCT(grad_e, projector_inactive_offdiag_z_e)
                     projector_inactive_offdiag_gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                     projector_inactive_offdiag_norm_energy = &
                        DOT_PRODUCT(projector_inactive_offdiag_z_e, &
                                    projector_inactive_offdiag_z_e)
                     projector_inactive_offdiag_norm_rotation = DOT_PRODUCT(sol, sol)
                     projector_inactive_offdiag_gdotp = &
                        projector_inactive_offdiag_gdot_energy + &
                        projector_inactive_offdiag_gdot_rotation
                     projector_inactive_offdiag_normp = &
                        projector_inactive_offdiag_norm_energy + &
                        projector_inactive_offdiag_norm_rotation
                     projector_inactive_offdiag_norm_ratio = &
                        projector_inactive_offdiag_normp/MAX(gnorm, EPSILON(1.0_dp))
                     IF (projector_inactive_offdiag_gdotp > 0.0_dp .AND. &
                         projector_inactive_offdiag_normp > &
                         EPSILON(projector_inactive_offdiag_normp) .AND. &
                         projector_inactive_offdiag_norm_ratio <= max_norm_ratio) THEN
                        projector_inactive_offdiag_unit_abs_step = &
                           MAXVAL(ABS(projector_inactive_offdiag_rx_e))
                        CALL para_env_inter_kp%max(projector_inactive_offdiag_unit_abs_step)
                        projector_inactive_offdiag_unit_weighted_step = &
                           kpoint_ot_weighted_response_step( &
                           projector_inactive_offdiag_rx_e, curv, curv_projection_sum)
                        projector_inactive_offdiag_trust_scale = 1.0_dp
                        IF (response_trust > EPSILON(response_trust) .AND. &
                            projector_inactive_offdiag_unit_weighted_step > &
                            EPSILON(projector_inactive_offdiag_unit_weighted_step)) &
                           projector_inactive_offdiag_trust_scale = &
                           MIN(projector_inactive_offdiag_trust_scale, &
                               0.8_dp*response_trust/ &
                               projector_inactive_offdiag_unit_weighted_step)
                        IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                            projector_inactive_offdiag_unit_abs_step > &
                            EPSILON(projector_inactive_offdiag_unit_abs_step)) &
                           projector_inactive_offdiag_trust_scale = &
                           MIN(projector_inactive_offdiag_trust_scale, &
                               0.8_dp*response_abs_trust/ &
                               projector_inactive_offdiag_unit_abs_step)
                        projector_inactive_offdiag_direction_scale = &
                           MIN(1.0_dp, projector_inactive_offdiag_trust_scale, &
                               projector_inactive_offdiag_gdotp/ &
                               MAX(projector_inactive_offdiag_normp, &
                                   EPSILON(projector_inactive_offdiag_normp)))
                        projector_inactive_offdiag_scale_quality = &
                           kpoint_ot_schur_scale_quality( &
                           projector_inactive_offdiag_direction_scale, &
                           schur_min_coupled_scale)
                        projector_inactive_offdiag_z_e(:) = &
                           projector_inactive_offdiag_direction_scale* &
                           projector_inactive_offdiag_z_e(:)
                        projector_inactive_offdiag_sol(:) = &
                           projector_inactive_offdiag_direction_scale*sol(:)
                        projector_inactive_offdiag_model_drop = &
                           projector_inactive_offdiag_direction_scale* &
                           projector_inactive_offdiag_gdotp - &
                           0.5_dp*projector_inactive_offdiag_direction_scale* &
                           projector_inactive_offdiag_direction_scale* &
                           projector_inactive_offdiag_normp
                        projector_inactive_offdiag_response_abs_step = &
                           projector_inactive_offdiag_direction_scale* &
                           projector_inactive_offdiag_unit_abs_step
                        projector_inactive_offdiag_response_weighted_step = &
                           projector_inactive_offdiag_direction_scale* &
                           projector_inactive_offdiag_unit_weighted_step
                        projector_inactive_offdiag_model_gap = &
                           projector_inactive_offdiag_direction_scale* &
                           MAXVAL(ABS(projector_physical_model_e - &
                                      projector_inactive_offdiag_rx_e))
                        projector_inactive_offdiag_model_gap_drop = &
                           kpoint_ot_response_mismatch_drop( &
                           projector_inactive_offdiag_rx_e, &
                           projector_physical_model_e, curv, &
                           projector_inactive_offdiag_direction_scale)
                        projector_inactive_offdiag_model_calibrated_drop = &
                           MAX(0.0_dp, projector_inactive_offdiag_model_drop - &
                               projector_inactive_offdiag_model_gap_drop)
                        projector_inactive_offdiag_model_gap_trust = &
                           schur_model_gap_factor*response_trust
                        IF (projector_inactive_offdiag_model_gap_trust > &
                            EPSILON(projector_inactive_offdiag_model_gap_trust)) &
                           projector_inactive_offdiag_model_gap_ratio = &
                           projector_inactive_offdiag_model_gap/ &
                           projector_inactive_offdiag_model_gap_trust
                        IF (response_trust > EPSILON(response_trust)) &
                           projector_inactive_offdiag_response_weighted_trust_ratio = &
                           projector_inactive_offdiag_response_weighted_step/ &
                           response_trust
                        IF (response_abs_trust > EPSILON(response_abs_trust)) &
                           projector_inactive_offdiag_response_abs_trust_ratio = &
                           projector_inactive_offdiag_response_abs_step/ &
                           response_abs_trust
                        projector_inactive_offdiag_trust_quality = &
                           kpoint_ot_schur_trust_quality( &
                           projector_inactive_offdiag_response_weighted_trust_ratio, &
                           projector_inactive_offdiag_response_abs_trust_ratio, &
                           projector_inactive_offdiag_model_gap_ratio)
                        IF (projector_inactive_offdiag_direction_scale < &
                            schur_min_coupled_scale) &
                           projector_inactive_offdiag_model_calibrated_drop = &
                           projector_inactive_offdiag_scale_quality* &
                           projector_inactive_offdiag_model_calibrated_drop
                        projector_inactive_offdiag_expected_drop = &
                           kpoint_ot_schur_expected_drop( &
                           projector_inactive_offdiag_model_calibrated_drop, &
                           projector_inactive_offdiag_quality_for_selection* &
                           projector_inactive_offdiag_selected_quality_for_selection, &
                           projector_inactive_offdiag_trust_quality)
                        projector_inactive_offdiag_candidate_ready = &
                           projector_inactive_offdiag_model_calibrated_drop > &
                           EPSILON(projector_inactive_offdiag_model_drop) .AND. &
                           projector_inactive_offdiag_response_weighted_step <= &
                           response_trust .AND. &
                           projector_inactive_offdiag_response_abs_step <= &
                           response_abs_trust
                     END IF
                  END IF
                  IF (projector_inactive_offdiag_candidate_ready .AND. &
                      projector_inactive_offdiag_expected_drop > &
                      EPSILON(projector_inactive_offdiag_expected_drop) .AND. &
                      (.NOT. projector_offdiag_candidate_ready .OR. &
                       projector_inactive_offdiag_expected_drop > &
                       projector_offdiag_expected_drop)) THEN
                     projector_offdiag_candidate_ready = .TRUE.
                     projector_offdiag_candidate_inactive = .TRUE.
                     projector_offdiag_direction_scale = &
                        projector_inactive_offdiag_direction_scale
                     projector_offdiag_expected_drop = &
                        projector_inactive_offdiag_expected_drop
                     projector_offdiag_gdot_energy = &
                        projector_inactive_offdiag_gdot_energy
                     projector_offdiag_gdot_rotation = &
                        projector_inactive_offdiag_gdot_rotation
                     projector_offdiag_gdotp = projector_inactive_offdiag_gdotp
                     projector_offdiag_model_calibrated_drop = &
                        projector_inactive_offdiag_model_calibrated_drop
                     projector_offdiag_model_drop = &
                        projector_inactive_offdiag_model_drop
                     projector_offdiag_model_gap = &
                        projector_inactive_offdiag_model_gap
                     projector_offdiag_model_gap_drop = &
                        projector_inactive_offdiag_model_gap_drop
                     projector_offdiag_model_gap_ratio = &
                        projector_inactive_offdiag_model_gap_ratio
                     projector_offdiag_model_gap_trust = &
                        projector_inactive_offdiag_model_gap_trust
                     projector_offdiag_norm_energy = &
                        projector_inactive_offdiag_norm_energy
                     projector_offdiag_norm_rotation = &
                        projector_inactive_offdiag_norm_rotation
                     projector_offdiag_normp = projector_inactive_offdiag_normp
                     projector_offdiag_norm_ratio = &
                        projector_inactive_offdiag_norm_ratio
                     projector_offdiag_response_abs_step = &
                        projector_inactive_offdiag_response_abs_step
                     projector_offdiag_response_abs_trust_ratio = &
                        projector_inactive_offdiag_response_abs_trust_ratio
                     projector_offdiag_response_weighted_step = &
                        projector_inactive_offdiag_response_weighted_step
                     projector_offdiag_response_weighted_trust_ratio = &
                        projector_inactive_offdiag_response_weighted_trust_ratio
                     projector_offdiag_scale_quality = &
                        projector_inactive_offdiag_scale_quality
                     projector_offdiag_trust_quality = &
                        projector_inactive_offdiag_trust_quality
                     projector_offdiag_trust_scale = &
                        projector_inactive_offdiag_trust_scale
                     projector_offdiag_unit_abs_step = &
                        projector_inactive_offdiag_unit_abs_step
                     projector_offdiag_unit_weighted_step = &
                        projector_inactive_offdiag_unit_weighted_step
                     projector_offdiag_response_correction_drop = &
                        projector_inactive_offdiag_response_correction_drop
                     projector_offdiag_response_correction_negative = &
                        projector_inactive_offdiag_response_correction_negative
                     projector_offdiag_response_negative_coeff = &
                        projector_inactive_offdiag_response_negative_coeff
                     projector_offdiag_response_positive_coeff = &
                        projector_inactive_offdiag_response_positive_coeff
                     projector_offdiag_response_cross_drop = &
                        projector_inactive_offdiag_response_cross_drop
                     projector_offdiag_response_negative_drop = &
                        projector_inactive_offdiag_response_negative_drop
                     projector_offdiag_response_positive_drop = &
                        projector_inactive_offdiag_response_positive_drop
                     projector_offdiag_response_raw_negative_fraction = &
                        projector_inactive_offdiag_response_raw_negative_fraction
                     projector_offdiag_response_weight = &
                        projector_inactive_offdiag_response_weight
                     projector_offdiag_rx_e(:) = projector_inactive_offdiag_rx_e(:)
                     projector_offdiag_z_e(:) = projector_inactive_offdiag_z_e(:)
                     projector_offdiag_sol(:) = projector_inactive_offdiag_sol(:)
                  END IF
               END IF
               IF (schur_attempt == 3 .AND. exact_attempt_response .AND. &
                   exact_physical_response_ready .AND. &
                   projector_physical_direct_shadow_enabled .AND. &
                   projector_coupled_weight > EPSILON(projector_coupled_weight) .AND. &
                   projector_offdiag_history_quality >= &
                   ot_kp_schur_projector_response_quality_min_ratio .AND. &
                   projector_offdiag_history_trust > EPSILON(projector_offdiag_history_trust)) THEN
                  projector_physical_direct_delta(:, :) = &
                     rot_hessian(:, :) + &
                     rot_hessian_projector_physical_offdiag_active(:, :)
                  response_physical_model(:, :) = response_exact_physical(:, :)
                  IF (exact_density_full_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_full_exact(:, :)
                  ELSE IF (exact_density_direct_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_direct_exact(:, :)
                  ELSE IF (exact_density_response_ready) THEN
                     response_physical_model(:, :) = response_physical_model(:, :) + &
                                                     response_density_exact(:, :)
                  END IF
                  projector_physical_model_e(:) = MATMUL(response_physical_model, sol)
                  CALL project_kpoint_ot_schur_response(projector_physical_model_e, &
                                                        occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                  CALL audit_kpoint_ot_projector_response_modes(rot_hessian, &
                                                                projector_physical_direct_delta, sol, &
                                                                response_exact_raw, response_physical_model, curv, &
                                                                occ_curv, tether_curv, occ_curv_projection_sum, &
                                                                channel_nmo, e_offset, .TRUE., &
                                                                projector_coupled_weight, residual_delta, &
                                                                projector_offdiag_history_quality, &
                                                                projector_offdiag_history_trust, &
                                                                projector_offdiag_history_response_ratio, grad_e, &
                                                                z_e + rx_e, rx_e, &
                                                                projector_offdiag_rx_e, &
                                                                projector_offdiag_response_weight, &
                                                                projector_offdiag_response_correction_drop, &
                                                                projector_offdiag_response_correction_negative, &
                                                                projector_offdiag_response_raw_negative_fraction, &
                                                                projector_offdiag_response_positive_drop, &
                                                                projector_offdiag_response_negative_drop, &
                                                                projector_offdiag_response_cross_drop, &
                                                                projector_offdiag_response_positive_coeff, &
                                                                projector_offdiag_response_negative_coeff, &
                                                                raw_residual_delta=response_raw_delta)
                  IF (projector_offdiag_response_weight > &
                      EPSILON(projector_offdiag_response_weight)) THEN
                     projector_offdiag_z_e(:) = z_e(:) + projector_offdiag_rx_e(:)
                     projector_offdiag_gdot_energy = DOT_PRODUCT(grad_e, projector_offdiag_z_e)
                     projector_offdiag_gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                     projector_offdiag_norm_energy = DOT_PRODUCT(projector_offdiag_z_e, &
                                                                 projector_offdiag_z_e)
                     projector_offdiag_norm_rotation = DOT_PRODUCT(sol, sol)
                     projector_offdiag_gdotp = projector_offdiag_gdot_energy + &
                                               projector_offdiag_gdot_rotation
                     projector_offdiag_normp = projector_offdiag_norm_energy + &
                                               projector_offdiag_norm_rotation
                     projector_offdiag_norm_ratio = projector_offdiag_normp/ &
                                                    MAX(gnorm, EPSILON(1.0_dp))
                     IF (projector_offdiag_gdotp > 0.0_dp .AND. &
                         projector_offdiag_normp > EPSILON(projector_offdiag_normp) .AND. &
                         projector_offdiag_norm_ratio <= max_norm_ratio) THEN
                        projector_offdiag_unit_abs_step = MAXVAL(ABS(projector_offdiag_rx_e))
                        CALL para_env_inter_kp%max(projector_offdiag_unit_abs_step)
                        projector_offdiag_unit_weighted_step = &
                           kpoint_ot_weighted_response_step(projector_offdiag_rx_e, curv, &
                                                            curv_projection_sum)
                        projector_offdiag_abs_trust = &
                           kpoint_ot_offdiag_tail_abs_trust(response_abs_trust, residual_delta, &
                                                            sigma, step_gauge_quality)
                        projector_offdiag_trust_scale = 1.0_dp
                        IF (response_trust > EPSILON(response_trust) .AND. &
                            projector_offdiag_unit_weighted_step > &
                            EPSILON(projector_offdiag_unit_weighted_step)) &
                           projector_offdiag_trust_scale = &
                           MIN(projector_offdiag_trust_scale, &
                               0.8_dp*response_trust/ &
                               projector_offdiag_unit_weighted_step)
                        IF (projector_offdiag_abs_trust > EPSILON(projector_offdiag_abs_trust) .AND. &
                            projector_offdiag_unit_abs_step > &
                            EPSILON(projector_offdiag_unit_abs_step)) &
                           projector_offdiag_trust_scale = &
                           MIN(projector_offdiag_trust_scale, &
                               0.8_dp*projector_offdiag_abs_trust/ &
                               projector_offdiag_unit_abs_step)
                        projector_offdiag_direction_scale = &
                           MIN(1.0_dp, projector_offdiag_trust_scale, &
                               projector_offdiag_gdotp/ &
                               MAX(projector_offdiag_normp, &
                                   EPSILON(projector_offdiag_normp)))
                        projector_offdiag_scale_quality = &
                           kpoint_ot_schur_scale_quality(projector_offdiag_direction_scale, &
                                                         schur_min_coupled_scale)
                        projector_offdiag_z_e(:) = projector_offdiag_direction_scale* &
                                                   projector_offdiag_z_e(:)
                        projector_offdiag_sol(:) = projector_offdiag_direction_scale*sol(:)
                        projector_offdiag_model_drop = projector_offdiag_direction_scale* &
                                                       projector_offdiag_gdotp - &
                                                       0.5_dp*projector_offdiag_direction_scale* &
                                                       projector_offdiag_direction_scale*projector_offdiag_normp
                        projector_offdiag_response_abs_step = &
                           projector_offdiag_direction_scale*projector_offdiag_unit_abs_step
                        projector_offdiag_response_weighted_step = &
                           projector_offdiag_direction_scale* &
                           projector_offdiag_unit_weighted_step
                        projector_offdiag_model_gap = projector_offdiag_direction_scale* &
                                                      MAXVAL(ABS(projector_physical_model_e - projector_offdiag_rx_e))
                        projector_offdiag_model_gap_drop = &
                           kpoint_ot_response_mismatch_drop(projector_offdiag_rx_e, &
                                                            projector_physical_model_e, curv, &
                                                            projector_offdiag_direction_scale)
                        projector_offdiag_model_calibrated_drop = &
                           MAX(0.0_dp, projector_offdiag_model_drop - &
                               projector_offdiag_model_gap_drop)
                        projector_offdiag_model_gap_trust = schur_model_gap_factor*response_trust
                        IF (projector_offdiag_model_gap_trust > &
                            EPSILON(projector_offdiag_model_gap_trust)) &
                           projector_offdiag_model_gap_ratio = &
                           projector_offdiag_model_gap/projector_offdiag_model_gap_trust
                        IF (response_trust > EPSILON(response_trust)) &
                           projector_offdiag_response_weighted_trust_ratio = &
                           projector_offdiag_response_weighted_step/response_trust
                        IF (projector_offdiag_abs_trust > EPSILON(projector_offdiag_abs_trust)) &
                           projector_offdiag_response_abs_trust_ratio = &
                           projector_offdiag_response_abs_step/projector_offdiag_abs_trust
                        projector_offdiag_trust_quality = &
                           kpoint_ot_schur_trust_quality( &
                           projector_offdiag_response_weighted_trust_ratio, &
                           projector_offdiag_response_abs_trust_ratio, &
                           projector_offdiag_model_gap_ratio)
                        IF (projector_offdiag_direction_scale < schur_min_coupled_scale) &
                           projector_offdiag_model_calibrated_drop = &
                           projector_offdiag_scale_quality* &
                           projector_offdiag_model_calibrated_drop
                        projector_offdiag_expected_drop = &
                           kpoint_ot_schur_expected_drop( &
                           projector_offdiag_model_calibrated_drop, &
                           projector_offdiag_quality_for_selection, &
                           projector_offdiag_trust_quality)
                        projector_offdiag_candidate_ready = &
                           projector_offdiag_model_calibrated_drop > &
                           EPSILON(projector_offdiag_model_drop) .AND. &
                           projector_offdiag_response_weighted_step <= response_trust .AND. &
                           projector_offdiag_response_abs_step <= projector_offdiag_abs_trust
                     END IF
                  END IF
               END IF
               IF (schur_attempt == 3 .AND. exact_attempt_response .AND. &
                   exact_physical_response_ready .AND. &
                   projector_physical_shadow_enabled .AND. &
                   projector_coupled_weight > EPSILON(projector_coupled_weight) .AND. &
                   (local_ot_env(1)%schur_projector_mode_quality_samples >= &
                    ot_kp_schur_calibration_min_samples .OR. &
                    projector_density_history_weight > EPSILON(projector_density_history_weight))) THEN
                  projector_physical_direct_delta(:, :) = &
                     0.5_dp*((rot_hessian_projector_physical(:, :) - rot_hessian(:, :)) + &
                             TRANSPOSE(rot_hessian_projector_physical(:, :) - &
                                       rot_hessian(:, :)))
                  projector_physical_direct_delta_diag_avg = 0.0_dp
                  projector_physical_direct_active_delta_diag_avg = 0.0_dp
                  DO r = 1, nrot
                     projector_physical_direct_delta_diag_avg = &
                        projector_physical_direct_delta_diag_avg + &
                        projector_physical_direct_delta(r, r)
                     projector_physical_direct_active_delta_diag_avg = &
                        projector_physical_direct_active_delta_diag_avg + &
                        rot_hessian_projector_physical_active(r, r) - rot_hessian(r, r)
                  END DO
                  projector_physical_direct_delta_diag_avg = &
                     projector_physical_direct_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  projector_physical_direct_active_delta_diag_avg = &
                     projector_physical_direct_active_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  projector_physical_direct_trace_active_basis_weight = 0.0_dp
                  IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
                     projector_physical_direct_trace_active_basis_weight = &
                     kpoint_ot_trace_active_basis_weight( &
                     local_ot_env(1)%schur_projector_physical_trace_raw_ema, &
                     local_ot_env(1)%schur_projector_physical_trace_active_ema, &
                     local_ot_env(1)%schur_projector_mixed_direct_quality_ema, &
                     local_ot_env(1)%schur_projector_mixed_direct_quality_samples)
                  IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                      local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples >= &
                      ot_kp_schur_calibration_min_samples) THEN
                     projector_physical_direct_trace_selected_quality = &
                        MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                                        local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema))
                     projector_physical_direct_trace_residual_support = &
                        kpoint_ot_selected_tail_mix_residual_quality( &
                        local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality, &
                        local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema)
                     projector_physical_direct_trace_residual_support = &
                        MAX(projector_physical_direct_trace_residual_support, &
                            0.25_dp*SQRT(MAX(0.0_dp, &
                                             MIN(1.0_dp, &
                                                 local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema/ &
                                                 MAX(ot_kp_schur_calibrated_quality_min_ratio, &
                                                     EPSILON(1.0_dp))))))
                     projector_physical_direct_trace_selected_quality = &
                        projector_physical_direct_trace_selected_quality* &
                        projector_physical_direct_trace_residual_support
                     projector_physical_direct_trace_active_basis_weight = &
                        MAX(projector_physical_direct_trace_active_basis_weight, &
                            kpoint_ot_trace_active_basis_weight( &
                            local_ot_env(1)%schur_projector_physical_trace_raw_ema, &
                            local_ot_env(1)%schur_projector_physical_trace_active_ema, &
                            projector_physical_direct_trace_selected_quality, &
                            local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples))
                  END IF
                  projector_physical_direct_trace_active_basis_weight = &
                     kpoint_ot_physical_direct_density_mix( &
                     projector_physical_direct_trace_active_basis_weight, &
                     projector_density_active_mix_weight, residual_delta, projector_coupled_weight)
                  IF (projector_physical_direct_trace_active_basis_weight > &
                      EPSILON(projector_physical_direct_trace_active_basis_weight)) THEN
                     projector_physical_direct_delta(:, :) = &
                        (1.0_dp - projector_physical_direct_trace_active_basis_weight)* &
                        projector_physical_direct_delta(:, :) + &
                        projector_physical_direct_trace_active_basis_weight*0.5_dp* &
                        ((rot_hessian_projector_physical_active(:, :) - rot_hessian(:, :)) + &
                         TRANSPOSE(rot_hessian_projector_physical_active(:, :) - rot_hessian(:, :)))
                     projector_physical_direct_delta_diag_avg = 0.0_dp
                     DO r = 1, nrot
                        projector_physical_direct_delta_diag_avg = &
                           projector_physical_direct_delta_diag_avg + projector_physical_direct_delta(r, r)
                     END DO
                     projector_physical_direct_delta_diag_avg = &
                        projector_physical_direct_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  END IF
                  projector_physical_direct_trace_base_diag_avg = &
                     projector_physical_direct_delta_diag_avg
                  projector_physical_direct_diag_compensation = 0.0_dp
                  projector_physical_direct_active_diag_compensation = 0.0_dp
                  projector_physical_direct_active_lcomp(:) = 0.0_dp
                  projector_physical_direct_diag_compensation_local_avg = 0.0_dp
                  projector_physical_direct_diag_compensation_local_fraction = 0.0_dp
                  projector_physical_direct_diag_compensation_local_max = 0.0_dp
                  projector_phys_direct_comp_trial = &
                     kpoint_ot_direct_trace_compensation(projector_coupled_weight, &
                                                         projector_physical_direct_delta_diag_avg, &
                                                         projector_hessian_delta_diag_avg)
                  projector_phys_direct_active_comp_trial = &
                     kpoint_ot_direct_trace_compensation(projector_coupled_weight, &
                                                         projector_physical_direct_active_delta_diag_avg, &
                                                         projector_hessian_delta_diag_avg)
                  projector_phys_direct_lcomp_trial_avg = 0.0_dp
                  projector_phys_direct_lcomp_trial_frac = 0.0_dp
                  projector_phys_direct_lcomp_trial_max = 0.0_dp
                  DO r = 1, nrot
                     projected_term = rot_hessian_projector(r, r) - rot_hessian(r, r)
                     diag_shift = kpoint_ot_direct_trace_compensation( &
                                  projector_coupled_weight, projector_physical_direct_delta(r, r), &
                                  projected_term)
                     projector_phys_direct_lcomp_trial_avg = &
                        projector_phys_direct_lcomp_trial_avg + diag_shift
                     projector_phys_direct_lcomp_trial_max = &
                        MAX(projector_phys_direct_lcomp_trial_max, diag_shift)
                     IF (diag_shift > 0.0_dp) &
                        projector_phys_direct_lcomp_trial_frac = &
                        projector_phys_direct_lcomp_trial_frac + 1.0_dp
                  END DO
                  projector_phys_direct_lcomp_trial_avg = &
                     projector_phys_direct_lcomp_trial_avg/REAL(MAX(1, nrot), KIND=dp)
                  projector_phys_direct_lcomp_trial_frac = &
                     projector_phys_direct_lcomp_trial_frac/REAL(MAX(1, nrot), KIND=dp)
                  projector_physical_direct_trace_diag_scale = &
                     kpoint_ot_trace_diag_component_scale( &
                     local_ot_env(1)%schur_projector_physical_trace_actual_diag_ema, &
                     local_ot_env(1)%schur_projector_physical_trace_actual_free_ema, &
                     local_ot_env(1)%schur_projector_physical_trace_actual_diag_quality_ema, &
                     local_ot_env(1)%schur_projector_physical_trace_actual_free_quality_ema, &
                     local_ot_env(1)%schur_projector_physical_quality_samples)
                  projector_physical_direct_trace_free_scale = 1.0_dp
                  projector_physical_direct_basis_signal = 0.0_dp
                  IF (projector_phys_direct_lcomp_trial_frac >= &
                      ot_kp_added_mos_auto_basis_signal_frac) THEN
                     projector_physical_direct_basis_signal = &
                        projector_phys_direct_lcomp_trial_frac*projector_phys_direct_comp_trial/ &
                        MAX(kpoint_ot_fermi_window_anchor(sigma), EPSILON(1.0_dp))
                     local_ot_env(1)%added_mos_auto_basis_signal = &
                        MAX(local_ot_env(1)%added_mos_auto_basis_signal, &
                            projector_physical_direct_basis_signal)
                  END IF
                  projector_physical_direct_basis_tail_limited = .FALSE.
                  projector_physical_direct_trace_tail_limited = .FALSE.
                  IF (added_mos_auto_tail_enabled) THEN
                     projector_physical_direct_basis_tail_limited = &
                        projector_physical_direct_basis_signal >= &
                        ot_kp_added_mos_auto_direct_veto_basis_frac* &
                        ot_kp_added_mos_auto_basis_signal_min .AND. &
                        residual_delta <= added_mos_auto_tail_residual_limit
                  END IF
                  IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
                     projector_physical_direct_diag_compensation = &
                        projector_physical_direct_trace_diag_scale* &
                        projector_phys_direct_lcomp_trial_avg
                     projector_physical_direct_active_diag_compensation = &
                        projector_physical_direct_trace_diag_scale* &
                        projector_phys_direct_active_comp_trial
                     ! Retain the trace curvature implied by the finite
                     ! Projector response inside the Direct curvature matrix,
                     ! but apply it only to the rows that actually need the
                     ! compensation.  A homogeneous average shift hardens
                     ! unrelated rotation modes in the metallic tail.
                     projector_physical_direct_diag_compensation_local_avg = &
                        projector_physical_direct_trace_diag_scale* &
                        projector_phys_direct_lcomp_trial_avg
                     projector_physical_direct_diag_compensation_local_fraction = &
                        projector_phys_direct_lcomp_trial_frac
                     projector_physical_direct_diag_compensation_local_max = &
                        projector_physical_direct_trace_diag_scale* &
                        projector_phys_direct_lcomp_trial_max
                     IF (projector_coupled_weight > EPSILON(projector_coupled_weight)) THEN
                        IF (projector_phys_direct_lcomp_trial_max > 0.0_dp) THEN
                           DO r = 1, nrot
                              projected_term = rot_hessian_projector(r, r) - rot_hessian(r, r)
                              diag_shift = kpoint_ot_direct_trace_compensation( &
                                           projector_coupled_weight, &
                                           projector_physical_direct_delta(r, r), projected_term)
                              diag_shift = projector_physical_direct_trace_diag_scale*diag_shift
                              IF (diag_shift <= 0.0_dp) CYCLE
                              projector_physical_direct_delta(r, r) = &
                                 projector_physical_direct_delta(r, r) + &
                                 diag_shift/projector_coupled_weight
                           END DO
                        END IF
                        DO r = 1, nrot
                           projected_term = rot_hessian_projector(r, r) - rot_hessian(r, r)
                           diag_shift = kpoint_ot_direct_trace_compensation( &
                                        projector_coupled_weight, &
                                        rot_hessian_projector_physical_active(r, r) - rot_hessian(r, r), &
                                        projected_term)
                           projector_physical_direct_active_lcomp(r) = &
                              projector_physical_direct_trace_diag_scale*diag_shift
                        END DO
                     END IF
                  END IF
                  projector_physical_direct_delta_diag_avg = 0.0_dp
                  DO r = 1, nrot
                     projector_physical_direct_delta_diag_avg = &
                        projector_physical_direct_delta_diag_avg + &
                        projector_physical_direct_delta(r, r)
                  END DO
                  projector_physical_direct_delta_diag_avg = &
                     projector_physical_direct_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  projector_physical_direct_trace_scale_diag_avg = &
                     projector_physical_direct_delta_diag_avg
                  projector_physical_direct_trace_local_separate_weight = &
                     MAX(0.0_dp, projector_physical_direct_trace_diag_scale - &
                         SQRT(ot_kp_schur_calibrated_quality_min_ratio))/ &
                     MAX(EPSILON(1.0_dp), &
                         1.0_dp - SQRT(ot_kp_schur_calibrated_quality_min_ratio))
                  projector_physical_direct_trace_local_separate_weight = &
                     MIN(1.0_dp, projector_physical_direct_trace_local_separate_weight)
                  projector_physical_direct_trace_scale_diag_avg = &
                     (1.0_dp - projector_physical_direct_trace_local_separate_weight)* &
                     projector_physical_direct_trace_scale_diag_avg + &
                     projector_physical_direct_trace_local_separate_weight* &
                     projector_physical_direct_trace_base_diag_avg
                  IF (ABS(projector_physical_direct_trace_diag_scale - 1.0_dp) > &
                      EPSILON(1.0_dp) .OR. &
                      ABS(projector_physical_direct_trace_free_scale - 1.0_dp) > &
                      EPSILON(1.0_dp)) THEN
                     projector_physical_direct_delta(:, :) = &
                        projector_physical_direct_trace_free_scale*projector_physical_direct_delta(:, :)
                     diag_shift = (projector_physical_direct_trace_diag_scale - &
                                   projector_physical_direct_trace_free_scale)* &
                                  projector_physical_direct_trace_scale_diag_avg
                     DO r = 1, nrot
                        projector_physical_direct_delta(r, r) = &
                           projector_physical_direct_delta(r, r) + diag_shift
                     END DO
                     projector_physical_direct_delta_diag_avg = 0.0_dp
                     DO r = 1, nrot
                        projector_physical_direct_delta_diag_avg = &
                           projector_physical_direct_delta_diag_avg + &
                           projector_physical_direct_delta(r, r)
                     END DO
                     projector_physical_direct_delta_diag_avg = &
                        projector_physical_direct_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  END IF
                  IF (projector_plateau_gap_model_enabled) &
                     projector_physical_direct_plateau_gap_mix_weight = &
                     kpoint_ot_projector_plateau_gap_mix_weight( &
                     residual_delta, projector_plateau_gap_quality_for_selection, &
                     local_ot_env(1)%schur_projector_plateau_gap_quality_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_weight_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_negative_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_step_ema, &
                     local_ot_env(1)%schur_projector_plateau_gap_quality_samples)
                  IF (projector_physical_direct_plateau_gap_mix_weight > &
                      EPSILON(projector_physical_direct_plateau_gap_mix_weight)) THEN
                     projector_physical_direct_delta(:, :) = projector_physical_direct_delta(:, :) + &
                        projector_physical_direct_plateau_gap_mix_weight* &
                        (rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                         rot_hessian_projector_physical_offdiag_active(:, :))
                     projector_physical_direct_delta_diag_avg = 0.0_dp
                     DO r = 1, nrot
                        projector_physical_direct_delta_diag_avg = &
                           projector_physical_direct_delta_diag_avg + &
                           projector_physical_direct_delta(r, r)
                     END DO
                     projector_physical_direct_delta_diag_avg = &
                        projector_physical_direct_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  END IF
                  projector_physical_direct_base_delta(:, :) = projector_physical_direct_delta(:, :)
                  ! Promote mixed active/physical curvature from accepted-drop history, not
                  ! from an absolute residual tail threshold.
                  IF (local_ot_env(1)%schur_projector_mixed_direct_quality_samples >= &
                      ot_kp_schur_projector_response_min_samples .AND. &
                      local_ot_env(1)%schur_projector_mixed_direct_weight_ema > &
                      EPSILON(local_ot_env(1)%schur_projector_mixed_direct_weight_ema)) THEN
                     projector_physical_direct_mixed_quality = &
                        kpoint_ot_schur_history_quality( &
                        local_ot_env(1)%schur_projector_mixed_direct_drop_sum, &
                        local_ot_env(1)%schur_projector_mixed_direct_measured_sum, &
                        local_ot_env(1)%schur_projector_mixed_direct_quality_ema, &
                        local_ot_env(1)%schur_projector_mixed_direct_quality_samples, &
                        ot_kp_schur_projector_response_min_samples, 0.0_dp, 0.0_dp, &
                        ot_kp_schur_projector_response_quality_max_ratio)
                     projector_physical_direct_mixed_drop_ratio = 0.0_dp
                     IF (local_ot_env(1)%schur_projector_mixed_direct_drop_sum > &
                         EPSILON(local_ot_env(1)%schur_projector_mixed_direct_drop_sum)) &
                        projector_physical_direct_mixed_drop_ratio = &
                        local_ot_env(1)%schur_projector_mixed_direct_measured_sum/ &
                        local_ot_env(1)%schur_projector_mixed_direct_drop_sum
                     projector_physical_direct_mixed_step_scale = &
                        kpoint_ot_direct_history_step_scale( &
                        projector_physical_direct_mixed_quality, &
                        local_ot_env(1)%schur_projector_mixed_direct_quality_samples, &
                        ot_kp_schur_projector_response_min_samples)
                     projector_physical_direct_mixed_consistency_scale = &
                        kpoint_ot_direct_history_consistency_scale( &
                        projector_physical_direct_mixed_drop_ratio, &
                        local_ot_env(1)%schur_projector_mixed_direct_quality_ema)
                     ! Large measured/predicted ratios mean that the
                     ! mixed Direct shadow is conservative.  Do not
                     ! reject such accepted history here; the actual
                     ! step and selection quality remain limited by the
                     ! shadow weight, quality clamp, maturity scale and
                     ! consistency scale below.
                     projector_physical_direct_mixed_promoted = &
                        kpoint_ot_mixed_direct_promoted( &
                        local_ot_env(1)%schur_projector_mixed_direct_quality_samples, &
                        ot_kp_schur_projector_response_min_samples, &
                        projector_physical_direct_mixed_drop_ratio, &
                        projector_physical_direct_mixed_quality, &
                        local_ot_env(1)%schur_projector_mixed_direct_quality_ema, &
                        local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema, &
                        local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples)
                     ! The mixed active/physical Direct curvature has its own
                     ! accepted-drop audit, but production use needs long
                     ! aggregate evidence plus selected-Direct support.  Early
                     ! shadow promotion was stable but slowed the residual tail.
                     projector_physical_direct_mixed_enabled = &
                        projector_physical_direct_mixed_promoted
                     IF (projector_physical_direct_mixed_enabled) THEN
                        ! The accepted mixed-Direct shadow weight is the
                        ! conservative production baseline.  Selected-Direct
                        ! trace separation may raise it, but lack of selected
                        ! samples must not create a circular no-mix state.
                        projector_physical_direct_mixed_weight = MIN( &
                                                                 ot_kp_schur_projector_trace_active_max_weight, &
                                                                 MAX(0.0_dp, &
                                                                     local_ot_env(1)%schur_projector_mixed_direct_weight_ema)* &
                                                                 MIN(1.0_dp, MAX(0.0_dp, &
                                                                                 projector_physical_direct_mixed_quality))* &
                                                                 projector_physical_direct_mixed_step_scale)
                        projector_physical_direct_mixed_weight = MAX( &
                                                                 projector_physical_direct_mixed_weight, &
                                                                 kpoint_ot_trace_active_mix_weight( &
                                                                 local_ot_env(1)%schur_projector_physical_trace_raw_ema, &
                                                                 local_ot_env(1)%schur_projector_physical_trace_active_ema, &
                                                                 local_ot_env(1)%schur_projector_mixed_direct_weight_ema, &
                                                                 local_ot_env(1)%schur_projector_mixed_direct_quality_ema, &
                                                                 local_ot_env(1)%schur_projector_mixed_direct_quality_samples, &
                                                             local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema, &
                                                          local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples))
                        projector_physical_direct_mixed_weight = &
                           projector_physical_direct_mixed_weight* &
                           projector_physical_direct_mixed_consistency_scale
                        projector_physical_direct_delta(:, :) = &
                           (1.0_dp - projector_physical_direct_mixed_weight)* &
                           projector_physical_direct_base_delta(:, :) + &
                           projector_physical_direct_mixed_weight*0.5_dp* &
                           ((rot_hessian_projector_physical_active(:, :) - rot_hessian(:, :)) + &
                            TRANSPOSE(rot_hessian_projector_physical_active(:, :) - &
                                      rot_hessian(:, :)))
                        IF (projector_coupled_weight > EPSILON(projector_coupled_weight)) THEN
                           DO r = 1, nrot
                              diag_shift = projector_physical_direct_mixed_weight* &
                                           projector_physical_direct_active_lcomp(r)/ &
                                           projector_coupled_weight
                              IF (diag_shift <= 0.0_dp) CYCLE
                              projector_physical_direct_delta(r, r) = &
                                 projector_physical_direct_delta(r, r) + diag_shift
                           END DO
                        END IF
                        projector_physical_direct_quality_for_selection = &
                           MAX(projector_physical_direct_quality_for_selection, &
                               MIN(1.0_dp, MAX(0.0_dp, &
                                               projector_physical_direct_mixed_quality))* &
                               MIN(1.0_dp, MAX(0.0_dp, &
                                               projector_physical_direct_mixed_consistency_scale)))
                        projector_physical_direct_delta_diag_avg = 0.0_dp
                        DO r = 1, nrot
                           projector_physical_direct_delta_diag_avg = &
                              projector_physical_direct_delta_diag_avg + &
                              projector_physical_direct_delta(r, r)
                        END DO
                        projector_physical_direct_delta_diag_avg = &
                           projector_physical_direct_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                     END IF
                  END IF
                  IF (projector_offdiag_quality_for_selection > &
                      EPSILON(projector_offdiag_quality_for_selection)) THEN
                     projector_physical_direct_offdiag_mix_weight = MIN( &
                                                                    ot_kp_schur_projector_trace_active_max_weight, &
                                                                    projector_offdiag_quality_for_selection)
                     projector_physical_direct_delta(:, :) = &
                        projector_physical_direct_delta(:, :) + &
                        projector_physical_direct_offdiag_mix_weight* &
                        rot_hessian_projector_physical_offdiag_active(:, :)
                     projector_physical_direct_delta(:, :) = 0.5_dp* &
                                                             (projector_physical_direct_delta(:, :) + &
                                                              TRANSPOSE(projector_physical_direct_delta(:, :)))
                     IF (residual_delta <= 0.25_dp* &
                         ot_kp_schur_projector_coupled_tail_delta .AND. &
                         local_ot_env(1)%schur_projector_density_full_direct_quality_samples >= &
                         2*ot_kp_schur_projector_response_min_samples .AND. &
                         local_ot_env(1)%schur_projector_density_full_direct_quality_ema >= &
                         ot_kp_schur_projector_response_quality_min_ratio) THEN
                        ! Use the offdiag finite-complex Projector history only
                        ! as a late-tail Direct quality floor.  Earlier use
                        ! perturbs the robust full-density descent path.
                        projector_physical_direct_quality_for_selection = &
                           MAX(projector_physical_direct_quality_for_selection, &
                               MIN(1.0_dp, MAX(0.0_dp, projector_offdiag_quality_for_selection))* &
                               MIN(1.0_dp, MAX(0.0_dp, projector_physical_trace_split_quality)))
                     END IF
                     projector_physical_direct_delta_diag_avg = 0.0_dp
                     DO r = 1, nrot
                        projector_physical_direct_delta_diag_avg = &
                           projector_physical_direct_delta_diag_avg + &
                           projector_physical_direct_delta(r, r)
                     END DO
                     projector_physical_direct_delta_diag_avg = &
                        projector_physical_direct_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
                  END IF
                  schur(:, :) = rot_hessian_coupled(:, :) + &
                                projector_coupled_weight* &
                                projector_physical_direct_delta(:, :)
                  projector_physical_direct_curv_cap = 0.0_dp
                  projector_physical_direct_curv_clip_sum = 0.0_dp
                  projector_physical_direct_curv_clip_max = 0.0_dp
                  projector_physical_direct_curv_diag_max = 0.0_dp
                  projector_physical_direct_curv_eval_min = 0.0_dp
                  projector_physical_direct_curv_eval_max = 0.0_dp
                  IF (projector_physical_direct_spectral_enabled) THEN
                     IF (sigma > EPSILON(sigma)) &
                        projector_physical_direct_curv_cap = kpoint_ot_fermi_window_anchor(sigma)
                     DO r = 1, nrot
                        projected_term = projector_physical_direct_delta(r, r)
                        projector_physical_direct_curv_diag_max = &
                           MAX(projector_physical_direct_curv_diag_max, projected_term)
                        IF (projected_term > projector_physical_direct_curv_cap) THEN
                           diag_shift = projected_term - projector_physical_direct_curv_cap
                           projector_physical_direct_curv_clip_sum = &
                              projector_physical_direct_curv_clip_sum + diag_shift
                           projector_physical_direct_curv_clip_max = &
                              MAX(projector_physical_direct_curv_clip_max, diag_shift)
                        END IF
                     END DO
                     projector_physical_direct_curv_clip_avg = &
                        projector_physical_direct_curv_clip_sum/REAL(MAX(1, nrot), KIND=dp)
                  END IF
                  IF (logger%iter_info%print_level >= high_print_level .OR. &
                      projector_physical_direct_spectral_enabled) THEN
                     projector_physical_direct_curv_evec(:, :) = &
                        0.5_dp*(projector_physical_direct_delta(:, :) + &
                                TRANSPOSE(projector_physical_direct_delta(:, :)))
                     CALL diamat_all(projector_physical_direct_curv_evec, &
                                     projector_physical_direct_curv_eval)
                     projector_physical_direct_curv_eval_min = &
                        MINVAL(projector_physical_direct_curv_eval)
                     projector_physical_direct_curv_eval_max = &
                        MAXVAL(projector_physical_direct_curv_eval)
                  END IF
                  DO r = 1, nrot
                     rtd(r) = grad_rot(r) + DOT_PRODUCT(response_exact_physical(:, r), grad_e)
                     IF (exact_density_direct_response_ready) &
                        rtd(r) = rtd(r) + DOT_PRODUCT(response_density_direct_exact(:, r), grad_e)
                     projector_physical_direct_sol(r) = rtd(r)
                  END DO
                  DO s = 1, nrot
                     DO r = 1, nrot
                        ! The physical-direct candidate solves the same reduced
                        ! fixed-N Mermin subproblem that supplies its occupation
                        ! response.  Use the corresponding self response in the
                        ! Schur curvature, and leave the raw/physical mismatch to
                        ! the line-search model-gap audit below.
                        projected_term = 0.5_dp* &
                                         (DOT_PRODUCT(energy_cross_physical(:, r), &
                                                      response_exact_physical(:, s)) + &
                                          DOT_PRODUCT(energy_cross_physical(:, s), &
                                                      response_exact_physical(:, r)))
                        IF (exact_density_direct_response_ready) &
                           projected_term = projected_term + 0.5_dp* &
                                            (DOT_PRODUCT(energy_cross_physical(:, r), &
                                                         response_density_direct_exact(:, s)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, r), &
                                                         response_exact_physical(:, s)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, r), &
                                                         response_density_direct_exact(:, s)) + &
                                             DOT_PRODUCT(energy_cross_physical(:, s), &
                                                         response_density_direct_exact(:, r)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, s), &
                                                         response_exact_physical(:, r)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, s), &
                                                         response_density_direct_exact(:, r)))
                        schur(r, s) = schur(r, s) - projected_term
                     END DO
                  END DO
                  projector_physical_direct_diag_shift_sum = 0.0_dp
                  projector_physical_direct_diag_shift_max = 0.0_dp
                  projector_physical_direct_rot_floor_min = rotation_curvature_floor
                  projector_physical_direct_schur_diag_min = HUGE(1.0_dp)
                  DO r = 1, nrot
                     ! The exact fixed-N Mermin Schur complement has genuinely soft
                     ! frontier rotation modes.  Do not re-harden the physical direct
                     ! candidate with the generic frontier floor once its own diagonal
                     ! curvature is already positive.
                     row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                                   rot_hessian_projector_physical(r, r), &
                                                                   rot_floor(r))
                     projector_physical_direct_rot_floor_min = &
                        MIN(projector_physical_direct_rot_floor_min, row_floor)
                     diag_shift = MAX(0.0_dp, row_floor - schur(r, r))
                     IF (diag_shift > 0.0_dp) THEN
                        schur(r, r) = schur(r, r) + diag_shift
                        projector_physical_direct_diag_shift_sum = &
                           projector_physical_direct_diag_shift_sum + diag_shift
                        projector_physical_direct_diag_shift_max = &
                           MAX(projector_physical_direct_diag_shift_max, diag_shift)
                     END IF
                     projector_physical_direct_schur_diag_min = &
                        MIN(projector_physical_direct_schur_diag_min, schur(r, r))
                  END DO
                  projector_physical_direct_diag_shift_avg = &
                     projector_physical_direct_diag_shift_sum/REAL(MAX(1, nrot), KIND=dp)
                  projector_physical_direct_schur_mat(:, :) = &
                     0.5_dp*(schur(:, :) + TRANSPOSE(schur(:, :)))
                  projector_physical_direct_schur_vec(:, :) = &
                     projector_physical_direct_schur_mat(:, :)
                  IF (logger%iter_info%print_level >= high_print_level .OR. &
                      projector_physical_direct_spectral_enabled) THEN
                     projector_physical_direct_schur_evec(:, :) = &
                        projector_physical_direct_schur_mat(:, :)
                     CALL diamat_all(projector_physical_direct_schur_evec, &
                                     projector_physical_direct_schur_eval)
                     projector_physical_direct_schur_eval_min = &
                        MINVAL(projector_physical_direct_schur_eval)
                     projector_physical_direct_schur_eval_max = &
                        MAXVAL(projector_physical_direct_schur_eval)
                     ! Audit against the row floor actually used by the
                     ! physical-direct solve.  The generic Schur
                     ! curvature floor would reintroduce the inactive
                     ! frontier hardening here and print a large
                     ! hypothetical shift that was never applied.
                     projector_physical_direct_spectral_floor = &
                        MAX(0.0_dp, projector_physical_direct_rot_floor_min)
                     projector_physical_direct_spectral_shift_avg = 0.0_dp
                     projector_physical_direct_spectral_shift_max = 0.0_dp
                     projector_physical_direct_schur_negative_fraction = 0.0_dp
                     ! Spectral positive-subspace model.  These
                     ! shifts are not added to the direct Schur
                     ! solve; the applied row shifts are reported
                     ! as applied_shift in the ready line.
                     DO r = 1, nrot
                        IF (projector_physical_direct_schur_eval(r) < 0.0_dp) &
                           projector_physical_direct_schur_negative_fraction = &
                           projector_physical_direct_schur_negative_fraction + 1.0_dp
                        diag_shift = MAX(0.0_dp, projector_physical_direct_spectral_floor - &
                                         ABS(projector_physical_direct_schur_eval(r)))
                        projector_physical_direct_spectral_shift_avg = &
                           projector_physical_direct_spectral_shift_avg + diag_shift
                        projector_physical_direct_spectral_shift_max = &
                           MAX(projector_physical_direct_spectral_shift_max, diag_shift)
                     END DO
                     projector_physical_direct_spectral_shift_avg = &
                        projector_physical_direct_spectral_shift_avg/REAL(MAX(1, nrot), KIND=dp)
                     projector_physical_direct_schur_negative_fraction = &
                        projector_physical_direct_schur_negative_fraction/REAL(MAX(1, nrot), KIND=dp)
                  END IF
                  projector_physical_direct_spectral_ready = .FALSE.
                  projector_physical_direct_spectral_dot = 0.0_dp
                  projector_physical_direct_spectral_drop = 0.0_dp
                  projector_physical_direct_spectral_norm = 0.0_dp
                  projector_physical_direct_spectral_sol(:) = 0.0_dp
                  CALL dgesv(nrot, 1, schur, nrot, ipiv, projector_physical_direct_sol, nrot, info)
                  IF (info == 0) THEN
                     IF (projector_physical_direct_spectral_enabled) THEN
                        projected_term = DOT_PRODUCT(rtd, projector_physical_direct_sol)
                        row_floor = MAX(0.0_dp, projector_physical_direct_rot_floor_min)
                        row_floor = MAX(row_floor, SQRT(EPSILON(1.0_dp))* &
                                        MAX(1.0_dp, &
                                            MAXVAL(ABS(projector_physical_direct_schur_eval))))
                        rhs(:) = 0.0_dp
                        DO r = 1, nrot
                           IF (projector_physical_direct_schur_eval(r) <= row_floor) CYCLE
                           rx_shift = DOT_PRODUCT(projector_physical_direct_schur_evec(:, r), rtd)
                           rhs(:) = rhs(:) + &
                                    (rx_shift/projector_physical_direct_schur_eval(r))* &
                                    projector_physical_direct_schur_evec(:, r)
                        END DO
                        projector_physical_direct_spectral_dot = DOT_PRODUCT(rtd, rhs)
                        projector_physical_direct_spectral_norm = DOT_PRODUCT(rhs, rhs)
                        projector_physical_direct_spectral_ready = &
                           projector_physical_direct_spectral_dot > &
                           EPSILON(projector_physical_direct_spectral_dot) .AND. &
                           projector_physical_direct_spectral_norm > &
                           EPSILON(projector_physical_direct_spectral_norm)
                        IF (projector_physical_direct_spectral_ready) &
                           projector_physical_direct_spectral_sol(:) = rhs(:)
                        IF (logger%iter_info%print_level >= high_print_level) &
                           WRITE (cp_logger_get_default_unit_nr(logger), &
                                  '(A,5(1X,ES16.8))') &
                           " OT Schur projector phys direct spectral subspace dot fdot norm floor emin:", &
                           projected_term, projector_physical_direct_spectral_dot, &
                           projector_physical_direct_spectral_norm, row_floor, &
                           projector_physical_direct_schur_eval_min
                     END IF
                     projector_physical_direct_sol(:) = &
                        projector_physical_direct_history_scale*projector_physical_direct_sol(:)
                     IF (logger%iter_info%print_level >= high_print_level) THEN
                        projector_physical_direct_trace_active_quad = 0.0_dp
                        projector_physical_direct_trace_actual_quad = 0.0_dp
                        projector_physical_direct_trace_full_quad = 0.0_dp
                        projector_physical_direct_trace_invariant_quad = 0.0_dp
                        DO s = 1, nrot
                           DO r = 1, nrot
                              projected_term = 0.5_dp* &
                                               ((rot_hessian_projector_physical(r, s) - rot_hessian(r, s)) + &
                                                (rot_hessian_projector_physical(s, r) - rot_hessian(s, r)))
                              projector_physical_direct_trace_invariant_term = 0.5_dp* &
                                                                              ((rot_hessian_projector(r, s) - rot_hessian(r, s)) + &
                                                                                (rot_hessian_projector(s, r) - rot_hessian(s, r)))
                              tether_projected_term = 0.5_dp* &
                                                      ((rot_hessian_projector_physical_active(r, s) - rot_hessian(r, s)) + &
                                                       (rot_hessian_projector_physical_active(s, r) - rot_hessian(s, r)))
                              rx_shift = 0.5_dp*(projector_physical_direct_delta(r, s) + &
                                                 projector_physical_direct_delta(s, r))
                              projector_physical_direct_trace_actual_quad = &
                                 projector_physical_direct_trace_actual_quad + &
                                 projector_physical_direct_sol(r)*rx_shift* &
                                 projector_physical_direct_sol(s)
                              projector_physical_direct_trace_full_quad = &
                                 projector_physical_direct_trace_full_quad + &
                                 projector_physical_direct_sol(r)*projected_term* &
                                 projector_physical_direct_sol(s)
                              projector_physical_direct_trace_invariant_quad = &
                                 projector_physical_direct_trace_invariant_quad + &
                                 projector_physical_direct_sol(r)* &
                                 projector_physical_direct_trace_invariant_term* &
                                 projector_physical_direct_sol(s)
                              projector_physical_direct_trace_active_quad = &
                                 projector_physical_direct_trace_active_quad + &
                                 projector_physical_direct_sol(r)*tether_projected_term* &
                                 projector_physical_direct_sol(s)
                           END DO
                        END DO
                        projector_physical_direct_trace_excess_quad = &
                           projector_physical_direct_trace_full_quad - &
                           projector_physical_direct_trace_active_quad
                        IF (ABS(projector_physical_direct_trace_full_quad) > &
                            EPSILON(projector_physical_direct_trace_full_quad)) &
                           projector_physical_direct_trace_ratio = &
                           projector_physical_direct_trace_active_quad/ &
                           projector_physical_direct_trace_full_quad
                        IF (ABS(projector_physical_direct_trace_actual_quad) > &
                            EPSILON(projector_physical_direct_trace_actual_quad)) &
                           projector_physical_direct_trace_active_actual_ratio = &
                           projector_physical_direct_trace_active_quad/ &
                           projector_physical_direct_trace_actual_quad
                        projector_physical_direct_trace_invariant_gap_quad = &
                           projector_physical_direct_trace_invariant_quad - &
                           projector_physical_direct_trace_full_quad
                        IF (ABS(projector_physical_direct_trace_invariant_quad) > &
                            EPSILON(projector_physical_direct_trace_invariant_quad)) &
                           projector_physical_direct_trace_invariant_ratio = &
                           projector_physical_direct_trace_full_quad/ &
                           projector_physical_direct_trace_invariant_quad
                        rx_weight = DOT_PRODUCT(projector_physical_direct_sol, &
                                                projector_physical_direct_sol)
                        IF (rx_weight > EPSILON(rx_weight)) THEN
                           projector_physical_direct_trace_actual_diag_quad = 0.0_dp
                           projector_physical_direct_trace_full_diag_quad = 0.0_dp
                           projector_physical_direct_trace_invariant_diag_quad = 0.0_dp
                           projector_physical_direct_trace_active_diag_quad = 0.0_dp
                           DO r = 1, nrot
                              rx_shift = projector_physical_direct_sol(r)* &
                                         projector_physical_direct_sol(r)
                              projector_physical_direct_trace_actual_diag_quad = &
                                 projector_physical_direct_trace_actual_diag_quad + &
                                 rx_shift*projector_physical_direct_delta(r, r)
                              projector_physical_direct_trace_full_diag_quad = &
                                 projector_physical_direct_trace_full_diag_quad + &
                                 rx_shift*(rot_hessian_projector_physical(r, r) - &
                                           rot_hessian(r, r))
                              projector_physical_direct_trace_invariant_diag_quad = &
                                 projector_physical_direct_trace_invariant_diag_quad + &
                                 rx_shift*(rot_hessian_projector(r, r) - rot_hessian(r, r))
                              projector_physical_direct_trace_active_diag_quad = &
                                 projector_physical_direct_trace_active_diag_quad + &
                                 rx_shift*(rot_hessian_projector_physical_active(r, r) - &
                                           rot_hessian(r, r))
                           END DO
                           projector_physical_direct_trace_actual_free_quad = &
                              projector_physical_direct_trace_actual_quad - &
                              projector_physical_direct_trace_actual_diag_quad
                           projector_physical_direct_trace_full_free_quad = &
                              projector_physical_direct_trace_full_quad - &
                              projector_physical_direct_trace_full_diag_quad
                           projector_physical_direct_trace_invariant_free_quad = &
                              projector_physical_direct_trace_invariant_quad - &
                              projector_physical_direct_trace_invariant_diag_quad
                           projector_physical_direct_trace_active_free_quad = &
                              projector_physical_direct_trace_active_quad - &
                              projector_physical_direct_trace_active_diag_quad
                           projector_physical_direct_trace_actual_norm = &
                              projector_physical_direct_trace_actual_quad/rx_weight
                           projector_physical_direct_trace_full_norm = &
                              projector_physical_direct_trace_full_quad/rx_weight
                           projector_physical_direct_trace_invariant_norm = &
                              projector_physical_direct_trace_invariant_quad/rx_weight
                           projector_physical_direct_trace_active_norm = &
                              projector_physical_direct_trace_active_quad/rx_weight
                        END IF
                        projector_physical_direct_delta_negative_norm = 0.0_dp
                        projector_physical_direct_delta_positive_norm = 0.0_dp
                        projector_physical_direct_step_negative_fraction = 0.0_dp
                        projector_physical_direct_delta_negative_fraction = 0.0_dp
                        rx_weight = DOT_PRODUCT(projector_physical_direct_sol, &
                                                projector_physical_direct_sol)
                        DO r = 1, nrot
                           projected_term = &
                              DOT_PRODUCT(projector_physical_direct_curv_evec(:, r), &
                                          projector_physical_direct_sol)
                           diag_shift = projected_term*projected_term
                           IF (projector_physical_direct_curv_eval(r) < 0.0_dp) THEN
                              projector_physical_direct_step_negative_fraction = &
                                 projector_physical_direct_step_negative_fraction + diag_shift
                              projector_physical_direct_delta_negative_norm = &
                                 projector_physical_direct_delta_negative_norm + &
                                 ABS(projector_physical_direct_curv_eval(r))*diag_shift
                           ELSE
                              projector_physical_direct_delta_positive_norm = &
                                 projector_physical_direct_delta_positive_norm + &
                                 projector_physical_direct_curv_eval(r)*diag_shift
                           END IF
                        END DO
                        IF (rx_weight > EPSILON(rx_weight)) &
                           projector_physical_direct_step_negative_fraction = &
                           projector_physical_direct_step_negative_fraction/rx_weight
                        rx_weight = projector_physical_direct_delta_negative_norm + &
                                    projector_physical_direct_delta_positive_norm
                        IF (rx_weight > EPSILON(rx_weight)) &
                           projector_physical_direct_delta_negative_fraction = &
                           projector_physical_direct_delta_negative_norm/rx_weight
                     END IF
                     IF (logger%iter_info%print_level < high_print_level) THEN
                        projector_physical_direct_trace_active_quad = 0.0_dp
                        projector_physical_direct_trace_actual_quad = 0.0_dp
                        projector_physical_direct_trace_full_quad = 0.0_dp
                        projector_physical_direct_trace_invariant_quad = 0.0_dp
                        DO s = 1, nrot
                           DO r = 1, nrot
                              projected_term = 0.5_dp* &
                                               ((rot_hessian_projector_physical(r, s) - rot_hessian(r, s)) + &
                                                (rot_hessian_projector_physical(s, r) - rot_hessian(s, r)))
                              projector_physical_direct_trace_invariant_term = 0.5_dp* &
                                                                              ((rot_hessian_projector(r, s) - rot_hessian(r, s)) + &
                                                                                (rot_hessian_projector(s, r) - rot_hessian(s, r)))
                              tether_projected_term = 0.5_dp* &
                                                      ((rot_hessian_projector_physical_active(r, s) - rot_hessian(r, s)) + &
                                                       (rot_hessian_projector_physical_active(s, r) - rot_hessian(s, r)))
                              rx_shift = 0.5_dp*(projector_physical_direct_delta(r, s) + &
                                                 projector_physical_direct_delta(s, r))
                              projector_physical_direct_trace_actual_quad = &
                                 projector_physical_direct_trace_actual_quad + &
                                 projector_physical_direct_sol(r)*rx_shift* &
                                 projector_physical_direct_sol(s)
                              projector_physical_direct_trace_full_quad = &
                                 projector_physical_direct_trace_full_quad + &
                                 projector_physical_direct_sol(r)*projected_term* &
                                 projector_physical_direct_sol(s)
                              projector_physical_direct_trace_invariant_quad = &
                                 projector_physical_direct_trace_invariant_quad + &
                                 projector_physical_direct_sol(r)* &
                                 projector_physical_direct_trace_invariant_term* &
                                 projector_physical_direct_sol(s)
                              projector_physical_direct_trace_active_quad = &
                                 projector_physical_direct_trace_active_quad + &
                                 projector_physical_direct_sol(r)*tether_projected_term* &
                                 projector_physical_direct_sol(s)
                           END DO
                        END DO
                        projector_physical_direct_trace_excess_quad = &
                           projector_physical_direct_trace_full_quad - &
                           projector_physical_direct_trace_active_quad
                        IF (ABS(projector_physical_direct_trace_full_quad) > &
                            EPSILON(projector_physical_direct_trace_full_quad)) &
                           projector_physical_direct_trace_ratio = &
                           projector_physical_direct_trace_active_quad/ &
                           projector_physical_direct_trace_full_quad
                        IF (ABS(projector_physical_direct_trace_actual_quad) > &
                            EPSILON(projector_physical_direct_trace_actual_quad)) &
                           projector_physical_direct_trace_active_actual_ratio = &
                           projector_physical_direct_trace_active_quad/ &
                           projector_physical_direct_trace_actual_quad
                        projector_physical_direct_trace_invariant_gap_quad = &
                           projector_physical_direct_trace_invariant_quad - &
                           projector_physical_direct_trace_full_quad
                        IF (ABS(projector_physical_direct_trace_invariant_quad) > &
                            EPSILON(projector_physical_direct_trace_invariant_quad)) &
                           projector_physical_direct_trace_invariant_ratio = &
                           projector_physical_direct_trace_full_quad/ &
                           projector_physical_direct_trace_invariant_quad
                        rx_weight = DOT_PRODUCT(projector_physical_direct_sol, &
                                                projector_physical_direct_sol)
                        IF (rx_weight > EPSILON(rx_weight)) THEN
                           projector_physical_direct_trace_actual_diag_quad = 0.0_dp
                           projector_physical_direct_trace_full_diag_quad = 0.0_dp
                           projector_physical_direct_trace_invariant_diag_quad = 0.0_dp
                           projector_physical_direct_trace_active_diag_quad = 0.0_dp
                           DO r = 1, nrot
                              rx_shift = projector_physical_direct_sol(r)* &
                                         projector_physical_direct_sol(r)
                              projector_physical_direct_trace_actual_diag_quad = &
                                 projector_physical_direct_trace_actual_diag_quad + &
                                 rx_shift*projector_physical_direct_delta(r, r)
                              projector_physical_direct_trace_full_diag_quad = &
                                 projector_physical_direct_trace_full_diag_quad + &
                                 rx_shift*(rot_hessian_projector_physical(r, r) - &
                                           rot_hessian(r, r))
                              projector_physical_direct_trace_invariant_diag_quad = &
                                 projector_physical_direct_trace_invariant_diag_quad + &
                                 rx_shift*(rot_hessian_projector(r, r) - rot_hessian(r, r))
                              projector_physical_direct_trace_active_diag_quad = &
                                 projector_physical_direct_trace_active_diag_quad + &
                                 rx_shift*(rot_hessian_projector_physical_active(r, r) - &
                                           rot_hessian(r, r))
                           END DO
                           projector_physical_direct_trace_actual_free_quad = &
                              projector_physical_direct_trace_actual_quad - &
                              projector_physical_direct_trace_actual_diag_quad
                           projector_physical_direct_trace_full_free_quad = &
                              projector_physical_direct_trace_full_quad - &
                              projector_physical_direct_trace_full_diag_quad
                           projector_physical_direct_trace_invariant_free_quad = &
                              projector_physical_direct_trace_invariant_quad - &
                              projector_physical_direct_trace_invariant_diag_quad
                           projector_physical_direct_trace_active_free_quad = &
                              projector_physical_direct_trace_active_quad - &
                              projector_physical_direct_trace_active_diag_quad
                           projector_physical_direct_trace_actual_norm = &
                              projector_physical_direct_trace_actual_quad/rx_weight
                           projector_physical_direct_trace_full_norm = &
                              projector_physical_direct_trace_full_quad/rx_weight
                           projector_physical_direct_trace_invariant_norm = &
                              projector_physical_direct_trace_invariant_quad/rx_weight
                           projector_physical_direct_trace_active_norm = &
                              projector_physical_direct_trace_active_quad/rx_weight
                        END IF
                     END IF
                     projector_physical_direct_rx_e(:) = &
                        MATMUL(response_exact_raw, projector_physical_direct_sol)
                     projector_physical_direct_model_e(:) = MATMUL(response_exact_physical, &
                                                                   projector_physical_direct_sol)
                     IF (exact_density_direct_response_ready) &
                        projector_physical_direct_model_e(:) = projector_physical_direct_model_e(:) + &
                                                               MATMUL(response_density_direct_exact, projector_physical_direct_sol)
                     IF (projector_physical_direct_mixed_enabled .AND. &
                         projector_physical_direct_mixed_weight > &
                         EPSILON(projector_physical_direct_mixed_weight)) &
                        projector_physical_direct_model_e(:) = &
                        (1.0_dp - projector_physical_direct_mixed_weight)* &
                        projector_physical_direct_rx_e(:) + &
                        projector_physical_direct_mixed_weight* &
                        projector_physical_direct_model_e(:)
                     CALL project_kpoint_ot_schur_response(projector_physical_direct_rx_e, &
                                                           occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                     CALL project_kpoint_ot_schur_response(projector_physical_direct_model_e, &
                                                           occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                     IF (projector_physical_direct_spectral_ready) THEN
                        projector_physical_direct_spectral_rx_e(:) = &
                           MATMUL(response_exact_raw, projector_physical_direct_spectral_sol)
                        projector_physical_direct_spectral_model_e(:) = &
                           MATMUL(response_exact_physical, projector_physical_direct_spectral_sol)
                        IF (exact_density_direct_response_ready) &
                           projector_physical_direct_spectral_model_e(:) = &
                           projector_physical_direct_spectral_model_e(:) + &
                           MATMUL(response_density_direct_exact, &
                                  projector_physical_direct_spectral_sol)
                        CALL project_kpoint_ot_schur_response(projector_physical_direct_spectral_rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                        CALL project_kpoint_ot_schur_response( &
                           projector_physical_direct_spectral_model_e, &
                           occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                        IF (projector_physical_direct_shadow_enabled .AND. &
                            projector_coupled_weight > EPSILON(projector_coupled_weight) .AND. &
                            local_ot_env(1)%schur_projector_mode_quality_samples >= &
                            ot_kp_schur_calibration_min_samples) THEN
                           response_physical_model(:, :) = response_exact_physical(:, :)
                           IF (exact_density_full_response_ready) THEN
                              response_physical_model(:, :) = response_physical_model(:, :) + &
                                                              response_density_full_exact(:, :)
                           ELSE IF (exact_density_direct_response_ready) THEN
                              response_physical_model(:, :) = response_physical_model(:, :) + &
                                                              response_density_direct_exact(:, :)
                           END IF
                           CALL audit_kpoint_ot_projector_response_modes(rot_hessian, &
                                                                         rot_hessian_projector_physical_active, &
                                                                       projector_physical_direct_spectral_sol, response_exact_raw, &
                                                                         response_physical_model, curv, occ_curv, tether_curv, &
                                                                         occ_curv_projection_sum, channel_nmo, e_offset, .TRUE., &
                                                                         projector_coupled_weight, residual_delta, &
                                                                         projector_mode_history_quality, &
                                                                         local_ot_env(1)%schur_projector_mode_trust_ema, &
                                                                         projector_mode_history_response_ratio, grad_e, &
                                                                 z_exact_physical_trial + projector_physical_direct_spectral_rx_e, &
                                                                         projector_physical_direct_spectral_rx_e, rx_model, &
                                                                         spectral_resp_weight, &
                                                                         spectral_resp_correction_drop, &
                                                                         spectral_resp_correction_negative, &
                                                                         spectral_resp_raw_negative_fraction, &
                                                                         spectral_resp_positive_drop, &
                                                                         spectral_resp_negative_drop, &
                                                                         spectral_resp_cross_drop, &
                                                                         spectral_resp_positive_coeff, &
                                                                         spectral_resp_negative_coeff, &
                                                                         raw_residual_delta=response_raw_delta)
                           IF (spectral_resp_weight > &
                               EPSILON(spectral_resp_weight)) THEN
                              projector_physical_direct_spectral_rx_e(:) = rx_model(:)
                              CALL project_kpoint_ot_schur_response( &
                                 projector_physical_direct_spectral_rx_e, occ_curv, tether_curv, &
                                 occ_curv_projection_sum, channel_nmo, e_offset)
                              projector_physical_direct_spectral_model_e(:) = &
                                 projector_physical_direct_spectral_rx_e(:)
                           END IF
                        END IF
                        projector_physical_direct_spectral_z_e(:) = &
                           z_exact_physical_trial(:) + projector_physical_direct_spectral_rx_e(:)
                        projector_physical_direct_spectral_gdot_energy = &
                           DOT_PRODUCT(grad_e, projector_physical_direct_spectral_z_e)
                        projector_physical_direct_spectral_gdot_rotation = &
                           DOT_PRODUCT(grad_rot, projector_physical_direct_spectral_sol)
                        projector_physical_direct_spectral_gdotp = &
                           projector_physical_direct_spectral_gdot_energy + &
                           projector_physical_direct_spectral_gdot_rotation
                        CALL kpoint_ot_mixed_projected_term( &
                           projector_physical_direct_spectral_z_e, &
                           projector_physical_direct_spectral_z_e, occ_curv, tether_curv, &
                           occ_curv_projection_sum, channel_nmo, e_offset, &
                           projector_physical_direct_spectral_metric_norm_energy)
                        projector_physical_direct_spectral_metric_norm_energy = &
                           MAX(0.0_dp, projector_physical_direct_spectral_metric_norm_energy)
                        ! Treat indefinite finite-complex Schur curvature as a
                        ! trust signal, not as zero model cost.
                        projector_physical_direct_spectral_metric_norm_rotation = &
                           ABS(projector_physical_direct_spectral_dot)
                        IF (projector_physical_direct_spectral_metric_norm_rotation <= &
                            EPSILON(projector_physical_direct_spectral_metric_norm_rotation)) &
                           projector_physical_direct_spectral_metric_norm_rotation = &
                           kpoint_ot_symmetric_abs_quad(projector_physical_direct_schur_mat, &
                                                        projector_physical_direct_spectral_sol)
                        projector_physical_direct_spectral_metric_normp = &
                           projector_physical_direct_spectral_metric_norm_energy + &
                           projector_physical_direct_spectral_metric_norm_rotation
                        IF (projector_physical_direct_spectral_gdotp > 0.0_dp .AND. &
                            projector_physical_direct_spectral_metric_normp > &
                            EPSILON(projector_physical_direct_spectral_metric_normp)) THEN
                           projector_physical_direct_spectral_unit_abs_step = &
                              MAXVAL(ABS(projector_physical_direct_spectral_rx_e))
                           CALL para_env_inter_kp%max(projector_physical_direct_spectral_unit_abs_step)
                           projector_physical_direct_spectral_unit_weighted_step = &
                              kpoint_ot_weighted_response_step( &
                              projector_physical_direct_spectral_rx_e, curv, curv_projection_sum)
                           projector_physical_direct_spectral_unit_model_gap_drop = &
                              kpoint_ot_response_mismatch_drop( &
                              projector_physical_direct_spectral_rx_e, &
                              projector_physical_direct_spectral_model_e, curv, 1.0_dp)
                           projector_physical_direct_spectral_trust_scale = &
                              MIN(1.0_dp, projector_physical_direct_spectral_gdotp/ &
                                  MAX(projector_physical_direct_spectral_metric_normp, &
                                      EPSILON(projector_physical_direct_spectral_metric_normp)))
                           IF (response_trust > EPSILON(response_trust) .AND. &
                               projector_physical_direct_spectral_unit_weighted_step > &
                               EPSILON(projector_physical_direct_spectral_unit_weighted_step)) &
                              projector_physical_direct_spectral_trust_scale = &
                              MIN(projector_physical_direct_spectral_trust_scale, &
                                  0.8_dp*response_trust/ &
                                  projector_physical_direct_spectral_unit_weighted_step)
                           IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                               projector_physical_direct_spectral_unit_abs_step > &
                               EPSILON(projector_physical_direct_spectral_unit_abs_step)) &
                              projector_physical_direct_spectral_trust_scale = &
                              MIN(projector_physical_direct_spectral_trust_scale, &
                                  0.8_dp*response_abs_trust/ &
                                  projector_physical_direct_spectral_unit_abs_step)
                           projector_physical_direct_spectral_direction_scale = &
                              MAX(0.0_dp, projector_physical_direct_spectral_trust_scale)
                           projector_physical_direct_spectral_response_abs_step = &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_unit_abs_step
                           projector_physical_direct_spectral_response_weighted_step = &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_unit_weighted_step
                           projector_physical_direct_spectral_model_drop = &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_gdotp - &
                              0.5_dp*projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_metric_normp
                           projector_physical_direct_spectral_model_drop = &
                              MAX(0.0_dp, projector_physical_direct_spectral_model_drop)
                           projector_physical_direct_spectral_model_gap_drop = &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_unit_model_gap_drop
                           projector_physical_direct_spectral_model_gap = &
                              projector_physical_direct_spectral_direction_scale* &
                              MAXVAL(ABS(projector_physical_direct_spectral_model_e - &
                                         projector_physical_direct_spectral_rx_e))
                           projector_physical_direct_spectral_model_calibrated_drop = &
                              MAX(0.0_dp, projector_physical_direct_spectral_model_drop - &
                                  projector_physical_direct_spectral_model_gap_drop)
                           projector_physical_direct_spectral_model_gap_trust = &
                              schur_model_gap_factor*response_trust
                           projector_physical_direct_spectral_model_gap_ratio = 0.0_dp
                           IF (projector_physical_direct_spectral_model_gap_trust > &
                               EPSILON(projector_physical_direct_spectral_model_gap_trust)) &
                              projector_physical_direct_spectral_model_gap_ratio = &
                              projector_physical_direct_spectral_model_gap/ &
                              projector_physical_direct_spectral_model_gap_trust
                           IF (response_trust > EPSILON(response_trust)) &
                              projector_physical_direct_spectral_resp_wtrust = &
                              projector_physical_direct_spectral_response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              projector_physical_direct_spectral_resp_atrust = &
                              projector_physical_direct_spectral_response_abs_step/response_abs_trust
                           projector_physical_direct_spectral_trust_quality = &
                              kpoint_ot_schur_trust_quality( &
                              projector_physical_direct_spectral_resp_wtrust, &
                              projector_physical_direct_spectral_resp_atrust, &
                              projector_physical_direct_spectral_model_gap_ratio)
                           projector_physical_direct_spectral_scale_quality = &
                              kpoint_ot_schur_scale_quality( &
                              projector_physical_direct_spectral_direction_scale, &
                              schur_min_coupled_scale)
                           IF (projector_physical_direct_spectral_direction_scale < &
                               schur_min_coupled_scale) &
                              projector_physical_direct_spectral_model_calibrated_drop = &
                              projector_physical_direct_spectral_scale_quality* &
                              projector_physical_direct_spectral_model_calibrated_drop
                           projector_physical_direct_spectral_norm_energy = &
                              projector_physical_direct_spectral_metric_norm_energy
                           projector_physical_direct_spectral_norm_rotation = &
                              projector_physical_direct_spectral_metric_norm_rotation
                           projector_physical_direct_spectral_normp = &
                              projector_physical_direct_spectral_norm_energy + &
                              projector_physical_direct_spectral_norm_rotation
                           projector_physical_direct_spectral_norm_ratio = &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_direction_scale* &
                              projector_physical_direct_spectral_normp/MAX(gnorm, EPSILON(1.0_dp))
                           projector_physical_direct_spectral_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              projector_physical_direct_spectral_model_calibrated_drop, &
                              projector_physical_direct_spectral_quality_for_selection, &
                              projector_physical_direct_spectral_trust_quality)
                           projector_physical_direct_spectral_probe_ready = &
                              .NOT. local_ot_env(1)%schur_projector_spectral_candidate_enabled &
                              .AND. &
                              local_ot_env(1)%schur_projector_spectral_selected_quality_samples < &
                              ot_kp_schur_projector_response_min_samples .AND. &
                              local_ot_env(1)%schur_projector_spectral_selected_failure_samples < &
                              ot_kp_schur_projector_spectral_probe_max_failures .AND. &
                              (local_ot_env(1)%schur_projector_spectral_selected_failure_samples == 0 .OR. &
                               local_ot_env(1)%schur_projector_spectral_selected_quality_ema >= &
                               0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .OR. &
                               local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema >= &
                               0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) .AND. &
                              local_ot_env(1)%schur_projector_spectral_quality_samples >= &
                              ot_kp_schur_projector_response_min_samples .AND. &
                              projector_physical_direct_spectral_shadow_quality_for_probe >= &
                              ot_kp_schur_projector_spectral_probe_quality_min .AND. &
                              local_ot_env(1)%schur_projector_spectral_quality_ema >= &
                              ot_kp_schur_projector_spectral_probe_quality_min .AND. &
                              local_ot_env(1)%schur_projector_spectral_quality >= &
                              0.5_dp*ot_kp_schur_projector_spectral_probe_quality_min .AND. &
                              local_ot_env(1)%schur_projector_spectral_dot_ema > 0.0_dp .AND. &
                              local_ot_env(1)%schur_projector_spectral_norm_ema > 0.0_dp .AND. &
                              local_ot_env(1)%schur_projector_spectral_floor_ema > &
                              EPSILON(local_ot_env(1)%schur_projector_spectral_floor_ema) .AND. &
                              projector_physical_direct_spectral_response_weighted_step <= &
                              ot_kp_schur_projector_spectral_probe_trust_fraction*response_trust .AND. &
                              projector_physical_direct_spectral_response_abs_step <= &
                              ot_kp_schur_projector_spectral_probe_trust_fraction*response_abs_trust
                           projector_physical_direct_spectral_candidate_ready = &
                              (local_ot_env(1)%schur_projector_spectral_candidate_enabled .OR. &
                               projector_physical_direct_spectral_probe_ready) .AND. &
                              projector_physical_direct_spectral_model_calibrated_drop > &
                              EPSILON(projector_physical_direct_spectral_model_calibrated_drop) .AND. &
                              projector_physical_direct_spectral_gdotp > 0.0_dp .AND. &
                              projector_physical_direct_spectral_normp > &
                              EPSILON(projector_physical_direct_spectral_normp) .AND. &
                              projector_physical_direct_spectral_response_weighted_step <= &
                              response_trust .AND. &
                              projector_physical_direct_spectral_response_abs_step <= &
                              response_abs_trust
                           IF (new_search_point .AND. &
                               projector_physical_direct_spectral_model_calibrated_drop > &
                               EPSILON(projector_physical_direct_spectral_model_calibrated_drop) .AND. &
                               projector_physical_direct_spectral_response_weighted_step <= &
                               response_trust .AND. &
                               projector_physical_direct_spectral_response_abs_step <= &
                               response_abs_trust) THEN
                              IF (.NOT. local_ot_env(1)%schur_projector_spectral_pending) THEN
                                 local_ot_env(1)%schur_projector_spectral_floor = row_floor
                                 local_ot_env(1)%schur_projector_spectral_emin = &
                                    projector_physical_direct_schur_eval_min
                              ELSE
                                 local_ot_env(1)%schur_projector_spectral_floor = &
                                    MAX(local_ot_env(1)%schur_projector_spectral_floor, row_floor)
                                 local_ot_env(1)%schur_projector_spectral_emin = &
                                    MIN(local_ot_env(1)%schur_projector_spectral_emin, &
                                        projector_physical_direct_schur_eval_min)
                              END IF
                              local_ot_env(1)%schur_projector_spectral_pending = .TRUE.
                              local_ot_env(1)%schur_projector_spectral_drop = &
                                 local_ot_env(1)%schur_projector_spectral_drop + &
                                 projector_physical_direct_spectral_model_calibrated_drop
                              local_ot_env(1)%schur_projector_spectral_dot = &
                                 local_ot_env(1)%schur_projector_spectral_dot + &
                                 projector_physical_direct_spectral_direction_scale* &
                                 projector_physical_direct_spectral_gdotp
                              local_ot_env(1)%schur_projector_spectral_norm = &
                                 local_ot_env(1)%schur_projector_spectral_norm + &
                                 projector_physical_direct_spectral_direction_scale* &
                                 projector_physical_direct_spectral_direction_scale* &
                                 projector_physical_direct_spectral_metric_normp
                           END IF
                        END IF
                     END IF
                     ! Feed the low-rank density-response shadow in normal
                     ! runs as well; only its printed diagnostics stay HIGH-only.
                     ! Its accepted step uses the same total physical+density
                     ! response that enters the Schur/RHS model.
                     IF (exact_density_direct_response_ready) THEN
                        projector_physical_direct_density_sol(:) = &
                           projector_physical_direct_sol(:)
                        projector_physical_direct_density_rx_e(:) = &
                           MATMUL(response_exact_physical, projector_physical_direct_sol) + &
                           MATMUL(response_density_direct_exact, projector_physical_direct_sol)
                        CALL project_kpoint_ot_schur_response(projector_physical_direct_density_rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                        projector_physical_direct_density_z_e(:) = &
                           z_exact_physical_trial(:) + projector_physical_direct_density_rx_e(:)
                        projector_physical_direct_density_gdot_energy = &
                           DOT_PRODUCT(grad_e, projector_physical_direct_density_z_e)
                        projector_physical_direct_density_gdot_rotation = &
                           DOT_PRODUCT(grad_rot, projector_physical_direct_sol)
                        projector_physical_direct_density_gdotp = &
                           projector_physical_direct_density_gdot_energy + &
                           projector_physical_direct_density_gdot_rotation
                        CALL kpoint_ot_mixed_projected_term(projector_physical_direct_density_z_e, &
                                                            projector_physical_direct_density_z_e, occ_curv, tether_curv, &
                                                            occ_curv_projection_sum, channel_nmo, e_offset, &
                                                            projector_physical_direct_density_norm_energy)
                        projector_physical_direct_density_norm_energy = &
                           MAX(0.0_dp, projector_physical_direct_density_norm_energy)
                        projector_physical_direct_density_norm_rotation = &
                           ABS(kpoint_ot_symmetric_quad(projector_physical_direct_schur_mat, &
                                                        projector_physical_direct_sol))
                        IF (projector_physical_direct_density_norm_rotation <= &
                            EPSILON(projector_physical_direct_density_norm_rotation)) &
                           projector_physical_direct_density_norm_rotation = &
                           ABS(DOT_PRODUCT(rtd, projector_physical_direct_sol))
                        IF (projector_physical_direct_density_norm_rotation <= &
                            EPSILON(projector_physical_direct_density_norm_rotation)) &
                           projector_physical_direct_density_norm_rotation = &
                           kpoint_ot_symmetric_abs_quad(projector_physical_direct_schur_mat, &
                                                        projector_physical_direct_sol)
                        projector_physical_direct_density_normp = &
                           projector_physical_direct_density_norm_energy + &
                           projector_physical_direct_density_norm_rotation
                        IF (projector_physical_direct_density_gdotp > 0.0_dp .AND. &
                            projector_physical_direct_density_normp > &
                            EPSILON(projector_physical_direct_density_normp)) THEN
                           projector_physical_direct_density_response_abs_step = &
                              MAXVAL(ABS(projector_physical_direct_density_rx_e))
                           CALL para_env_inter_kp%max(projector_physical_direct_density_response_abs_step)
                           projector_physical_direct_density_response_weighted_step = &
                              kpoint_ot_weighted_response_step( &
                              projector_physical_direct_density_rx_e, curv, curv_projection_sum)
                           projector_physical_direct_density_direction_scale = &
                              MIN(1.0_dp, projector_physical_direct_density_gdotp/ &
                                  MAX(projector_physical_direct_density_normp, &
                                      EPSILON(projector_physical_direct_density_normp)))
                           IF (response_trust > EPSILON(response_trust) .AND. &
                               projector_physical_direct_density_response_weighted_step > &
                               EPSILON(projector_physical_direct_density_response_weighted_step)) &
                              projector_physical_direct_density_direction_scale = &
                              MIN(projector_physical_direct_density_direction_scale, &
                                  0.8_dp*response_trust/ &
                                  projector_physical_direct_density_response_weighted_step)
                           IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                               projector_physical_direct_density_response_abs_step > &
                               EPSILON(projector_physical_direct_density_response_abs_step)) &
                              projector_physical_direct_density_direction_scale = &
                              MIN(projector_physical_direct_density_direction_scale, &
                                  0.8_dp*response_abs_trust/ &
                                  projector_physical_direct_density_response_abs_step)
                           projector_physical_direct_density_scale_quality = &
                              kpoint_ot_schur_scale_quality( &
                              projector_physical_direct_density_direction_scale, &
                              schur_min_coupled_scale)
                           projector_physical_direct_density_model_drop = &
                              projector_physical_direct_density_direction_scale* &
                              projector_physical_direct_density_gdotp - &
                              0.5_dp*projector_physical_direct_density_direction_scale* &
                              projector_physical_direct_density_direction_scale* &
                              projector_physical_direct_density_normp
                           projector_physical_direct_density_model_drop = &
                              MAX(0.0_dp, projector_physical_direct_density_model_drop)
                           projector_physical_direct_density_model_calibrated_drop = &
                              projector_physical_direct_density_model_drop
                           IF (projector_physical_direct_density_direction_scale < &
                               schur_min_coupled_scale) &
                              projector_physical_direct_density_model_calibrated_drop = &
                              projector_physical_direct_density_scale_quality* &
                              projector_physical_direct_density_model_calibrated_drop
                           projector_physical_direct_density_response_abs_step = &
                              projector_physical_direct_density_direction_scale* &
                              projector_physical_direct_density_response_abs_step
                           projector_physical_direct_density_response_weighted_step = &
                              projector_physical_direct_density_direction_scale* &
                              projector_physical_direct_density_response_weighted_step
                           IF (response_trust > EPSILON(response_trust)) &
                              projector_physical_direct_density_response_weighted_trust_ratio = &
                              projector_physical_direct_density_response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              projector_physical_direct_density_response_abs_trust_ratio = &
                              projector_physical_direct_density_response_abs_step/response_abs_trust
                           projector_physical_direct_density_trust_quality = &
                              kpoint_ot_schur_trust_quality( &
                              projector_physical_direct_density_response_weighted_trust_ratio, &
                              projector_physical_direct_density_response_abs_trust_ratio, 0.0_dp)
                           IF (projector_physical_direct_floor_density_weight > &
                               EPSILON(projector_physical_direct_floor_density_weight) .AND. &
                               projector_physical_direct_floor_density_quality >= &
                               ot_kp_schur_projector_response_quality_min_ratio .AND. &
                               projector_physical_direct_floor_density_trust_quality >= &
                               ot_kp_schur_projector_response_quality_min_ratio) THEN
                              projector_physical_direct_density_quality_for_selection = &
                                 kpoint_ot_direct_floor_selected_quality( &
                                 projector_physical_direct_floor_density_quality, &
                                 projector_physical_direct_density_selected_history_quality, &
                                 local_ot_env(1)% &
                                 schur_projector_phys_direct_density_sel_quality_samples, &
                                 ot_kp_schur_calibration_min_samples)
                           END IF
                           projector_physical_direct_density_shadow_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              projector_physical_direct_density_model_calibrated_drop, &
                              projector_physical_direct_density_shadow_quality_for_selection, &
                              projector_physical_direct_density_trust_quality* &
                              projector_physical_direct_density_audit_quality)
                           projector_physical_direct_density_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              projector_physical_direct_density_model_calibrated_drop, &
                              projector_physical_direct_density_quality_for_selection, &
                              projector_physical_direct_density_trust_quality* &
                              projector_physical_direct_density_audit_quality)
                           projector_physical_direct_density_probe_expected_drop = &
                              kpoint_ot_density_full_direct_probe_drop( &
                              residual_delta, projector_physical_direct_density_expected_drop, &
                              projector_physical_direct_density_shadow_expected_drop, &
                              projector_physical_direct_density_response_weighted_trust_ratio, &
                              projector_physical_direct_density_response_abs_trust_ratio)
                           projector_physical_direct_density_tail_probe_ready = &
                              projector_physical_direct_density_probe_expected_drop > &
                              MAX(projector_physical_direct_density_expected_drop, &
                                  ot_kp_schur_projector_density_full_min_drop)
                           projector_physical_direct_density_quality_ready = &
                              residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                              local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples < &
                              ot_kp_schur_calibration_min_samples .AND. &
                              projector_physical_direct_density_quality_for_selection >= &
                              ot_kp_schur_projector_response_quality_min_ratio .AND. &
                              projector_physical_direct_density_trust_quality >= &
                              ot_kp_schur_projector_response_quality_min_ratio
                           projector_physical_direct_density_candidate_ready = &
                              ((local_ot_env(1)%schur_projector_density_quality_samples >= &
                                ot_kp_schur_projector_response_min_samples .AND. &
                                local_ot_env(1)%schur_projector_density_quality_ema >= &
                                ot_kp_schur_projector_response_quality_min_ratio .AND. &
                                local_ot_env(1)%schur_projector_density_quality >= &
                                0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) .OR. &
                               (projector_physical_direct_floor_density_weight > &
                                EPSILON(projector_physical_direct_floor_density_weight) .AND. &
                                projector_physical_direct_floor_density_quality >= &
                                ot_kp_schur_projector_response_quality_min_ratio .AND. &
                                projector_physical_direct_floor_density_trust_quality >= &
                                ot_kp_schur_projector_response_quality_min_ratio) .OR. &
                               projector_physical_direct_density_quality_ready .OR. &
                               projector_physical_direct_density_selected_probe_ready .OR. &
                               projector_physical_direct_density_tail_probe_ready) .AND. &
                              MAX(projector_physical_direct_density_expected_drop, &
                                  projector_physical_direct_density_probe_expected_drop) > &
                              EPSILON(projector_physical_direct_density_probe_expected_drop) .AND. &
                              projector_physical_direct_density_response_weighted_step <= &
                              response_trust .AND. &
                              projector_physical_direct_density_response_abs_step <= &
                              response_abs_trust
                        END IF
                     END IF
                     IF (logger%iter_info%print_level >= high_print_level .AND. &
                         logger%para_env%is_source()) &
                        WRITE (cp_logger_get_default_unit_nr(logger), &
                               '(A,1X,I3,3(1X,L1),8(1X,ES16.8))') &
                        " OT Schur projector phys direct density gate group ready selected probe "// &
                        "exp pexp qsel cdrop rratio aratio tq scale:", &
                        target_group, projector_physical_direct_density_candidate_ready, &
                        projector_physical_direct_density_candidate_selected, &
                        projector_physical_direct_density_tail_probe_ready, &
                        projector_physical_direct_density_expected_drop, &
                        projector_physical_direct_density_probe_expected_drop, &
                        projector_physical_direct_density_quality_for_selection, &
                        projector_physical_direct_density_model_calibrated_drop, &
                        projector_physical_direct_density_response_weighted_trust_ratio, &
                        projector_physical_direct_density_response_abs_trust_ratio, &
                        projector_physical_direct_density_trust_quality, &
                        projector_physical_direct_density_direction_scale
                     IF (exact_density_full_response_ready) THEN
                        schur(:, :) = rot_hessian_coupled(:, :) + &
                                      projector_coupled_weight* &
                                      projector_physical_direct_delta(:, :)
                        DO s = 1, nrot
                           DO r = 1, nrot
                              projected_term = 0.5_dp* &
                                               (DOT_PRODUCT(energy_cross_physical(:, r), &
                                                            response_exact_physical(:, s)) + &
                                                DOT_PRODUCT(energy_cross_physical(:, s), &
                                                            response_exact_physical(:, r)))
                              projected_term = projected_term + 0.5_dp* &
                                               (DOT_PRODUCT(energy_cross_physical(:, r), &
                                                            response_density_full_exact(:, s)) + &
                                                DOT_PRODUCT(energy_cross_density_full(:, r), &
                                                            response_exact_physical(:, s)) + &
                                                DOT_PRODUCT(energy_cross_density_full(:, r), &
                                                            response_density_full_exact(:, s)) + &
                                                DOT_PRODUCT(energy_cross_physical(:, s), &
                                                            response_density_full_exact(:, r)) + &
                                                DOT_PRODUCT(energy_cross_density_full(:, s), &
                                                            response_exact_physical(:, r)) + &
                                                DOT_PRODUCT(energy_cross_density_full(:, s), &
                                                            response_density_full_exact(:, r)))
                              schur(r, s) = schur(r, s) - projected_term
                           END DO
                        END DO
                        DO r = 1, nrot
                           row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                                         rot_hessian_projector_physical(r, r), rot_floor(r))
                           diag_shift = MAX(0.0_dp, row_floor - schur(r, r))
                           IF (diag_shift > 0.0_dp) schur(r, r) = schur(r, r) + diag_shift
                        END DO
                        DO r = 1, nrot
                           rtd(r) = grad_rot(r) + DOT_PRODUCT(response_exact_physical(:, r), grad_e) + &
                                    DOT_PRODUCT(response_density_full_exact(:, r), grad_e)
                        END DO
                        density_full_sol(:) = rtd(:)
                        CALL dgesv(nrot, 1, schur, nrot, ipiv, density_full_sol, nrot, info)
                        IF (info == 0) THEN
                           density_full_rx_e(:) = &
                              MATMUL(response_exact_physical, density_full_sol) + &
                              MATMUL(response_density_full_exact, density_full_sol)
                           CALL project_kpoint_ot_schur_response(density_full_rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                           density_full_z_e(:) = z_exact_physical_trial(:) + density_full_rx_e(:)
                           density_full_gdot_energy = DOT_PRODUCT(grad_e, density_full_z_e)
                           density_full_gdot_rotation = DOT_PRODUCT(grad_rot, density_full_sol)
                           density_full_gdotp = density_full_gdot_energy + density_full_gdot_rotation
                           CALL kpoint_ot_mixed_projected_term(density_full_z_e, &
                                                               density_full_z_e, occ_curv, tether_curv, occ_curv_projection_sum, &
                                                               channel_nmo, e_offset, density_full_norm_energy)
                           density_full_norm_energy = MAX(0.0_dp, density_full_norm_energy)
                           density_full_norm_rotation = &
                              ABS(DOT_PRODUCT(rtd, density_full_sol))
                           IF (density_full_norm_rotation <= EPSILON(density_full_norm_rotation)) &
                              density_full_norm_rotation = DOT_PRODUCT(density_full_sol, density_full_sol)
                           density_full_normp = density_full_norm_energy + density_full_norm_rotation
                        END IF
                        IF (info == 0 .AND. density_full_gdotp > 0.0_dp .AND. &
                            density_full_normp > EPSILON(density_full_normp)) THEN
                           density_full_direction_scale = density_full_gdotp/ &
                                                          MAX(density_full_normp, EPSILON(density_full_normp))
                           density_full_response_abs_step = MAXVAL(ABS(density_full_rx_e))
                           CALL para_env_inter_kp%max(density_full_response_abs_step)
                           density_full_response_weighted_step = &
                              kpoint_ot_weighted_response_step( &
                              density_full_rx_e, curv, &
                              curv_projection_sum)
                           IF (response_trust > EPSILON(response_trust) .AND. &
                               density_full_response_weighted_step > &
                               EPSILON(density_full_response_weighted_step)) &
                              density_full_direction_scale = &
                              MIN(density_full_direction_scale, &
                                  0.8_dp*response_trust/density_full_response_weighted_step)
                           IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                               density_full_response_abs_step > &
                               EPSILON(density_full_response_abs_step)) &
                              density_full_direction_scale = &
                              MIN(density_full_direction_scale, &
                                  0.8_dp*response_abs_trust/density_full_response_abs_step)
                           density_full_scale_quality = &
                              kpoint_ot_schur_scale_quality( &
                              density_full_direction_scale, &
                              schur_min_coupled_scale)
                           density_full_model_drop = &
                              density_full_direction_scale*density_full_gdotp - &
                              0.5_dp*density_full_direction_scale* &
                              density_full_direction_scale*density_full_normp
                           density_full_model_drop = MAX(0.0_dp, density_full_model_drop)
                           density_full_model_calibrated_drop = &
                              density_full_model_drop
                           IF (density_full_direction_scale < &
                               schur_min_coupled_scale) &
                              density_full_model_calibrated_drop = &
                              density_full_scale_quality* &
                              density_full_model_calibrated_drop
                           density_full_response_abs_step = &
                              density_full_direction_scale*density_full_response_abs_step
                           density_full_response_weighted_step = &
                              density_full_direction_scale*density_full_response_weighted_step
                           IF (response_trust > EPSILON(response_trust)) &
                              density_full_response_weighted_trust_ratio = &
                              density_full_response_weighted_step/ &
                              response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              density_full_response_abs_trust_ratio = &
                              density_full_response_abs_step/ &
                              response_abs_trust
                           density_full_trust_quality = &
                              kpoint_ot_schur_trust_quality( &
                              density_full_response_weighted_trust_ratio, &
                              density_full_response_abs_trust_ratio, 0.0_dp)
                           IF (local_ot_env(1)%schur_projector_density_full_quality_samples >= &
                               ot_kp_schur_projector_response_min_samples) THEN
                              density_full_quality_for_selection = &
                                 kpoint_ot_schur_history_quality( &
                                 local_ot_env(1)%schur_projector_density_full_drop_sum, &
                                 local_ot_env(1)%schur_projector_density_full_measured_sum, &
                                 local_ot_env(1)%schur_projector_density_full_quality_ema, &
                                 local_ot_env(1)%schur_projector_density_full_quality_samples, &
                                 ot_kp_schur_projector_response_min_samples, 0.0_dp, &
                                 ot_kp_schur_projector_response_quality_min_ratio, &
                                 ot_kp_schur_projector_response_quality_max_ratio)
                           END IF
                           IF (local_ot_env(1)%schur_projector_density_full_selected_quality_samples >= &
                               ot_kp_schur_calibration_min_samples) THEN
                              density_full_quality_for_selection = &
                                 kpoint_ot_schur_history_quality( &
                                 local_ot_env(1)%schur_projector_density_full_selected_drop_sum, &
                                 local_ot_env(1)%schur_projector_density_full_selected_measured_sum, &
                                 local_ot_env(1)%schur_projector_density_full_selected_quality_ema, &
                                 local_ot_env(1)%schur_projector_density_full_selected_quality_samples, &
                                 ot_kp_schur_calibration_min_samples, &
                                 density_full_quality_for_selection, &
                                 ot_kp_schur_projector_response_quality_min_ratio, &
                                 ot_kp_schur_projector_response_quality_max_ratio)
                              IF (residual_delta <= &
                                  ot_kp_schur_projector_coupled_tail_delta) THEN
                                 density_full_quality_for_selection = &
                                    density_full_quality_for_selection* &
                                    MAX(0.0_dp, MIN(1.0_dp, &
                                                    local_ot_env(1)% &
                                                    schur_projector_density_full_selected_residual_quality_ema))
                              END IF
                           END IF
                           IF (local_ot_env(1)%schur_projector_density_full_direct_quality_samples >= &
                               ot_kp_schur_projector_response_min_samples) THEN
                              density_full_direct_quality_for_selection = &
                                 kpoint_ot_schur_history_quality( &
                                 local_ot_env(1)%schur_projector_density_full_direct_drop_sum, &
                                 local_ot_env(1)%schur_projector_density_full_direct_measured_sum, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_ema, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                                 ot_kp_schur_projector_response_min_samples, 1.0_dp, &
                                 ot_kp_schur_projector_response_quality_min_ratio, &
                                 ot_kp_schur_projector_response_quality_max_ratio)
                              density_full_direct_quality_for_selection = &
                                 kpoint_ot_floor_bootstrap_history_quality( &
                                 density_full_direct_quality_for_selection, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_ema, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                                 ot_kp_schur_projector_response_min_samples)
                              density_full_direct_history_quality = &
                                 kpoint_ot_direct_history_quality( &
                                 local_ot_env(1)%schur_projector_density_full_direct_drop_sum, &
                                 local_ot_env(1)%schur_projector_density_full_direct_measured_sum, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_ema, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                                 ot_kp_schur_projector_response_min_samples)
                              density_full_direct_history_quality = &
                                 kpoint_ot_floor_bootstrap_history_quality( &
                                 density_full_direct_history_quality, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_ema, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                                 ot_kp_schur_projector_response_min_samples)
                              density_full_direct_history_scale = &
                                 kpoint_ot_direct_history_growth_scale( &
                                 density_full_direct_history_quality, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                                 ot_kp_schur_projector_response_min_samples)
                           END IF
                           IF (local_ot_env(1)% &
                               schur_projector_density_fdir_sel_quality_samples >= &
                               ot_kp_schur_calibration_min_samples) THEN
                              density_full_direct_quality_for_selection = &
                                 kpoint_ot_direct_selected_history_quality( &
                                 density_full_direct_quality_for_selection, &
                                 local_ot_env(1)% &
                                 schur_projector_density_fdir_sel_drop_sum, &
                                 local_ot_env(1)% &
                                 schur_projector_density_fdir_sel_measured_sum, &
                                 local_ot_env(1)% &
                                 schur_projector_density_fdir_sel_quality_ema, &
                                 local_ot_env(1)% &
                                 schur_projector_density_fdir_sel_quality_samples, &
                                 ot_kp_schur_calibration_min_samples)
                              IF (residual_delta <= &
                                  ot_kp_schur_projector_coupled_tail_delta) THEN
                                 density_full_direct_quality_for_selection = &
                                    density_full_direct_quality_for_selection* &
                                    MAX(0.0_dp, MIN(1.0_dp, &
                                                    local_ot_env(1)% &
                                                    schur_projector_density_fdir_sel_resid_quality_ema))
                              END IF
                              density_full_direct_history_scale = &
                                 MIN(density_full_direct_history_scale, &
                                     kpoint_ot_direct_history_step_scale( &
                                     density_full_direct_quality_for_selection, &
                                     local_ot_env(1)% &
                                     schur_projector_density_fdir_sel_quality_samples, &
                                     ot_kp_schur_calibration_min_samples))
                           END IF
                           density_full_history_scale = &
                              kpoint_ot_direct_history_step_scale( &
                              density_full_quality_for_selection, &
                              local_ot_env(1)%schur_projector_density_full_selected_quality_samples, &
                              ot_kp_schur_calibration_min_samples)
                           IF (density_full_history_scale < 1.0_dp) THEN
                              density_full_direction_scale = &
                                 density_full_direction_scale*density_full_history_scale
                              density_full_response_abs_step = &
                                 density_full_response_abs_step*density_full_history_scale
                              density_full_response_weighted_step = &
                                 density_full_response_weighted_step*density_full_history_scale
                              density_full_scale_quality = &
                                 kpoint_ot_schur_scale_quality( &
                                 density_full_direction_scale, &
                                 schur_min_coupled_scale)
                              density_full_model_drop = &
                                 density_full_direction_scale*density_full_gdotp - &
                                 0.5_dp*density_full_direction_scale* &
                                 density_full_direction_scale*density_full_normp
                              density_full_model_drop = MAX(0.0_dp, density_full_model_drop)
                              density_full_model_calibrated_drop = &
                                 density_full_model_drop
                              IF (density_full_direction_scale < schur_min_coupled_scale) &
                                 density_full_model_calibrated_drop = &
                                 density_full_scale_quality*density_full_model_calibrated_drop
                              IF (response_trust > EPSILON(response_trust)) &
                                 density_full_response_weighted_trust_ratio = &
                                 density_full_response_weighted_step/ &
                                 response_trust
                              IF (response_abs_trust > EPSILON(response_abs_trust)) &
                                 density_full_response_abs_trust_ratio = &
                                 density_full_response_abs_step/ &
                                 response_abs_trust
                              density_full_trust_quality = &
                                 kpoint_ot_schur_trust_quality( &
                                 density_full_response_weighted_trust_ratio, &
                                 density_full_response_abs_trust_ratio, 0.0_dp)
                           END IF
                           density_full_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              density_full_model_calibrated_drop, &
                              density_full_quality_for_selection, &
                              density_full_trust_quality* &
                              projector_physical_direct_density_audit_quality)
                           density_full_tail_probe_ready = &
                              kpoint_ot_density_full_tail_probe_ready( &
                              residual_delta, density_full_expected_drop, &
                              local_ot_env(1)%schur_projector_density_full_quality, &
                              local_ot_env(1)%schur_projector_density_full_quality_ema, &
                              local_ot_env(1)%schur_projector_density_full_quality_samples, &
                              density_full_response_weighted_trust_ratio, &
                              density_full_response_abs_trust_ratio)
                           density_full_candidate_ready = &
                              (local_ot_env(1)%schur_projector_density_full_candidate_enabled .OR. &
                               density_full_tail_probe_ready) .AND. &
                              density_full_model_calibrated_drop > &
                              ot_kp_schur_projector_density_full_min_drop .AND. &
                              density_full_expected_drop > &
                              ot_kp_schur_projector_density_full_min_drop .AND. &
                              density_full_response_weighted_step <= response_trust .AND. &
                              density_full_response_abs_step <= response_abs_trust
                        END IF
                        IF (DOT_PRODUCT(projector_physical_direct_sol, &
                                        projector_physical_direct_sol) > EPSILON(1.0_dp)) THEN
                           IF (exact_density_full_audit_ready) THEN
                              rx_e(:) = MATMUL(response_exact_physical, &
                                               projector_physical_direct_sol) + &
                                        MATMUL(response_density_full_audit_exact, &
                                               projector_physical_direct_sol)
                           ELSE
                              rx_e(:) = MATMUL(response_exact_physical, &
                                               projector_physical_direct_sol) + &
                                        MATMUL(response_density_full_exact, &
                                               projector_physical_direct_sol)
                           END IF
                           CALL project_kpoint_ot_schur_response(rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                           z_density_full_trial(:) = z_exact_physical_trial(:) + rx_e(:)
                           density_full_direct_gdot_energy = &
                              DOT_PRODUCT(grad_e, z_density_full_trial)
                           density_full_direct_gdot_rotation = &
                              DOT_PRODUCT(grad_rot, projector_physical_direct_sol)
                           density_full_direct_gdotp = density_full_direct_gdot_energy + &
                                                       density_full_direct_gdot_rotation
                           CALL kpoint_ot_mixed_projected_term(z_density_full_trial, &
                                                             z_density_full_trial, occ_curv, tether_curv, occ_curv_projection_sum, &
                                                               channel_nmo, e_offset, density_full_direct_norm_energy)
                           density_full_direct_norm_energy = &
                              MAX(0.0_dp, density_full_direct_norm_energy)
                           density_full_direct_norm_rotation = &
                              ABS(kpoint_ot_symmetric_quad(projector_physical_direct_schur_mat, &
                                                           projector_physical_direct_sol))
                           IF (density_full_direct_norm_rotation <= &
                               EPSILON(density_full_direct_norm_rotation)) &
                              density_full_direct_norm_rotation = &
                              ABS(DOT_PRODUCT(rtd, projector_physical_direct_sol))
                           IF (density_full_direct_norm_rotation <= &
                               EPSILON(density_full_direct_norm_rotation)) &
                              density_full_direct_norm_rotation = &
                              kpoint_ot_symmetric_abs_quad(projector_physical_direct_schur_mat, &
                                                           projector_physical_direct_sol)
                           density_full_direct_normp = density_full_direct_norm_energy + &
                                                       density_full_direct_norm_rotation
                           IF (density_full_direct_gdotp > 0.0_dp .AND. &
                               density_full_direct_normp > &
                               EPSILON(density_full_direct_normp)) THEN
                              density_full_direct_direction_scale = MIN(1.0_dp, &
                                                                        density_full_direct_gdotp/ &
                                                                        MAX(density_full_direct_normp, &
                                                                            EPSILON(density_full_direct_normp)))
                              density_full_direct_direction_scale = &
                                 density_full_direct_direction_scale*density_full_direct_history_scale
                              density_full_direct_response_abs_step = MAXVAL(ABS(rx_e))
                              CALL para_env_inter_kp%max(density_full_direct_response_abs_step)
                              density_full_direct_response_weighted_step = &
                                 kpoint_ot_weighted_response_step(rx_e, curv, curv_projection_sum)
                              IF (response_trust > EPSILON(response_trust) .AND. &
                                  density_full_direct_response_weighted_step > &
                                  EPSILON(density_full_direct_response_weighted_step)) &
                                 density_full_direct_direction_scale = &
                                 MIN(density_full_direct_direction_scale, &
                                     0.8_dp*response_trust/ &
                                     density_full_direct_response_weighted_step)
                              IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                                  density_full_direct_response_abs_step > &
                                  EPSILON(density_full_direct_response_abs_step)) &
                                 density_full_direct_direction_scale = &
                                 MIN(density_full_direct_direction_scale, &
                                     0.8_dp*response_abs_trust/ &
                                     density_full_direct_response_abs_step)
                              density_full_direct_scale_quality = &
                                 kpoint_ot_schur_scale_quality( &
                                 density_full_direct_direction_scale, &
                                 schur_min_coupled_scale)
                              density_full_direct_model_drop = &
                                 density_full_direct_direction_scale* &
                                 density_full_direct_gdotp - &
                                 0.5_dp*density_full_direct_direction_scale* &
                                 density_full_direct_direction_scale* &
                                 density_full_direct_normp
                              density_full_direct_model_drop = &
                                 MAX(0.0_dp, density_full_direct_model_drop)
                              density_full_direct_model_calibrated_drop = &
                                 density_full_direct_model_drop
                              IF (density_full_direct_direction_scale < schur_min_coupled_scale) &
                                 density_full_direct_model_calibrated_drop = &
                                 density_full_direct_scale_quality* &
                                 density_full_direct_model_calibrated_drop
                              density_full_direct_response_abs_step = &
                                 density_full_direct_direction_scale* &
                                 density_full_direct_response_abs_step
                              density_full_direct_response_weighted_step = &
                                 density_full_direct_direction_scale* &
                                 density_full_direct_response_weighted_step
                              IF (response_trust > EPSILON(response_trust)) &
                                 density_full_direct_response_weighted_trust_ratio = &
                                 density_full_direct_response_weighted_step/response_trust
                              IF (response_abs_trust > EPSILON(response_abs_trust)) &
                                 density_full_direct_response_abs_trust_ratio = &
                                 density_full_direct_response_abs_step/response_abs_trust
                              density_full_direct_trust_quality = &
                                 kpoint_ot_schur_trust_quality( &
                                 density_full_direct_response_weighted_trust_ratio, &
                                 density_full_direct_response_abs_trust_ratio, 0.0_dp)
                              density_full_direct_expected_drop = &
                                 kpoint_ot_schur_expected_drop( &
                                 density_full_direct_model_calibrated_drop, &
                                 density_full_direct_quality_for_selection, &
                                 density_full_direct_trust_quality* &
                                 projector_physical_direct_density_audit_quality)
                              density_full_direct_tail_probe_ready = &
                                 kpoint_ot_density_full_tail_probe_ready( &
                                 residual_delta, density_full_direct_expected_drop, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_ema, &
                                 local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                                 density_full_direct_response_weighted_trust_ratio, &
                                 density_full_direct_response_abs_trust_ratio)
                              density_full_direct_candidate_ready = &
                                 (local_ot_env(1)%schur_projector_density_full_direct_candidate_enabled .OR. &
                                  density_full_direct_tail_probe_ready) .AND. &
                                 density_full_direct_expected_drop > &
                                 ot_kp_schur_projector_density_full_min_drop .AND. &
                                 density_full_direct_model_calibrated_drop > &
                                 ot_kp_schur_projector_density_full_min_drop .AND. &
                                 density_full_direct_response_weighted_step <= response_trust .AND. &
                                 density_full_direct_response_abs_step <= response_abs_trust
                           END IF
                        END IF
                     END IF
                     IF (exact_density_full_audit_ready) THEN
                        schur(:, :) = rot_hessian_coupled(:, :) + &
                                      projector_coupled_weight* &
                                      projector_physical_direct_delta(:, :)
                        DO s = 1, nrot
                           DO r = 1, nrot
                              projected_term = 0.5_dp* &
                                               (DOT_PRODUCT(energy_cross_physical(:, r), &
                                                            response_exact_physical(:, s)) + &
                                                DOT_PRODUCT(energy_cross_physical(:, s), &
                                                            response_exact_physical(:, r)))
                              projected_term = projected_term + 0.5_dp* &
                                               (DOT_PRODUCT(energy_cross_physical(:, r), &
                                                            response_density_full_audit_exact(:, s)) + &
                                                DOT_PRODUCT(energy_cross_density_full_audit(:, r), &
                                                            response_exact_physical(:, s)) + &
                                                DOT_PRODUCT(energy_cross_density_full_audit(:, r), &
                                                            response_density_full_audit_exact(:, s)) + &
                                                DOT_PRODUCT(energy_cross_physical(:, s), &
                                                            response_density_full_audit_exact(:, r)) + &
                                                DOT_PRODUCT(energy_cross_density_full_audit(:, s), &
                                                            response_exact_physical(:, r)) + &
                                                DOT_PRODUCT(energy_cross_density_full_audit(:, s), &
                                                            response_density_full_audit_exact(:, r)))
                              schur(r, s) = schur(r, s) - projected_term
                           END DO
                        END DO
                        DO r = 1, nrot
                           row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                                         rot_hessian_projector_physical(r, r), rot_floor(r))
                           diag_shift = MAX(0.0_dp, row_floor - schur(r, r))
                           IF (diag_shift > 0.0_dp) schur(r, r) = schur(r, r) + diag_shift
                        END DO
                        DO r = 1, nrot
                           rtd(r) = grad_rot(r) + DOT_PRODUCT(response_exact_physical(:, r), grad_e) + &
                                    DOT_PRODUCT(response_density_full_audit_exact(:, r), grad_e)
                        END DO
                        density_full_global_sol(:) = rtd(:)
                        CALL dgesv(nrot, 1, schur, nrot, ipiv, density_full_global_sol, nrot, info)
                        IF (info == 0) THEN
                           density_full_global_rx_e(:) = &
                              MATMUL(response_exact_physical, density_full_global_sol) + &
                              MATMUL(response_density_full_audit_exact, density_full_global_sol)
                           CALL project_kpoint_ot_schur_response(density_full_global_rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                           z_density_full_global_trial(:) = &
                              z_exact_physical_trial(:) + density_full_global_rx_e(:)
                           density_full_global_gdot_energy = &
                              DOT_PRODUCT(grad_e, z_density_full_global_trial)
                           density_full_global_gdot_rotation = &
                              DOT_PRODUCT(grad_rot, density_full_global_sol)
                           density_full_global_gdotp = density_full_global_gdot_energy + &
                                                       density_full_global_gdot_rotation
                           CALL kpoint_ot_mixed_projected_term(z_density_full_global_trial, &
                                                               z_density_full_global_trial, occ_curv, tether_curv, &
                                                               occ_curv_projection_sum, channel_nmo, e_offset, &
                                                               density_full_global_norm_energy)
                           density_full_global_norm_energy = &
                              MAX(0.0_dp, density_full_global_norm_energy)
                           density_full_global_norm_rotation = &
                              ABS(DOT_PRODUCT(rtd, density_full_global_sol))
                           IF (density_full_global_norm_rotation <= &
                               EPSILON(density_full_global_norm_rotation)) &
                              density_full_global_norm_rotation = &
                              DOT_PRODUCT(density_full_global_sol, density_full_global_sol)
                           density_full_global_normp = density_full_global_norm_energy + &
                                                       density_full_global_norm_rotation
                        END IF
                        IF (info == 0 .AND. density_full_global_gdotp > 0.0_dp .AND. &
                            density_full_global_normp > EPSILON(density_full_global_normp)) THEN
                           density_full_global_direction_scale = density_full_global_gdotp/ &
                                                                 MAX(density_full_global_normp, EPSILON(density_full_global_normp))
                           density_full_global_response_abs_step = &
                              MAXVAL(ABS(density_full_global_rx_e))
                           CALL para_env_inter_kp%max(density_full_global_response_abs_step)
                           density_full_global_response_weighted_step = &
                              kpoint_ot_weighted_response_step( &
                              density_full_global_rx_e, curv, curv_projection_sum)
                           IF (response_trust > EPSILON(response_trust) .AND. &
                               density_full_global_response_weighted_step > &
                               EPSILON(density_full_global_response_weighted_step)) &
                              density_full_global_direction_scale = &
                              MIN(density_full_global_direction_scale, &
                                  ot_kp_schur_projector_spectral_probe_trust_fraction* &
                                  response_trust/density_full_global_response_weighted_step)
                           IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                               density_full_global_response_abs_step > &
                               EPSILON(density_full_global_response_abs_step)) &
                              density_full_global_direction_scale = &
                              MIN(density_full_global_direction_scale, &
                                  0.8_dp*response_abs_trust/density_full_global_response_abs_step)
                           density_full_global_scale_quality = &
                              kpoint_ot_schur_scale_quality( &
                              density_full_global_direction_scale, &
                              schur_min_coupled_scale)
                           density_full_global_model_drop = &
                              density_full_global_direction_scale*density_full_global_gdotp - &
                              0.5_dp*density_full_global_direction_scale* &
                              density_full_global_direction_scale*density_full_global_normp
                           density_full_global_model_drop = MAX(0.0_dp, density_full_global_model_drop)
                           density_full_global_model_calibrated_drop = &
                              density_full_global_model_drop
                           IF (density_full_global_direction_scale < &
                               schur_min_coupled_scale) &
                              density_full_global_model_calibrated_drop = &
                              density_full_global_scale_quality* &
                              density_full_global_model_calibrated_drop
                           density_full_global_response_abs_step = &
                              density_full_global_direction_scale* &
                              density_full_global_response_abs_step
                           density_full_global_response_weighted_step = &
                              density_full_global_direction_scale* &
                              density_full_global_response_weighted_step
                           IF (response_trust > EPSILON(response_trust)) &
                              density_full_global_response_weighted_trust_ratio = &
                              density_full_global_response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              density_full_global_response_abs_trust_ratio = &
                              density_full_global_response_abs_step/response_abs_trust
                           density_full_global_trust_quality = &
                              kpoint_ot_schur_metric_trust_quality( &
                              density_full_global_response_weighted_trust_ratio, 0.0_dp)
                           IF (local_ot_env(1)%schur_projector_density_full_global_quality_samples >= &
                               ot_kp_schur_projector_response_min_samples) &
                              density_full_global_quality_for_selection = &
                              MIN(1.0_dp, MAX(0.0_dp, &
                                              local_ot_env(1)%schur_projector_density_full_global_quality_ema))
                           IF (density_full_global_quality_for_selection <= 0.0_dp .AND. &
                               new_search_point .AND. &
                               local_ot_env(1)%schur_model_quality_ready .AND. &
                               projector_physical_direct_density_audit_quality >= &
                               ot_kp_schur_projector_response_quality_min_ratio .AND. &
                               density_full_global_response_weighted_trust_ratio <= &
                               ot_kp_schur_projector_spectral_probe_trust_fraction) THEN
                              density_full_global_bootstrap_ready = .TRUE.
                              density_full_global_quality_for_selection = &
                                 MIN(1.0_dp, MAX( &
                                     ot_kp_schur_projector_response_quality_min_ratio, &
                                     0.5_dp*dense_quality_for_selection))
                           END IF
                           IF (density_full_global_bootstrap_ready .AND. &
                               local_ot_env(1)%schur_projector_density_full_global_quality_samples > 0) &
                              density_full_global_quality_for_selection = &
                              kpoint_ot_floor_bootstrap_history_quality( &
                              density_full_global_quality_for_selection, &
                              local_ot_env(1)%schur_projector_density_full_global_quality, &
                              local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
                              local_ot_env(1)%schur_projector_density_full_global_quality_samples, 1)
                           density_full_global_history_scale = &
                              kpoint_ot_direct_history_step_scale( &
                              density_full_global_quality_for_selection, &
                              local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                              ot_kp_schur_projector_response_min_samples)
                           IF (density_full_global_history_scale < 1.0_dp) THEN
                              density_full_global_direction_scale = &
                                 density_full_global_direction_scale*density_full_global_history_scale
                              density_full_global_response_abs_step = &
                                 density_full_global_response_abs_step*density_full_global_history_scale
                              density_full_global_response_weighted_step = &
                                 density_full_global_response_weighted_step*density_full_global_history_scale
                              density_full_global_scale_quality = &
                                 kpoint_ot_schur_scale_quality( &
                                 density_full_global_direction_scale, &
                                 schur_min_coupled_scale)
                              density_full_global_model_drop = &
                                 density_full_global_direction_scale*density_full_global_gdotp - &
                                 0.5_dp*density_full_global_direction_scale* &
                                 density_full_global_direction_scale*density_full_global_normp
                              density_full_global_model_drop = &
                                 MAX(0.0_dp, density_full_global_model_drop)
                              density_full_global_model_calibrated_drop = &
                                 density_full_global_model_drop
                              IF (density_full_global_direction_scale < &
                                  schur_min_coupled_scale) &
                                 density_full_global_model_calibrated_drop = &
                                 density_full_global_scale_quality* &
                                 density_full_global_model_calibrated_drop
                              IF (response_trust > EPSILON(response_trust)) &
                                 density_full_global_response_weighted_trust_ratio = &
                                 density_full_global_response_weighted_step/response_trust
                              IF (response_abs_trust > EPSILON(response_abs_trust)) &
                                 density_full_global_response_abs_trust_ratio = &
                                 density_full_global_response_abs_step/response_abs_trust
                              density_full_global_trust_quality = &
                                 kpoint_ot_schur_metric_trust_quality( &
                                 density_full_global_response_weighted_trust_ratio, 0.0_dp)
                           END IF
                           density_full_global_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              density_full_global_model_calibrated_drop, &
                              density_full_global_quality_for_selection, &
                              density_full_global_trust_quality* &
                              projector_physical_direct_density_audit_quality)
                           density_full_global_tail_probe_ready = &
                              kpoint_ot_density_full_tail_probe_ready( &
                              residual_delta, density_full_global_expected_drop, &
                              local_ot_env(1)%schur_projector_density_full_global_quality, &
                              local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
                              local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                              density_full_global_response_weighted_trust_ratio, &
                              density_full_global_response_abs_trust_ratio)
                           density_full_global_candidate_ready = &
                              projector_density_full_history_enabled .AND. &
                              (density_full_global_bootstrap_ready .OR. &
                               (local_ot_env(1)%schur_projector_density_full_global_quality_samples >= &
                                ot_kp_schur_projector_response_min_samples .AND. &
                                local_ot_env(1)%schur_projector_density_full_global_quality_ema >= &
                                ot_kp_schur_projector_response_quality_min_ratio .AND. &
                                local_ot_env(1)%schur_projector_density_full_global_quality >= &
                                0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) .OR. &
                               density_full_global_tail_probe_ready) .AND. &
                              density_full_global_model_calibrated_drop > &
                              ot_kp_schur_projector_density_full_min_drop .AND. &
                              density_full_global_expected_drop > &
                              ot_kp_schur_projector_density_full_min_drop .AND. &
                              density_full_global_response_weighted_step <= response_trust
                        END IF
                     END IF
                     IF (exact_density_response_ready .AND. &
                         exact_density_full_response_ready) THEN
                        density_gap_rx_e(:) = density_full_rx_e(:) - &
                                              projector_physical_direct_density_rx_e(:)
                        density_gap_gdot = DOT_PRODUCT(grad_e, density_gap_rx_e)
                        density_gap_norm = DOT_PRODUCT(density_gap_rx_e, density_gap_rx_e)
                        density_gap_raw_abs = MAXVAL(ABS(density_gap_rx_e))
                        CALL para_env_inter_kp%max(density_gap_raw_abs)
                        density_gap_raw_weighted = &
                           kpoint_ot_weighted_response_step(density_gap_rx_e, curv, &
                                                            curv_projection_sum)
                        CALL project_kpoint_ot_descent_response( &
                           density_gap_rx_e, z_exact_physical_trial, grad_e, &
                           density_gap_projected_e, density_descent_gap_coeff, &
                           density_gap_gdot, density_descent_gap_denom, .TRUE., &
                           occ_curv, tether_curv, occ_curv_projection_sum, &
                           channel_nmo, e_offset)
                        density_descent_gap_projected_abs = MAXVAL(ABS(density_gap_projected_e))
                        CALL para_env_inter_kp%max(density_descent_gap_projected_abs)
                        density_descent_gap_projected_weighted = &
                           kpoint_ot_weighted_response_step(density_gap_projected_e, curv, &
                                                            curv_projection_sum)
                        IF (density_gap_raw_weighted > EPSILON(density_gap_raw_weighted)) &
                           density_descent_gap_recoverable_fraction = &
                           density_descent_gap_projected_weighted/density_gap_raw_weighted
                        IF (density_gap_raw_weighted > EPSILON(density_gap_raw_weighted) .AND. &
                            density_descent_gap_recoverable_fraction < &
                            ot_kp_schur_projector_response_ratio_gate) THEN
                           CALL project_kpoint_ot_descent_response( &
                              density_gap_rx_e, z_trial, grad_e, &
                              density_gap_projected_e, density_descent_gap_coeff, &
                              density_gap_gdot, density_descent_gap_denom, .TRUE., &
                              occ_curv, tether_curv, occ_curv_projection_sum, &
                              channel_nmo, e_offset)
                           density_descent_gap_projected_abs = &
                              MAXVAL(ABS(density_gap_projected_e))
                           CALL para_env_inter_kp%max(density_descent_gap_projected_abs)
                           density_descent_gap_projected_weighted = &
                              kpoint_ot_weighted_response_step(density_gap_projected_e, curv, &
                                                               curv_projection_sum)
                           density_descent_gap_recoverable_fraction = &
                              density_descent_gap_projected_weighted/density_gap_raw_weighted
                        END IF
                        density_descent_rx_e(:) = projector_physical_direct_density_rx_e(:) + &
                                                  density_gap_projected_e(:)
                        CALL project_kpoint_ot_schur_response(density_descent_rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                        density_descent_z_e(:) = z_exact_physical_trial(:) + density_descent_rx_e(:)
                        density_descent_gdot_energy = DOT_PRODUCT(grad_e, density_descent_z_e)
                        density_descent_gdot_rotation = &
                           DOT_PRODUCT(grad_rot, projector_physical_direct_sol)
                        density_descent_gdotp = density_descent_gdot_energy + &
                                                density_descent_gdot_rotation
                        CALL kpoint_ot_mixed_projected_term(density_descent_z_e, &
                                                            density_descent_z_e, occ_curv, tether_curv, occ_curv_projection_sum, &
                                                            channel_nmo, e_offset, density_descent_norm_energy)
                        density_descent_norm_energy = MAX(0.0_dp, density_descent_norm_energy)
                        density_descent_norm_rotation = &
                           ABS(kpoint_ot_symmetric_quad(projector_physical_direct_schur_mat, &
                                                        projector_physical_direct_sol))
                        IF (density_descent_norm_rotation <= EPSILON(density_descent_norm_rotation)) &
                           density_descent_norm_rotation = ABS(DOT_PRODUCT(rtd, projector_physical_direct_sol))
                        IF (density_descent_norm_rotation <= EPSILON(density_descent_norm_rotation)) &
                           density_descent_norm_rotation = &
                           kpoint_ot_symmetric_abs_quad(projector_physical_direct_schur_mat, &
                                                        projector_physical_direct_sol)
                        density_descent_normp = density_descent_norm_energy + &
                                                density_descent_norm_rotation
                        IF (density_descent_gdotp > 0.0_dp .AND. &
                            density_descent_normp > EPSILON(density_descent_normp)) THEN
                           density_descent_direction_scale = density_descent_gdotp/ &
                                                             MAX(density_descent_normp, EPSILON(density_descent_normp))
                           density_descent_model_drop = &
                              density_descent_direction_scale*density_descent_gdotp - &
                              0.5_dp*density_descent_direction_scale* &
                              density_descent_direction_scale*density_descent_normp
                           density_descent_response_abs_step = density_descent_direction_scale* &
                                                               MAXVAL(ABS(density_descent_rx_e))
                           CALL para_env_inter_kp%max(density_descent_response_abs_step)
                           density_descent_response_weighted_step = density_descent_direction_scale* &
                                                                    kpoint_ot_weighted_response_step(density_descent_rx_e, curv, &
                                                                                                     curv_projection_sum)
                           density_descent_history_scale = 1.0_dp
                           IF (response_trust > EPSILON(response_trust) .AND. &
                               density_descent_response_weighted_step > &
                               EPSILON(density_descent_response_weighted_step)) &
                              density_descent_history_scale = MIN(density_descent_history_scale, &
                                                                  response_trust/density_descent_response_weighted_step)
                           IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                               density_descent_response_abs_step > &
                               EPSILON(density_descent_response_abs_step)) &
                              density_descent_history_scale = MIN(density_descent_history_scale, &
                                                                  response_abs_trust/density_descent_response_abs_step)
                           density_descent_history_scale = MIN(1.0_dp, &
                                                               density_descent_history_scale)
                           IF (density_descent_history_scale < 1.0_dp) THEN
                              density_descent_direction_scale = density_descent_history_scale* &
                                                                density_descent_direction_scale
                              density_descent_response_abs_step = density_descent_history_scale* &
                                                                  density_descent_response_abs_step
                              density_descent_response_weighted_step = density_descent_history_scale* &
                                                                       density_descent_response_weighted_step
                              density_descent_model_drop = &
                                 density_descent_direction_scale*density_descent_gdotp - &
                                 0.5_dp*density_descent_direction_scale* &
                                 density_descent_direction_scale*density_descent_normp
                           END IF
                           density_descent_model_drop = MAX(0.0_dp, density_descent_model_drop)
                           density_descent_scale_quality = &
                              kpoint_ot_schur_scale_quality(density_descent_direction_scale, &
                                                            schur_min_coupled_scale)
                           density_descent_model_calibrated_drop = density_descent_model_drop
                           IF (density_descent_direction_scale < schur_min_coupled_scale) &
                              density_descent_model_calibrated_drop = &
                              density_descent_scale_quality*density_descent_model_calibrated_drop
                           density_descent_growth_scale = &
                              kpoint_ot_density_descent_history_growth_scale( &
                              density_descent_bootstrap_quality, &
                              local_ot_env(1)%schur_projector_density_descent_support_ema, &
                              local_ot_env(1)%schur_projector_density_descent_quality_samples, &
                              ot_kp_schur_projector_response_min_samples)
                           density_descent_model_calibrated_drop = &
                              density_descent_growth_scale*density_descent_model_calibrated_drop
                           IF (response_trust > EPSILON(response_trust)) &
                              density_descent_response_weighted_trust_ratio = &
                              density_descent_response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              density_descent_response_abs_trust_ratio = &
                              density_descent_response_abs_step/response_abs_trust
                           density_descent_trust_quality = &
                              kpoint_ot_schur_trust_quality( &
                              density_descent_response_weighted_trust_ratio, &
                              density_descent_response_abs_trust_ratio, 0.0_dp)
                           density_descent_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              density_descent_model_calibrated_drop, &
                              density_descent_quality_for_selection, &
                              density_descent_trust_quality)
                           density_descent_candidate_ready = &
                              ((local_ot_env(1)%schur_projector_density_descent_quality_samples >= &
                                ot_kp_schur_projector_response_min_samples .AND. &
                                local_ot_env(1)%schur_projector_density_descent_support_ready .AND. &
                                local_ot_env(1)%schur_projector_density_descent_quality_ema >= &
                                ot_kp_schur_projector_response_quality_min_ratio .AND. &
                                local_ot_env(1)%schur_projector_density_descent_quality >= &
                                0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) .OR. &
                               density_descent_bootstrap_ready) .AND. &
                              density_descent_quality_for_selection >= &
                              ot_kp_schur_projector_response_quality_min_ratio .AND. &
                              density_descent_expected_drop > &
                              EPSILON(density_descent_expected_drop) .AND. &
                              density_descent_response_weighted_step <= response_trust .AND. &
                              density_descent_response_abs_step <= response_abs_trust
                        END IF
                        IF (density_gap_gdot > 0.0_dp .AND. &
                            density_gap_norm > EPSILON(density_gap_norm)) THEN
                           density_gap_direction_scale = density_gap_gdot/ &
                                                         MAX(density_gap_norm, &
                                                             EPSILON(density_gap_norm))
                           density_gap_scale_quality = &
                              kpoint_ot_schur_scale_quality(density_gap_direction_scale, &
                                                            schur_min_coupled_scale)
                           density_gap_model_drop = 0.5_dp*density_gap_direction_scale* &
                                                    density_gap_gdot
                           density_gap_model_calibrated_drop = density_gap_model_drop
                           IF (density_gap_direction_scale < schur_min_coupled_scale) &
                              density_gap_model_calibrated_drop = &
                              density_gap_scale_quality*density_gap_model_calibrated_drop
                           density_gap_response_abs_step = density_gap_direction_scale* &
                                                           MAXVAL(ABS(density_gap_rx_e))
                           CALL para_env_inter_kp%max(density_gap_response_abs_step)
                           density_gap_response_weighted_step = density_gap_direction_scale* &
                                                                kpoint_ot_weighted_response_step(density_gap_rx_e, curv, &
                                                                                                 curv_projection_sum)
                           IF (response_trust > EPSILON(response_trust)) &
                              density_gap_response_weighted_trust_ratio = &
                              density_gap_response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              density_gap_response_abs_trust_ratio = &
                              density_gap_response_abs_step/response_abs_trust
                           density_gap_trust_quality = &
                              kpoint_ot_schur_trust_quality( &
                              density_gap_response_weighted_trust_ratio, &
                              density_gap_response_abs_trust_ratio, 0.0_dp)
                           density_gap_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              density_gap_model_calibrated_drop, &
                              projector_physical_quality_for_selection, &
                              density_gap_trust_quality)
                        END IF
                     END IF
                     IF (projector_plateau_gap_model_enabled .AND. &
                         exact_density_plateau_response_ready) THEN
                        density_plateau_rx_e(:) = &
                           MATMUL(response_exact_physical, projector_physical_direct_sol) + &
                           MATMUL(response_density_plateau_exact, projector_physical_direct_sol)
                        CALL project_kpoint_ot_schur_response(density_plateau_rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                        density_plateau_z_e(:) = z_exact_physical_trial(:) + density_plateau_rx_e(:)
                        density_plateau_gdot_energy = DOT_PRODUCT(grad_e, density_plateau_z_e)
                        density_plateau_gdot_rotation = DOT_PRODUCT(grad_rot, &
                                                                    projector_physical_direct_sol)
                        density_plateau_gdotp = density_plateau_gdot_energy + &
                                                density_plateau_gdot_rotation
                        CALL kpoint_ot_mixed_projected_term(density_plateau_z_e, &
                                                            density_plateau_z_e, occ_curv, tether_curv, occ_curv_projection_sum, &
                                                            channel_nmo, e_offset, density_plateau_norm_energy)
                        density_plateau_norm_energy = MAX(0.0_dp, density_plateau_norm_energy)
                        density_plateau_norm_rotation = &
                           DOT_PRODUCT(projector_physical_direct_sol, &
                                       projector_physical_direct_sol)
                        density_plateau_normp = density_plateau_norm_energy + &
                                                density_plateau_norm_rotation
                        IF (density_plateau_gdotp > 0.0_dp .AND. &
                            density_plateau_normp > EPSILON(density_plateau_normp)) THEN
                           density_plateau_direction_scale = density_plateau_gdotp/ &
                                                             MAX(density_plateau_normp, EPSILON(density_plateau_normp))
                           density_plateau_scale_quality = &
                              kpoint_ot_schur_scale_quality(density_plateau_direction_scale, &
                                                            schur_min_coupled_scale)
                           density_plateau_model_drop = 0.5_dp*density_plateau_direction_scale* &
                                                        density_plateau_gdotp
                           density_plateau_model_calibrated_drop = density_plateau_model_drop
                           IF (density_plateau_direction_scale < schur_min_coupled_scale) &
                              density_plateau_model_calibrated_drop = &
                              density_plateau_scale_quality*density_plateau_model_calibrated_drop
                           density_plateau_response_abs_step = density_plateau_direction_scale* &
                                                               MAXVAL(ABS(density_plateau_rx_e))
                           CALL para_env_inter_kp%max(density_plateau_response_abs_step)
                           density_plateau_response_weighted_step = &
                              density_plateau_direction_scale* &
                              kpoint_ot_weighted_response_step(density_plateau_rx_e, curv, &
                                                               curv_projection_sum)
                           IF (response_trust > EPSILON(response_trust)) &
                              density_plateau_response_weighted_trust_ratio = &
                              density_plateau_response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              density_plateau_response_abs_trust_ratio = &
                              density_plateau_response_abs_step/response_abs_trust
                           density_plateau_model_gap_drop = &
                              kpoint_ot_response_mismatch_drop( &
                              projector_physical_direct_density_rx_e, density_plateau_rx_e, &
                              curv, density_plateau_direction_scale)
                           density_plateau_trust_quality = &
                              kpoint_ot_schur_trust_quality( &
                              density_plateau_response_weighted_trust_ratio, &
                              density_plateau_response_abs_trust_ratio, 0.0_dp)
                           density_plateau_expected_drop = &
                              kpoint_ot_schur_expected_drop( &
                              density_plateau_model_calibrated_drop, &
                              projector_physical_quality_for_selection, &
                              density_plateau_trust_quality)
                        END IF
                     END IF
                     IF (local_ot_env(1)%schur_projector_mode_quality_samples >= &
                         ot_kp_schur_calibration_min_samples) THEN
                        response_physical_model(:, :) = response_exact_physical(:, :)
                        IF (exact_density_full_response_ready) THEN
                           response_physical_model(:, :) = response_physical_model(:, :) + &
                                                           response_density_full_exact(:, :)
                        ELSE IF (exact_density_direct_response_ready) THEN
                           response_physical_model(:, :) = response_physical_model(:, :) + &
                                                           response_density_direct_exact(:, :)
                        END IF
                        CALL audit_kpoint_ot_projector_response_modes(rot_hessian, &
                                                                      rot_hessian_projector_physical_active, &
                                                                      projector_physical_direct_sol, response_exact_raw, &
                                                                      response_physical_model, curv, occ_curv, tether_curv, &
                                                                      occ_curv_projection_sum, channel_nmo, e_offset, .TRUE., &
                                                                      projector_coupled_weight, &
                                                                      residual_delta, projector_mode_history_quality, &
                                                                      local_ot_env(1)%schur_projector_mode_trust_ema, &
                                                                      projector_mode_history_response_ratio, grad_e, &
                                                                      z_exact_physical_trial + projector_physical_direct_rx_e, &
                                                                      projector_physical_direct_rx_e, &
                                                                      projector_physical_direct_response_rx_e, &
                                                                      projector_physical_direct_response_weight, &
                                                                      projector_physical_direct_response_correction_drop, &
                                                                      projector_physical_direct_response_correction_negative, &
                                                                      projector_physical_direct_response_raw_negative_fraction, &
                                                                      projector_physical_direct_response_positive_drop, &
                                                                      projector_physical_direct_response_negative_drop, &
                                                                      projector_physical_direct_response_cross_drop, &
                                                                      projector_physical_direct_response_positive_coeff, &
                                                                      projector_physical_direct_response_negative_coeff, &
                                                                      raw_residual_delta=response_raw_delta)
                        IF (projector_physical_direct_shadow_enabled) &
                           CALL audit_kpoint_ot_projector_response_modes(rot_hessian, &
                                                                         rot_hessian_projector_physical_diagref, &
                                                                         projector_physical_direct_sol, response_exact_raw, &
                                                                         response_physical_model, curv, occ_curv, tether_curv, &
                                                                         occ_curv_projection_sum, channel_nmo, e_offset, .TRUE., &
                                                                         projector_coupled_weight, &
                                                                         residual_delta, projector_mode_history_quality, &
                                                                         local_ot_env(1)%schur_projector_mode_trust_ema, &
                                                                         projector_mode_history_response_ratio, grad_e, &
                                                                         z_exact_physical_trial + projector_physical_direct_rx_e, &
                                                                         projector_physical_direct_rx_e, &
                                                                         projector_physical_direct_diagref_rx_e, &
                                                                         projector_physical_direct_diagref_weight, &
                                                                         projector_physical_direct_diagref_correction_drop, &
                                                                         projector_physical_direct_diagref_correction_negative, &
                                                                         projector_physical_direct_diagref_raw_negative_fraction, &
                                                                         projector_physical_direct_diagref_positive_drop, &
                                                                         projector_physical_direct_diagref_negative_drop, &
                                                                         projector_physical_direct_diagref_cross_drop, &
                                                                         projector_physical_direct_diagref_positive_coeff, &
                                                                         projector_physical_direct_diagref_negative_coeff, &
                                                                         raw_residual_delta=response_raw_delta)
                        IF (projector_physical_direct_diagref_weight > &
                            EPSILON(projector_physical_direct_diagref_weight)) THEN
                           CALL project_kpoint_ot_schur_response( &
                              projector_physical_direct_diagref_rx_e, occ_curv, tether_curv, &
                              occ_curv_projection_sum, channel_nmo, e_offset)
                           projector_physical_direct_diagref_gdot_energy = &
                              DOT_PRODUCT(grad_e, z_exact_physical_trial + &
                                          projector_physical_direct_diagref_rx_e)
                           projector_physical_direct_diagref_gdot_rotation = &
                              DOT_PRODUCT(grad_rot, projector_physical_direct_sol)
                           projector_physical_direct_diagref_norm_energy = &
                              DOT_PRODUCT(z_exact_physical_trial + &
                                          projector_physical_direct_diagref_rx_e, &
                                          z_exact_physical_trial + &
                                          projector_physical_direct_diagref_rx_e)
                           projector_physical_direct_diagref_norm_rotation = &
                              DOT_PRODUCT(projector_physical_direct_sol, &
                                          projector_physical_direct_sol)
                           projector_physical_direct_diagref_gdotp = &
                              projector_physical_direct_diagref_gdot_energy + &
                              projector_physical_direct_diagref_gdot_rotation
                           projector_physical_direct_diagref_normp = &
                              projector_physical_direct_diagref_norm_energy + &
                              projector_physical_direct_diagref_norm_rotation
                           IF (projector_physical_direct_diagref_gdotp > 0.0_dp .AND. &
                               projector_physical_direct_diagref_normp > &
                               EPSILON(projector_physical_direct_diagref_normp)) THEN
                              projector_physical_direct_diagref_direction_scale = &
                                 projector_physical_direct_diagref_gdotp/ &
                                 MAX(projector_physical_direct_diagref_normp, &
                                     EPSILON(projector_physical_direct_diagref_normp))
                              projector_physical_direct_diagref_scale_quality = &
                                 kpoint_ot_schur_scale_quality( &
                                 projector_physical_direct_diagref_direction_scale, &
                                 schur_min_coupled_scale)
                              projector_physical_direct_diagref_response_abs_step = &
                                 projector_physical_direct_diagref_direction_scale* &
                                 MAXVAL(ABS(projector_physical_direct_diagref_rx_e))
                              CALL para_env_inter_kp%max(projector_physical_direct_diagref_response_abs_step)
                              projector_physical_direct_diagref_response_weighted_step = &
                                 projector_physical_direct_diagref_direction_scale* &
                                 kpoint_ot_weighted_response_step( &
                                 projector_physical_direct_diagref_rx_e, curv, &
                                 curv_projection_sum)
                              projector_physical_direct_diagref_response_weighted_trust_ratio = 0.0_dp
                              IF (response_trust > EPSILON(response_trust)) &
                                 projector_physical_direct_diagref_response_weighted_trust_ratio = &
                                 projector_physical_direct_diagref_response_weighted_step/ &
                                 response_trust
                              projector_physical_direct_diagref_response_abs_trust_ratio = 0.0_dp
                              IF (response_abs_trust > EPSILON(response_abs_trust)) &
                                 projector_physical_direct_diagref_response_abs_trust_ratio = &
                                 projector_physical_direct_diagref_response_abs_step/ &
                                 response_abs_trust
                              projector_physical_direct_diagref_trust_quality = &
                                 kpoint_ot_schur_trust_quality( &
                                 projector_physical_direct_diagref_response_weighted_trust_ratio, &
                                 projector_physical_direct_diagref_response_abs_trust_ratio, &
                                 0.0_dp)
                              IF (projector_physical_direct_diagref_response_weighted_step <= &
                                  response_trust .AND. &
                                  projector_physical_direct_diagref_response_abs_step <= &
                                  response_abs_trust) THEN
                                 projector_physical_direct_diagref_model_drop = 0.5_dp* &
                                                                                projector_physical_direct_diagref_direction_scale* &
                                                                                projector_physical_direct_diagref_gdotp
                                 projector_physical_direct_diagref_model_calibrated_drop = &
                                    projector_physical_direct_diagref_model_drop
                                 IF (projector_physical_direct_diagref_direction_scale < &
                                     schur_min_coupled_scale) &
                                    projector_physical_direct_diagref_model_calibrated_drop = &
                                    projector_physical_direct_diagref_scale_quality* &
                                    projector_physical_direct_diagref_model_calibrated_drop
                                 projector_physical_direct_diagref_expected_drop = &
                                    kpoint_ot_schur_expected_drop( &
                                    projector_physical_direct_diagref_model_calibrated_drop, &
                                    projector_diagref_quality_for_selection, &
                                    projector_physical_direct_diagref_trust_quality)
                                 projector_physical_direct_diagref_candidate_ready = &
                                    projector_physical_direct_diagref_model_calibrated_drop > &
                                    EPSILON(projector_physical_direct_diagref_model_drop)
                              END IF
                           END IF
                        END IF
                        IF (projector_physical_direct_response_weight > &
                            EPSILON(projector_physical_direct_response_weight)) THEN
                           projector_physical_direct_rx_e(:) = &
                              projector_physical_direct_response_rx_e(:)
                           CALL project_kpoint_ot_schur_response(projector_physical_direct_rx_e, &
                                                              occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                           projector_physical_direct_model_e(:) = &
                              projector_physical_direct_rx_e(:)
                        END IF
                        IF (projector_plateau_gap_model_enabled .AND. &
                            exact_density_response_ready .AND. &
                            exact_density_full_response_ready) THEN
                           direct_pg_base_e(:) = projector_physical_direct_rx_e(:)
                           CALL audit_kpoint_ot_projector_response_modes( &
                              rot_hessian_projector_physical_offdiag_active, &
                              rot_hessian_projector_physical_offdiag_plateau_active, &
                              projector_physical_direct_sol, response_density_exact, &
                              response_density_full_exact, curv, occ_curv, tether_curv, &
                              occ_curv_projection_sum, channel_nmo, e_offset, .TRUE., &
                              projector_coupled_weight, &
                              residual_delta, projector_mode_history_quality, &
                              local_ot_env(1)%schur_projector_mode_trust_ema, &
                              projector_mode_history_response_ratio, grad_e, &
                              z_exact_physical_trial + direct_pg_base_e, direct_pg_base_e, &
                              direct_pg_rx_e, direct_pg_response_weight, &
                              direct_pg_correction_drop, direct_pg_correction_negative, &
                              direct_pg_raw_negative_fraction, direct_pg_positive_drop, &
                              direct_pg_negative_drop, direct_pg_cross_drop, &
                              direct_pg_positive_coeff, direct_pg_negative_coeff, &
                              raw_residual_delta=response_raw_delta)
                           CALL project_kpoint_ot_schur_response(direct_pg_rx_e, occ_curv, &
                                                                 tether_curv, occ_curv_projection_sum, channel_nmo, e_offset)
                           direct_pg_base_e(:) = direct_pg_rx_e(:) - direct_pg_base_e(:)
                           CALL kpoint_ot_mixed_projected_term(direct_pg_base_e, &
                                                               direct_pg_base_e, occ_curv, tether_curv, &
                                                               occ_curv_projection_sum, channel_nmo, e_offset, &
                                                               direct_pg_metric_drop)
                           direct_pg_metric_drop = 0.5_dp*MAX(0.0_dp, direct_pg_metric_drop)
                           direct_pg_metric_step = &
                              kpoint_ot_weighted_response_step(direct_pg_base_e, curv, &
                                                               curv_projection_sum)
                           IF (direct_pg_correction_drop > EPSILON(direct_pg_correction_drop)) &
                              direct_pg_metric_ratio = &
                              direct_pg_metric_drop/direct_pg_correction_drop
                        END IF
                     END IF
                     projector_physical_direct_z_e(:) = z_exact_physical_trial(:) + &
                                                        projector_physical_direct_rx_e(:)
                     projector_physical_direct_gdot_base_energy = &
                        DOT_PRODUCT(grad_e, z_exact_physical_trial)
                     projector_physical_direct_gdot_raw_response = &
                        DOT_PRODUCT(grad_e, projector_physical_direct_rx_e)
                     projector_physical_direct_gdot_model_response = &
                        DOT_PRODUCT(grad_e, projector_physical_direct_model_e)
                     projector_physical_direct_gdot_energy = &
                        DOT_PRODUCT(grad_e, projector_physical_direct_z_e)
                     projector_physical_direct_gdot_rotation = &
                        DOT_PRODUCT(grad_rot, projector_physical_direct_sol)
                     projector_physical_direct_norm_energy = DOT_PRODUCT(projector_physical_direct_z_e, &
                                                                         projector_physical_direct_z_e)
                     projector_physical_direct_norm_rotation = DOT_PRODUCT(projector_physical_direct_sol, &
                                                                           projector_physical_direct_sol)
                     CALL kpoint_ot_mixed_projected_term(projector_physical_direct_z_e, &
                                                         projector_physical_direct_z_e, occ_curv, tether_curv, &
                                                         occ_curv_projection_sum, channel_nmo, e_offset, &
                                                         projector_physical_direct_metric_norm_energy)
                     projector_physical_direct_metric_norm_energy = &
                        MAX(0.0_dp, projector_physical_direct_metric_norm_energy)
                     ! Indefinite physical Schur curvature is a trust signal,
                     ! not a reason to suppress the candidate completely.
                     projector_physical_direct_metric_norm_rotation = &
                        ABS(kpoint_ot_symmetric_quad(projector_physical_direct_schur_mat, &
                                                     projector_physical_direct_sol))
                     IF (projector_physical_direct_metric_norm_rotation <= &
                         EPSILON(projector_physical_direct_metric_norm_rotation)) &
                        projector_physical_direct_metric_norm_rotation = &
                        ABS(DOT_PRODUCT(rtd, projector_physical_direct_sol))
                     IF (projector_physical_direct_metric_norm_rotation <= &
                         EPSILON(projector_physical_direct_metric_norm_rotation)) &
                        projector_physical_direct_metric_norm_rotation = &
                        kpoint_ot_symmetric_abs_quad(projector_physical_direct_schur_mat, &
                                                     projector_physical_direct_sol)
                     projector_physical_direct_metric_normp = &
                        projector_physical_direct_metric_norm_energy + &
                        projector_physical_direct_metric_norm_rotation
                     projector_physical_direct_normp = projector_physical_direct_norm_energy + &
                                                       projector_physical_direct_norm_rotation
                     IF (projector_physical_direct_normp > &
                         EPSILON(projector_physical_direct_normp)) &
                        projector_physical_direct_metric_norm_ratio = &
                        projector_physical_direct_metric_normp/ &
                        projector_physical_direct_normp
                     IF (logger%iter_info%print_level >= high_print_level .AND. &
                         projector_physical_direct_norm_rotation > &
                         EPSILON(projector_physical_direct_norm_rotation) .AND. &
                         projector_physical_direct_metric_norm_rotation > &
                         EPSILON(projector_physical_direct_metric_norm_rotation)) THEN
                        projector_physical_direct_soft_cut = &
                           projector_physical_direct_metric_norm_ratio
                        rhs(:) = MATMUL(TRANSPOSE(projector_physical_direct_schur_evec), &
                                        projector_physical_direct_sol)
                        projector_physical_direct_soft_norm_fraction = 0.0_dp
                        projector_physical_direct_soft_metric_fraction = 0.0_dp
                        DO r = 1, nrot
                           IF (projector_physical_direct_schur_eval(r) <= &
                               projector_physical_direct_soft_cut) THEN
                              projector_physical_direct_soft_norm_fraction = &
                                 projector_physical_direct_soft_norm_fraction + rhs(r)*rhs(r)
                              projector_physical_direct_soft_metric_fraction = &
                                 projector_physical_direct_soft_metric_fraction + &
                                 MAX(0.0_dp, projector_physical_direct_schur_eval(r))* &
                                 rhs(r)*rhs(r)
                           END IF
                        END DO
                        projector_physical_direct_soft_norm_fraction = &
                           projector_physical_direct_soft_norm_fraction/ &
                           projector_physical_direct_norm_rotation
                        projector_physical_direct_soft_metric_fraction = &
                           projector_physical_direct_soft_metric_fraction/ &
                           projector_physical_direct_metric_norm_rotation
                     END IF
                     projector_physical_direct_gdotp = projector_physical_direct_gdot_energy + &
                                                       projector_physical_direct_gdot_rotation
                     projector_physical_direct_norm_ratio = projector_physical_direct_normp/ &
                                                            MAX(gnorm, EPSILON(1.0_dp))
                     IF (projector_physical_direct_gdotp > 0.0_dp .AND. &
                         projector_physical_direct_normp > EPSILON(projector_physical_direct_normp) .AND. &
                         projector_physical_direct_metric_normp > &
                         EPSILON(projector_physical_direct_metric_normp)) THEN
                        projector_physical_direct_euclidean_scale = &
                           projector_physical_direct_gdotp/ &
                           MAX(projector_physical_direct_normp, EPSILON(projector_physical_direct_normp))
                        projector_physical_direct_curvature_scale = &
                           projector_physical_direct_gdotp/ &
                           MAX(projector_physical_direct_metric_normp, &
                               EPSILON(projector_physical_direct_metric_normp))
                        projector_physical_direct_unit_abs_step = &
                           MAXVAL(ABS(projector_physical_direct_rx_e))
                        CALL para_env_inter_kp%max(projector_physical_direct_unit_abs_step)
                        projector_physical_direct_unit_weighted_step = &
                           kpoint_ot_weighted_response_step(projector_physical_direct_rx_e, curv, &
                                                            curv_projection_sum)
                        projector_physical_direct_unit_model_gap = &
                           MAXVAL(ABS(projector_physical_direct_model_e - projector_physical_direct_rx_e))
                        projector_physical_direct_unit_model_gap_drop = &
                           kpoint_ot_response_mismatch_drop(projector_physical_direct_rx_e, &
                                                            projector_physical_direct_model_e, curv, &
                                                            1.0_dp)
                        projector_physical_direct_unit_trace_invariant_gap_drop = &
                           kpoint_ot_direct_trace_model_gap_drop( &
                           projector_physical_direct_trace_actual_quad, &
                           projector_physical_direct_trace_invariant_quad, 1.0_dp)
                        projector_physical_direct_unit_trace_gap_drop = 0.0_dp
                        IF (projector_physical_direct_mixed_enabled) &
                           projector_physical_direct_unit_trace_gap_drop = &
                           kpoint_ot_direct_trace_model_gap_drop( &
                           projector_physical_direct_trace_actual_quad, &
                           projector_physical_direct_trace_active_quad, 1.0_dp)
                        projector_physical_direct_trace_trust_gap_drop = &
                           projector_physical_direct_unit_trace_invariant_gap_drop
                        IF (projector_physical_direct_mixed_enabled .AND. &
                            projector_physical_direct_unit_trace_gap_drop > &
                            EPSILON(projector_physical_direct_unit_trace_gap_drop)) &
                           projector_physical_direct_trace_trust_gap_drop = &
                           MIN(projector_physical_direct_trace_trust_gap_drop, &
                               projector_physical_direct_unit_trace_gap_drop)
                        projector_physical_direct_trust_scale = 1.0_dp
                        IF (response_trust > EPSILON(response_trust) .AND. &
                            projector_physical_direct_unit_weighted_step > &
                            EPSILON(projector_physical_direct_unit_weighted_step)) &
                           projector_physical_direct_trust_scale = &
                           MIN(projector_physical_direct_trust_scale, &
                               0.8_dp*response_trust/ &
                               projector_physical_direct_unit_weighted_step)
                        IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                            projector_physical_direct_unit_abs_step > &
                            EPSILON(projector_physical_direct_unit_abs_step)) &
                           projector_physical_direct_trust_scale = &
                           MIN(projector_physical_direct_trust_scale, &
                               0.8_dp*response_abs_trust/ &
                               projector_physical_direct_unit_abs_step)
                        direction_scale = 1.0_dp
                        direction_scale = MIN(direction_scale, &
                                              projector_physical_direct_curvature_scale)
                        direction_scale = MIN(direction_scale, projector_physical_direct_trust_scale)
                        projector_physical_direct_direction_scale = direction_scale
                        projector_physical_direct_norm_ratio = &
                           direction_scale*direction_scale* &
                           projector_physical_direct_normp/MAX(gnorm, EPSILON(1.0_dp))
                        IF (projector_physical_direct_norm_ratio > max_norm_ratio .AND. &
                            max_norm_ratio > 0.0_dp) THEN
                           projector_physical_direct_normcap_scale = &
                              direction_scale*SQRT(max_norm_ratio/ &
                                                   MAX(projector_physical_direct_norm_ratio, &
                                                       EPSILON(projector_physical_direct_norm_ratio)))
                           projector_physical_direct_normcap_norm_ratio = &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_normp/MAX(gnorm, EPSILON(1.0_dp))
                           projector_physical_direct_normcap_model_drop = &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_gdotp - &
                              0.5_dp*projector_physical_direct_normcap_scale* &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_metric_normp
                           projector_physical_direct_normcap_model_drop = &
                              MAX(0.0_dp, projector_physical_direct_normcap_model_drop)
                           projector_physical_direct_normcap_gap_drop = &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_unit_model_gap_drop
                           projector_physical_direct_normcap_model_calibrated_drop = &
                              MAX(0.0_dp, projector_physical_direct_normcap_model_drop - &
                                  projector_physical_direct_normcap_gap_drop)
                           projector_physical_direct_normcap_response_abs_step = &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_unit_abs_step
                           projector_physical_direct_normcap_response_weighted_step = &
                              projector_physical_direct_normcap_scale* &
                              projector_physical_direct_unit_weighted_step
                           ! Audit only: accepted-drop history promoted these
                           ! norm-limited soft-mode steps too eagerly for Al.
                           projector_physical_direct_normcap_shadow_ready = &
                              projector_physical_direct_normcap_model_calibrated_drop > &
                              EPSILON(projector_physical_direct_normcap_model_drop) .AND. &
                              projector_physical_direct_normcap_model_drop == &
                              projector_physical_direct_normcap_model_drop .AND. &
                              projector_physical_direct_normcap_response_weighted_step <= &
                              response_trust .AND. &
                              projector_physical_direct_normcap_response_abs_step <= &
                              response_abs_trust
                        END IF
                        IF (direction_scale > 0.0_dp .AND. &
                            projector_physical_direct_norm_ratio <= max_norm_ratio) THEN
                           projector_physical_direct_direction_scale = direction_scale
                           projector_physical_direct_scale_quality = &
                              kpoint_ot_schur_scale_quality(direction_scale, &
                                                            schur_min_coupled_scale)
                           projector_physical_direct_z_e(:) = direction_scale*projector_physical_direct_z_e(:)
                           projector_physical_direct_sol(:) = direction_scale*projector_physical_direct_sol(:)
                           projector_physical_direct_model_drop = &
                              direction_scale*projector_physical_direct_gdotp - &
                              0.5_dp*direction_scale*direction_scale* &
                              projector_physical_direct_metric_normp
                           projector_physical_direct_model_drop = &
                              MAX(0.0_dp, projector_physical_direct_model_drop)
                           projector_physical_direct_response_abs_step = &
                              direction_scale*projector_physical_direct_unit_abs_step
                           projector_physical_direct_response_weighted_step = &
                              direction_scale*projector_physical_direct_unit_weighted_step
                           projector_physical_direct_model_gap = &
                              direction_scale*projector_physical_direct_unit_model_gap
                           projector_physical_direct_model_gap_drop = &
                              direction_scale*direction_scale* &
                              projector_physical_direct_unit_model_gap_drop
                           projector_physical_direct_model_calibrated_drop = &
                              MAX(0.0_dp, projector_physical_direct_model_drop - &
                                  projector_physical_direct_model_gap_drop)
                           projector_physical_direct_trace_invariant_trust_quality = &
                              kpoint_ot_direct_trace_mismatch_trust( &
                              projector_physical_direct_model_drop, &
                              direction_scale*direction_scale* &
                              projector_physical_direct_trace_trust_gap_drop, &
                              projector_physical_trace_invariant_quality_for_selection, &
                              local_ot_env(1)%schur_projector_physical_quality_samples)
                           projector_physical_direct_model_gap_trust = schur_model_gap_factor*response_trust
                           IF (projector_physical_direct_model_gap_trust > &
                               EPSILON(projector_physical_direct_model_gap_trust)) &
                              projector_physical_direct_model_gap_ratio = &
                              projector_physical_direct_model_gap/ &
                              projector_physical_direct_model_gap_trust
                           IF (response_trust > EPSILON(response_trust)) &
                              projector_physical_direct_response_weighted_trust_ratio = &
                              projector_physical_direct_response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              projector_physical_direct_response_abs_trust_ratio = &
                              projector_physical_direct_response_abs_step/response_abs_trust
                           projector_physical_direct_trust_quality = &
                              kpoint_ot_schur_trust_quality( &
                              projector_physical_direct_response_weighted_trust_ratio, &
                              projector_physical_direct_response_abs_trust_ratio, &
                              projector_physical_direct_model_gap_ratio)
                           projector_physical_direct_line_step_curvature = &
                              projector_physical_direct_curvature_scale
                           projector_physical_direct_line_step_trust = &
                              projector_physical_direct_trust_scale
                           projector_physical_direct_line_step = &
                              direction_scale
                           IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
                              projector_physical_direct_quality_for_selection = &
                              kpoint_ot_direct_tail_selection_quality( &
                              projector_physical_direct_quality_for_selection, &
                              projector_physical_direct_history_quality)
                              projector_physical_direct_quality_for_selection = &
                              kpoint_ot_direct_tail_residual_selection_quality( &
                              projector_physical_direct_quality_for_selection, &
                              projector_physical_trace_invariant_quality_for_selection, &
                              local_ot_env(1)%schur_projector_physical_direct_selected_quality, &
                              local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema, &
                              local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality, &
                              local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema, &
                              local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples, &
                              ot_kp_schur_calibration_min_samples)
                           END IF
                           ! The physical-direct candidate is selected only after
                           ! accepted-drop history proves it conservative.  Keep the
                           ! Euclidean z.z=g.z scale diagnostic separate from the
                           ! Mermin-metric curvature/trust scale used above.
                           projector_physical_direct_expected_drop = &
                              kpoint_ot_schur_expected_drop(projector_physical_direct_model_calibrated_drop, &
                                                            projector_physical_direct_quality_for_selection* &
                                                            projector_plateau_gap_quality_for_selection, &
                                                            projector_physical_direct_trust_quality* &
                                                            projector_physical_direct_trace_invariant_trust_quality* &
                                                            projector_physical_direct_density_audit_quality)
                           projector_physical_direct_candidate_ready = &
                              projector_physical_direct_model_calibrated_drop > &
                              EPSILON(projector_physical_direct_model_drop) .AND. &
                              projector_physical_direct_response_weighted_step <= response_trust .AND. &
                              projector_physical_direct_response_abs_step <= response_abs_trust
                           IF (added_mos_auto_tail_enabled) THEN
                              projector_physical_direct_trace_tail_limited = &
                                 projector_physical_direct_norm_ratio >= &
                                 ot_kp_added_mos_auto_direct_veto_norm_ratio .AND. &
                                 MAX(ABS(projector_physical_direct_trace_actual_norm), &
                                     ABS(projector_physical_direct_trace_full_norm)) > &
                                 EPSILON(1.0_dp) .AND. &
                                 ABS(projector_physical_direct_trace_active_norm) <= &
                                 ot_kp_added_mos_auto_direct_veto_trace_frac* &
                                 MAX(ABS(projector_physical_direct_trace_actual_norm), &
                                     ABS(projector_physical_direct_trace_full_norm)) .AND. &
                                 projector_physical_direct_model_calibrated_drop >= &
                                 added_mos_auto_tail_residual_limit
                           END IF
                           IF (projector_physical_direct_basis_tail_limited) &
                              projector_physical_direct_candidate_ready = .FALSE.
                           IF (projector_physical_direct_trace_tail_limited) &
                              projector_physical_direct_candidate_ready = .FALSE.
                        END IF
                     END IF
                  END IF
                  IF (projector_physical_direct_candidate_ready) THEN
                     projector_physical_candidate_ready = .TRUE.
                     projector_physical_direct_candidate_used = .TRUE.
                     projector_physical_model_e(:) = projector_physical_direct_model_e(:)
                     projector_physical_rx_e(:) = projector_physical_direct_rx_e(:)
                     projector_physical_z_e(:) = projector_physical_direct_z_e(:)
                     projector_physical_sol(:) = projector_physical_direct_sol(:)
                     projector_physical_direction_scale = projector_physical_direct_direction_scale
                     projector_physical_expected_drop = projector_physical_direct_expected_drop
                     projector_physical_gdot_energy = projector_physical_direct_gdot_energy
                     projector_physical_gdot_rotation = projector_physical_direct_gdot_rotation
                     projector_physical_gdotp = projector_physical_direct_gdotp
                     projector_physical_model_calibrated_drop = &
                        projector_physical_direct_model_calibrated_drop
                     projector_physical_model_drop = projector_physical_direct_model_drop
                     projector_physical_model_gap = projector_physical_direct_model_gap
                     projector_physical_model_gap_drop = projector_physical_direct_model_gap_drop
                     projector_physical_model_gap_ratio = projector_physical_direct_model_gap_ratio
                     projector_physical_model_gap_trust = projector_physical_direct_model_gap_trust
                     projector_physical_norm_energy = projector_physical_direct_norm_energy
                     projector_physical_norm_rotation = projector_physical_direct_norm_rotation
                     projector_physical_normp = projector_physical_direct_normp
                     projector_physical_norm_ratio = projector_physical_direct_norm_ratio
                     projector_physical_response_abs_step = projector_physical_direct_response_abs_step
                     projector_physical_response_abs_trust_ratio = &
                        projector_physical_direct_response_abs_trust_ratio
                     projector_physical_response_weighted_step = &
                        projector_physical_direct_response_weighted_step
                     projector_physical_response_weighted_trust_ratio = &
                        projector_physical_direct_response_weighted_trust_ratio
                     projector_physical_scale_quality = projector_physical_direct_scale_quality
                     projector_physical_trust_quality = projector_physical_direct_trust_quality
                     IF (projector_physical_response_weight <= &
                         EPSILON(projector_physical_response_weight)) &
                        projector_physical_response_weight = projector_coupled_weight
                     IF (projector_physical_direct_response_weight > &
                         EPSILON(projector_physical_direct_response_weight)) THEN
                        projector_physical_response_weight = &
                           MAX(projector_physical_response_weight, &
                               projector_physical_direct_response_weight)
                        projector_physical_response_correction_drop = &
                           MAX(projector_physical_response_correction_drop, &
                               projector_physical_direct_response_correction_drop)
                        projector_physical_response_correction_negative = &
                           MAX(projector_physical_response_correction_negative, &
                               projector_physical_direct_response_correction_negative)
                        projector_physical_response_raw_negative_fraction = &
                           MAX(projector_physical_response_raw_negative_fraction, &
                               projector_physical_direct_response_raw_negative_fraction)
                        projector_physical_response_positive_drop = &
                           MAX(projector_physical_response_positive_drop, &
                               projector_physical_direct_response_positive_drop)
                        projector_physical_response_negative_drop = &
                           MAX(projector_physical_response_negative_drop, &
                               projector_physical_direct_response_negative_drop)
                        projector_physical_response_cross_drop = &
                           MAX(projector_physical_response_cross_drop, &
                               projector_physical_direct_response_cross_drop)
                        projector_physical_response_positive_coeff = &
                           projector_physical_direct_response_positive_coeff
                        projector_physical_response_negative_coeff = &
                           projector_physical_direct_response_negative_coeff
                     END IF
                  END IF
                  projector_physical_direct_tail_probe_ready = &
                     kpoint_ot_direct_tail_probe_ready( &
                     projector_physical_direct_candidate_used, &
                     projector_physical_direct_promoted, &
                     local_ot_env(1)%schur_projector_physical_candidate_enabled, &
                     residual_delta, local_ot_env(1)%schur_coupled_quality_samples, &
                     local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples, &
                     local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema, &
                     local_ot_env(1)%schur_projector_physical_direct_selected_quality, &
                     projector_physical_direct_shadow_quality_for_promotion, &
                     local_ot_env(1)%schur_coupled_residual_quality_ema, &
                     projector_physical_direct_response_weighted_trust_ratio, &
                     projector_physical_direct_response_abs_trust_ratio, &
                     projector_physical_direct_model_gap_ratio)
               END IF
               z_e(:) = z_e(:) + rx_e(:)

               gdot_energy = DOT_PRODUCT(grad_e, z_e)
               gdot_rotation = DOT_PRODUCT(grad_rot, sol)
               norm_energy = DOT_PRODUCT(z_e, z_e)
               norm_rotation = DOT_PRODUCT(sol, sol)
               gdotp = gdot_energy + gdot_rotation
               gnorm = DOT_PRODUCT(grad_e, grad_e) + DOT_PRODUCT(grad_rot, grad_rot)
               normp = norm_energy + norm_rotation
               norm_ratio = normp/MAX(gnorm, EPSILON(1.0_dp))
               metric_attempt_response = schur_attempt == 3 .AND. exact_attempt_response .AND. &
                                         projector_coupled_weight > EPSILON(projector_coupled_weight) .AND. &
                                         response_model_available
               metric_attempt_tail_bridge = .FALSE.
               metric_attempt_selectable = metric_attempt_response .AND. dense_exact_scale_ready .AND. &
                                           local_ot_env(1)%schur_coupled_quality_samples >= &
                                           ot_kp_schur_calibration_min_samples .AND. &
                                           local_ot_env(1)%schur_coupled_residual_quality_ema >= &
                                           ot_kp_schur_calibrated_quality_min_ratio
               IF (metric_attempt_selectable .AND. &
                   residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
                  metric_attempt_selectable = &
                  local_ot_env(1)%schur_step_gauge_quality_samples >= &
                  ot_kp_schur_calibration_min_samples .AND. &
                  local_ot_env(1)%schur_step_gauge_residual_quality_ema >= &
                  ot_kp_schur_calibrated_quality_min_ratio
               IF (metric_attempt_response .AND. .NOT. metric_attempt_selectable) THEN
                  metric_attempt_tail_bridge = &
                     kpoint_ot_dense_metric_tail_bridge_ready( &
                     residual_delta, dense_coupled_gate_quality, &
                     dense_coupled_gate_quality_ema, &
                     local_ot_env(1)%schur_coupled_quality_samples, dense_residual_quality_strict, &
                     local_ot_env(1)%mermin_ls_accepted_quality_ema, &
                     local_ot_env(1)%mermin_ls_accepted_quality_samples)
                  IF (metric_attempt_tail_bridge) metric_attempt_selectable = .TRUE.
               END IF
               IF (gdotp <= 0.0_dp .OR. gdotp /= gdotp .OR. normp /= normp) THEN
                  attempt_failed = .TRUE.
                  reject_reason = reject_nondescent
               END IF
               IF (.NOT. attempt_failed) THEN
                  ! The generic OT line searches assume that the stored search vector z has
                  ! z.z = g.z.  Rescale the external Schur direction to preserve that slope.
                  IF (metric_attempt_response) THEN
                     CALL kpoint_ot_mixed_projected_term(z_e, z_e, occ_curv, tether_curv, &
                                                         occ_curv_projection_sum, channel_nmo, e_offset, &
                                                         dense_metric_norm_energy)
                     dense_metric_norm_energy = MAX(0.0_dp, dense_metric_norm_energy)
                     dense_metric_norm_rotation = ABS(kpoint_ot_symmetric_quad(schur_metric, sol))
                     IF (dense_metric_norm_rotation <= EPSILON(dense_metric_norm_rotation)) &
                        dense_metric_norm_rotation = kpoint_ot_symmetric_abs_quad(schur_metric, sol)
                     dense_metric_normp = dense_metric_norm_energy + dense_metric_norm_rotation
                     IF (dense_metric_normp <= EPSILON(dense_metric_normp)) THEN
                        attempt_failed = .TRUE.
                        reject_reason = reject_nondescent
                     END IF
                  END IF
               END IF
               IF (.NOT. attempt_failed .AND. norm_ratio > max_norm_ratio .AND. &
                   .NOT. metric_attempt_selectable) THEN
                  attempt_failed = .TRUE.
                  reject_reason = reject_norm
               END IF
               IF (.NOT. attempt_failed) THEN
                  IF (metric_attempt_response) THEN
                     dense_metric_unit_abs_step = MAXVAL(ABS(rx_e))
                     CALL para_env_inter_kp%max(dense_metric_unit_abs_step)
                     dense_metric_unit_weighted_step = &
                        kpoint_ot_weighted_response_step(rx_e, curv, curv_projection_sum)
                     dense_metric_trust_scale = 1.0_dp
                     IF (response_trust > EPSILON(response_trust) .AND. &
                         dense_metric_unit_weighted_step > EPSILON(dense_metric_unit_weighted_step)) &
                        dense_metric_trust_scale = &
                        MIN(dense_metric_trust_scale, 0.8_dp*response_trust/dense_metric_unit_weighted_step)
                     IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                         dense_metric_unit_abs_step > EPSILON(dense_metric_unit_abs_step)) &
                        dense_metric_trust_scale = &
                        MIN(dense_metric_trust_scale, 0.8_dp*response_abs_trust/dense_metric_unit_abs_step)
                  END IF
                  IF (metric_attempt_selectable) THEN
                     direction_scale = MIN(1.0_dp, dense_metric_trust_scale, &
                                           gdotp/MAX(dense_metric_normp, EPSILON(dense_metric_normp)))
                     norm_ratio = direction_scale*direction_scale*normp/MAX(gnorm, EPSILON(1.0_dp))
                     IF (norm_ratio > max_norm_ratio .AND. max_norm_ratio > 0.0_dp) THEN
                        direction_scale = direction_scale*SQRT(max_norm_ratio/ &
                                                               MAX(norm_ratio, EPSILON(norm_ratio)))
                        norm_ratio = direction_scale*direction_scale*normp/MAX(gnorm, EPSILON(1.0_dp))
                     END IF
                  ELSE
                     direction_scale = gdotp/MAX(normp, EPSILON(normp))
                  END IF
                  IF (direction_scale <= 0.0_dp .OR. direction_scale /= direction_scale) THEN
                     attempt_failed = .TRUE.
                     reject_reason = reject_nondescent
                  ELSE
                     scale_quality = kpoint_ot_schur_scale_quality(direction_scale, schur_min_coupled_scale)
                     z_e(:) = direction_scale*z_e(:)
                     sol(:) = direction_scale*sol(:)
                     IF (metric_attempt_selectable) THEN
                        model_drop = direction_scale*gdotp - &
                                     0.5_dp*direction_scale*direction_scale*dense_metric_normp
                        model_drop = MAX(0.0_dp, model_drop)
                     ELSE
                        model_drop = 0.5_dp*direction_scale*gdotp
                     END IF
                     row_floor_shift_drop = 0.5_dp*direction_scale*direction_scale*row_floor_shift_quad
                     model_calibrated_drop = model_drop
                     IF (schur_attempt <= 2) model_calibrated_drop = &
                        split_quality_for_calibration*model_drop
                     IF (metric_attempt_selectable) THEN
                        response_abs_step = direction_scale*dense_metric_unit_abs_step
                        response_weighted_step = direction_scale*dense_metric_unit_weighted_step
                     ELSE
                        response_abs_step = direction_scale*MAXVAL(ABS(rx_e))
                        CALL para_env_inter_kp%max(response_abs_step)
                        response_weighted_step = direction_scale* &
                                                 kpoint_ot_weighted_response_step(rx_e, curv, curv_projection_sum)
                     END IF
                     response_step_max = response_abs_step
                     IF (response_trust > EPSILON(response_trust)) &
                        response_weighted_trust_ratio = response_weighted_step/response_trust
                     IF (response_abs_trust > EPSILON(response_abs_trust)) &
                        response_abs_trust_ratio = response_abs_step/response_abs_trust
                     IF (response_model_available) THEN
                        model_gap = direction_scale*MAXVAL(ABS(rx_model - rx_e))
                        model_gap_drop = kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, direction_scale)
                        IF (schur_attempt <= 2) THEN
                           model_calibrated_drop = &
                              MAX(0.0_dp, split_quality_for_calibration*model_drop - model_gap_drop)
                        ELSE
                           model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
                        END IF
                        IF (.NOT. metric_attempt_selectable) &
                           model_calibrated_drop = MAX(0.0_dp, model_calibrated_drop - row_floor_shift_drop)
                        IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source() .AND. &
                            row_floor_shift_drop > EPSILON(row_floor_shift_drop)) &
                           WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),4(1X,ES16.8))') &
                           " OT Schur row-floor model audit group att drop gap_drop floor_drop cdrop:", &
                           target_group, schur_attempt, model_drop, model_gap_drop, row_floor_shift_drop, &
                           model_calibrated_drop
                        model_gap_trust = schur_model_gap_factor*response_trust
                        IF (model_gap_trust > EPSILON(model_gap_trust)) model_gap_ratio = model_gap/model_gap_trust
                        IF (schur_attempt == 3 .AND. exact_attempt_response .AND. &
                            projector_coupled_weight > 0.0_dp .AND. &
                            (local_ot_env(1)%schur_projector_mode_quality_samples < &
                             ot_kp_schur_calibration_min_samples .OR. split_candidate_ready)) THEN
                           CALL audit_kpoint_ot_projector_modes(rot_hessian, rot_hessian_projector, sol, &
                                                                response_exact_raw, response_exact, curv, &
                                                                model_calibrated_drop, projector_coupled_weight, &
                                                                projector_mode_history_quality, dense_residual_quality, &
                                                                projector_mode_quality, projector_mode_negative_fraction, &
                                                                projector_mode_damped_abs_avg, projector_mode_eval_min, &
                                                                projector_mode_eval_max, &
                                                                projector_mode_step_negative_fraction, &
                                                                projector_mode_response_negative_fraction, &
                                                                projector_mode_response_drop, &
                                                                projector_mode_response_drop_ratio, &
                                                                projector_mode_trust_quality)
                           model_calibrated_drop = projector_mode_trust_quality*model_calibrated_drop
                        END IF
                     END IF
                     IF (schur_attempt <= 2 .AND. .NOT. attempt_failed .AND. &
                         model_calibrated_drop <= EPSILON(model_drop)) THEN
                        attempt_failed = .TRUE.
                        trust_rejected = .TRUE.
                        reject_reason = reject_model_mismatch
                     END IF
                     IF (schur_attempt <= 3 .AND. direction_scale < schur_min_coupled_scale) THEN
                        IF (metric_attempt_selectable) THEN
                           model_calibrated_drop = scale_quality*model_calibrated_drop
                        ELSE IF (schur_attempt == 3 .AND. exact_attempt_response .AND. &
                                 projector_coupled_weight > 0.0_dp .AND. dense_exact_scale_ready) THEN
                           model_calibrated_drop = scale_quality*model_calibrated_drop
                        ELSE
                           attempt_failed = .TRUE.
                           reject_reason = reject_scale
                        END IF
                     END IF
                     IF (schur_attempt <= 3 .AND. .NOT. attempt_failed) THEN
                        rx_model(:) = MATMUL(response_occ - response, sol)
                        occgap_shadow_abs_step = MAXVAL(ABS(rx_model))
                        CALL para_env_inter_kp%max(occgap_shadow_abs_step)
                        occgap_shadow_step = kpoint_ot_weighted_response_step(rx_model, occ_curv, &
                                                                              occ_curv_projection_sum)
                        IF (response_trust > EPSILON(response_trust)) &
                           occgap_shadow_gap_ratio = MAX(occgap_shadow_gap_ratio, &
                                                         occgap_shadow_step/response_trust)
                        IF (response_abs_trust > EPSILON(response_abs_trust)) &
                           occgap_shadow_gap_ratio = MAX(occgap_shadow_gap_ratio, &
                                                         occgap_shadow_abs_step/response_abs_trust)
                        occgap_shadow_quality = 1.0_dp/MAX(1.0_dp, occgap_shadow_gap_ratio)
                        occgap_shadow_drop = kpoint_ot_schur_expected_drop(model_calibrated_drop, &
                                                                           1.0_dp, occgap_shadow_quality)
                     END IF
                     ! Trust the Schur response in the fixed-N Mermin metric.  A
                     ! single weakly-curved band may have a large absolute energy
                     ! response; the broad outer guard below catches real Fermi-window
                     ! escapes without rejecting curvature-weighted rotation steps.
                     IF (schur_attempt <= 3 .AND. .NOT. attempt_failed .AND. &
                         response_weighted_step > response_trust) THEN
                        attempt_failed = .TRUE.
                        trust_rejected = .TRUE.
                        reject_reason = reject_response
                     END IF
                     IF (schur_attempt <= 3 .AND. .NOT. attempt_failed .AND. &
                         response_abs_step > response_abs_trust) THEN
                        attempt_failed = .TRUE.
                        trust_rejected = .TRUE.
                        reject_reason = reject_response
                     END IF
                     IF (schur_attempt <= 2 .AND. .NOT. attempt_failed .AND. &
                         model_gap > model_gap_trust) THEN
                        attempt_failed = .TRUE.
                        trust_rejected = .TRUE.
                        reject_reason = reject_model_gap
                     END IF
                     IF (schur_attempt <= 2 .AND. .NOT. attempt_failed .AND. &
                         .NOT. split_candidate_enabled) THEN
                        attempt_failed = .TRUE.
                        reject_reason = reject_quality_gate
                     END IF
                     IF (logger%iter_info%print_level >= high_print_level .AND. &
                         logger%para_env%is_source() .AND. metric_attempt_response) &
                        WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),1(1X,L1),8(1X,ES16.8))') &
                        " OT Schur dense metric attempt group att select scale trust men mrot mp nratio cdrop:", &
                        target_group, schur_attempt, metric_attempt_selectable, direction_scale, dense_metric_trust_scale, &
                        dense_metric_norm_energy, dense_metric_norm_rotation, dense_metric_normp, &
                        norm_ratio, model_calibrated_drop
                     IF (metric_attempt_tail_bridge) &
                        WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),8(1X,ES16.8))') &
                        " OT Schur dense metric tail bridge group att gate_q gate_ema rq mqema raw_q cal_q "// &
                        "scale cdrop:", &
                        target_group, schur_attempt, dense_coupled_gate_quality, &
                        dense_coupled_gate_quality_ema, dense_residual_quality, &
                        local_ot_env(1)%mermin_ls_accepted_quality_ema, &
                        local_ot_env(1)%schur_coupled_quality, &
                        local_ot_env(1)%schur_coupled_calibrated_quality, direction_scale, &
                        model_calibrated_drop
                  END IF
               END IF
            END IF

            IF (logger%iter_info%print_level >= high_print_level .AND. logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,3(1X,I6),1(1X,L1),13(1X,ES16.8))') &
               " OT Schur attempt decision group att failed code scale sq drop cdrop gapdrop floordrop "// &
               "wtrust atrust mgap normratio gdotp normp:", &
               target_group, schur_attempt, reject_reason, attempt_failed, direction_scale, scale_quality, &
               model_drop, model_calibrated_drop, model_gap_drop, row_floor_shift_drop, &
               response_weighted_trust_ratio, response_abs_trust_ratio, model_gap_ratio, norm_ratio, &
               gdotp, normp

            IF (schur_attempt == 1 .AND. .NOT. attempt_failed) THEN
               constrained_candidate_ready = .TRUE.
               constrained_sol(:) = sol(:)
               constrained_z_e(:) = z_e(:)
               constrained_gdotp = gdotp
               constrained_gdot_energy = gdot_energy
               constrained_gdot_rotation = gdot_rotation
               constrained_norm_energy = norm_energy
               constrained_norm_rotation = norm_rotation
               constrained_normp = normp
               constrained_scale_quality = scale_quality
               constrained_occgap_shadow_drop = occgap_shadow_drop
               constrained_occgap_shadow_gap_ratio = occgap_shadow_gap_ratio
               ! Delay the constrained candidate until the raw Split candidate for
               ! the same search point gives an absolute Mermin-drop comparator.
               attempt_failed = .TRUE.
               reject_reason = reject_quality_gate
            END IF

            IF (schur_attempt == 2) THEN
               coupled_diag_shift_avg = diag_shift_sum/REAL(MAX(1, nrot), KIND=dp)
               coupled_direction_scale = direction_scale
               coupled_gdot_energy = gdot_energy
               coupled_gdot_rotation = gdot_rotation
               coupled_model_drop = model_drop
               coupled_model_calibrated_drop = model_calibrated_drop
               coupled_model_gap = model_gap
               coupled_model_gap_drop = model_gap_drop
               coupled_model_gap_ratio = model_gap_ratio
               coupled_model_gap_trust = model_gap_trust
               coupled_norm_energy = norm_energy
               coupled_norm_rotation = norm_rotation
               coupled_norm_ratio = norm_ratio
               coupled_scale_quality = scale_quality
               coupled_occ_response_diag_avg = occ_response_diag_sum/REAL(MAX(1, nrot), KIND=dp)
               coupled_rot_diag_avg = rot_diag_sum/REAL(MAX(1, nrot), KIND=dp)
               coupled_tether_response_diag_avg = tether_response_diag_sum/REAL(MAX(1, nrot), KIND=dp)
               coupled_reject_reason = reject_reason
               coupled_response_abs_step = response_abs_step
               coupled_response_abs_trust_ratio = response_abs_trust_ratio
               coupled_response_step = response_step_max
               coupled_response_trust_ratio = 0.0_dp
               IF (response_trust > EPSILON(response_trust)) &
                  coupled_response_trust_ratio = response_step_max/response_trust
               coupled_response_weighted_step = response_weighted_step
               coupled_response_weighted_trust_ratio = response_weighted_trust_ratio
            ELSE IF (schur_attempt == 1) THEN
               constrained_diag_shift_avg = diag_shift_sum/REAL(MAX(1, nrot), KIND=dp)
               constrained_direction_scale = direction_scale
               constrained_gdot_energy = gdot_energy
               constrained_gdot_rotation = gdot_rotation
               constrained_model_drop = model_drop
               constrained_model_calibrated_drop = model_calibrated_drop
               constrained_model_gap = model_gap
               constrained_model_gap_drop = model_gap_drop
               constrained_model_gap_ratio = model_gap_ratio
               constrained_model_gap_trust = model_gap_trust
               constrained_norm_energy = norm_energy
               constrained_norm_rotation = norm_rotation
               constrained_norm_ratio = norm_ratio
               constrained_scale_quality = scale_quality
               constrained_occ_response_diag_avg = occ_response_diag_sum/REAL(MAX(1, nrot), KIND=dp)
               constrained_response_penalty_diag_avg = response_penalty_diag_sum/REAL(MAX(1, nrot), KIND=dp)
               constrained_rot_diag_avg = rot_diag_sum/REAL(MAX(1, nrot), KIND=dp)
               constrained_tether_response_diag_avg = tether_response_diag_sum/REAL(MAX(1, nrot), KIND=dp)
               constrained_reject_reason = reject_reason
               constrained_response_abs_step = response_abs_step
               constrained_response_abs_trust_ratio = response_abs_trust_ratio
               constrained_response_step = response_step_max
               constrained_response_trust_ratio = 0.0_dp
               IF (response_trust > EPSILON(response_trust)) &
                  constrained_response_trust_ratio = response_step_max/response_trust
               constrained_response_weighted_step = response_weighted_step
               constrained_response_weighted_trust_ratio = response_weighted_trust_ratio
               IF (new_search_point .AND. split_candidate_enabled .AND. &
                   model_calibrated_drop > EPSILON(model_drop) .AND. &
                   (reject_reason == 0 .OR. reject_reason == reject_quality_gate)) THEN
                  local_ot_env(1)%schur_constrained_pending = .TRUE.
                  local_ot_env(1)%schur_constrained_drop = &
                     local_ot_env(1)%schur_constrained_drop + model_drop
                  local_ot_env(1)%schur_constrained_calibrated_drop = &
                     local_ot_env(1)%schur_constrained_calibrated_drop + model_calibrated_drop
                  local_ot_env(1)%schur_constrained_gap_ratio = &
                     MAX(local_ot_env(1)%schur_constrained_gap_ratio, model_gap_ratio)
               END IF
            END IF

            IF (schur_attempt == 2 .AND. constrained_candidate_ready .AND. &
                model_calibrated_drop > EPSILON(model_calibrated_drop)) THEN
               split_trust_quality = kpoint_ot_schur_trust_quality(response_weighted_trust_ratio, &
                                                                   response_abs_trust_ratio, &
                                                                   model_gap_ratio)
               constrained_trust_quality = &
                  kpoint_ot_schur_trust_quality(constrained_response_weighted_trust_ratio, &
                                                constrained_response_abs_trust_ratio, &
                                                constrained_model_gap_ratio)
               split_expected_drop = kpoint_ot_schur_expected_drop(model_calibrated_drop, &
                                                                   split_quality_for_selection, &
                                                                   split_trust_quality)
               constrained_expected_drop = &
                  kpoint_ot_schur_expected_drop(constrained_model_calibrated_drop, &
                                                constrained_quality_for_selection, &
                                                constrained_trust_quality)
               IF (split_expected_drop > EPSILON(split_expected_drop)) &
                  constrained_expected_drop_ratio = constrained_expected_drop/split_expected_drop
               IF (.NOT. attempt_failed .AND. constrained_candidate_enabled .AND. &
                   constrained_expected_drop_ratio >= ot_kp_schur_constrained_drop_advantage_ratio) THEN
                  constrained_candidate_selected = .TRUE.
                  z_e(:) = constrained_z_e(:)
                  sol(:) = constrained_sol(:)
                  direction_scale = constrained_direction_scale
                  gdotp = constrained_gdotp
                  gdot_energy = constrained_gdot_energy
                  gdot_rotation = constrained_gdot_rotation
                  norm_energy = constrained_norm_energy
                  norm_rotation = constrained_norm_rotation
                  normp = constrained_normp
                  norm_ratio = constrained_norm_ratio
                  scale_quality = constrained_scale_quality
                  model_drop = constrained_model_drop
                  model_calibrated_drop = constrained_model_calibrated_drop
                  model_gap_ratio = constrained_model_gap_ratio
                  occgap_shadow_drop = constrained_occgap_shadow_drop
                  occgap_shadow_gap_ratio = constrained_occgap_shadow_gap_ratio
                  response_step_max = constrained_response_step
                  response_abs_step = constrained_response_abs_step
                  response_abs_trust_ratio = constrained_response_abs_trust_ratio
                  response_weighted_step = constrained_response_weighted_step
                  response_weighted_trust_ratio = constrained_response_weighted_trust_ratio
                  constrained_reject_reason = 0
               END IF
            END IF
            IF (schur_attempt == 2 .AND. .NOT. attempt_failed) THEN
               IF (.NOT. constrained_candidate_selected) THEN
                  split_trust_quality = kpoint_ot_schur_trust_quality(response_weighted_trust_ratio, &
                                                                      response_abs_trust_ratio, &
                                                                      model_gap_ratio)
                  split_expected_drop = &
                     kpoint_ot_schur_expected_drop(model_calibrated_drop, split_quality_for_selection, &
                                                   split_trust_quality)
               END IF
               split_candidate_ready = .TRUE.
               split_selected_attempt = MERGE(1, 2, constrained_candidate_selected)
               split_z_e(:) = z_e(:)
               split_sol(:) = sol(:)
               split_direction_scale = direction_scale
               split_gdotp = gdotp
               split_gdot_energy = gdot_energy
               split_gdot_rotation = gdot_rotation
               split_norm_energy = norm_energy
               split_norm_rotation = norm_rotation
               split_normp = normp
               split_norm_ratio = norm_ratio
               split_scale_quality = scale_quality
               split_model_drop = model_drop
               split_model_calibrated_drop = model_calibrated_drop
               split_model_gap_ratio = model_gap_ratio
               split_occgap_shadow_drop = occgap_shadow_drop
               split_occgap_shadow_gap_ratio = occgap_shadow_gap_ratio
               split_density_projector_fraction = density_projector_fraction
               split_diag_shift_max = diag_shift_max
               split_diag_shift_sum = diag_shift_sum
               split_residual_delta = residual_delta
               split_response_step = response_step_max
               split_response_abs_step = response_abs_step
               split_response_abs_trust = response_abs_trust
               split_response_abs_trust_ratio = response_abs_trust_ratio
               split_response_trust = response_trust
               split_response_trust_factor = response_trust_factor
               split_response_weighted_step = response_weighted_step
               split_response_weighted_trust_ratio = response_weighted_trust_ratio
               split_rot_floor_min = rot_floor_min
               split_schur_diag_min = schur_diag_min
               attempt_failed = .TRUE.
               reject_reason = reject_quality_gate
            ELSE IF (schur_attempt >= 3 .AND. split_candidate_ready) THEN
               dense_direction_scale = direction_scale
               dense_gdot_energy = gdot_energy
               dense_gdot_rotation = gdot_rotation
               dense_model_gap = model_gap
               dense_model_gap_drop = model_gap_drop
               dense_model_gap_ratio = model_gap_ratio
               dense_model_gap_trust = model_gap_trust
               dense_norm_energy = norm_energy
               dense_norm_rotation = norm_rotation
               dense_projector_coupled_weight = projector_coupled_weight
               dense_reject_reason = reject_reason
               dense_scale_quality = scale_quality
               dense_trust_quality = kpoint_ot_schur_trust_quality(response_weighted_trust_ratio, &
                                                                   response_abs_trust_ratio, &
                                                                   model_gap_ratio)
               IF (.NOT. attempt_failed) &
                  dense_expected_drop = kpoint_ot_schur_expected_drop(model_calibrated_drop, &
                                                                      dense_quality_for_selection, &
                                                                      dense_trust_quality)
               ! Candidate-specific response trust may rescue a dense base step
               ! rejected by the generic attempt gate.
               IF (local_ot_env(1)%schur_projector_response_candidate_enabled .AND. &
                   projector_response_candidate_ready .AND. &
                   projector_response_expected_drop > EPSILON(projector_response_expected_drop) .AND. &
                   projector_response_expected_drop >= &
                   ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, EPSILON(dense_expected_drop))) THEN
                  attempt_failed = .FALSE.
                  projector_response_candidate_selected = .TRUE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  z_e(:) = projector_response_z_e(:)
                  sol(:) = projector_response_sol(:)
                  direction_scale = projector_response_direction_scale
                  gdotp = projector_response_gdotp
                  gdot_energy = projector_response_gdot_energy
                  gdot_rotation = projector_response_gdot_rotation
                  norm_energy = projector_response_norm_energy
                  norm_rotation = projector_response_norm_rotation
                  normp = projector_response_normp
                  norm_ratio = projector_response_norm_ratio
                  scale_quality = projector_response_scale_quality
                  model_drop = projector_response_model_drop
                  model_calibrated_drop = projector_response_model_calibrated_drop
                  model_gap = projector_response_model_gap
                  model_gap_drop = projector_response_model_gap_drop
                  model_gap_ratio = projector_response_model_gap_ratio
                  model_gap_trust = projector_response_model_gap_trust
                  response_abs_step = projector_response_response_abs_step
                  response_abs_trust_ratio = projector_response_response_abs_trust_ratio
                  response_weighted_step = projector_response_response_weighted_step
                  response_weighted_trust_ratio = projector_response_response_weighted_trust_ratio
                  dense_expected_drop = projector_response_expected_drop
