                           schur(r, r) = schur(r, r) + diag_shift
                           diag_shift_sum = diag_shift_sum + diag_shift
                           diag_shift_max = MAX(diag_shift_max, diag_shift)
                        END IF
                        schur_diag_min = MIN(schur_diag_min, schur(r, r))
                     END DO
