                        normp = norm_energy + norm_rotation
                        CALL kpoint_ot_mixed_projected_term(z_e, z_e, occ_curv, tether_curv, &
                                                            occ_curv_projection_sum, channel_nmo, e_offset, &
                                                            projector_physical_direct_metric_norm_energy)
                        projector_physical_direct_metric_norm_energy = &
                           MAX(0.0_dp, projector_physical_direct_metric_norm_energy)
                        projector_physical_direct_metric_norm_rotation = &
                           kpoint_ot_modal_abs_quad(projector_physical_direct_schur_evec, &
                                                    projector_physical_direct_schur_eval, sol)
                        projector_physical_direct_metric_normp = &
                           projector_physical_direct_metric_norm_energy + &
                           projector_physical_direct_metric_norm_rotation
                        IF (gdotp > 0.0_dp .AND. &
                            projector_physical_direct_metric_normp > &
                            EPSILON(projector_physical_direct_metric_normp)) THEN
                           projector_physical_direct_unit_abs_step = MAXVAL(ABS(rx_e))
                           CALL para_env_inter_kp%max(projector_physical_direct_unit_abs_step)
                           projector_physical_direct_unit_weighted_step = &
                              kpoint_ot_weighted_response_step(rx_e, curv, curv_projection_sum)
                           projector_physical_direct_trust_scale = 1.0_dp
                           IF (response_trust > EPSILON(response_trust) .AND. &
                               projector_physical_direct_unit_weighted_step > &
                               EPSILON(projector_physical_direct_unit_weighted_step)) &
                              projector_physical_direct_trust_scale = &
                              MIN(projector_physical_direct_trust_scale, &
                                  0.8_dp*response_trust/ &
                                  projector_physical_direct_unit_weighted_step)
                           IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                               projector_physical_direct_unit_abs_step > &
                               EPSILON(projector_physical_direct_unit_abs_step)) &
                              projector_physical_direct_trust_scale = &
                              MIN(projector_physical_direct_trust_scale, &
                                  0.8_dp*response_abs_trust/ &
                                  projector_physical_direct_unit_abs_step)
                           direction_scale = MIN(1.0_dp, projector_physical_direct_trust_scale, &
                                                 gdotp/MAX(projector_physical_direct_metric_normp, &
                                                           EPSILON(projector_physical_direct_metric_normp)))
                           scale_quality = kpoint_ot_schur_scale_quality(direction_scale, schur_min_coupled_scale)
                           model_drop = direction_scale*gdotp - &
                                        0.5_dp*direction_scale*direction_scale* &
                                        projector_physical_direct_metric_normp
                           model_drop = MAX(0.0_dp, model_drop)
                           response_abs_step = direction_scale*projector_physical_direct_unit_abs_step
                           response_weighted_step = direction_scale*projector_physical_direct_unit_weighted_step
                           model_gap = direction_scale*MAXVAL(ABS(rx_model - rx_e))
                           model_gap_drop = kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, direction_scale)
                           model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
                           IF (direction_scale < schur_min_coupled_scale) &
                              model_calibrated_drop = scale_quality*model_calibrated_drop
                           model_gap_trust = schur_model_gap_factor*response_trust
                           model_gap_ratio = 0.0_dp
                           IF (model_gap_trust > EPSILON(model_gap_trust)) model_gap_ratio = model_gap/model_gap_trust
                           IF (response_trust > EPSILON(response_trust)) &
                              response_weighted_trust_ratio = response_weighted_step/response_trust
                           IF (response_abs_trust > EPSILON(response_abs_trust)) &
                              response_abs_trust_ratio = response_abs_step/response_abs_trust
                           dense_trust_quality = kpoint_ot_schur_trust_quality(response_weighted_trust_ratio, &
                                                                               response_abs_trust_ratio, &
                                                                               model_gap_ratio)
                           dense_expected_drop = kpoint_ot_schur_expected_drop(model_calibrated_drop, &
                                                                               projector_physical_direct_quality_for_selection* &
                                                                               projector_plateau_gap_quality_for_selection, &
                                                                dense_trust_quality*projector_physical_direct_density_audit_quality)
                        END IF
                     END IF
                     WRITE (cp_logger_get_default_unit_nr(logger), '(A,1(1X,L1),12(1X,ES16.8))') &
                        " OT Schur projector active direct shadow solved exp cdrop mgap rratio aratio "// &
                        "scale dsum dmax dmin active_comp emin emax:", &
                        solved, dense_expected_drop, model_calibrated_drop, model_gap, &
                        response_weighted_trust_ratio, response_abs_trust_ratio, direction_scale, &
                        diag_shift_sum, diag_shift_max, schur_diag_min, &
                        projector_physical_direct_active_diag_compensation, &
                        projector_physical_direct_schur_eval_min, projector_physical_direct_schur_eval_max
                     DO ivar = 1, 4
                        z_weight = REAL(ivar, KIND=dp)/4.0_dp
                        projector_physical_direct_schur_vec(:, :) = &
                           (1.0_dp - z_weight)*projector_physical_direct_base_delta(:, :) + &
                           z_weight*0.5_dp*((rot_hessian_projector_physical_active(:, :) - rot_hessian(:, :)) + &
                                            TRANSPOSE(rot_hessian_projector_physical_active(:, :) - &
                                                      rot_hessian(:, :)))
                        IF (projector_physical_direct_shadow_weight > &
                            EPSILON(projector_physical_direct_shadow_weight)) THEN
                           DO r = 1, nrot
                              diag_shift = z_weight*projector_physical_direct_active_lcomp(r)/ &
                                           projector_physical_direct_shadow_weight
                              IF (diag_shift <= 0.0_dp) CYCLE
                              projector_physical_direct_schur_vec(r, r) = &
                                 projector_physical_direct_schur_vec(r, r) + diag_shift
                           END DO
                        END IF
                        schur(:, :) = rot_hessian_coupled(:, :) + &
                                      projector_physical_direct_shadow_weight* &
                                      projector_physical_direct_schur_vec(:, :)
                        DO s = 1, nrot
                           DO r = 1, nrot
                              projected_term = 0.5_dp* &
                                               (DOT_PRODUCT(energy_cross_physical(:, r), response_exact_physical(:, s)) + &
                                                DOT_PRODUCT(energy_cross_physical(:, s), response_exact_physical(:, r)))
                              IF (exact_density_direct_response_ready) &
                                 projected_term = projected_term + 0.5_dp* &
                                                  (DOT_PRODUCT(energy_cross_physical(:, r), response_density_direct_exact(:, s)) + &
                                                   DOT_PRODUCT(energy_cross_density_direct(:, r), response_exact_physical(:, s)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, r), response_density_direct_exact(:, s)) + &
                                                   DOT_PRODUCT(energy_cross_physical(:, s), response_density_direct_exact(:, r)) + &
                                                   DOT_PRODUCT(energy_cross_density_direct(:, s), response_exact_physical(:, r)) + &
                                                DOT_PRODUCT(energy_cross_density_direct(:, s), response_density_direct_exact(:, r)))
                              schur(r, s) = schur(r, s) - projected_term
                           END DO
                        END DO
                        diag_shift_sum = 0.0_dp
                        diag_shift_max = 0.0_dp
                        schur_diag_min = HUGE(1.0_dp)
                        DO r = 1, nrot
                           row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                        rot_hessian(r, r) + projector_physical_direct_schur_vec(r, r), rot_floor(r))
                           diag_shift = MAX(0.0_dp, row_floor - schur(r, r))
                           IF (diag_shift > 0.0_dp) THEN
                              schur(r, r) = schur(r, r) + diag_shift
                              diag_shift_sum = diag_shift_sum + diag_shift
                              diag_shift_max = MAX(diag_shift_max, diag_shift)
                           END IF
                           schur_diag_min = MIN(schur_diag_min, schur(r, r))
                        END DO
                        projector_physical_direct_schur_evec(:, :) = 0.5_dp*(schur(:, :) + TRANSPOSE(schur(:, :)))
                        CALL diamat_all(projector_physical_direct_schur_evec, projector_physical_direct_schur_eval)
                        projector_physical_direct_schur_eval_min = MINVAL(projector_physical_direct_schur_eval)
                        projector_physical_direct_schur_eval_max = MAXVAL(projector_physical_direct_schur_eval)
                        DO r = 1, nrot
                           rhs(r) = grad_rot(r) + DOT_PRODUCT(response_exact_physical(:, r), grad_e)
                           IF (exact_density_direct_response_ready) &
                              rhs(r) = rhs(r) + DOT_PRODUCT(response_density_direct_exact(:, r), grad_e)
                        END DO
                        sol(:) = rhs(:)
                        CALL dgesv(nrot, 1, schur, nrot, ipiv, sol, nrot, info)
                        solved = info == 0
                        dense_expected_drop = 0.0_dp
                        direction_scale = 0.0_dp
                        model_calibrated_drop = 0.0_dp
                        model_gap = 0.0_dp
                        response_weighted_trust_ratio = 0.0_dp
                        response_abs_trust_ratio = 0.0_dp
                        dense_trust_quality = 1.0_dp
                        IF (solved) THEN
                           rx_e(:) = MATMUL(response_exact_raw, sol)
                           rx_model(:) = (1.0_dp - z_weight)*MATMUL(response_exact_raw, sol) + &
                                         z_weight*MATMUL(response_exact_physical, sol)
                           IF (exact_density_direct_response_ready) &
                              rx_model(:) = rx_model(:) + z_weight*MATMUL(response_density_direct_exact, sol)
                           CALL project_kpoint_ot_schur_response(rx_e, occ_curv, tether_curv, &
                                                                 occ_curv_projection_sum, channel_nmo, e_offset)
                           CALL project_kpoint_ot_schur_response(rx_model, occ_curv, tether_curv, &
                                                                 occ_curv_projection_sum, channel_nmo, e_offset)
                           z_e(:) = z_exact_physical_trial(:) + rx_e(:)
                           gdot_energy = DOT_PRODUCT(grad_e, z_e)
                           gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                           norm_energy = DOT_PRODUCT(z_e, z_e)
                           norm_rotation = DOT_PRODUCT(sol, sol)
                           gdotp = gdot_energy + gdot_rotation
                           normp = norm_energy + norm_rotation
                           CALL kpoint_ot_mixed_projected_term(z_e, z_e, occ_curv, tether_curv, &
                                                               occ_curv_projection_sum, channel_nmo, e_offset, &
                                                               projector_physical_direct_metric_norm_energy)
                           projector_physical_direct_metric_norm_energy = &
                              MAX(0.0_dp, projector_physical_direct_metric_norm_energy)
                           projector_physical_direct_metric_norm_rotation = &
                              kpoint_ot_modal_abs_quad(projector_physical_direct_schur_evec, &
                                                       projector_physical_direct_schur_eval, sol)
                           projector_physical_direct_metric_normp = &
                              projector_physical_direct_metric_norm_energy + &
                              projector_physical_direct_metric_norm_rotation
                           IF (gdotp > 0.0_dp .AND. &
                               projector_physical_direct_metric_normp > &
                               EPSILON(projector_physical_direct_metric_normp)) THEN
                              projector_physical_direct_unit_abs_step = MAXVAL(ABS(rx_e))
                              CALL para_env_inter_kp%max(projector_physical_direct_unit_abs_step)
                              projector_physical_direct_unit_weighted_step = &
                                 kpoint_ot_weighted_response_step(rx_e, curv, curv_projection_sum)
                              projector_physical_direct_trust_scale = 1.0_dp
                              IF (response_trust > EPSILON(response_trust) .AND. &
                                  projector_physical_direct_unit_weighted_step > &
                                  EPSILON(projector_physical_direct_unit_weighted_step)) &
                                 projector_physical_direct_trust_scale = &
                                 MIN(projector_physical_direct_trust_scale, &
                                     0.8_dp*response_trust/ &
                                     projector_physical_direct_unit_weighted_step)
                              IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                                  projector_physical_direct_unit_abs_step > &
                                  EPSILON(projector_physical_direct_unit_abs_step)) &
                                 projector_physical_direct_trust_scale = &
                                 MIN(projector_physical_direct_trust_scale, &
                                     0.8_dp*response_abs_trust/ &
                                     projector_physical_direct_unit_abs_step)
                              direction_scale = MIN(1.0_dp, projector_physical_direct_trust_scale, &
                                                    gdotp/MAX(projector_physical_direct_metric_normp, &
                                                              EPSILON(projector_physical_direct_metric_normp)))
                              scale_quality = kpoint_ot_schur_scale_quality(direction_scale, schur_min_coupled_scale)
                              model_drop = direction_scale*gdotp - &
                                           0.5_dp*direction_scale*direction_scale* &
                                           projector_physical_direct_metric_normp
                              model_drop = MAX(0.0_dp, model_drop)
                              response_abs_step = direction_scale*projector_physical_direct_unit_abs_step
                              response_weighted_step = direction_scale*projector_physical_direct_unit_weighted_step
                              model_gap = direction_scale*MAXVAL(ABS(rx_model - rx_e))
                              model_gap_drop = kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, direction_scale)
                              model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
                              IF (direction_scale < schur_min_coupled_scale) &
                                 model_calibrated_drop = scale_quality*model_calibrated_drop
                              model_gap_trust = schur_model_gap_factor*response_trust
                              model_gap_ratio = 0.0_dp
                              IF (model_gap_trust > EPSILON(model_gap_trust)) model_gap_ratio = model_gap/model_gap_trust
                              IF (response_trust > EPSILON(response_trust)) &
                                 response_weighted_trust_ratio = response_weighted_step/response_trust
                              IF (response_abs_trust > EPSILON(response_abs_trust)) &
                                 response_abs_trust_ratio = response_abs_step/response_abs_trust
                              dense_trust_quality = kpoint_ot_schur_trust_quality(response_weighted_trust_ratio, &
                                                                                  response_abs_trust_ratio, &
                                                                                  model_gap_ratio)
                              dense_expected_drop = kpoint_ot_schur_expected_drop(model_calibrated_drop, &
                                                                                  projector_physical_direct_quality_for_selection* &
                                                                                  projector_plateau_gap_quality_for_selection, &
                                                                dense_trust_quality*projector_physical_direct_density_audit_quality)
                           END IF
                        END IF
                        ! Keep this HIGH-only active/full Direct probe diagnostic.
                        ! Promotion must be learned from print-level-neutral
                        ! accepted steps, otherwise PRINT_LEVEL changes the
                        ! k-point OT minimizer path.
                        WRITE (cp_logger_get_default_unit_nr(logger), '(A,1(1X,L1),13(1X,ES16.8))') &
                           " OT Schur projector mixed direct shadow solved wactive exp cdrop mgap rratio aratio "// &
                           "scale dsum dmax dmin wactive_comp emin emax:", &
                           solved, z_weight, dense_expected_drop, model_calibrated_drop, model_gap, &
                           response_weighted_trust_ratio, response_abs_trust_ratio, direction_scale, &
                           diag_shift_sum, diag_shift_max, schur_diag_min, &
                           z_weight*projector_physical_direct_active_diag_compensation, &
                           projector_physical_direct_schur_eval_min, projector_physical_direct_schur_eval_max
                     END DO
                  END IF
               END IF
            END IF
         END IF
         ! Learn the mixed active/physical Direct curvature from any accepted
         ! exact-response dense step, including the row-floor fallback that
         ! dominates the metallic residual tail. Waiting for an already selected
         ! Direct candidate makes promotion circular.
         ! Keep this outside the HIGH print block so PRINT_LEVEL cannot change
         ! the k-point OT minimizer path.
         IF (new_search_point .AND. accepted_model_drop > EPSILON(accepted_model_drop) .AND. &
             (selected_attempt == 3 .OR. selected_attempt == 4 .OR. &
              projector_physical_direct_candidate_selected .OR. &
              projector_physical_direct_density_candidate_selected .OR. &
              projector_physical_direct_spectral_candidate_selected)) THEN
            projector_physical_direct_shadow_weight = &
               MAX(projector_coupled_weight, &
                   MAX(projector_physical_response_weight, projector_physical_direct_response_weight))
            IF (projector_physical_shadow_enabled .AND. exact_physical_response_ready .AND. &
                projector_physical_direct_shadow_weight > &
                EPSILON(projector_physical_direct_shadow_weight) .AND. &
                (local_ot_env(1)%schur_projector_mode_quality_samples >= &
                 ot_kp_schur_calibration_min_samples .OR. &
                 projector_physical_direct_promoted .OR. &
                 projector_density_history_weight > EPSILON(projector_density_history_weight))) THEN
               DO ivar = 1, 4
                  z_weight = REAL(ivar, KIND=dp)/4.0_dp
                  projector_physical_direct_schur_vec(:, :) = &
                     (1.0_dp - z_weight)*projector_physical_direct_base_delta(:, :) + &
                     z_weight*0.5_dp*((rot_hessian_projector_physical_active(:, :) - rot_hessian(:, :)) + &
                                      TRANSPOSE(rot_hessian_projector_physical_active(:, :) - &
                                                rot_hessian(:, :)))
                  IF (projector_physical_direct_shadow_weight > &
                      EPSILON(projector_physical_direct_shadow_weight)) THEN
                     DO r = 1, nrot
                        diag_shift = z_weight*projector_physical_direct_active_lcomp(r)/ &
                                     projector_physical_direct_shadow_weight
                        IF (diag_shift <= 0.0_dp) CYCLE
                        projector_physical_direct_schur_vec(r, r) = &
                           projector_physical_direct_schur_vec(r, r) + diag_shift
                     END DO
                  END IF
                  schur(:, :) = rot_hessian_coupled(:, :) + &
                                projector_physical_direct_shadow_weight* &
                                projector_physical_direct_schur_vec(:, :)
                  DO s = 1, nrot
                     DO r = 1, nrot
                        projected_term = 0.5_dp* &
                                         (DOT_PRODUCT(energy_cross_physical(:, r), response_exact_physical(:, s)) + &
                                          DOT_PRODUCT(energy_cross_physical(:, s), response_exact_physical(:, r)))
                        IF (exact_density_direct_response_ready) &
                           projected_term = projected_term + 0.5_dp* &
                                            (DOT_PRODUCT(energy_cross_physical(:, r), response_density_direct_exact(:, s)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, r), response_exact_physical(:, s)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, r), response_density_direct_exact(:, s)) + &
                                             DOT_PRODUCT(energy_cross_physical(:, s), response_density_direct_exact(:, r)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, s), response_exact_physical(:, r)) + &
                                             DOT_PRODUCT(energy_cross_density_direct(:, s), response_density_direct_exact(:, r)))
                        schur(r, s) = schur(r, s) - projected_term
                     END DO
                  END DO
                  DO r = 1, nrot
                     row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                        rot_hessian(r, r) + projector_physical_direct_schur_vec(r, r), rot_floor(r))
                     schur(r, r) = schur(r, r) + MAX(0.0_dp, row_floor - schur(r, r))
                  END DO
                  projector_physical_direct_schur_vec(:, :) = 0.5_dp*(schur(:, :) + TRANSPOSE(schur(:, :)))
                  rx_e(:) = accepted_z_e(:) - z_exact_physical_trial(:)
                  rx_model(:) = (1.0_dp - z_weight)*MATMUL(response_exact_raw, accepted_sol) + &
                                z_weight*MATMUL(response_exact_physical, accepted_sol)
                  IF (exact_density_direct_response_ready) &
                     rx_model(:) = rx_model(:) + z_weight*MATMUL(response_density_direct_exact, accepted_sol)
                  CALL project_kpoint_ot_schur_response(rx_e, occ_curv, tether_curv, &
                                                        occ_curv_projection_sum, channel_nmo, e_offset)
                  CALL project_kpoint_ot_schur_response(rx_model, occ_curv, tether_curv, &
                                                        occ_curv_projection_sum, channel_nmo, e_offset)
                  gdotp = DOT_PRODUCT(grad_e, accepted_z_e) + DOT_PRODUCT(grad_rot, accepted_sol)
                  CALL kpoint_ot_mixed_projected_term(accepted_z_e, accepted_z_e, occ_curv, tether_curv, &
                                                      occ_curv_projection_sum, channel_nmo, e_offset, &
                                                      projector_physical_direct_metric_norm_energy)
                  projector_physical_direct_metric_norm_energy = &
                     MAX(0.0_dp, projector_physical_direct_metric_norm_energy)
                  rhs(:) = MATMUL(projector_physical_direct_schur_vec, accepted_sol)
                  projector_physical_direct_metric_norm_rotation = SUM(ABS(accepted_sol(:)*rhs(:)))
                  projector_physical_direct_metric_normp = &
                     projector_physical_direct_metric_norm_energy + &
                     projector_physical_direct_metric_norm_rotation
                  IF (gdotp <= 0.0_dp .OR. &
                      projector_physical_direct_metric_normp <= &
                      EPSILON(projector_physical_direct_metric_normp)) CYCLE
                  model_drop = gdotp - 0.5_dp*projector_physical_direct_metric_normp
                  model_drop = MAX(0.0_dp, model_drop)
                  IF (model_drop <= EPSILON(model_drop)) CYCLE
                  model_gap_drop = kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, 1.0_dp)
                  model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
                  IF (model_calibrated_drop > local_ot_env(1)%schur_projector_mixed_direct_drop .AND. &
                      model_calibrated_drop >= &
                      MAX(accepted_model_calibrated_drop/ot_kp_schur_calibrated_quality_max_ratio, &
                          EPSILON(accepted_model_calibrated_drop)) .AND. &
                      model_calibrated_drop <= ot_kp_schur_calibrated_quality_max_ratio* &
                      MAX(accepted_model_calibrated_drop, EPSILON(accepted_model_calibrated_drop))) THEN
                     local_ot_env(1)%schur_projector_mixed_direct_pending = .TRUE.
                     local_ot_env(1)%schur_projector_mixed_direct_drop = model_calibrated_drop
                     local_ot_env(1)%schur_projector_mixed_direct_weight = z_weight
                  END IF
               END DO
            END IF
         END IF

         DEALLOCATE (curv, grad_e, occ_curv, tether_curv, z_e, accepted_z_e, z_density_plateau_trial, &
                     z_density_floor_audit_trial, z_density_full_audit_trial, &
                     z_density_full_global_trial, &
                     z_density_full_trial, z_density_trial, &
                     z_exact_physical_trial, z_exact_raw_trial, &
                     z_exact_trial, z_trial, rx_e, rx_model, constrained_z_e, &
                     direct_pg_base_e, direct_pg_rx_e, &
                     projector_physical_direct_curv_eval, projector_physical_direct_model_e, &
                     projector_physical_direct_response_rx_e, &
                     projector_physical_direct_diagref_rx_e, &
                     projector_physical_direct_density_rx_e, &
                     projector_physical_direct_density_z_e, &
                     density_descent_rx_e, &
                     density_descent_z_e, &
                     density_full_rx_e, &
                     density_full_global_rx_e, &
                     density_full_global_sol, &
                     density_full_sol, &
                     density_full_z_e, &
                     density_gap_projected_e, &
                     density_gap_rx_e, &
                     density_plateau_rx_e, density_plateau_z_e, &
                     projector_physical_direct_rx_e, &
                     projector_physical_direct_schur_eval, &
                     projector_physical_direct_spectral_model_e, &
                     projector_physical_direct_spectral_rx_e, &
                     projector_physical_direct_z_e, &
                     projector_physical_direct_spectral_z_e, &
                     projector_offdiag_rx_e, projector_offdiag_z_e, &
                     projector_inactive_offdiag_rx_e, &
                     projector_inactive_offdiag_z_e, &
                     projector_physical_model_e, projector_physical_rx_e, &
                     projector_physical_z_e, &
                     projector_response_rx_e, projector_response_z_e, split_z_e)
         DEALLOCATE (grad_rot, rhs, rtd, sol, accepted_sol, constrained_sol, &
                     projector_physical_direct_sol, &
                     projector_physical_direct_spectral_sol, &
                     projector_physical_sol, projector_offdiag_sol, &
                     projector_inactive_offdiag_sol, projector_response_sol, split_sol, &
                     var_occ_gap_weight, var_projector_active_weight, var_projector_weight)
         DEALLOCATE (var_channel, var_ei, var_ej, var_i, var_j, var_kind)
         DEALLOCATE (rot_floor, row_floor_shift, projector_physical_direct_active_lcomp, &
                     energy_cross, energy_cross_density, &
                     energy_cross_density_direct, energy_cross_physical, &
                     energy_cross_raw, &
                     energy_cross_density_floor_audit, &
                     energy_cross_density_full, energy_cross_density_full_audit, &
                     energy_cross_density_full_global, energy_cross_density_plateau, &
                     energy_hessian, response, response_coupled, response_density_direct_exact, &
                     response_density_exact, &
                     response_density_floor_audit, response_density_floor_audit_exact, &
                     response_density_full, response_density_full_audit, &
                     response_density_full_audit_exact, response_density_full_exact, &
                     response_density_full_global, response_density_full_global_exact, response_density_physical, &
                     response_density_plateau, response_density_plateau_exact, &
                     response_exact, response_exact_physical, response_exact_raw, &
                     response_occ, response_occ_physical, response_physical_model, response_split, rot_hessian, &
                     projector_physical_direct_base_delta, projector_physical_direct_curv_evec, &
                     projector_physical_direct_curv_vec, &
                     projector_physical_direct_delta, &
                     rot_hessian_coupled, rot_hessian_projector, &
                     projector_physical_direct_schur_evec, projector_physical_direct_schur_mat, &
                     projector_physical_direct_schur_vec, &
                     rot_hessian_projector_physical, &
                     rot_hessian_projector_physical_active, rot_hessian_projector_physical_diagref, &
                     rot_hessian_projector_physical_offdiag_active, &
                     rot_hessian_projector_physical_offdiag, &
                     rot_hessian_projector_physical_offdiag_plateau, &
                     rot_hessian_projector_physical_offdiag_plateau_active, &
                     schur, schur_metric, ipiv, ipiv_energy, channel_nmo, e_offset)
      END SUBROUTINE precondition_kpoint_ot_schur_group

! **************************************************************************************************
!> \brief ...
!> \param response_vec ...
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
! **************************************************************************************************
      SUBROUTINE project_kpoint_ot_schur_response(response_vec, occ_curv, tether_curv, &
                                                  occ_curv_sum, channel_nmo, e_offset)
      REAL(KIND=dp), DIMENSION(:), INTENT(INOUT)         :: response_vec
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv, tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset

      INTEGER                                            :: first_energy, ie, local_channel, nmo, &
                                                            pass
      LOGICAL                                            :: projected
      REAL(KIND=dp)                                      :: response_shift, weight_sum

         ! The fixed-N Mermin projector is global over the spin/k group, while
         ! the canonical tether gauge is local to each OT channel.
         projected = .FALSE.
         CALL project_kpoint_ot_schur_response_metric(response_vec, occ_curv, tether_curv, &
                                                      occ_curv_sum, channel_nmo, e_offset, projected)
         IF (.NOT. projected) THEN
            DO pass = 1, 2
               IF (occ_curv_sum > EPSILON(occ_curv_sum)) THEN
                  response_shift = DOT_PRODUCT(occ_curv, response_vec)
                  CALL para_env_inter_kp%sum(response_shift)
                  response_vec(:) = response_vec(:) - response_shift/occ_curv_sum
               END IF
               DO local_channel = 1, SIZE(channel_nmo)
                  nmo = channel_nmo(local_channel)
                  IF (nmo <= 0) CYCLE
                  first_energy = e_offset(local_channel)
                  weight_sum = SUM(tether_curv(first_energy:first_energy + nmo - 1))
                  IF (weight_sum <= EPSILON(weight_sum)) CYCLE
                  response_shift = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                               response_vec(first_energy:first_energy + nmo - 1))
                  response_vec(first_energy:first_energy + nmo - 1) = &
                     response_vec(first_energy:first_energy + nmo - 1) - response_shift/weight_sum
               END DO
            END DO
         END IF

         DO ie = 1, SIZE(response_vec)
            IF (occ_curv(ie) + tether_curv(ie) <= EPSILON(occ_curv(ie) + tether_curv(ie))) &
               response_vec(ie) = 0.0_dp
         END DO
      END SUBROUTINE project_kpoint_ot_schur_response

! **************************************************************************************************
!> \brief ...
!> \param response_vec ...
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
!> \param projected ...
! **************************************************************************************************
      SUBROUTINE project_kpoint_ot_schur_response_metric(response_vec, occ_curv, tether_curv, &
                                                         occ_curv_sum, channel_nmo, e_offset, projected)
      REAL(KIND=dp), DIMENSION(:), INTENT(INOUT)         :: response_vec
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv, tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      LOGICAL, INTENT(OUT)                               :: projected

      INTEGER                                            :: first_energy, ie, local_channel, nmo
      REAL(KIND=dp) :: channel_alpha, channel_beta, channel_rhs, curv_max, denom, &
         global_alpha2_over_beta, global_alpha_rhs_over_beta, lambda_occ, max_lambda, occ_metric, &
         occ_rhs, total_curv
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: channel_lambda, inv_curv

         projected = .FALSE.

         curv_max = MAXVAL(occ_curv(:) + tether_curv(:))
         CALL para_env_inter_kp%max(curv_max)
         IF (curv_max <= EPSILON(curv_max)) THEN
            RETURN
         END IF
         ALLOCATE (channel_lambda(SIZE(channel_nmo)), inv_curv(SIZE(response_vec)))
         channel_lambda(:) = 0.0_dp
         DO ie = 1, SIZE(response_vec)
            total_curv = occ_curv(ie) + tether_curv(ie)
            IF (total_curv > EPSILON(curv_max)) THEN
               inv_curv(ie) = 1.0_dp/total_curv
            ELSE
               inv_curv(ie) = 0.0_dp
            END IF
         END DO

         occ_metric = DOT_PRODUCT(occ_curv(:)*inv_curv(:), occ_curv(:))
         occ_rhs = DOT_PRODUCT(occ_curv(:), response_vec(:))
         global_alpha2_over_beta = 0.0_dp
         global_alpha_rhs_over_beta = 0.0_dp
         DO local_channel = 1, SIZE(channel_nmo)
            nmo = channel_nmo(local_channel)
            IF (nmo <= 0) CYCLE
            first_energy = e_offset(local_channel)
            channel_alpha = DOT_PRODUCT(occ_curv(first_energy:first_energy + nmo - 1)* &
                                        inv_curv(first_energy:first_energy + nmo - 1), &
                                        tether_curv(first_energy:first_energy + nmo - 1))
            channel_beta = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1)* &
                                       inv_curv(first_energy:first_energy + nmo - 1), &
                                       tether_curv(first_energy:first_energy + nmo - 1))
            channel_rhs = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                      response_vec(first_energy:first_energy + nmo - 1))
            IF (channel_beta > EPSILON(curv_max)) THEN
               global_alpha2_over_beta = global_alpha2_over_beta + channel_alpha*channel_alpha/channel_beta
               global_alpha_rhs_over_beta = global_alpha_rhs_over_beta + channel_alpha*channel_rhs/channel_beta
            END IF
         END DO
         CALL para_env_inter_kp%sum(occ_metric)
         CALL para_env_inter_kp%sum(occ_rhs)
         CALL para_env_inter_kp%sum(global_alpha2_over_beta)
         CALL para_env_inter_kp%sum(global_alpha_rhs_over_beta)

         lambda_occ = 0.0_dp
         IF (occ_curv_sum > EPSILON(occ_curv_sum)) THEN
            denom = occ_metric - global_alpha2_over_beta
            IF (denom <= SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, occ_metric)) THEN
               DEALLOCATE (channel_lambda, inv_curv)
               RETURN
            END IF
            lambda_occ = (occ_rhs - global_alpha_rhs_over_beta)/denom
         END IF

         DO local_channel = 1, SIZE(channel_nmo)
            nmo = channel_nmo(local_channel)
            IF (nmo <= 0) CYCLE
            first_energy = e_offset(local_channel)
            channel_alpha = DOT_PRODUCT(occ_curv(first_energy:first_energy + nmo - 1)* &
                                        inv_curv(first_energy:first_energy + nmo - 1), &
                                        tether_curv(first_energy:first_energy + nmo - 1))
            channel_beta = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1)* &
                                       inv_curv(first_energy:first_energy + nmo - 1), &
                                       tether_curv(first_energy:first_energy + nmo - 1))
            channel_rhs = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                      response_vec(first_energy:first_energy + nmo - 1))
            IF (channel_beta > EPSILON(curv_max)) &
               channel_lambda(local_channel) = (channel_rhs - channel_alpha*lambda_occ)/channel_beta
         END DO

         max_lambda = 0.0_dp
         DO local_channel = 1, SIZE(channel_nmo)
            max_lambda = MAX(max_lambda, ABS(channel_lambda(local_channel)))
         END DO
         IF (ABS(lambda_occ) > EPSILON(lambda_occ) .OR. max_lambda > EPSILON(curv_max)) THEN
            response_vec(:) = response_vec(:) - lambda_occ*inv_curv(:)*occ_curv(:)
            DO local_channel = 1, SIZE(channel_nmo)
               nmo = channel_nmo(local_channel)
               IF (nmo <= 0) CYCLE
               first_energy = e_offset(local_channel)
               response_vec(first_energy:first_energy + nmo - 1) = &
                  response_vec(first_energy:first_energy + nmo - 1) - &
                  channel_lambda(local_channel)*inv_curv(first_energy:first_energy + nmo - 1)* &
                  tether_curv(first_energy:first_energy + nmo - 1)
            END DO
            projected = .TRUE.
         ELSE
            projected = .TRUE.
         END IF
         DEALLOCATE (channel_lambda, inv_curv)

      END SUBROUTINE project_kpoint_ot_schur_response_metric

! **************************************************************************************************
!> \brief ...
!> \param response_vec ...
!> \param descent_vec ...
!> \param grad_e ...
!> \param projected_vec ...
!> \param coeff ...
!> \param gdot ...
!> \param denom ...
!> \param flip_negative ...
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
! **************************************************************************************************
      SUBROUTINE project_kpoint_ot_descent_response(response_vec, descent_vec, grad_e, projected_vec, &
                                                    coeff, gdot, denom, flip_negative, occ_curv, &
                                                    tether_curv, occ_curv_sum, channel_nmo, e_offset)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: response_vec, descent_vec, grad_e
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: projected_vec
      REAL(KIND=dp), INTENT(OUT)                         :: coeff, gdot, denom
      LOGICAL, INTENT(IN), OPTIONAL                      :: flip_negative
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: occ_curv, tether_curv
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN), OPTIONAL        :: channel_nmo, e_offset

      REAL(KIND=dp)                                      :: grad_coeff, metric_coeff, metric_cross, &
                                                            metric_denom

         projected_vec(:) = 0.0_dp
         coeff = 0.0_dp
         gdot = DOT_PRODUCT(grad_e, response_vec)
         denom = DOT_PRODUCT(grad_e, descent_vec)
         CALL para_env_inter_kp%sum(gdot)
         CALL para_env_inter_kp%sum(denom)
         IF (denom <= EPSILON(denom)) RETURN

         grad_coeff = 0.0_dp
         IF (gdot > 0.0_dp) THEN
            grad_coeff = gdot/denom
         ELSE IF (PRESENT(flip_negative)) THEN
            IF (flip_negative .AND. gdot < -EPSILON(denom)) &
               grad_coeff = ABS(gdot)/denom
         END IF

         metric_coeff = 0.0_dp
         IF (PRESENT(occ_curv) .AND. PRESENT(tether_curv) .AND. PRESENT(occ_curv_sum) .AND. &
             PRESENT(channel_nmo) .AND. PRESENT(e_offset)) THEN
            CALL kpoint_ot_mixed_projected_term(response_vec, descent_vec, occ_curv, tether_curv, &
                                                occ_curv_sum, channel_nmo, e_offset, metric_cross)
            CALL kpoint_ot_mixed_projected_term(descent_vec, descent_vec, occ_curv, tether_curv, &
                                                occ_curv_sum, channel_nmo, e_offset, metric_denom)
            IF (metric_denom > EPSILON(metric_denom)) THEN
               IF (metric_cross > 0.0_dp) THEN
                  metric_coeff = metric_cross/metric_denom
               ELSE IF (PRESENT(flip_negative)) THEN
                  IF (flip_negative .AND. metric_cross < -EPSILON(metric_denom)) &
                     metric_coeff = ABS(metric_cross)/metric_denom
               END IF
            END IF
         END IF

         coeff = MAX(grad_coeff, metric_coeff)
         IF (coeff <= 0.0_dp) RETURN
         projected_vec(:) = coeff*descent_vec(:)

      END SUBROUTINE project_kpoint_ot_descent_response

! **************************************************************************************************
!> \brief ...
!> \param response_left ...
!> \param response_right ...
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
!> \param projected_term ...
!> \param occ_projected_term ...
!> \param tether_projected_term ...
! **************************************************************************************************
      SUBROUTINE kpoint_ot_mixed_projected_term(response_left, response_right, occ_curv, tether_curv, &
                                                occ_curv_sum, channel_nmo, e_offset, projected_term, &
                                                occ_projected_term, tether_projected_term)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: response_left, response_right, occ_curv, &
                                                            tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      REAL(KIND=dp), INTENT(OUT)                         :: projected_term
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: occ_projected_term, tether_projected_term

      INTEGER                                            :: first_energy, local_channel, nmo
      REAL(KIND=dp)                                      :: left_shift, occ_term, right_shift, &
                                                            tether_term, weight_sum

         occ_term = DOT_PRODUCT(occ_curv(:)*response_left(:), response_right(:))
         IF (occ_curv_sum > EPSILON(occ_curv_sum)) THEN
            left_shift = DOT_PRODUCT(occ_curv, response_left)
            right_shift = DOT_PRODUCT(occ_curv, response_right)
            CALL para_env_inter_kp%sum(left_shift)
            CALL para_env_inter_kp%sum(right_shift)
            CALL para_env_inter_kp%sum(occ_term)
            occ_term = occ_term - left_shift*right_shift/occ_curv_sum
         ELSE
            CALL para_env_inter_kp%sum(occ_term)
         END IF
         tether_term = DOT_PRODUCT(tether_curv(:)*response_left(:), response_right(:))
         DO local_channel = 1, SIZE(channel_nmo)
            nmo = channel_nmo(local_channel)
            IF (nmo <= 0) CYCLE
            first_energy = e_offset(local_channel)
            weight_sum = SUM(tether_curv(first_energy:first_energy + nmo - 1))
            IF (weight_sum <= EPSILON(weight_sum)) CYCLE
            left_shift = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                     response_left(first_energy:first_energy + nmo - 1))
            right_shift = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                      response_right(first_energy:first_energy + nmo - 1))
            tether_term = tether_term - left_shift*right_shift/weight_sum
         END DO
         CALL para_env_inter_kp%sum(tether_term)
         projected_term = occ_term + tether_term
         IF (PRESENT(occ_projected_term)) occ_projected_term = occ_term
         IF (PRESENT(tether_projected_term)) tether_projected_term = tether_term
      END SUBROUTINE kpoint_ot_mixed_projected_term

! **************************************************************************************************
!> \brief ...
!> \param response_occ_left ...
!> \param response_occ_right ...
!> \param response_tether_left ...
!> \param response_tether_right ...
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
!> \param projected_term ...
!> \param occ_projected_term ...
!> \param tether_projected_term ...
! **************************************************************************************************
      SUBROUTINE kpoint_ot_mixed_projected_cross_term(response_occ_left, response_occ_right, &
                                                      response_tether_left, response_tether_right, &
                                                      occ_curv, tether_curv, occ_curv_sum, &
                                                      channel_nmo, e_offset, projected_term, &
                                                      occ_projected_term, tether_projected_term)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: response_occ_left, response_occ_right, &
                                                            response_tether_left, &
                                                            response_tether_right, occ_curv, &
                                                            tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      REAL(KIND=dp), INTENT(OUT)                         :: projected_term
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: occ_projected_term, tether_projected_term

      INTEGER                                            :: first_energy, local_channel, nmo
      REAL(KIND=dp)                                      :: left_shift, occ_term, right_shift, &
                                                            tether_term, weight_sum

         occ_term = DOT_PRODUCT(occ_curv(:)*response_occ_left(:), response_occ_right(:))
         IF (occ_curv_sum > EPSILON(occ_curv_sum)) THEN
            left_shift = DOT_PRODUCT(occ_curv, response_occ_left)
            right_shift = DOT_PRODUCT(occ_curv, response_occ_right)
            CALL para_env_inter_kp%sum(left_shift)
            CALL para_env_inter_kp%sum(right_shift)
            CALL para_env_inter_kp%sum(occ_term)
            occ_term = occ_term - left_shift*right_shift/occ_curv_sum
         ELSE
            CALL para_env_inter_kp%sum(occ_term)
         END IF
         tether_term = DOT_PRODUCT(tether_curv(:)*response_tether_left(:), response_tether_right(:))
         DO local_channel = 1, SIZE(channel_nmo)
            nmo = channel_nmo(local_channel)
            IF (nmo <= 0) CYCLE
            first_energy = e_offset(local_channel)
            weight_sum = SUM(tether_curv(first_energy:first_energy + nmo - 1))
            IF (weight_sum <= EPSILON(weight_sum)) CYCLE
            left_shift = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                     response_tether_left(first_energy:first_energy + nmo - 1))
            right_shift = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                      response_tether_right(first_energy:first_energy + nmo - 1))
            tether_term = tether_term - left_shift*right_shift/weight_sum
         END DO
         CALL para_env_inter_kp%sum(tether_term)
         projected_term = occ_term + tether_term
         IF (PRESENT(occ_projected_term)) occ_projected_term = occ_term
         IF (PRESENT(tether_projected_term)) tether_projected_term = tether_term
      END SUBROUTINE kpoint_ot_mixed_projected_cross_term

! **************************************************************************************************
!> \brief ...
!> \param occ_curv ...
!> \param tether_curv ...
!> \param response_occ ...
!> \param response_tether ...
!> \param grad_e ...
!> \param channel_nmo ...
!> \param e_offset ...
!> \param energy_hessian ...
!> \param energy_cross ...
!> \param response_exact ...
!> \param z_exact ...
!> \param ipiv_energy ...
!> \param ready ...
!> \param gauge_weight ...
! **************************************************************************************************
      SUBROUTINE build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_occ, &
                                                       response_tether, grad_e, channel_nmo, e_offset, &
                                                       energy_hessian, energy_cross, response_exact, z_exact, &
                                                       ipiv_energy, ready, gauge_weight)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv, tether_curv
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: response_occ, response_tether
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: grad_e
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      REAL(KIND=dp), DIMENSION(:, :), INTENT(INOUT)      :: energy_hessian, energy_cross, &
                                                            response_exact
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: z_exact
      INTEGER, DIMENSION(:), INTENT(INOUT)               :: ipiv_energy
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT)                         :: gauge_weight

      INTEGER                                            :: first_energy, ie, info, je, &
                                                            local_channel, ne_local, nmo, nrhs, &
                                                            nrot_local, r
      REAL(KIND=dp)                                      :: channel_occ_sum, curv_max, occ_sum, &
                                                            response_shift, weight_sum
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: rhs, rhs_source

         ready = .FALSE.
         gauge_weight = 0.0_dp
         ne_local = SIZE(grad_e)
         nrot_local = SIZE(response_occ, 2)
         IF (ne_local <= 0 .OR. nrot_local <= 0) RETURN

         energy_hessian(:, :) = 0.0_dp
         energy_cross(:, :) = 0.0_dp
         response_exact(:, :) = 0.0_dp
         z_exact(:) = 0.0_dp

         DO ie = 1, ne_local
            energy_hessian(ie, ie) = occ_curv(ie) + tether_curv(ie)
         END DO

         occ_sum = SUM(occ_curv)
         CALL para_env_inter_kp%sum(occ_sum)
         IF (occ_sum > EPSILON(occ_sum)) THEN
            DO je = 1, ne_local
               DO ie = 1, ne_local
                  energy_hessian(ie, je) = energy_hessian(ie, je) - &
                                           occ_curv(ie)*occ_curv(je)/occ_sum
               END DO
            END DO
            DO r = 1, nrot_local
               response_shift = DOT_PRODUCT(occ_curv, response_occ(:, r))
               CALL para_env_inter_kp%sum(response_shift)
               energy_cross(:, r) = energy_cross(:, r) + &
                                    occ_curv(:)*(response_occ(:, r) - response_shift/occ_sum)
            END DO
         END IF

         DO local_channel = 1, SIZE(channel_nmo)
            nmo = channel_nmo(local_channel)
            IF (nmo <= 0) CYCLE
            first_energy = e_offset(local_channel)
            weight_sum = SUM(tether_curv(first_energy:first_energy + nmo - 1))
            IF (weight_sum <= EPSILON(weight_sum)) CYCLE
            DO je = first_energy, first_energy + nmo - 1
               DO ie = first_energy, first_energy + nmo - 1
                  energy_hessian(ie, je) = energy_hessian(ie, je) - &
                                           tether_curv(ie)*tether_curv(je)/weight_sum
               END DO
            END DO
            DO r = 1, nrot_local
               response_shift = DOT_PRODUCT(tether_curv(first_energy:first_energy + nmo - 1), &
                                            response_tether(first_energy:first_energy + nmo - 1, r))
               energy_cross(first_energy:first_energy + nmo - 1, r) = &
                  energy_cross(first_energy:first_energy + nmo - 1, r) + &
                  tether_curv(first_energy:first_energy + nmo - 1)* &
                  (response_tether(first_energy:first_energy + nmo - 1, r) - response_shift/weight_sum)
            END DO
         END DO

         curv_max = MAXVAL(occ_curv(:) + tether_curv(:))
         CALL para_env_inter_kp%max(curv_max)
         IF (curv_max <= 0.0_dp) RETURN
         gauge_weight = curv_max/REAL(MAX(1, ne_local), KIND=dp)
         IF (occ_sum > EPSILON(occ_sum)) THEN
            ! Lift the global fixed-N gauge.  The response RHS is fixed-N
            ! projected, so this rank-one term only pins the null direction.
            energy_hessian(:, :) = energy_hessian(:, :) + gauge_weight
         END IF
         DO local_channel = 1, SIZE(channel_nmo)
            nmo = channel_nmo(local_channel)
            IF (nmo <= 0) CYCLE
            first_energy = e_offset(local_channel)
            weight_sum = SUM(tether_curv(first_energy:first_energy + nmo - 1))
            channel_occ_sum = SUM(occ_curv(first_energy:first_energy + nmo - 1))
            IF (weight_sum <= EPSILON(weight_sum) .OR. channel_occ_sum > EPSILON(channel_occ_sum)) CYCLE
            ! If the smearing curvature is absent for a channel, the canonical
            ! tether projector leaves a channel-local constant-energy gauge.
            DO je = first_energy, first_energy + nmo - 1
               DO ie = first_energy, first_energy + nmo - 1
                  energy_hessian(ie, je) = energy_hessian(ie, je) + gauge_weight
               END DO
            END DO
         END DO
         DO ie = 1, ne_local
            IF (occ_curv(ie) + tether_curv(ie) > EPSILON(curv_max)) CYCLE
            energy_hessian(ie, :) = 0.0_dp
            energy_hessian(:, ie) = 0.0_dp
            energy_hessian(ie, ie) = 1.0_dp
            energy_cross(ie, :) = 0.0_dp
         END DO

         nrhs = nrot_local + 1
         ALLOCATE (rhs(ne_local, nrhs), rhs_source(ne_local, nrhs))
         rhs(:, 1:nrot_local) = energy_cross(:, 1:nrot_local)
         rhs(:, nrhs) = grad_e(:)
         DO ie = 1, ne_local
            IF (occ_curv(ie) + tether_curv(ie) <= EPSILON(curv_max)) rhs(ie, nrhs) = 0.0_dp
         END DO
         rhs_source(:, :) = rhs(:, :)
         CALL dgesv(ne_local, nrhs, energy_hessian, ne_local, ipiv_energy, rhs, ne_local, info)
         IF (info /= 0) THEN
            DO r = 1, nrhs
               DO ie = 1, ne_local
                  IF (occ_curv(ie) + tether_curv(ie) > EPSILON(curv_max)) THEN
                     rhs(ie, r) = rhs_source(ie, r)/(occ_curv(ie) + tether_curv(ie))
                  ELSE
                     rhs(ie, r) = 0.0_dp
                  END IF
               END DO
            END DO
            info = 0
         END IF
         IF (info == 0) THEN
            response_exact(:, 1:nrot_local) = rhs(:, 1:nrot_local)
            z_exact(:) = rhs(:, nrhs)
            DO r = 1, nrot_local
               CALL project_kpoint_ot_schur_response(response_exact(:, r), occ_curv, tether_curv, &
                                                     occ_sum, channel_nmo, e_offset)
            END DO
            CALL project_kpoint_ot_schur_response(z_exact, occ_curv, tether_curv, &
                                                  occ_sum, channel_nmo, e_offset)
            ready = .TRUE.
         END IF
         DEALLOCATE (rhs, rhs_source)

      END SUBROUTINE build_kpoint_ot_exact_energy_response

! **************************************************************************************************
!> \brief ...
!> \param response_vec ...
!> \param curv ...
!> \param curv_sum ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_weighted_response_step(response_vec, curv, curv_sum) RESULT(step)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: response_vec, curv
      REAL(KIND=dp), INTENT(IN)                          :: curv_sum
      REAL(KIND=dp)                                      :: step

      REAL(KIND=dp)                                      :: weighted_norm

         weighted_norm = DOT_PRODUCT(curv(:)*response_vec(:), response_vec(:))
         CALL para_env_inter_kp%sum(weighted_norm)
         IF (curv_sum > EPSILON(curv_sum)) THEN
            step = SQRT(MAX(0.0_dp, weighted_norm/curv_sum))
         ELSE
            step = MAXVAL(ABS(response_vec))
            CALL para_env_inter_kp%max(step)
         END IF

      END FUNCTION kpoint_ot_weighted_response_step

! **************************************************************************************************
!> \brief ...
!> \param sigma ...
!> \param row_diag ...
!> \param physical_diag ...
!> \param frontier_floor ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_physical_rotation_floor(sigma, row_diag, physical_diag, frontier_floor) RESULT(row_floor)
      REAL(KIND=dp), INTENT(IN)                          :: sigma, row_diag, physical_diag, &
                                                            frontier_floor
      REAL(KIND=dp)                                      :: row_floor

         row_floor = SQRT(EPSILON(1.0_dp))* &
                     MAX(1.0_dp, ABS(row_diag), ABS(physical_diag))
         IF (sigma > EPSILON(sigma)) &
            row_floor = MAX(row_floor, &
                            ot_kp_schur_response_trust_min_factor*kpoint_ot_fermi_window_anchor(sigma))
         row_floor = MIN(frontier_floor, row_floor)

      END FUNCTION kpoint_ot_physical_rotation_floor

! **************************************************************************************************
!> \brief active-window curvature blend driven by accepted density-response history
!> \param active_weight current active-window trace weight
!> \param density_history_weight accepted density-response history weight
!> \param residual_delta current OT residual
!> \param projector_weight active finite Projector-Hessian weight in the Schur block
!> \return trace-active curvature weight for the physical Direct model
! **************************************************************************************************
      FUNCTION kpoint_ot_physical_direct_density_mix(active_weight, density_history_weight, &
                                                     residual_delta, projector_weight) RESULT(mix_weight)
      REAL(KIND=dp), INTENT(IN)                          :: active_weight, density_history_weight, &
                                                            residual_delta
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_weight
      REAL(KIND=dp)                                      :: mix_weight

      REAL(KIND=dp)                                      :: density_weight

         mix_weight = MIN(ot_kp_schur_projector_trace_active_max_weight, &
                          MAX(0.0_dp, active_weight))
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN

         density_weight = MAX(0.0_dp, density_history_weight)
         IF (PRESENT(projector_weight)) &
            density_weight = MAX(density_weight, &
                                 kpoint_ot_projector_tail_active_delta_weight(projector_weight, density_history_weight))
         mix_weight = MAX(mix_weight, MIN(ot_kp_schur_projector_trace_active_max_weight, &
                                          density_weight))

      END FUNCTION kpoint_ot_physical_direct_density_mix

! **************************************************************************************************
!> \brief pair-aware row floor for the raw Schur fallback in the metallic residual tail
!> \param base_floor generic raw-fallback curvature floor
!> \param pair_floor Fermi-frontier or occupation-gauge pair floor
!> \param residual_delta current OT residual
!> \return raw-fallback row floor
! **************************************************************************************************
      FUNCTION kpoint_ot_raw_tail_rotation_floor(base_floor, pair_floor, residual_delta) RESULT(row_floor)
      REAL(KIND=dp), INTENT(IN)                          :: base_floor, pair_floor, residual_delta
      REAL(KIND=dp)                                      :: row_floor

         row_floor = base_floor
         IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
            row_floor = MAX(row_floor, pair_floor)

      END FUNCTION kpoint_ot_raw_tail_rotation_floor

! **************************************************************************************************
!> \brief ...
!> \param direction_scale ...
!> \param scale_floor ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_schur_scale_quality(direction_scale, scale_floor) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: direction_scale, scale_floor
      REAL(KIND=dp)                                      :: quality

         IF (scale_floor > EPSILON(scale_floor)) THEN
            quality = MIN(1.0_dp, MAX(0.0_dp, direction_scale)/scale_floor)
         ELSE
            quality = 1.0_dp
         END IF

      END FUNCTION kpoint_ot_schur_scale_quality

! **************************************************************************************************
!> \brief ...
!> \param predicted_sum ...
!> \param measured_sum ...
!> \param ema_quality ...
!> \param samples ...
!> \param min_samples ...
!> \param default_quality ...
!> \param min_quality ...
!> \param max_quality ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_schur_history_quality(predicted_sum, measured_sum, ema_quality, &
                                               samples, min_samples, default_quality, &
                                               min_quality, max_quality) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: predicted_sum, measured_sum, ema_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp), INTENT(IN)                          :: default_quality, min_quality, max_quality
      REAL(KIND=dp)                                      :: quality

         quality = default_quality
         IF (samples >= min_samples) THEN
            IF (predicted_sum > EPSILON(predicted_sum) .AND. measured_sum > 0.0_dp) THEN
               quality = measured_sum/predicted_sum
            ELSE IF (ema_quality > 0.0_dp) THEN
               quality = ema_quality
            END IF
         END IF
         quality = MAX(min_quality, MIN(max_quality, quality))

      END FUNCTION kpoint_ot_schur_history_quality

! **************************************************************************************************
!> \brief residual-tail quality for accepted inactive-offdiag projector steps
!> \param base_quality accepted selected-history Mermin-drop quality
!> \param selected_mermin_quality_ema EMA of selected-step Mermin-drop quality
!> \param selected_predicted_sum accumulated selected-step predicted Mermin drop
!> \param selected_measured_sum accumulated selected-step measured Mermin drop
!> \param selected_residual_quality latest selected-step residual quality
!> \param selected_residual_quality_ema EMA of selected-step residual quality
!> \param residual_reference_quality split/coupled residual quality reference
!> \param selected_quality_samples number of accepted selected inactive-offdiag samples
!> \param residual_delta current OT residual delta
!> \return selected inactive-offdiag quality for candidate selection
! **************************************************************************************************
      FUNCTION kpoint_ot_inactive_offdiag_selected_tail_quality(base_quality, selected_mermin_quality_ema, &
                                                               selected_predicted_sum, selected_measured_sum, &
                                                               selected_residual_quality, &
                                                               selected_residual_quality_ema, &
                                                               residual_reference_quality, &
                                                               selected_quality_samples, &
                                                               residual_delta) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: base_quality, selected_mermin_quality_ema, &
                                                            selected_predicted_sum, selected_measured_sum, &
                                                            selected_residual_quality, &
                                                            selected_residual_quality_ema, &
                                                            residual_reference_quality, residual_delta
      INTEGER, INTENT(IN)                                :: selected_quality_samples
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: mermin_factor, mermin_quality, residual_factor, &
                                                            residual_ref, residual_quality

         quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, base_quality))
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (selected_quality_samples < 2*ot_kp_schur_calibration_min_samples) RETURN

         mermin_quality = quality
         IF (selected_predicted_sum > EPSILON(selected_predicted_sum) .AND. &
             selected_measured_sum > 0.0_dp) mermin_quality = selected_measured_sum/selected_predicted_sum
         IF (selected_mermin_quality_ema > 0.0_dp) &
            mermin_quality = MIN(mermin_quality, selected_mermin_quality_ema)
         mermin_quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                                          mermin_quality))
         IF (mermin_quality < ot_kp_schur_projector_response_quality_min_ratio) THEN
            quality = 0.0_dp
            RETURN
         END IF

         residual_ref = MAX(residual_reference_quality, ot_kp_schur_calibrated_quality_min_ratio, &
                            EPSILON(1.0_dp))
         residual_quality = MAX(0.0_dp, MIN(1.0_dp, selected_residual_quality_ema))
         IF (selected_residual_quality > EPSILON(selected_residual_quality)) &
            residual_quality = MIN(residual_quality, &
                                   0.5_dp*(residual_quality + &
                                           MAX(0.0_dp, MIN(1.0_dp, selected_residual_quality))))

         mermin_factor = MIN(1.0_dp, SQRT(MAX(0.0_dp, mermin_quality)/ &
                                          MAX(ot_kp_schur_calibrated_quality_min_ratio, EPSILON(1.0_dp))))
         residual_factor = MIN(1.0_dp, SQRT(residual_quality/residual_ref))

         quality = quality*mermin_factor*residual_factor
         quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, quality))

      END FUNCTION kpoint_ot_inactive_offdiag_selected_tail_quality

! **************************************************************************************************
!> \brief residual-tail cap for offdiag projector candidate history
!> \param base_quality accepted Mermin-drop history quality
!> \param residual_quality latest accepted coupled residual quality
!> \param residual_quality_ema EMA of accepted coupled residual quality
!> \param residual_samples number of coupled accepted samples
!> \param residual_delta current OT residual delta
!> \return offdiag candidate selection quality capped by residual consistency
! **************************************************************************************************
      FUNCTION kpoint_ot_offdiag_tail_residual_quality(base_quality, residual_quality, &
                                                       residual_quality_ema, residual_samples, &
                                                       residual_delta) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: base_quality, residual_quality, &
                                                            residual_quality_ema, residual_delta
      INTEGER, INTENT(IN)                                :: residual_samples
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: residual_cap, residual_ref, residual_signal

         quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, base_quality))
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (residual_samples < 2*ot_kp_schur_calibration_min_samples) RETURN

         residual_signal = MAX(0.0_dp, MIN(1.0_dp, residual_quality_ema))
         IF (residual_quality > EPSILON(residual_quality)) &
            residual_signal = MIN(residual_signal, &
                                  0.5_dp*(residual_signal + &
                                          MAX(0.0_dp, MIN(1.0_dp, residual_quality))))
         IF (residual_signal <= EPSILON(residual_signal)) THEN
            quality = 0.0_dp
            RETURN
         END IF

         residual_ref = MAX(ot_kp_schur_calibrated_quality_min_ratio, EPSILON(1.0_dp))
         residual_cap = ot_kp_schur_projector_response_quality_max_ratio* &
                        MIN(1.0_dp, residual_signal/residual_ref)
         quality = MIN(quality, residual_cap)
         quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, quality))

      END FUNCTION kpoint_ot_offdiag_tail_residual_quality

! **************************************************************************************************
!> \brief accepted-history gate for conservative projector-response underprediction
!> \param samples number of accepted shadow response samples
!> \param quality most recent measured/predicted Mermin-drop ratio
!> \param quality_ema measured/predicted Mermin-drop EMA
!> \param predicted_sum accumulated predicted Mermin drop
!> \param measured_sum accumulated accepted Mermin drop
!> \param negative_ema accepted negative response fraction
!> \return whether the projector-response candidate can enter selection
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_response_candidate_enabled(samples, quality, quality_ema, predicted_sum, &
                                                              measured_sum, negative_ema) RESULT(enabled)
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: quality, quality_ema, predicted_sum, &
                                                            measured_sum, negative_ema
      LOGICAL                                            :: enabled

      LOGICAL                                            :: aggregate_recovered_quality, &
                                                            normal_quality, underpredicted_quality
      REAL(KIND=dp)                                      :: aggregate_quality

         enabled = .FALSE.
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (quality_ema < ot_kp_schur_projector_response_quality_min_ratio) RETURN
         IF (quality < 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN

         aggregate_quality = 0.0_dp
         IF (predicted_sum > EPSILON(predicted_sum) .AND. measured_sum > 0.0_dp) &
            aggregate_quality = measured_sum/predicted_sum

         normal_quality = quality_ema <= ot_kp_schur_projector_response_quality_max_ratio .AND. &
                          quality <= 2.0_dp*ot_kp_schur_projector_response_quality_max_ratio .AND. &
                          negative_ema <= ot_kp_schur_projector_negative_balance_max
         aggregate_recovered_quality = aggregate_quality >= ot_kp_schur_projector_response_quality_min_ratio .AND. &
                                       aggregate_quality <= ot_kp_schur_projector_response_quality_max_ratio .AND. &
                                       quality >= ot_kp_schur_projector_response_quality_min_ratio .AND. &
                                       quality <= 2.0_dp*ot_kp_schur_projector_response_quality_max_ratio .AND. &
                                       negative_ema <= ot_kp_schur_projector_negative_balance_floor
         underpredicted_quality = quality_ema > ot_kp_schur_projector_response_quality_max_ratio .AND. &
                                  quality_ema <= ot_kp_schur_projector_response_underpredict_max_ratio .AND. &
                                  quality <= ot_kp_schur_projector_response_underpredict_max_ratio .AND. &
                                  predicted_sum > EPSILON(predicted_sum) .AND. &
                                  measured_sum > predicted_sum .AND. &
                                  negative_ema <= ot_kp_schur_projector_negative_balance_floor

         enabled = normal_quality .OR. aggregate_recovered_quality .OR. underpredicted_quality

      END FUNCTION kpoint_ot_projector_response_candidate_enabled

! **************************************************************************************************
!> \brief ...
!> \param predicted_sum ...
!> \param measured_sum ...
!> \param ema_quality ...
!> \param samples ...
!> \param min_samples ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_history_quality(predicted_sum, measured_sum, ema_quality, &
                                                samples, min_samples) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: predicted_sum, measured_sum, ema_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: quality

         quality = 1.0_dp
         IF (samples < min_samples) RETURN

         IF (predicted_sum > EPSILON(predicted_sum) .AND. measured_sum > 0.0_dp) THEN
            quality = measured_sum/predicted_sum
            IF (ema_quality > 0.0_dp) quality = MAX(quality, ema_quality)
         ELSE IF (ema_quality > 0.0_dp) THEN
            quality = ema_quality
         END IF
         quality = MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                       MIN(ot_kp_schur_projector_response_quality_max_ratio, quality))

      END FUNCTION kpoint_ot_direct_history_quality

! **************************************************************************************************
!> \brief combine correlated Direct quality histories for residual-tail candidate selection
!> \param base_quality physical/trace-split quality already calibrated by accepted Mermin drops
!> \param history_quality selected or shadow Direct history from the same accepted-drop stream
!> \return conservative correlated quality without turning stale Direct history into a hard veto
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_tail_selection_quality(base_quality, history_quality) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: base_quality, history_quality
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: clipped_history

         quality = MAX(0.0_dp, MIN(1.0_dp, base_quality))
         IF (history_quality <= 0.0_dp) RETURN

         clipped_history = MAX(0.0_dp, MIN(1.0_dp, history_quality))
         IF (clipped_history < quality) &
            quality = SQRT(MAX(0.0_dp, quality*clipped_history))
         quality = MIN(quality, MAX(0.0_dp, MIN(1.0_dp, base_quality)))

      END FUNCTION kpoint_ot_direct_tail_selection_quality

! **************************************************************************************************
!> \brief residual-aware selected Direct quality for the metallic tail
!> \param current_quality Mermin-calibrated Direct quality used for selection
!> \param trace_quality invariant-trace cap for the physical Direct channel
!> \param selected_quality latest selected Direct Mermin measured/predicted quality
!> \param selected_quality_ema selected Direct Mermin quality EMA
!> \param selected_residual_quality latest selected Direct residual quality
!> \param selected_residual_quality_ema selected Direct residual quality EMA
!> \param samples selected Direct accepted samples
!> \param min_samples minimum selected samples before residual history contributes
!> \return Direct quality with residual-tail support but bounded by trace quality
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_tail_residual_selection_quality(current_quality, trace_quality, &
                                                                selected_quality, selected_quality_ema, &
                                                                selected_residual_quality, &
                                                                selected_residual_quality_ema, samples, &
                                                                min_samples) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: current_quality, trace_quality, &
                                                            selected_quality, selected_quality_ema, &
                                                            selected_residual_quality, &
                                                            selected_residual_quality_ema
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: mermin_signal, residual_support, trace_cap

         quality = MAX(0.0_dp, MIN(1.0_dp, current_quality))
         IF (samples < min_samples) RETURN

         mermin_signal = MAX(0.0_dp, MIN(1.0_dp, selected_quality_ema))
         IF (selected_quality > EPSILON(selected_quality)) &
            mermin_signal = MAX(0.0_dp, MIN(mermin_signal, &
                                            MAX(0.0_dp, MIN(1.0_dp, selected_quality))))
         IF (mermin_signal < 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN

         residual_support = kpoint_ot_selected_tail_residual_quality( &
                            selected_residual_quality, selected_residual_quality_ema)
         IF (residual_support <= EPSILON(residual_support)) RETURN

         trace_cap = MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                         MAX(0.0_dp, MIN(1.0_dp, trace_quality)))
         quality = MAX(quality, MIN(trace_cap, residual_support))
         quality = MAX(0.0_dp, MIN(1.0_dp, quality))

      END FUNCTION kpoint_ot_direct_tail_residual_selection_quality

! **************************************************************************************************
!> \brief maturity-weighted selected-history calibration for physical Direct selection
!> \param base_quality trace/mixed Direct history quality before selected-history override
!> \param predicted_sum selected Direct predicted Mermin drop sum
!> \param measured_sum selected Direct measured Mermin drop sum
!> \param ema_quality recent selected Direct measured/predicted quality
!> \param samples number of selected Direct accepted samples
!> \param min_samples minimum samples before selected history contributes
!> \return selected-history quality blended with the non-circular Direct base
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_selected_history_quality(base_quality, predicted_sum, measured_sum, &
                                                         ema_quality, samples, min_samples) &
         RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: base_quality, predicted_sum, &
                                                            measured_sum, ema_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: quality

      INTEGER                                            :: maturity_samples
      REAL(KIND=dp)                                      :: maturity, selected_quality

         quality = base_quality
         IF (samples < min_samples) RETURN

         selected_quality = kpoint_ot_schur_history_quality(predicted_sum, measured_sum, ema_quality, &
                                                            samples, min_samples, base_quality, &
                                                            ot_kp_schur_projector_response_quality_min_ratio, &
                                                            ot_kp_schur_projector_response_quality_max_ratio)
         maturity_samples = MAX(1, 2*ot_kp_schur_projector_response_min_samples - min_samples + 1)
         maturity = REAL(MAX(0, samples - min_samples + 1), KIND=dp)/REAL(maturity_samples, KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))

         quality = (1.0_dp - maturity)*base_quality + maturity*selected_quality
         quality = MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                       MIN(ot_kp_schur_projector_response_quality_max_ratio, quality))

      END FUNCTION kpoint_ot_direct_selected_history_quality

! **************************************************************************************************
!> \brief selected-history calibration for continued Direct tail probes
!> \param base_quality trace/mixed Direct quality before selected-history evidence
!> \param selected_quality measured/predicted quality from accepted selected probes
!> \param samples number of selected Direct accepted samples
!> \param min_samples minimum samples before selected history contributes
!> \return maturity-blended Direct quality without the promotion-quality floor
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_selected_probe_quality(base_quality, selected_quality, samples, min_samples) &
         RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: base_quality, selected_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: quality

      INTEGER                                            :: maturity_samples
      REAL(KIND=dp)                                      :: maturity, selected_quality_clipped

         quality = base_quality
         IF (samples < min_samples) RETURN

         selected_quality_clipped = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                                                    selected_quality))
         maturity_samples = MAX(1, 2*ot_kp_schur_projector_response_min_samples - min_samples + 1)
         maturity = REAL(MAX(0, samples - min_samples + 1), KIND=dp)/REAL(maturity_samples, KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))

         quality = (1.0_dp - maturity)*base_quality + maturity*selected_quality_clipped
         quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, quality))

      END FUNCTION kpoint_ot_direct_selected_probe_quality

! **************************************************************************************************
!> \brief apply selected Direct history after floor/bootstrap quality calibration
!> \param floor_quality calibrated bootstrap quality from a floor-density response
!> \param selected_quality accepted selected-Direct Mermin-drop quality
!> \param samples number of accepted selected-Direct samples
!> \param min_samples minimum samples before selected history contributes
!> \return floor-calibrated quality consistent with accepted selected history
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_floor_selected_quality(floor_quality, selected_quality, samples, min_samples) &
         RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: floor_quality, selected_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: quality

         quality = floor_quality
         quality = kpoint_ot_direct_selected_probe_quality(quality, selected_quality, samples, min_samples)

      END FUNCTION kpoint_ot_direct_floor_selected_quality

! **************************************************************************************************
!> \brief tiny floor-density bootstrap before selected density-response history exists
!> \param residual_delta current OT residual
!> \param mermin_quality_ema accepted Mermin line-search quality EMA
!> \param mermin_samples accepted Mermin line-search quality samples
!> \param floor_abs_avg floor-audit source magnitude
!> \param floor_exact_abs_avg exact floor-response magnitude
!> \param floor_low_curv_fraction low-curvature contribution to the floor model
!> \param projected_abs_avg projected physical density source magnitude
!> \return conservative floor-density Direct blend weight
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_floor_density_bootstrap_weight(residual_delta, mermin_quality_ema, &
                                                               mermin_samples, floor_abs_avg, &
                                                               floor_exact_abs_avg, floor_low_curv_fraction, &
                                                               projected_abs_avg) RESULT(weight)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, mermin_quality_ema, &
                                                            floor_abs_avg, floor_exact_abs_avg, &
                                                            floor_low_curv_fraction, projected_abs_avg
      INTEGER, INTENT(IN)                                :: mermin_samples
      REAL(KIND=dp)                                      :: weight

      REAL(KIND=dp)                                      :: low_curv_quality, source_limit

         weight = 0.0_dp
         IF (residual_delta > ot_kp_schur_projector_response_full_delta) RETURN
         IF (mermin_samples < ot_kp_schur_calibration_min_samples) RETURN
         IF (mermin_quality_ema < ot_kp_schur_projector_density_floor_bootstrap_mermin_min) RETURN
         IF (floor_abs_avg <= EPSILON(floor_abs_avg)) RETURN
         IF (floor_exact_abs_avg <= EPSILON(floor_exact_abs_avg)) RETURN
         IF (floor_low_curv_fraction > ot_kp_schur_projector_density_floor_bootstrap_lowcurv_max) RETURN
         source_limit = MAX(1.0E1_dp*floor_exact_abs_avg, 1.0E-1_dp*floor_abs_avg)
         IF (projected_abs_avg > source_limit) RETURN

         low_curv_quality = 1.0_dp - &
                            floor_low_curv_fraction/ot_kp_schur_projector_density_floor_bootstrap_lowcurv_max
         low_curv_quality = MAX(0.0_dp, MIN(1.0_dp, low_curv_quality))
         weight = ot_kp_schur_projector_density_floor_bootstrap_weight* &
                  MIN(1.0_dp, mermin_quality_ema)*low_curv_quality
         weight = MIN(0.5_dp*ot_kp_schur_projector_trace_active_max_weight, &
                      MAX(0.0_dp, weight))

      END FUNCTION kpoint_ot_direct_floor_density_bootstrap_weight

! **************************************************************************************************
!> \brief trust-safe tail probe for calibrated full-density response candidates
!> \param residual_delta current OT residual
!> \param candidate_expected_drop calibrated candidate Mermin drop
!> \param recent_quality most recent accepted shadow-history Mermin quality
!> \param ema_quality accepted shadow-history Mermin quality EMA
!> \param samples number of accepted shadow-history samples
!> \param weighted_trust_ratio curvature-weighted response trust ratio
!> \param abs_trust_ratio absolute response trust ratio
!> \return true if a mature, low-residual full-density response may collect selected history
! **************************************************************************************************
      FUNCTION kpoint_ot_density_full_tail_probe_ready(residual_delta, candidate_expected_drop, &
                                                       recent_quality, ema_quality, samples, &
                                                       weighted_trust_ratio, abs_trust_ratio) &
         RESULT(probe_ready)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, candidate_expected_drop, &
                                                            recent_quality, ema_quality
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: weighted_trust_ratio, abs_trust_ratio
      LOGICAL                                            :: probe_ready

         probe_ready = .FALSE.
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (candidate_expected_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN
         IF (ema_quality < 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN
         IF (recent_quality < 0.25_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN
         IF (weighted_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN
         IF (abs_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN

         probe_ready = .TRUE.

      END FUNCTION kpoint_ot_density_full_tail_probe_ready

! **************************************************************************************************
!> \brief residual-tail cap from the latest selected residual quality and its EMA
!> \param selected_residual_quality latest selected-step residual quality
!> \param selected_residual_quality_ema EMA of selected-step residual quality
!> \return smooth quality cap for residual-tail selected-history use
! **************************************************************************************************
      FUNCTION kpoint_ot_selected_tail_residual_quality(selected_residual_quality, &
                                                        selected_residual_quality_ema) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: selected_residual_quality, &
                                                            selected_residual_quality_ema
      REAL(KIND=dp)                                      :: quality

         quality = MAX(0.0_dp, MIN(1.0_dp, selected_residual_quality_ema))
         quality = quality* &
                   SQRT(MAX(0.0_dp, MIN(1.0_dp, selected_residual_quality/ &
                                        MAX(ot_kp_schur_calibrated_quality_min_ratio, &
                                            EPSILON(1.0_dp)))))

      END FUNCTION kpoint_ot_selected_tail_residual_quality

! **************************************************************************************************
!> \brief EMA-stabilized residual quality for non-promoting active-Hessian tail mix
!> \param selected_residual_quality latest selected-step residual quality
!> \param selected_residual_quality_ema EMA of selected-step residual quality
!> \return residual-quality factor for tiny Direct-density active-Hessian mix
! **************************************************************************************************
      FUNCTION kpoint_ot_selected_tail_mix_residual_quality(selected_residual_quality, &
                                                            selected_residual_quality_ema) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: selected_residual_quality, &
                                                            selected_residual_quality_ema
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: recent_quality

         quality = MAX(0.0_dp, MIN(1.0_dp, selected_residual_quality_ema))
         IF (quality <= EPSILON(quality)) RETURN

         IF (selected_residual_quality > EPSILON(selected_residual_quality)) THEN
            recent_quality = SQRT(MAX(0.0_dp, MIN(1.0_dp, selected_residual_quality/ &
                                                  MAX(ot_kp_schur_calibrated_quality_min_ratio, &
                                                      EPSILON(1.0_dp)))))
            quality = SQRT(quality*recent_quality)
         ELSE
            quality = 0.5_dp*quality
         END IF
         quality = MAX(0.0_dp, MIN(1.0_dp, quality))

      END FUNCTION kpoint_ot_selected_tail_mix_residual_quality

! **************************************************************************************************
!> \brief accepted-history calibrated floor-source mix for global full-density response
!> \param residual_delta current OT residual
!> \param selected_quality latest selected global Mermin measured/predicted quality
!> \param selected_quality_ema EMA of selected global Mermin measured/predicted quality
!> \param selected_residual_quality latest selected global residual quality
!> \param selected_residual_quality_ema EMA of selected global residual quality
!> \param selected_samples number of accepted selected global samples
!> \return tiny source weight for the floor-limited finite-projector density response
! **************************************************************************************************
      FUNCTION kpoint_ot_density_full_global_floor_source_weight(residual_delta, selected_quality, &
                                                                 selected_quality_ema, &
                                                                 selected_residual_quality, &
                                                                 selected_residual_quality_ema, &
                                                                 selected_samples) RESULT(weight)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, selected_quality, &
                                                            selected_quality_ema, selected_residual_quality, &
                                                            selected_residual_quality_ema
      INTEGER, INTENT(IN)                                :: selected_samples
      REAL(KIND=dp)                                      :: weight

      INTEGER                                            :: maturity_samples
      REAL(KIND=dp)                                      :: mermin_ref, maturity, recent_quality, &
                                                            residual_support, underprediction_weight

         weight = 0.0_dp
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (selected_samples < ot_kp_schur_calibration_min_samples) RETURN
         IF (selected_quality_ema <= 1.0_dp) RETURN

         mermin_ref = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                                      selected_quality_ema))
         IF (selected_quality > EPSILON(selected_quality)) THEN
            recent_quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                                             selected_quality))
            IF (recent_quality < 1.0_dp) THEN
               mermin_ref = MIN(mermin_ref, SQRT(recent_quality))
            ELSE
               mermin_ref = MIN(mermin_ref, recent_quality)
            END IF
         END IF
         IF (mermin_ref <= 1.0_dp) RETURN

         residual_support = kpoint_ot_selected_tail_mix_residual_quality(selected_residual_quality, &
                                                                         selected_residual_quality_ema)
         IF (residual_support <= EPSILON(residual_support)) RETURN

         maturity_samples = MAX(1, 2*ot_kp_schur_projector_response_min_samples - &
                                   ot_kp_schur_calibration_min_samples + 1)
         maturity = REAL(MAX(0, selected_samples - ot_kp_schur_calibration_min_samples + 1), KIND=dp)/ &
                    REAL(maturity_samples, KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))
         underprediction_weight = (mermin_ref - 1.0_dp)/ &
                                  MAX(ot_kp_schur_projector_response_quality_max_ratio - 1.0_dp, &
                                      EPSILON(1.0_dp))
         underprediction_weight = MAX(0.0_dp, MIN(1.0_dp, underprediction_weight))

         weight = ot_kp_schur_projector_density_global_floor_max_weight* &
                  maturity*underprediction_weight*SQRT(MAX(0.0_dp, MIN(1.0_dp, residual_support)))
         weight = MAX(0.0_dp, MIN(ot_kp_schur_projector_density_global_floor_max_weight, weight))

      END FUNCTION kpoint_ot_density_full_global_floor_source_weight

! **************************************************************************************************
!> \brief residual-aware active-Hessian mix from accepted Direct-density tail history
!> \param residual_delta current OT residual
!> \param selected_mermin_quality accepted selected-step Mermin-drop quality
!> \param selected_residual_quality accepted selected-step residual quality cap
!> \param selected_samples number of accepted selected Direct-density samples
!> \return bounded active Direct-Hessian mix weight for the residual tail
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_density_selected_mix_weight(residual_delta, selected_mermin_quality, &
                                                            selected_residual_quality, selected_samples) &
         RESULT(weight)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, selected_mermin_quality, &
                                                            selected_residual_quality
      INTEGER, INTENT(IN)                                :: selected_samples
      REAL(KIND=dp)                                      :: weight

      INTEGER                                            :: maturity_samples
      REAL(KIND=dp)                                      :: maturity, mermin_weight, residual_weight

         weight = 0.0_dp
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (selected_samples < ot_kp_schur_calibration_min_samples) RETURN
         IF (selected_mermin_quality < 0.25_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN
         IF (selected_residual_quality <= EPSILON(selected_residual_quality)) RETURN

         maturity_samples = MAX(1, 2*ot_kp_schur_projector_response_min_samples - &
                                   ot_kp_schur_calibration_min_samples + 1)
         maturity = REAL(MAX(0, selected_samples - ot_kp_schur_calibration_min_samples + 1), KIND=dp)/ &
                    REAL(maturity_samples, KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))

         mermin_weight = SQRT(MIN(1.0_dp, MAX(0.0_dp, selected_mermin_quality)))
         residual_weight = SQRT(MIN(1.0_dp, MAX(0.0_dp, selected_residual_quality)))
         weight = 0.25_dp*ot_kp_schur_projector_trace_active_max_weight* &
                  maturity*mermin_weight*residual_weight
         weight = MIN(0.25_dp*ot_kp_schur_projector_trace_active_max_weight, &
                      MAX(0.0_dp, weight))

      END FUNCTION kpoint_ot_direct_density_selected_mix_weight

! **************************************************************************************************
!> \brief whether the dense metric-response scale may bridge a residual-tail fallback
!> \param residual_delta current OT residual
!> \param coupled_quality latest coupled Mermin-drop quality
!> \param coupled_quality_ema EMA of coupled Mermin-drop quality
!> \param coupled_samples number of coupled calibration samples
!> \param dense_residual_quality coupled residual quality relative to the active reference
!> \param mermin_quality_ema accepted-state Mermin line-search quality EMA
!> \param mermin_samples number of accepted-state Mermin line-search samples
!> \return true if the metric-response scale is mature enough for fallback handoff
! **************************************************************************************************
      FUNCTION kpoint_ot_dense_metric_tail_bridge_ready(residual_delta, coupled_quality, &
                                                        coupled_quality_ema, coupled_samples, &
                                                        dense_residual_quality, mermin_quality_ema, &
                                                        mermin_samples) RESULT(bridge_ready)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, coupled_quality, &
                                                            coupled_quality_ema
      INTEGER, INTENT(IN)                                :: coupled_samples
      REAL(KIND=dp), INTENT(IN)                          :: dense_residual_quality, &
                                                            mermin_quality_ema
      INTEGER, INTENT(IN)                                :: mermin_samples
      LOGICAL                                            :: bridge_ready

         bridge_ready = .FALSE.
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (coupled_samples < ot_kp_schur_calibration_min_samples) RETURN
         IF (mermin_samples < ot_kp_schur_calibration_min_samples) RETURN
         IF (coupled_quality < 0.5_dp*ot_kp_schur_quality_min_ratio) RETURN
         IF (coupled_quality_ema < 0.75_dp*ot_kp_schur_quality_min_ratio) RETURN
         IF (dense_residual_quality < ot_kp_schur_calibrated_quality_min_ratio) RETURN
         IF (mermin_quality_ema < 0.8_dp) RETURN

         bridge_ready = .TRUE.

      END FUNCTION kpoint_ot_dense_metric_tail_bridge_ready

! **************************************************************************************************
!> \brief whether a mature full-density response candidate may collect selected tail history
!> \param probe_ready prechecked residual, trust, and shadow-history quality gate
!> \param candidate_expected_drop calibrated candidate Mermin drop
!> \param reference_expected_drop currently selected dense-coupled expected drop
!> \param selected_residual_quality latest residual quality of already selected probes
!> \param selected_residual_quality_ema residual quality of already selected probes
!> \param selected_samples number of already selected full-density probes
!> \param dense_residual_quality residual quality of the dense-coupled baseline
!> \return true if this is a calibrated residual-tail close call
! **************************************************************************************************
      FUNCTION kpoint_ot_density_full_tail_selection_probe(probe_ready, candidate_expected_drop, &
                                                           reference_expected_drop, &
                                                           selected_residual_quality, &
                                                           selected_residual_quality_ema, selected_samples, &
                                                           dense_residual_quality) RESULT(do_probe)
      LOGICAL, INTENT(IN)                                :: probe_ready
      REAL(KIND=dp), INTENT(IN) :: candidate_expected_drop, reference_expected_drop, &
         selected_residual_quality, selected_residual_quality_ema
      INTEGER, INTENT(IN)                                :: selected_samples
      REAL(KIND=dp), INTENT(IN)                          :: dense_residual_quality
      LOGICAL                                            :: do_probe

         do_probe = .FALSE.
         IF (.NOT. probe_ready) RETURN
         IF (candidate_expected_drop < ot_kp_schur_projector_density_fdir_probe_ratio* &
             MAX(reference_expected_drop, ot_kp_schur_projector_density_full_min_drop)) RETURN

         IF (selected_samples >= ot_kp_schur_calibration_min_samples) THEN
            IF (selected_residual_quality_ema < &
                ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)) RETURN
            IF (selected_residual_quality < &
                0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)) RETURN
         END IF

         do_probe = .TRUE.

      END FUNCTION kpoint_ot_density_full_tail_selection_probe

! **************************************************************************************************
!> \brief residual-tail preference for global full-density response probes
!> \param residual_delta current OT residual
!> \param bootstrap_ready new-search bootstrap from the accepted Mermin model
!> \param probe_ready mature shadow-history probe gate
!> \param candidate_expected_drop calibrated global full-density Mermin drop
!> \param reference_expected_drop currently selected reference Mermin drop
!> \param history_quality latest global shadow Mermin quality
!> \param history_quality_ema global shadow Mermin quality EMA
!> \param history_samples number of global shadow samples
!> \param selected_quality latest selected global Mermin quality
!> \param selected_quality_ema selected global Mermin quality EMA
!> \param selected_residual_quality latest selected global residual quality
!> \param selected_residual_quality_ema selected global residual quality EMA
!> \param selected_samples number of selected global samples
!> \param direct_selected whether Direct-density already owns this attempt
!> \param direct_residual_bad precomputed Direct-density residual weakness
!> \param direct_residual_quality latest Direct-density selected residual quality
!> \param direct_residual_quality_ema Direct-density selected residual quality EMA
!> \param direct_samples number of selected Direct-density samples
!> \param dense_residual_quality residual quality of the dense-coupled baseline
!> \return true if a global full-density probe should break the Direct-density tail deadlock
! **************************************************************************************************
      FUNCTION kpoint_ot_density_full_global_tail_prefer(residual_delta, bootstrap_ready, probe_ready, &
                                                         candidate_expected_drop, reference_expected_drop, &
                                                         history_quality, history_quality_ema, history_samples, &
                                                         selected_quality, selected_quality_ema, &
                                                         selected_residual_quality, &
                                                         selected_residual_quality_ema, selected_samples, &
                                                         direct_selected, direct_residual_bad, &
                                                         direct_residual_quality, &
                                                         direct_residual_quality_ema, direct_samples, &
                                                         dense_residual_quality) RESULT(prefer)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, candidate_expected_drop, &
                                                            reference_expected_drop, history_quality, &
                                                            history_quality_ema, selected_quality, &
                                                            selected_quality_ema, selected_residual_quality, &
                                                            selected_residual_quality_ema, &
                                                            direct_residual_quality, &
                                                            direct_residual_quality_ema, dense_residual_quality
      INTEGER, INTENT(IN)                                :: history_samples, selected_samples, direct_samples
      LOGICAL, INTENT(IN)                                :: bootstrap_ready, probe_ready, direct_selected, &
                                                            direct_residual_bad
      LOGICAL                                            :: prefer

      LOGICAL                                            :: direct_weak, global_mature, global_selected_mature
      REAL(KIND=dp)                                      :: drop_ratio, residual_reference

         prefer = .FALSE.
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (candidate_expected_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN

         global_mature = probe_ready .OR. bootstrap_ready
         IF (history_samples > 0) &
            global_mature = global_mature .OR. &
                            (history_quality_ema >= ot_kp_schur_projector_response_quality_min_ratio .AND. &
                             history_quality >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio)
         global_selected_mature = selected_samples > 0 .AND. &
                                  selected_quality_ema >= &
                                  ot_kp_schur_projector_response_quality_min_ratio .AND. &
                                  selected_quality >= &
                                  0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
         global_mature = global_mature .OR. global_selected_mature
         IF (.NOT. global_mature) RETURN

         drop_ratio = ot_kp_schur_projector_density_fdir_probe_ratio
         IF (history_samples < ot_kp_schur_projector_response_min_samples .OR. &
             selected_samples < ot_kp_schur_calibration_min_samples) &
            drop_ratio = ot_kp_schur_projector_density_fdir_refresh_ratio
         IF (candidate_expected_drop < drop_ratio* &
             MAX(reference_expected_drop, ot_kp_schur_projector_density_full_min_drop)) RETURN

         residual_reference = MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)
         IF (selected_samples >= ot_kp_schur_calibration_min_samples) THEN
            IF (selected_residual_quality_ema < &
                0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference) RETURN
            IF (selected_residual_quality < &
                0.25_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference) RETURN
         END IF

         direct_weak = .TRUE.
         IF (direct_selected) THEN
            direct_weak = direct_residual_bad .OR. &
                          direct_samples < ot_kp_schur_calibration_min_samples
            IF (direct_samples >= ot_kp_schur_calibration_min_samples) THEN
               direct_weak = direct_weak .OR. &
                             direct_residual_quality_ema < &
                             ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                             residual_reference .OR. &
                             direct_residual_quality < &
                             0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                             residual_reference
            END IF
         END IF
         IF (.NOT. direct_weak) RETURN

         prefer = .TRUE.

      END FUNCTION kpoint_ot_density_full_global_tail_prefer

! **************************************************************************************************
!> \brief periodic refresh probe for stale full-density selected residual history
!> \param probe_ready prechecked residual, trust, and shadow-history quality gate
!> \param candidate_expected_drop residual-capped candidate Mermin drop
!> \param reference_expected_drop currently selected dense-coupled expected drop
!> \param history_samples number of full-density shadow samples
!> \param selected_residual_quality_ema residual-quality EMA of selected probes
!> \param dense_residual_quality residual quality of the dense-coupled baseline
!> \return true if a stale selected residual cap may be refreshed by one probe
! **************************************************************************************************
      FUNCTION kpoint_ot_density_full_tail_refresh_probe(probe_ready, candidate_expected_drop, &
                                                         reference_expected_drop, history_samples, &
                                                         selected_residual_quality_ema, &
                                                         dense_residual_quality) RESULT(do_probe)
      LOGICAL, INTENT(IN)                                :: probe_ready
      REAL(KIND=dp), INTENT(IN)                          :: candidate_expected_drop, &
                                                            reference_expected_drop, &
                                                            selected_residual_quality_ema, &
                                                            dense_residual_quality
      INTEGER, INTENT(IN)                                :: history_samples
      LOGICAL                                            :: do_probe

      REAL(KIND=dp)                                      :: probe_expected_drop

         do_probe = .FALSE.
         IF (.NOT. probe_ready) RETURN
         IF (history_samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (MOD(history_samples, MAX(1, 2*ot_kp_schur_calibration_min_samples)) /= 0) RETURN
         IF (dense_residual_quality < ot_kp_schur_calibrated_quality_min_ratio) RETURN
         IF (selected_residual_quality_ema <= EPSILON(selected_residual_quality_ema)) RETURN
         IF (selected_residual_quality_ema >= &
             ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
             MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)) RETURN

         probe_expected_drop = candidate_expected_drop/ &
                               MAX(selected_residual_quality_ema, EPSILON(selected_residual_quality_ema))
         IF (probe_expected_drop < ot_kp_schur_projector_density_fdir_refresh_ratio* &
             MAX(reference_expected_drop, ot_kp_schur_projector_density_full_min_drop)) RETURN

         do_probe = .TRUE.

      END FUNCTION kpoint_ot_density_full_tail_refresh_probe

! **************************************************************************************************
!> \brief trust-safe Direct-density drop used only for residual-tail probe selection
!> \param residual_delta current OT residual
!> \param capped_expected_drop residual-quality capped candidate drop
!> \param shadow_expected_drop Mermin-history calibrated shadow drop
!> \param weighted_trust_ratio weighted response trust ratio
!> \param abs_trust_ratio absolute response trust ratio
!> \return candidate drop visible to close-call tail probes, never to normal promotion
! **************************************************************************************************
      FUNCTION kpoint_ot_density_full_direct_probe_drop(residual_delta, capped_expected_drop, &
                                                        shadow_expected_drop, weighted_trust_ratio, &
                                                        abs_trust_ratio) RESULT(probe_drop)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, capped_expected_drop, &
                                                            shadow_expected_drop, &
                                                            weighted_trust_ratio, abs_trust_ratio
      REAL(KIND=dp)                                      :: probe_drop

         probe_drop = MAX(0.0_dp, capped_expected_drop)
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (shadow_expected_drop <= probe_drop) RETURN
         IF (shadow_expected_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN
         IF (weighted_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN
         IF (abs_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN

         probe_drop = shadow_expected_drop

      END FUNCTION kpoint_ot_density_full_direct_probe_drop

! **************************************************************************************************
!> \brief whether a full-density Direct candidate may collect tail line-search history
!> \param residual_delta current OT residual
!> \param candidate_expected_drop calibrated candidate Mermin drop
!> \param reference_expected_drop currently selected dense-coupled expected drop
!> \param quality_ema accepted shadow-history Mermin quality
!> \param samples number of accepted shadow-history samples
!> \param selected_residual_quality latest residual quality of already selected Direct probes
!> \param selected_residual_quality_ema residual quality of already selected Direct probes
!> \param selected_samples number of selected Direct probes
!> \param dense_residual_quality residual quality of the dense-coupled baseline
!> \return true if the candidate is a calibrated residual-tail close call
! **************************************************************************************************
      FUNCTION kpoint_ot_density_full_direct_tail_probe(residual_delta, candidate_expected_drop, &
                                                        reference_expected_drop, quality_ema, samples, &
                                                        selected_residual_quality, &
                                                        selected_residual_quality_ema, selected_samples, &
                                                        dense_residual_quality) RESULT(do_probe)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, candidate_expected_drop, &
                                                            reference_expected_drop, quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: selected_residual_quality, &
                                                            selected_residual_quality_ema
      INTEGER, INTENT(IN)                                :: selected_samples
      REAL(KIND=dp), INTENT(IN)                          :: dense_residual_quality
      LOGICAL                                            :: do_probe

      LOGICAL                                            :: stale_residual_probe
      REAL(KIND=dp)                                      :: required_drop_ratio

         do_probe = .FALSE.
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (quality_ema < ot_kp_schur_projector_response_quality_min_ratio) RETURN
         IF (candidate_expected_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN

         stale_residual_probe = .FALSE.
         IF (selected_samples >= ot_kp_schur_calibration_min_samples) THEN
            stale_residual_probe = &
               dense_residual_quality <= 2.0_dp*ot_kp_schur_calibrated_quality_min_ratio .AND. &
               selected_residual_quality_ema < ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
               MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio) .AND. &
               quality_ema >= 2.0_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
               MOD(samples, MAX(1, 2*ot_kp_schur_calibration_min_samples)) == 0
         END IF

         required_drop_ratio = ot_kp_schur_projector_density_fdir_probe_ratio
         IF (stale_residual_probe) &
            required_drop_ratio = MIN(required_drop_ratio, &
                                      ot_kp_schur_projector_density_fdir_refresh_ratio)
         IF (candidate_expected_drop < required_drop_ratio* &
             MAX(reference_expected_drop, ot_kp_schur_projector_density_full_min_drop)) RETURN

         IF (selected_samples >= ot_kp_schur_calibration_min_samples) THEN
            IF (.NOT. stale_residual_probe) THEN
               IF (selected_residual_quality_ema < &
                   ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                   MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)) RETURN
               IF (selected_residual_quality < &
                   0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                   MAX(dense_residual_quality, ot_kp_schur_calibrated_quality_min_ratio)) RETURN
            END IF
         END IF

         do_probe = .TRUE.

      END FUNCTION kpoint_ot_density_full_direct_tail_probe

! **************************************************************************************************
!> \brief whether a fixed-N density-descent response may collect residual-tail history
!> \param residual_delta current OT residual
!> \param candidate_expected_drop calibrated candidate Mermin drop
!> \param reference_expected_drop currently selected dense-coupled expected drop
!> \param quality_for_selection accepted-drop quality used for the density-descent candidate
!> \param gap_recoverable_fraction fraction of the full-density gap recovered by fixed-N projection
!> \param weighted_trust_ratio curvature-weighted response trust ratio
!> \param abs_trust_ratio absolute response trust ratio
!> \param selected_residual_quality latest residual quality of already selected probes
!> \param selected_residual_quality_ema residual-quality EMA of already selected probes
!> \param selected_samples number of already selected density-descent probes
!> \param dense_residual_quality residual quality of the dense-coupled baseline
!> \return true if the physical density-gap response is a trust-safe residual-tail close call
! **************************************************************************************************
      FUNCTION kpoint_ot_density_descent_tail_probe(residual_delta, candidate_expected_drop, &
                                                    reference_expected_drop, quality_for_selection, &
                                                    gap_recoverable_fraction, weighted_trust_ratio, &
                                                    abs_trust_ratio, selected_residual_quality, &
                                                    selected_residual_quality_ema, selected_samples, &
                                                    dense_residual_quality) RESULT(do_probe)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, candidate_expected_drop, &
                                                            reference_expected_drop, quality_for_selection, &
                                                            gap_recoverable_fraction, weighted_trust_ratio, &
                                                            abs_trust_ratio, selected_residual_quality, &
                                                            selected_residual_quality_ema
      INTEGER, INTENT(IN)                                :: selected_samples
      REAL(KIND=dp), INTENT(IN)                          :: dense_residual_quality
      LOGICAL                                            :: do_probe

      REAL(KIND=dp)                                      :: residual_reference

         do_probe = .FALSE.
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (quality_for_selection < 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN
         IF (gap_recoverable_fraction < 0.5_dp) RETURN
         IF (candidate_expected_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN
         IF (candidate_expected_drop < ot_kp_schur_projector_density_fdir_probe_ratio* &
             MAX(reference_expected_drop, ot_kp_schur_projector_density_full_min_drop)) RETURN
         IF (weighted_trust_ratio > 1.0_dp) RETURN
         IF (abs_trust_ratio > 1.0_dp) RETURN

         IF (selected_samples >= ot_kp_schur_calibration_min_samples) THEN
            residual_reference = MAX(dense_residual_quality, &
                                     ot_kp_schur_calibrated_quality_min_ratio)
            IF (selected_residual_quality_ema < &
                ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference) RETURN
            IF (selected_residual_quality < &
                0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference) RETURN
         END IF

         do_probe = .TRUE.

      END FUNCTION kpoint_ot_density_descent_tail_probe

! **************************************************************************************************
!> \brief recent accepted-drop cap for floor/bootstrap Direct-density quality
!> \param history_quality aggregate accepted-drop quality
!> \param recent_quality most recent accepted-drop quality
!> \param ema_quality exponential moving average accepted-drop quality
!> \param samples number of accepted floor/bootstrap samples
!> \param min_samples minimum samples before recent quality contributes
!> \return aggregate quality capped by recent/EMA Mermin-drop consistency
! **************************************************************************************************
      FUNCTION kpoint_ot_floor_bootstrap_history_quality(history_quality, recent_quality, ema_quality, &
                                                         samples, min_samples) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: history_quality, recent_quality, &
                                                            ema_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: recent_cap, recent_clipped, recent_ref

         quality = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, history_quality))
         IF (samples < min_samples) RETURN

         recent_clipped = MAX(0.0_dp, MIN(ot_kp_schur_projector_response_quality_max_ratio, recent_quality))
         IF (recent_clipped <= EPSILON(recent_clipped)) RETURN

         recent_ref = quality
         IF (ema_quality > EPSILON(ema_quality)) &
            recent_ref = MIN(recent_ref, MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                                             MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                                                 ema_quality)))
         recent_cap = SQRT(recent_clipped*MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                                              recent_ref))
         recent_cap = MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                          MIN(ot_kp_schur_projector_response_quality_max_ratio, recent_cap))
         quality = MIN(quality, recent_cap)

      END FUNCTION kpoint_ot_floor_bootstrap_history_quality

! **************************************************************************************************
!> \brief ...
!> \param history_quality ...
!> \param samples ...
!> \param min_samples ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_history_step_scale(history_quality, samples, min_samples) RESULT(step_scale)
      REAL(KIND=dp), INTENT(IN)                          :: history_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: step_scale

      INTEGER                                            :: maturity_samples
      REAL(KIND=dp)                                      :: clipped_quality, maturity, target_scale

         clipped_quality = MIN(1.0_dp, MAX(ot_kp_schur_calibration_floor, &
                                           history_quality))
         target_scale = SQRT(clipped_quality)
         maturity_samples = MAX(1, 2*ot_kp_schur_projector_response_min_samples - min_samples + 1)
         maturity = REAL(MAX(0, samples - min_samples + 1), KIND=dp)/ &
                    REAL(maturity_samples, KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))
         step_scale = 1.0_dp - maturity*(1.0_dp - target_scale)

      END FUNCTION kpoint_ot_direct_history_step_scale

! **************************************************************************************************
!> \brief accepted-drop growth for repeatedly underpredicted Direct candidates
!> \param history_quality ...
!> \param samples ...
!> \param min_samples ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_history_growth_scale(history_quality, samples, min_samples) RESULT(step_scale)
      REAL(KIND=dp), INTENT(IN)                          :: history_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: step_scale

      INTEGER                                            :: maturity_samples
      REAL(KIND=dp)                                      :: clipped_quality, maturity, target_scale

         step_scale = 1.0_dp
         IF (samples < min_samples) RETURN

         clipped_quality = MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                               MAX(1.0_dp, history_quality))
         target_scale = SQRT(clipped_quality)
         maturity_samples = MAX(1, 2*ot_kp_schur_projector_response_min_samples - min_samples + 1)
         maturity = REAL(MAX(0, samples - min_samples + 1), KIND=dp)/ &
                    REAL(maturity_samples, KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))
         step_scale = 1.0_dp + maturity*(target_scale - 1.0_dp)

      END FUNCTION kpoint_ot_direct_history_growth_scale

! **************************************************************************************************
!> \brief accepted-drop growth for the density-descent response candidate
!> \param history_quality accepted density-descent measured/predicted Mermin-drop quality
!> \param support_quality bounded support quality for the same accepted history
!> \param samples number of accepted density-descent shadow samples
!> \param min_samples minimum samples for a mature response history
!> \return maturity-limited scale for repeatedly underpredicted density-descent drops
! **************************************************************************************************
      FUNCTION kpoint_ot_density_descent_history_growth_scale(history_quality, support_quality, &
                                                              samples, min_samples) RESULT(step_scale)
      REAL(KIND=dp), INTENT(IN)                          :: history_quality, support_quality
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp)                                      :: step_scale

      REAL(KIND=dp)                                      :: maturity, target_scale

         step_scale = 1.0_dp
         IF (samples <= 0) RETURN
         IF (support_quality < ot_kp_schur_projector_response_quality_min_ratio) RETURN

         target_scale = MIN(ot_kp_schur_density_descent_history_max_scale, &
                            SQRT(MAX(1.0_dp, history_quality)))
         maturity = REAL(MIN(samples, MAX(1, min_samples)), KIND=dp)/ &
                    REAL(MAX(1, min_samples), KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))
         step_scale = 1.0_dp + maturity*(target_scale - 1.0_dp)

      END FUNCTION kpoint_ot_density_descent_history_growth_scale

! **************************************************************************************************
!> \brief consistency scaling for accepted mixed-Direct history
!> \param drop_ratio ...
!> \param ema_quality ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_direct_history_consistency_scale(drop_ratio, ema_quality) RESULT(consistency_scale)
      REAL(KIND=dp), INTENT(IN)                          :: drop_ratio, ema_quality
      REAL(KIND=dp)                                      :: consistency_scale

         consistency_scale = 1.0_dp
         IF (drop_ratio > ot_kp_schur_projector_response_quality_max_ratio) &
            consistency_scale = MIN(consistency_scale, &
                                    SQRT(ot_kp_schur_projector_response_quality_max_ratio/drop_ratio))
         IF (ema_quality > ot_kp_schur_projector_response_quality_max_ratio) &
            consistency_scale = MIN(consistency_scale, &
                                    SQRT(ot_kp_schur_projector_response_quality_max_ratio/ema_quality))

      END FUNCTION kpoint_ot_direct_history_consistency_scale

! **************************************************************************************************
!> \brief accepted-history promotion for mixed active/physical Direct curvature
!> \param samples ...
!> \param min_samples ...
!> \param drop_ratio accepted measured/predicted sum ratio
!> \param history_quality accepted-history quality used for candidate scaling
!> \param ema_quality recent accepted-history quality
!> \param selected_quality accepted-drop quality of actually selected Direct steps
!> \param selected_samples number of actually selected Direct samples
!> \return true if shadow and selected-Direct evidence are mature enough for production use
! **************************************************************************************************
      FUNCTION kpoint_ot_mixed_direct_promoted(samples, min_samples, drop_ratio, history_quality, &
                                               ema_quality, selected_quality, selected_samples) RESULT(promoted)
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp), INTENT(IN)                          :: drop_ratio, history_quality, &
                                                            ema_quality, selected_quality
      INTEGER, INTENT(IN)                                :: selected_samples
      LOGICAL                                            :: promoted

      INTEGER                                            :: promotion_samples, selected_promotion_samples, &
                                                            shadow_promotion_samples
      LOGICAL                                            :: selected_promoted, shadow_promoted

         promotion_samples = MAX(min_samples, 5*min_samples)
         selected_promotion_samples = MAX(min_samples, 3*min_samples)
         shadow_promotion_samples = MAX(promotion_samples, 10*min_samples)
         selected_promoted = samples >= selected_promotion_samples .AND. &
                             drop_ratio >= ot_kp_schur_projector_response_quality_min_ratio .AND. &
                             history_quality >= ot_kp_schur_projector_response_quality_min_ratio .AND. &
                             ema_quality >= 0.9_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
                             selected_samples >= min_samples .AND. &
                             selected_quality >= ot_kp_schur_projector_response_quality_min_ratio
         shadow_promoted = samples >= shadow_promotion_samples .AND. &
                           drop_ratio >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
                           history_quality >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
                           ema_quality >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
         promoted = selected_promoted .OR. shadow_promoted

      END FUNCTION kpoint_ot_mixed_direct_promoted

! **************************************************************************************************
!> \brief ...
!> \param weighted_trust_ratio ...
!> \param abs_trust_ratio ...
!> \param gap_trust_ratio ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_schur_trust_quality(weighted_trust_ratio, abs_trust_ratio, &
                                             gap_trust_ratio) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: weighted_trust_ratio, abs_trust_ratio, &
                                                            gap_trust_ratio
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: trust_ratio

         trust_ratio = MAX(1.0_dp, weighted_trust_ratio, abs_trust_ratio, gap_trust_ratio)
         quality = 1.0_dp/trust_ratio

      END FUNCTION kpoint_ot_schur_trust_quality

! **************************************************************************************************
!> \brief accepted-state Mermin branch-loss severity for density-response candidate selection
!> \param accepted_quality accepted/free-energy branch quality EMA
!> \param accepted_gap accepted/free-energy branch gap EMA
!> \param samples number of accepted-state line-search samples
!> \return smooth severity in [0,1]
! **************************************************************************************************
      FUNCTION kpoint_ot_mermin_branch_loss_weight(accepted_quality, accepted_gap, samples) &
         RESULT(weight)
      REAL(KIND=dp), INTENT(IN)                          :: accepted_quality, accepted_gap
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: weight

      REAL(KIND=dp)                                      :: gap, quality

         weight = 0.0_dp
         IF (samples < ot_kp_schur_quality_min_samples) RETURN

         quality = MAX(0.0_dp, MIN(1.0_dp, accepted_quality))
         gap = MAX(0.0_dp, MIN(1.0_dp, accepted_gap))
         weight = SQRT(MAX(0.0_dp, gap*(1.0_dp - quality)))

      END FUNCTION kpoint_ot_mermin_branch_loss_weight

! **************************************************************************************************
!> \brief candidate competition drop including recoverable accepted-state density branch loss
!> \param candidate_drop expected drop of the density-response candidate
!> \param reference_drop current best non-density competition drop
!> \param branch_loss_weight accepted-state Mermin branch-loss severity
!> \return expected competition drop used only for candidate selection
! **************************************************************************************************
      FUNCTION kpoint_ot_branch_loss_density_drop(candidate_drop, reference_drop, branch_loss_weight) &
         RESULT(expected_drop)
      REAL(KIND=dp), INTENT(IN)                          :: candidate_drop, reference_drop, &
                                                            branch_loss_weight
      REAL(KIND=dp)                                      :: expected_drop

         expected_drop = MAX(0.0_dp, candidate_drop)
         IF (expected_drop <= EPSILON(expected_drop)) RETURN

         expected_drop = expected_drop + &
                         ot_kp_schur_branch_loss_density_recovery* &
                         MAX(0.0_dp, MIN(1.0_dp, branch_loss_weight))* &
                         MAX(expected_drop, MAX(0.0_dp, reference_drop))

      END FUNCTION kpoint_ot_branch_loss_density_drop

! **************************************************************************************************
!> \brief ...
!> \param weighted_trust_ratio ...
!> \param gap_trust_ratio ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_schur_metric_trust_quality(weighted_trust_ratio, &
                                                    gap_trust_ratio) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: weighted_trust_ratio, gap_trust_ratio
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: trust_ratio

         trust_ratio = MAX(1.0_dp, weighted_trust_ratio, gap_trust_ratio)
         quality = 1.0_dp/trust_ratio

      END FUNCTION kpoint_ot_schur_metric_trust_quality

! **************************************************************************************************
!> \brief residual quality used for gauge-like tail rotations
!> \param raw_residual_quality unmodified residual-drop ratio
!> \param residual_quality line-search/plateau adjusted residual quality
!> \return strict residual quality for the gauge-step history
! **************************************************************************************************
      FUNCTION kpoint_ot_step_gauge_residual_quality(raw_residual_quality, residual_quality) RESULT(gauge_quality)
      REAL(KIND=dp), INTENT(IN)                          :: raw_residual_quality, residual_quality
      REAL(KIND=dp)                                      :: gauge_quality

         gauge_quality = MIN(MAX(0.0_dp, raw_residual_quality), &
                             MAX(0.0_dp, residual_quality))

      END FUNCTION kpoint_ot_step_gauge_residual_quality

! **************************************************************************************************
!> \brief shadow tail quality from accepted gauge-like rotation content
!> \param gauge_ratio last accepted inactive gauge/gap step-norm ratio
!> \param gauge_ratio_ema smoothed inactive gauge/gap step-norm ratio
!> \param residual_quality last accepted residual-drop quality for those steps
!> \param residual_quality_ema smoothed residual-drop quality for those steps
!> \param samples number of accepted samples in the gauge/gap history
!> \return conservative shadow quality for future coupled tail candidate selection
! **************************************************************************************************
      FUNCTION kpoint_ot_schur_step_gauge_quality(gauge_ratio, gauge_ratio_ema, residual_quality, &
                                                  residual_quality_ema, samples) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: gauge_ratio, gauge_ratio_ema, &
                                                            residual_quality, residual_quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: quality

      REAL(KIND=dp)                                      :: gauge_signal, gauge_weight, &
                                                            residual_signal, residual_weight

         quality = 1.0_dp
         IF (samples < ot_kp_schur_calibration_min_samples) RETURN
         gauge_signal = MAX(0.0_dp, gauge_ratio, gauge_ratio_ema)
         residual_signal = MIN(MAX(0.0_dp, residual_quality), MAX(0.0_dp, residual_quality_ema))
         IF (gauge_signal <= 1.5_dp .OR. residual_signal >= 0.25_dp) RETURN

         gauge_weight = MIN(1.0_dp, &
                            MAX(0.0_dp, (gauge_signal - 1.5_dp)/6.5_dp))
         residual_weight = MIN(1.0_dp, &
                               MAX(0.0_dp, (0.25_dp - residual_signal)/0.25_dp))
         quality = 1.0_dp - 0.65_dp*gauge_weight*residual_weight
         quality = MIN(1.0_dp, MAX(MAX(0.25_dp, ot_kp_schur_calibrated_quality_min_ratio), quality))

      END FUNCTION kpoint_ot_schur_step_gauge_quality

! **************************************************************************************************
!> \brief absolute residual-tail trust for gauge-like offdiag projector response
!> \param response_abs_trust default thermal absolute response trust
!> \param residual_delta current OT residual delta
!> \param sigma electronic smearing width
!> \param step_gauge_quality accepted residual quality of gauge-like tail steps
!> \return absolute trust for the offdiag projector response
! **************************************************************************************************
      FUNCTION kpoint_ot_offdiag_tail_abs_trust(response_abs_trust, residual_delta, sigma, &
                                                step_gauge_quality) RESULT(abs_trust)
      REAL(KIND=dp), INTENT(IN)                          :: response_abs_trust, residual_delta, sigma, &
                                                            step_gauge_quality
      REAL(KIND=dp)                                      :: abs_trust

      REAL(KIND=dp)                                      :: sigma_eff, tail_cap, tail_floor

         abs_trust = response_abs_trust
         IF (response_abs_trust <= EPSILON(response_abs_trust)) RETURN
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (step_gauge_quality >= 0.95_dp) RETURN

         sigma_eff = MAX(sigma, EPSILON(1.0_dp))
         tail_cap = SQRT(MAX(0.0_dp, residual_delta)*sigma_eff)
         tail_floor = 0.5_dp*SQRT(ot_kp_schur_projector_coupled_tail_delta*sigma_eff)
         tail_cap = MAX(tail_cap, tail_floor)
         abs_trust = MIN(response_abs_trust, tail_cap)

      END FUNCTION kpoint_ot_offdiag_tail_abs_trust

! **************************************************************************************************
!> \brief residual-tail floor for gauge-like rotations
!> \param base_floor current rotation floor
!> \param gauge_floor upper gauge floor for nearly equal-occupation pairs
!> \param occ_gap_weight occupation-gap character of this rotation
!> \param step_gauge_quality residual quality of accepted gauge-like steps
!> \return floor raised only for gauge-like rotations with poor residual history
! **************************************************************************************************
      FUNCTION kpoint_ot_residual_gauge_rotation_floor(base_floor, gauge_floor, occ_gap_weight, &
                                                       step_gauge_quality) RESULT(rotation_floor)
      REAL(KIND=dp), INTENT(IN)                          :: base_floor, gauge_floor, occ_gap_weight, &
                                                            step_gauge_quality
      REAL(KIND=dp)                                      :: rotation_floor

      REAL(KIND=dp)                                      :: gap_fraction, residual_weight

         rotation_floor = MAX(0.0_dp, base_floor)
         IF (gauge_floor <= rotation_floor) RETURN

         gap_fraction = 1.0_dp - MIN(1.0_dp, MAX(0.0_dp, occ_gap_weight))
         residual_weight = 1.0_dp - MIN(1.0_dp, MAX(0.0_dp, step_gauge_quality))
         IF (gap_fraction <= EPSILON(gap_fraction) .OR. &
             residual_weight <= EPSILON(residual_weight)) RETURN

         rotation_floor = rotation_floor + &
                          gap_fraction*residual_weight*(gauge_floor - rotation_floor)

      END FUNCTION kpoint_ot_residual_gauge_rotation_floor

! **************************************************************************************************
!> \brief ...
!> \param model_drop ...
!> \param history_quality ...
!> \param trust_quality ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_schur_expected_drop(model_drop, history_quality, trust_quality) RESULT(expected_drop)
      REAL(KIND=dp), INTENT(IN)                          :: model_drop, history_quality, &
                                                            trust_quality
      REAL(KIND=dp)                                      :: expected_drop

         expected_drop = MAX(0.0_dp, model_drop)*MAX(0.0_dp, history_quality)* &
                         MAX(0.0_dp, MIN(1.0_dp, trust_quality))

      END FUNCTION kpoint_ot_schur_expected_drop

!> \brief accepted-drop quality for high-amplification low-curvature density response
!> \param lowcurv_ema accepted density-response low-curvature fraction
!> \param lowcurv_quality_ema accepted-drop weighted low-curvature fraction
!> \param amplification_ema accepted density-response/RHS amplification
!> \param amplification_quality_ema accepted-drop weighted amplification
!> \param samples number of accepted audit samples
!> \return neutral trust factor without history; otherwise a selective
!>         low-curvature density-response quality factor in [qmin,1]
! **************************************************************************************************
      FUNCTION kpoint_ot_density_audit_trust_quality(lowcurv_ema, lowcurv_quality_ema, &
                                                     amplification_ema, amplification_quality_ema, &
                                                     samples) RESULT(trust_quality)
      REAL(KIND=dp), INTENT(IN)                          :: lowcurv_ema, lowcurv_quality_ema, &
                                                            amplification_ema, &
                                                            amplification_quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: trust_quality

      REAL(KIND=dp) :: amplification_quality, amplification_weight, component_quality, &
         lowcurv_quality, lowcurv_weight, raw_amplification_quality, raw_lowcurv_quality

         trust_quality = 1.0_dp
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (lowcurv_ema <= 0.25_dp) RETURN

         lowcurv_quality = 0.0_dp
         amplification_quality = 0.0_dp
         raw_lowcurv_quality = 0.0_dp
         raw_amplification_quality = 0.0_dp
         IF (ABS(lowcurv_ema) > EPSILON(lowcurv_ema)) &
            raw_lowcurv_quality = ABS(lowcurv_quality_ema)/ABS(lowcurv_ema)
         IF (ABS(amplification_ema) > EPSILON(amplification_ema)) &
            raw_amplification_quality = ABS(amplification_quality_ema)/ABS(amplification_ema)
         IF (raw_lowcurv_quality > EPSILON(1.0_dp)) &
            lowcurv_quality = MIN(raw_lowcurv_quality, 1.0_dp/raw_lowcurv_quality)
         IF (raw_amplification_quality > EPSILON(1.0_dp)) &
            amplification_quality = MIN(raw_amplification_quality, &
                                        1.0_dp/raw_amplification_quality)
         component_quality = lowcurv_quality
         IF (amplification_quality > EPSILON(amplification_quality)) &
            component_quality = MIN(component_quality, amplification_quality)
         IF (component_quality <= EPSILON(component_quality)) RETURN

         component_quality = MIN(1.0_dp, MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                                             component_quality))
         lowcurv_weight = MIN(1.0_dp, MAX(0.0_dp, (lowcurv_ema - 0.25_dp)/0.75_dp))
         amplification_weight = MIN(1.0_dp, MAX(0.0_dp, LOG(MAX(1.0_dp, amplification_ema))/ &
                                                LOG(1.0E6_dp)))
         amplification_weight = MAX(amplification_weight, &
                                    MIN(1.0_dp, MAX(0.0_dp, &
                                                    LOG(MAX(1.0_dp, raw_lowcurv_quality, &
                                                            raw_amplification_quality))/LOG(1.0E6_dp))))

         trust_quality = 1.0_dp - lowcurv_weight*amplification_weight*(1.0_dp - component_quality)
         trust_quality = MIN(1.0_dp, MAX(ot_kp_schur_projector_response_quality_min_ratio, trust_quality))

      END FUNCTION kpoint_ot_density_audit_trust_quality

!> \brief accepted-drop quality for trace-bearing and trace-free Direct response pieces
!> \param trace_diag_ema accepted Direct diagonal trace-bearing curvature average
!> \param trace_free_ema accepted Direct trace-free curvature average
!> \param trace_diag_quality_ema measured-drop weighted diagonal trace quality
!> \param trace_free_quality_ema measured-drop weighted trace-free quality
!> \param samples number of accepted physical Direct quality samples
!> \param fallback_quality regular physical response history quality
!> \return calibrated Direct quality from separately tracked diag/free pieces
! **************************************************************************************************
      FUNCTION kpoint_ot_trace_split_history_quality(trace_diag_ema, trace_free_ema, &
                                                     trace_diag_quality_ema, trace_free_quality_ema, &
                                                     samples, fallback_quality) RESULT(history_quality)
      REAL(KIND=dp), INTENT(IN)                          :: trace_diag_ema, trace_free_ema, &
                                                            trace_diag_quality_ema, &
                                                            trace_free_quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: fallback_quality
      REAL(KIND=dp)                                      :: history_quality

      REAL(KIND=dp) :: balance_quality, component_fraction, component_quality, diag_abs, &
         diag_quality, dominant_quality, free_abs, free_quality, trace_abs_sum

         history_quality = fallback_quality
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN

         diag_abs = ABS(trace_diag_ema)
         free_abs = ABS(trace_free_ema)
         trace_abs_sum = diag_abs + free_abs
         IF (trace_abs_sum <= EPSILON(trace_abs_sum)) RETURN

         diag_quality = 0.0_dp
         free_quality = 0.0_dp
         IF (diag_abs > EPSILON(diag_abs)) diag_quality = ABS(trace_diag_quality_ema)/diag_abs
         IF (free_abs > EPSILON(free_abs)) free_quality = ABS(trace_free_quality_ema)/free_abs
         component_fraction = MIN(diag_abs, free_abs)/trace_abs_sum
         IF (component_fraction < 1.0E-1_dp) THEN
            dominant_quality = MERGE(diag_quality, free_quality, diag_abs >= free_abs)
            IF (dominant_quality > EPSILON(dominant_quality)) &
               history_quality = MAX(history_quality, &
                                     MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                                         MAX(ot_kp_schur_projector_response_quality_min_ratio, dominant_quality)))
            RETURN
         END IF

         component_quality = (diag_abs*diag_quality + free_abs*free_quality)/trace_abs_sum
         IF (component_quality <= EPSILON(component_quality)) RETURN

         balance_quality = 1.0_dp - ABS(trace_diag_ema + trace_free_ema)/trace_abs_sum
         balance_quality = MIN(1.0_dp, MAX(0.0_dp, balance_quality))

         history_quality = MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                               MAX(ot_kp_schur_projector_response_quality_min_ratio, component_quality))
         history_quality = history_quality*MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                                               balance_quality)
         history_quality = MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                               MAX(ot_kp_schur_projector_response_quality_min_ratio, history_quality))

      END FUNCTION kpoint_ot_trace_split_history_quality

!> \brief conservative Direct quality cap from gauge-invariant trace history
!> \param trace_ema accepted invariant trace curvature average
!> \param trace_quality_ema measured-drop weighted invariant trace quality
!> \param trace_diag_ema accepted invariant diagonal trace curvature average
!> \param trace_free_ema accepted invariant off-diagonal/free trace curvature average
!> \param trace_diag_quality_ema measured-drop weighted diagonal invariant trace quality
!> \param trace_free_quality_ema measured-drop weighted free invariant trace quality
!> \param samples number of accepted physical Direct quality samples
!> \param fallback_quality regular Direct trace quality before invariant audit
!> \return fallback quality capped by mature invariant-trace consistency
! **************************************************************************************************
      FUNCTION kpoint_ot_trace_invariant_history_quality(trace_ema, trace_quality_ema, trace_diag_ema, &
                                                         trace_free_ema, trace_diag_quality_ema, &
                                                         trace_free_quality_ema, samples, fallback_quality) &
         RESULT(history_quality)
      REAL(KIND=dp), INTENT(IN) :: trace_ema, trace_quality_ema, trace_diag_ema, trace_free_ema, &
         trace_diag_quality_ema, trace_free_quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: fallback_quality
      REAL(KIND=dp)                                      :: history_quality

      REAL(KIND=dp)                                      :: split_quality, trace_abs, trace_quality

         history_quality = fallback_quality
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN

         trace_abs = ABS(trace_ema)
         trace_quality = 0.0_dp
         IF (trace_abs > EPSILON(trace_abs)) trace_quality = ABS(trace_quality_ema)/trace_abs
         split_quality = kpoint_ot_trace_split_history_quality(trace_diag_ema, trace_free_ema, &
                                                               trace_diag_quality_ema, trace_free_quality_ema, &
                                                               samples, fallback_quality)
         IF (trace_quality > EPSILON(trace_quality)) THEN
            trace_quality = MIN(1.0_dp, MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                                            trace_quality))
            history_quality = MIN(history_quality, trace_quality)
         END IF
         history_quality = MIN(history_quality, split_quality)
         history_quality = MIN(1.0_dp, MAX(ot_kp_schur_projector_response_quality_min_ratio, history_quality))

      END FUNCTION kpoint_ot_trace_invariant_history_quality

!> \brief conservative trace-bearing Direct curvature scale from accepted drops
!> \param trace_diag_ema accepted Direct diagonal trace-bearing curvature average
!> \param trace_free_ema accepted Direct trace-free curvature average
!> \param trace_diag_quality_ema measured-drop weighted diagonal trace quality
!> \param trace_free_quality_ema measured-drop weighted trace-free quality
!> \param samples number of accepted physical Direct quality samples
!> \return scale for the diagonal trace-bearing Direct curvature component
! **************************************************************************************************
      FUNCTION kpoint_ot_trace_diag_component_scale(trace_diag_ema, trace_free_ema, &
                                                    trace_diag_quality_ema, trace_free_quality_ema, &
                                                    samples) RESULT(component_scale)
      REAL(KIND=dp), INTENT(IN)                          :: trace_diag_ema, trace_free_ema, &
                                                            trace_diag_quality_ema, &
                                                            trace_free_quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: component_scale

      REAL(KIND=dp)                                      :: balance_scale, diag_abs, diag_quality, &
                                                            free_abs, free_quality, quality_ratio, &
                                                            trace_balance, trace_norm

         component_scale = 1.0_dp
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN

         diag_abs = ABS(trace_diag_ema)
         IF (diag_abs <= EPSILON(diag_abs)) RETURN
         diag_quality = ABS(trace_diag_quality_ema)/diag_abs
         free_abs = ABS(trace_free_ema)
         IF (free_abs <= EPSILON(free_abs)) THEN
            component_scale = MIN(component_scale, &
                                  SQRT(MIN(1.0_dp, &
                                           MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                                               diag_quality))))
            RETURN
         END IF

         free_quality = ABS(trace_free_quality_ema)/free_abs
         IF (free_quality <= EPSILON(free_quality)) THEN
            component_scale = MIN(component_scale, &
                                  SQRT(MIN(1.0_dp, &
                                           MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                                               diag_quality))))
            RETURN
         END IF
         trace_norm = diag_abs + free_abs
         trace_balance = ABS(trace_diag_ema + trace_free_ema)/MAX(trace_norm, EPSILON(trace_norm))
         trace_balance = MIN(1.0_dp, MAX(0.0_dp, trace_balance))
         balance_scale = SQRT(MAX(ot_kp_schur_projector_response_quality_min_ratio, trace_balance))
         component_scale = MIN(component_scale, balance_scale)
         IF (diag_quality >= free_quality) RETURN

         quality_ratio = MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                             diag_quality/free_quality)
         component_scale = MIN(component_scale, SQRT(MIN(1.0_dp, quality_ratio)))

      END FUNCTION kpoint_ot_trace_diag_component_scale

!> \brief early tail blend toward active-covariant Direct curvature
!> \param raw_trace_ema accepted raw finite Projector trace contribution
!> \param active_trace_ema accepted active-window trace contribution
!> \param history_quality accepted-drop quality of the active-mix shadow
!> \param samples number of accepted active-mix shadow samples
!> \return bounded non-promoting basis weight for the physical Direct Hessian
! **************************************************************************************************
      FUNCTION kpoint_ot_trace_active_basis_weight(raw_trace_ema, active_trace_ema, &
                                                   history_quality, samples) RESULT(basis_weight)
      REAL(KIND=dp), INTENT(IN)                          :: raw_trace_ema, active_trace_ema, &
                                                            history_quality
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: basis_weight

      REAL(KIND=dp)                                      :: active_fraction, gauge_fraction, &
                                                            quality_weight, raw_abs

         basis_weight = 0.0_dp
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (history_quality < 0.25_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN

         raw_abs = ABS(raw_trace_ema)
         IF (raw_abs <= EPSILON(raw_abs)) RETURN

         active_fraction = ABS(active_trace_ema)/raw_abs
         active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
         gauge_fraction = 1.0_dp - active_fraction
         quality_weight = SQRT(MIN(1.0_dp, MAX(0.0_dp, history_quality)))

         basis_weight = MIN(0.25_dp, gauge_fraction*quality_weight)

      END FUNCTION kpoint_ot_trace_active_basis_weight

!> \brief active-response Direct blend from accepted raw/active trace separation
!> \param raw_trace_ema accepted raw finite Projector trace contribution
!> \param active_trace_ema accepted active-window trace contribution
!> \param history_weight accepted active-mix weight from the line-search shadow
!> \param history_quality accepted-drop quality of the active-mix shadow
!> \param samples number of accepted active-mix shadow samples
!> \param selected_quality accepted-drop quality of actually selected Direct steps
!> \param selected_samples number of actually selected Direct samples
!> \return Direct Hessian active-window blend weight
! **************************************************************************************************
      FUNCTION kpoint_ot_trace_active_mix_weight(raw_trace_ema, active_trace_ema, history_weight, &
                                                 history_quality, samples, selected_quality, &
                                                 selected_samples) RESULT(mix_weight)
      REAL(KIND=dp), INTENT(IN)                          :: raw_trace_ema, active_trace_ema, &
                                                            history_weight, history_quality
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: selected_quality
      INTEGER, INTENT(IN)                                :: selected_samples
      REAL(KIND=dp)                                      :: mix_weight

      REAL(KIND=dp)                                      :: active_fraction, gauge_fraction, &
                                                            quality_weight, raw_abs

         mix_weight = 0.0_dp
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (history_quality < ot_kp_schur_projector_response_quality_min_ratio) RETURN
         quality_weight = MIN(1.0_dp, MAX(0.0_dp, history_quality))
         mix_weight = MIN(0.75_dp, MAX(0.0_dp, history_weight)*quality_weight)
         IF (selected_samples < ot_kp_schur_projector_response_min_samples) RETURN
         IF (selected_quality < ot_kp_schur_projector_response_quality_min_ratio) RETURN

         raw_abs = ABS(raw_trace_ema)
         IF (raw_abs <= EPSILON(raw_abs)) RETURN

         active_fraction = ABS(active_trace_ema)/raw_abs
         active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
         gauge_fraction = 1.0_dp - active_fraction

         mix_weight = MAX(mix_weight, &
                          ot_kp_schur_projector_trace_active_max_weight*gauge_fraction*quality_weight)
         mix_weight = MIN(ot_kp_schur_projector_trace_active_max_weight, MAX(0.0_dp, mix_weight))

      END FUNCTION kpoint_ot_trace_active_mix_weight

!> \brief accepted-drop calibrated finite Projector-Hessian weight for the low residual tail
!> \param residual_delta current OT residual
!> \param history_quality measured/predicted dense-coupled Mermin drop quality
!> \param samples number of accepted dense-coupled quality samples
!> \param density_projector_fraction active canonical density-projector fraction
!> \param projector_diag_avg average finite Projector-Hessian diagonal
!> \param projector_delta_diag_avg average finite Projector-Hessian diagonal shift
!> \return full finite Projector weight above the validated tail gate, otherwise
!>         a small Mermin-mismatch-calibrated correction
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_coupled_weight(residual_delta, history_quality, samples, &
                                                  density_projector_fraction, projector_diag_avg, &
                                                  projector_delta_diag_avg) RESULT(projector_weight)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, history_quality
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: density_projector_fraction, &
                                                            projector_diag_avg, &
                                                            projector_delta_diag_avg
      REAL(KIND=dp)                                      :: projector_weight

      REAL(KIND=dp)                                      :: clipped_quality, curvature_fraction, &
                                                            density_fraction, diag_ratio, &
                                                            quality_weight

         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) THEN
            projector_weight = 1.0_dp
            RETURN
         END IF

         projector_weight = 0.0_dp
         IF (samples < ot_kp_schur_calibration_min_samples) RETURN

         IF (history_quality <= 1.0_dp) THEN
            clipped_quality = MIN(1.0_dp, MAX(0.0_dp, history_quality))
            quality_weight = (1.0_dp - clipped_quality)/ &
                             MAX(EPSILON(1.0_dp), 1.0_dp - ot_kp_schur_calibrated_quality_min_ratio)
         ELSE
            clipped_quality = MIN(ot_kp_schur_calibrated_quality_max_ratio, history_quality)
            quality_weight = (clipped_quality - 1.0_dp)/ &
                             MAX(EPSILON(1.0_dp), ot_kp_schur_calibrated_quality_max_ratio - 1.0_dp)
         END IF
         quality_weight = MIN(1.0_dp, MAX(0.0_dp, quality_weight))
         diag_ratio = ABS(projector_delta_diag_avg)/MAX(ABS(projector_diag_avg), EPSILON(1.0_dp))
         curvature_fraction = diag_ratio/MAX(1.0_dp, 1.0_dp + diag_ratio)
         density_fraction = MAX(MIN(1.0_dp, MAX(0.0_dp, density_projector_fraction)), &
                                0.25_dp*curvature_fraction)
         projector_weight = ot_kp_schur_projector_coupled_tail_max_weight* &
                            quality_weight*density_fraction/ &
                            MAX(1.0_dp, 1.0_dp + diag_ratio)

      END FUNCTION kpoint_ot_projector_coupled_weight

! **************************************************************************************************
!> \brief map accepted density-response history weight to a Projector-delta blend fraction
!> \param projector_weight active finite Projector-Hessian weight in the Schur block
!> \param density_history_weight accepted-drop calibrated physical density-response weight
!> \return fraction in [0,1] used to replace the raw Projector delta by the filtered physical delta
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_tail_active_delta_weight(projector_weight, density_history_weight) &
         RESULT(delta_weight)
      REAL(KIND=dp), INTENT(IN)                          :: projector_weight, density_history_weight
      REAL(KIND=dp)                                      :: delta_weight

         delta_weight = 0.0_dp
         IF (projector_weight <= EPSILON(projector_weight)) RETURN
         IF (density_history_weight <= EPSILON(density_history_weight)) RETURN

         delta_weight = MIN(1.0_dp, MAX(0.0_dp, density_history_weight)/ &
                            MAX(projector_weight, EPSILON(projector_weight)))

      END FUNCTION kpoint_ot_projector_tail_active_delta_weight

! **************************************************************************************************
!> \brief accepted-drop audit source for finite projector plateau-gap modes
!> \param direct_metric_drop projected direct-response Mermin metric drop
!> \param mode_abs_quad absolute accepted-step quadratic in the plateau-gap Hessian delta
!> \return positive drop used to calibrate plateau-gap history
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_plateau_gap_audit_drop(direct_metric_drop, mode_abs_quad) &
         RESULT(audit_drop)
      REAL(KIND=dp), INTENT(IN)                          :: direct_metric_drop, mode_abs_quad
      REAL(KIND=dp)                                      :: audit_drop

         audit_drop = MAX(0.0_dp, direct_metric_drop)
         IF (mode_abs_quad > EPSILON(mode_abs_quad)) &
            audit_drop = MAX(audit_drop, 0.5_dp*MAX(0.0_dp, mode_abs_quad))

      END FUNCTION kpoint_ot_projector_plateau_gap_audit_drop

! **************************************************************************************************
!> \brief accepted-history weight for mixing plateau-gap Projector curvature into Direct Hessian
!> \param residual_delta current effective OT residual
!> \param history_quality accepted-drop quality for plateau-gap Hessian modes
!> \param history_quality_ema smoothed measured/predicted quality
!> \param mode_weight_ema smoothed accepted modal quadratic weight
!> \param mode_negative_ema smoothed negative-mode fraction
!> \param mode_step_ema smoothed accepted-step fraction in those modes
!> \param samples number of accepted plateau-gap audit samples
!> \return small curvature-mix weight in [0,max_weight]
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_plateau_gap_mix_weight(residual_delta, history_quality, &
                                                          history_quality_ema, mode_weight_ema, &
                                                          mode_negative_ema, mode_step_ema, samples) &
         RESULT(mix_weight)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, history_quality, &
                                                            history_quality_ema, mode_weight_ema, &
                                                            mode_negative_ema, mode_step_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: mix_weight

      REAL(KIND=dp)                                      :: maturity, mode_signal, negative_quality, &
                                                            quality_signal, underprediction_signal

         mix_weight = 0.0_dp
         IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
         IF (samples < ot_kp_schur_projector_response_min_samples) RETURN

         quality_signal = MIN(1.0_dp, MAX(0.0_dp, history_quality))
         IF (quality_signal < ot_kp_schur_projector_response_quality_min_ratio) RETURN

         underprediction_signal = LOG(MAX(1.0_dp, history_quality_ema))/ &
                                  LOG(ot_kp_schur_projector_response_underpredict_max_ratio)
         underprediction_signal = MIN(1.0_dp, MAX(0.0_dp, underprediction_signal))
         IF (underprediction_signal <= EPSILON(underprediction_signal)) RETURN

         mode_signal = MAX(SQRT(MAX(0.0_dp, mode_weight_ema)), &
                           0.5_dp*SQRT(MAX(0.0_dp, mode_step_ema)))
         mode_signal = MIN(1.0_dp, MAX(0.0_dp, mode_signal))
         IF (mode_signal <= EPSILON(mode_signal)) RETURN

         negative_quality = 1.0_dp - 0.5_dp*MIN(1.0_dp, MAX(0.0_dp, mode_negative_ema))
         maturity = REAL(samples - ot_kp_schur_projector_response_min_samples + 1, KIND=dp)/ &
                    REAL(ot_kp_schur_projector_response_min_samples, KIND=dp)
         maturity = MIN(1.0_dp, MAX(0.0_dp, maturity))

         mix_weight = ot_kp_schur_projector_plateau_gap_mix_max_weight*maturity* &
                      quality_signal*underprediction_signal*mode_signal*negative_quality
         mix_weight = MIN(ot_kp_schur_projector_plateau_gap_mix_max_weight, &
                          MAX(0.0_dp, mix_weight))

      END FUNCTION kpoint_ot_projector_plateau_gap_mix_weight

! **************************************************************************************************
!> \brief finite Projector-response residual taper used by modal response audits
!> \param residual_delta current effective OT residual
!> \param raw_residual_delta optional unprojected OT residual
!> \return response weight in [0,1], with extra damping below the validated floor
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_response_residual_weight(residual_delta, raw_residual_delta) RESULT(residual_weight)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: raw_residual_delta
      REAL(KIND=dp)                                      :: residual_weight

      REAL(KIND=dp)                                      :: raw_signal, response_delta

         response_delta = MAX(0.0_dp, residual_delta)
         IF (PRESENT(raw_residual_delta)) THEN
            IF (raw_residual_delta > response_delta) THEN
               raw_signal = MIN(MAX(0.0_dp, raw_residual_delta), &
                                ot_kp_schur_projector_coupled_tail_delta)
               response_delta = MAX(response_delta, SQRT(response_delta*raw_signal))
            END IF
         END IF

         residual_weight = response_delta/ &
                           MAX(EPSILON(1.0_dp), ot_kp_schur_projector_response_full_delta)
         residual_weight = MAX(0.0_dp, MIN(1.0_dp, residual_weight))
         IF (response_delta < ot_kp_schur_projector_response_floor_delta) &
            residual_weight = residual_weight* &
                              SQRT(MAX(0.0_dp, response_delta/ &
                                       MAX(EPSILON(1.0_dp), &
                                           ot_kp_schur_projector_response_floor_delta)))

      END FUNCTION kpoint_ot_projector_response_residual_weight

! **************************************************************************************************
!> \brief sign-aware finite Projector-response balance for negative curvature modes
!> \param positive_sum positive-mode projected response norm
!> \param raw_negative_sum negative-mode projected response norm
!> \param history_quality accepted finite-response Mermin-drop quality
!> \param history_trust accepted finite-response trust quality
!> \param history_response_ratio response-mismatch/predicted-drop history
!> \return negative-mode balance in [0,1]
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_negative_response_balance(positive_sum, raw_negative_sum, history_quality, &
                                                             history_trust, history_response_ratio) RESULT(balance)
      REAL(KIND=dp), INTENT(IN)                          :: positive_sum, raw_negative_sum, &
                                                            history_quality, history_trust, &
                                                            history_response_ratio
      REAL(KIND=dp)                                      :: balance

      REAL(KIND=dp)                                      :: coherent_negative, history_scale, &
                                                            modal_floor, negative_fraction, &
                                                            response_total, scalar_floor

         balance = 0.0_dp
         IF (raw_negative_sum <= EPSILON(raw_negative_sum)) RETURN

         balance = SQRT(MAX(0.0_dp, positive_sum)/raw_negative_sum)
         history_scale = MIN(1.0_dp, MAX(0.0_dp, history_trust))/ &
                         SQRT(MAX(1.0_dp, history_response_ratio/ &
                                  ot_kp_schur_projector_response_ratio_gate))
         scalar_floor = ot_kp_schur_projector_negative_balance_floor* &
                        MIN(1.0_dp, MAX(0.0_dp, history_quality))*history_scale
         response_total = positive_sum + raw_negative_sum
         IF (response_total > EPSILON(response_total)) THEN
            negative_fraction = raw_negative_sum/response_total
            coherent_negative = MAX(0.0_dp, 2.0_dp*negative_fraction - 1.0_dp)
            modal_floor = SQRT(coherent_negative)* &
                          SQRT(MIN(1.0_dp, MAX(0.0_dp, history_quality)))*history_scale
            scalar_floor = MAX(scalar_floor, &
                               MIN(ot_kp_schur_projector_negative_balance_max, modal_floor))
         END IF
         balance = MAX(balance, scalar_floor)
         balance = MIN(1.0_dp, MAX(0.0_dp, balance))

      END FUNCTION kpoint_ot_projector_negative_response_balance

! **************************************************************************************************
!> \brief sign-aware finite Projector balance for accepted negative-step history
!> \param history_quality accepted finite-response Mermin-drop quality
!> \param history_trust accepted finite-response trust quality
!> \param history_response_ratio response-mismatch/predicted-drop history
!> \param step_negative_fraction fraction of accepted rotation step in negative modes
!> \return negative-history balance in [0,1]
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_negative_step_balance(history_quality, history_trust, &
                                                         history_response_ratio, &
                                                         step_negative_fraction) RESULT(balance)
      REAL(KIND=dp), INTENT(IN)                          :: history_quality, history_trust, &
                                                            history_response_ratio, &
                                                            step_negative_fraction
      REAL(KIND=dp)                                      :: balance

      REAL(KIND=dp)                                      :: coherent_negative, history_scale, &
                                                            modal_floor, scalar_floor, &
                                                            step_negative

         history_scale = MIN(1.0_dp, MAX(0.0_dp, history_trust))/ &
                         SQRT(MAX(1.0_dp, history_response_ratio/ &
                                  ot_kp_schur_projector_response_ratio_gate))
         scalar_floor = ot_kp_schur_projector_negative_balance_floor* &
                        MIN(1.0_dp, MAX(0.0_dp, history_quality))*history_scale
         step_negative = MIN(1.0_dp, MAX(0.0_dp, step_negative_fraction))
         coherent_negative = MAX(0.0_dp, 2.0_dp*step_negative - 1.0_dp)
         modal_floor = SQRT(coherent_negative)* &
                       SQRT(MIN(1.0_dp, MAX(0.0_dp, history_quality)))*history_scale
         balance = MAX(scalar_floor, MIN(ot_kp_schur_projector_negative_balance_max, modal_floor))
         balance = MIN(1.0_dp, MAX(0.0_dp, balance))

      END FUNCTION kpoint_ot_projector_negative_step_balance

! **************************************************************************************************
!> \brief adverse fraction of finite Projector response in negative Schur modes
!> \param negative_norm metric norm of the selected negative-mode response
!> \param correction_norm metric norm of the full selected response correction
!> \param negative_gdot Mermin residual-gradient contraction of the negative response
!> \return fraction of the correction that is both negative-mode and anti-descent
! **************************************************************************************************
      FUNCTION kpoint_ot_projector_response_adverse_fraction(negative_norm, correction_norm, &
                                                             negative_gdot) RESULT(fraction)
      REAL(KIND=dp), INTENT(IN)                          :: negative_norm, correction_norm, &
                                                            negative_gdot
      REAL(KIND=dp)                                      :: fraction

         fraction = 0.0_dp
         IF (negative_norm <= EPSILON(negative_norm)) RETURN
         IF (correction_norm <= EPSILON(correction_norm)) RETURN
         IF (negative_gdot >= 0.0_dp) RETURN

         fraction = negative_norm/correction_norm
         fraction = MAX(0.0_dp, MIN(1.0_dp, fraction))

      END FUNCTION kpoint_ot_projector_response_adverse_fraction

!> \brief audit an accepted-history calibrated finite-response correction in Projector modes
!> \param rot_hessian diagonal/canonical rotation Hessian
!> \param rot_hessian_projector finite complex Projector-Hessian
!> \param step_rot Schur rotation step before line-search normalization
!> \param response_raw conservative response used by the accepted update
!> \param response_exact finite fixed-N/tether response model
!> \param curv energy curvature weights
!> \param occ_curv projected fixed-N occupation curvature weights
!> \param tether_curv projected canonical tether curvature weights
!> \param occ_curv_projection_sum global fixed-N projection normalization
!> \param channel_nmo number of MOs in each local spin/k-point channel
!> \param e_offset energy-vector offset for each local spin/k-point channel
!> \param use_projected_metric use the fixed-N/tether-projected Mermin metric for response norms
!> \param projector_weight scalar finite Projector-Hessian tail weight
!> \param residual_delta current OT residual
!> \param raw_residual_delta optional unprojected OT residual for tail response weighting
!> \param history_quality accepted Mermin-drop quality of Projector-mode predictions
!> \param history_trust accepted Projector-mode trust EMA
!> \param history_response_ratio accepted response-mismatch drop over predicted drop
!> \param grad_e Mermin energy-variable gradient
!> \param energy_base energy search vector before finite-response correction
!> \param response_base conservative response vector used by the accepted update
!> \param response_candidate finite-response candidate vector
!> \param applied_weight step-weighted average shadow correction weight
!> \param correction_drop selected-metric norm of the applied correction
!> \param correction_negative_fraction fraction of sign-aware correction in negative Projector modes
!> \param raw_negative_fraction raw negative finite Projector-response mode fraction
!> \param positive_drop positive-mode contribution to the signed two-mode model
!> \param negative_drop negative-mode contribution to the signed two-mode model
!> \param cross_drop positive/negative cross contribution to the signed two-mode model
!> \param positive_coeff bounded positive-subspace response coefficient
!> \param negative_coeff bounded negative-subspace response coefficient
!> \param diag_base_weight raw scalar response weight before modal projection
!> \param diag_response_total_sum modal projected response norm before weighting
!> \param diag_step_weight_sum squared Schur step norm in Projector eigenmodes
!> \param diag_eval_abs_avg average absolute Projector-Hessian eigenvalue shift
!> \param diag_positive_weight_sum step-weighted positive-mode response weight
!> \param diag_negative_weight_sum step-weighted negative-mode response weight
!> \note Below the nominal response floor the correction is softly tapered, not
!>       disabled.  The late metallic tail still needs accepted-history feedback
!>       to calibrate finite Projector/Occupation response toward 1e-6.
! **************************************************************************************************
      SUBROUTINE audit_kpoint_ot_projector_response_modes(rot_hessian, rot_hessian_projector, step_rot, &
                                                          response_raw, response_exact, curv, occ_curv, tether_curv, &
                                                          occ_curv_projection_sum, channel_nmo, e_offset, &
                                                          use_projected_metric, &
                                                          projector_weight, residual_delta, history_quality, &
                                                          history_trust, history_response_ratio, grad_e, energy_base, &
                                                          response_base, response_candidate, applied_weight, &
                                                          correction_drop, correction_negative_fraction, raw_negative_fraction, &
                                                          positive_drop, negative_drop, cross_drop, positive_coeff, &
                                                          negative_coeff, diag_base_weight, &
                                                          diag_response_total_sum, diag_step_weight_sum, &
                                                          diag_eval_abs_avg, diag_positive_weight_sum, &
                                                          diag_negative_weight_sum, raw_residual_delta)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rot_hessian, rot_hessian_projector
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step_rot
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: response_raw, response_exact
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: curv, occ_curv, tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_projection_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      LOGICAL, INTENT(IN)                                :: use_projected_metric
      REAL(KIND=dp), INTENT(IN)                          :: projector_weight, residual_delta, &
                                                            history_quality, history_trust, &
                                                            history_response_ratio
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: grad_e, energy_base, response_base
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: response_candidate
      REAL(KIND=dp), INTENT(OUT) :: applied_weight, correction_drop, correction_negative_fraction, &
         raw_negative_fraction, positive_drop, negative_drop, cross_drop, positive_coeff, &
         negative_coeff
      REAL(KIND=dp), INTENT(OUT), OPTIONAL :: diag_base_weight, diag_response_total_sum, &
         diag_step_weight_sum, diag_eval_abs_avg, diag_positive_weight_sum, &
         diag_negative_weight_sum
      REAL(KIND=dp), INTENT(IN), OPTIONAL :: raw_residual_delta

      INTEGER                                            :: imode, nrot_local
      REAL(KIND=dp) :: base_projected_neg, base_projected_pos, base_weight, coeff_det, &
         coeff_negative, coeff_positive, eval_abs_avg, g1, g2, h11, h12, h22, mode_norm, &
         mode_sign, mode_weight, negative_balance, negative_gdot, negative_norm, &
         negative_weight_sum, positive_sum, positive_weight_sum, raw_negative_sum, &
         residual_weight, response_total_sum, spectral_weight, step_weight, step_weight_sum
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: mode_coeff, mode_eval, mode_norms, &
                                                            mode_rx, response_corr, response_neg, &
                                                            response_pos
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: mode_vec

         applied_weight = 0.0_dp
         correction_drop = 0.0_dp
         correction_negative_fraction = 0.0_dp
         cross_drop = 0.0_dp
         negative_coeff = 0.0_dp
         negative_drop = 0.0_dp
         positive_coeff = 0.0_dp
         positive_drop = 0.0_dp
         raw_negative_fraction = 0.0_dp
         response_candidate(:) = response_base(:)
         IF (PRESENT(diag_base_weight)) diag_base_weight = 0.0_dp
         IF (PRESENT(diag_response_total_sum)) diag_response_total_sum = 0.0_dp
         IF (PRESENT(diag_step_weight_sum)) diag_step_weight_sum = 0.0_dp
         IF (PRESENT(diag_eval_abs_avg)) diag_eval_abs_avg = 0.0_dp
         IF (PRESENT(diag_positive_weight_sum)) diag_positive_weight_sum = 0.0_dp
         IF (PRESENT(diag_negative_weight_sum)) diag_negative_weight_sum = 0.0_dp
         IF (projector_weight <= EPSILON(projector_weight)) RETURN
         IF (history_quality < ot_kp_schur_calibrated_quality_min_ratio) RETURN
         IF (history_trust <= EPSILON(history_trust)) RETURN

         nrot_local = SIZE(rot_hessian, 1)
         IF (nrot_local <= 0) RETURN
         IF (SIZE(response_base) /= SIZE(curv)) RETURN
         IF (SIZE(energy_base) /= SIZE(curv)) RETURN
         IF (SIZE(grad_e) /= SIZE(curv)) RETURN

         residual_weight = kpoint_ot_projector_response_residual_weight(residual_delta, raw_residual_delta)
         base_weight = ot_kp_schur_projector_response_max_weight*residual_weight* &
                       MIN(1.0_dp, MAX(0.0_dp, projector_weight))* &
                       MIN(1.0_dp, MAX(0.0_dp, history_quality))* &
                       MIN(1.0_dp, MAX(0.0_dp, history_trust))/ &
                       MAX(1.0_dp, history_response_ratio/ &
                           ot_kp_schur_projector_response_ratio_gate)
         IF (PRESENT(diag_base_weight)) diag_base_weight = base_weight
         IF (base_weight <= EPSILON(base_weight)) RETURN

         ALLOCATE (mode_coeff(nrot_local), mode_eval(nrot_local), mode_norms(nrot_local), &
                   mode_rx(SIZE(curv)), response_corr(SIZE(curv)), response_neg(SIZE(curv)), &
                   response_pos(SIZE(curv)), mode_vec(nrot_local, nrot_local))
         response_corr(:) = 0.0_dp
         response_neg(:) = 0.0_dp
         response_pos(:) = 0.0_dp
         mode_vec(:, :) = 0.5_dp*((rot_hessian_projector(:, :) - rot_hessian(:, :)) + &
                                  TRANSPOSE(rot_hessian_projector(:, :) - rot_hessian(:, :)))
         CALL diamat_all(mode_vec, mode_eval)
         mode_coeff(:) = MATMUL(TRANSPOSE(mode_vec), step_rot)
         eval_abs_avg = SUM(ABS(mode_eval))/REAL(MAX(1, nrot_local), KIND=dp)
         response_total_sum = 0.0_dp
         raw_negative_sum = 0.0_dp
         mode_norms(:) = 0.0_dp
         DO imode = 1, nrot_local
            IF (ABS(mode_coeff(imode)) <= EPSILON(mode_coeff(imode))) CYCLE
            mode_rx(:) = mode_coeff(imode)*MATMUL(response_exact - response_raw, mode_vec(:, imode))
            IF (use_projected_metric) THEN
               CALL kpoint_ot_mixed_projected_term(mode_rx, mode_rx, occ_curv, tether_curv, &
                                                   occ_curv_projection_sum, channel_nmo, e_offset, &
                                                   mode_norm)
            ELSE
               mode_norm = DOT_PRODUCT(curv(:)*mode_rx(:), mode_rx(:))
               CALL para_env_inter_kp%sum(mode_norm)
            END IF
            mode_norms(imode) = MAX(0.0_dp, mode_norm)
            response_total_sum = response_total_sum + mode_norms(imode)
            IF (mode_eval(imode) < 0.0_dp) raw_negative_sum = raw_negative_sum + mode_norms(imode)
         END DO
         IF (PRESENT(diag_response_total_sum)) diag_response_total_sum = response_total_sum
         IF (PRESENT(diag_eval_abs_avg)) diag_eval_abs_avg = eval_abs_avg
         IF (response_total_sum > EPSILON(response_total_sum)) &
            raw_negative_fraction = raw_negative_sum/response_total_sum
         positive_sum = MAX(0.0_dp, response_total_sum - raw_negative_sum)
         negative_balance = kpoint_ot_projector_negative_response_balance(positive_sum, raw_negative_sum, &
                                                                          history_quality, history_trust, &
                                                                          history_response_ratio)

         step_weight_sum = DOT_PRODUCT(mode_coeff, mode_coeff)
         IF (PRESENT(diag_step_weight_sum)) diag_step_weight_sum = step_weight_sum
         negative_weight_sum = 0.0_dp
         positive_weight_sum = 0.0_dp
         DO imode = 1, nrot_local
            IF (ABS(mode_coeff(imode)) <= EPSILON(mode_coeff(imode))) CYCLE
            spectral_weight = 1.0_dp
            mode_sign = 1.0_dp
            IF (mode_eval(imode) < 0.0_dp) THEN
               mode_sign = -1.0_dp
               spectral_weight = 1.0_dp/MAX(1.0_dp, ABS(mode_eval(imode))/ &
                                            MAX(eval_abs_avg, EPSILON(eval_abs_avg)))
               spectral_weight = spectral_weight*negative_balance
            END IF
            mode_weight = base_weight*MAX(0.0_dp, MIN(1.0_dp, spectral_weight))
            IF (mode_weight <= EPSILON(mode_weight)) CYCLE
            mode_rx(:) = mode_coeff(imode)*MATMUL(response_exact - response_raw, mode_vec(:, imode))
            step_weight = mode_coeff(imode)*mode_coeff(imode)
            IF (mode_sign > 0.0_dp) THEN
               response_pos(:) = response_pos(:) + mode_weight*mode_rx(:)
               positive_weight_sum = positive_weight_sum + mode_weight*step_weight
            ELSE
               response_neg(:) = response_neg(:) + mode_weight*mode_rx(:)
               negative_weight_sum = negative_weight_sum + mode_weight*step_weight
            END IF
         END DO
         IF (PRESENT(diag_positive_weight_sum)) diag_positive_weight_sum = positive_weight_sum
         IF (PRESENT(diag_negative_weight_sum)) diag_negative_weight_sum = negative_weight_sum
         IF (use_projected_metric) THEN
            CALL project_kpoint_ot_schur_response(response_pos, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
            CALL project_kpoint_ot_schur_response(response_neg, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
         END IF
         IF (use_projected_metric) THEN
            CALL kpoint_ot_mixed_projected_term(response_pos, response_pos, occ_curv, tether_curv, &
                                                occ_curv_projection_sum, channel_nmo, e_offset, h11)
            CALL kpoint_ot_mixed_projected_term(response_pos, response_neg, occ_curv, tether_curv, &
                                                occ_curv_projection_sum, channel_nmo, e_offset, h12)
            CALL kpoint_ot_mixed_projected_term(response_neg, response_neg, occ_curv, tether_curv, &
                                                occ_curv_projection_sum, channel_nmo, e_offset, h22)
         ELSE
            h11 = DOT_PRODUCT(curv(:)*response_pos(:), response_pos(:))
            h12 = DOT_PRODUCT(curv(:)*response_pos(:), response_neg(:))
            h22 = DOT_PRODUCT(curv(:)*response_neg(:), response_neg(:))
            CALL para_env_inter_kp%sum(h11)
            CALL para_env_inter_kp%sum(h12)
            CALL para_env_inter_kp%sum(h22)
         END IF
         h11 = MAX(0.0_dp, h11)
         h22 = MAX(0.0_dp, h22)
         IF (use_projected_metric) THEN
            CALL kpoint_ot_mixed_projected_term(energy_base, response_pos, occ_curv, tether_curv, &
                                                occ_curv_projection_sum, channel_nmo, e_offset, &
                                                base_projected_pos)
            CALL kpoint_ot_mixed_projected_term(energy_base, response_neg, occ_curv, tether_curv, &
                                                occ_curv_projection_sum, channel_nmo, e_offset, &
                                                base_projected_neg)
            g1 = DOT_PRODUCT(grad_e(:), response_pos(:))
            g2 = DOT_PRODUCT(grad_e(:), response_neg(:))
            CALL para_env_inter_kp%sum(g1)
            CALL para_env_inter_kp%sum(g2)
            g1 = g1 - base_projected_pos
            g2 = g2 - base_projected_neg
         ELSE
            g1 = DOT_PRODUCT(grad_e(:) - curv(:)*energy_base(:), response_pos(:))
            g2 = DOT_PRODUCT(grad_e(:) - curv(:)*energy_base(:), response_neg(:))
            CALL para_env_inter_kp%sum(g1)
            CALL para_env_inter_kp%sum(g2)
         END IF
         coeff_positive = 1.0_dp
         coeff_negative = 1.0_dp
         coeff_det = h11*h22 - h12*h12
         IF (coeff_det > EPSILON(coeff_det)) THEN
            coeff_positive = (g1*h22 - g2*h12)/coeff_det
            coeff_negative = (h11*g2 - h12*g1)/coeff_det
            coeff_positive = MIN(1.0_dp, MAX(0.0_dp, coeff_positive))
            coeff_negative = MIN(1.0_dp, MAX(0.0_dp, coeff_negative))
         END IF
         positive_coeff = coeff_positive
         negative_coeff = coeff_negative
         response_corr(:) = coeff_positive*response_pos(:) + coeff_negative*response_neg(:)
         response_candidate(:) = response_base(:) + response_corr(:)
         IF (use_projected_metric) &
            CALL project_kpoint_ot_schur_response(response_candidate, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
         positive_drop = 0.5_dp*coeff_positive*coeff_positive*MAX(0.0_dp, h11)
         negative_drop = 0.5_dp*coeff_negative*coeff_negative*MAX(0.0_dp, h22)
         cross_drop = coeff_positive*coeff_negative*h12
         IF (use_projected_metric) THEN
            CALL kpoint_ot_mixed_projected_term(response_corr, response_corr, occ_curv, tether_curv, &
                                                occ_curv_projection_sum, channel_nmo, e_offset, &
                                                correction_drop)
            CALL kpoint_ot_mixed_projected_term(coeff_negative*response_neg, coeff_negative*response_neg, &
                                                occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, &
                                                e_offset, negative_norm)
         ELSE
            correction_drop = DOT_PRODUCT(curv(:)*response_corr(:), response_corr(:))
            negative_norm = DOT_PRODUCT(curv(:)*(coeff_negative*response_neg(:)), &
                                        coeff_negative*response_neg(:))
            CALL para_env_inter_kp%sum(correction_drop)
            CALL para_env_inter_kp%sum(negative_norm)
         END IF
         correction_drop = 0.5_dp*MAX(0.0_dp, correction_drop)
         IF (step_weight_sum > EPSILON(step_weight_sum)) &
            applied_weight = (coeff_positive*positive_weight_sum + coeff_negative*negative_weight_sum)/step_weight_sum
         negative_gdot = coeff_negative*g2
         IF (correction_drop > EPSILON(correction_drop)) &
            correction_negative_fraction = kpoint_ot_projector_response_adverse_fraction( &
                                           negative_norm, 2.0_dp*correction_drop, negative_gdot)
         DEALLOCATE (mode_coeff, mode_eval, mode_norms, mode_rx, response_corr, response_neg, response_pos, mode_vec)

      END SUBROUTINE audit_kpoint_ot_projector_response_modes

!> \brief audit a Schur step in the finite Projector-Hessian eigenbasis
!> \param rot_hessian diagonal/canonical rotation Hessian
!> \param rot_hessian_projector finite complex Projector-Hessian
!> \param step_rot scaled Schur rotation step
!> \param response_actual actual energy response used by the candidate
!> \param response_model calibrated response model used for mismatch
!> \param curv energy curvature weights
!> \param candidate_drop calibrated candidate Mermin drop before mode trust
!> \param projector_weight scalar accepted-drop calibrated projector weight
!> \param history_quality accepted Mermin-drop quality of recent coupled steps
!> \param residual_quality residual-quality calibration of recent coupled steps
!> \param mode_quality accepted/residual quality used for Projector-Hessian diagnostics
!> \param mode_negative_fraction fraction of Projector-Hessian delta eigenmodes with negative curvature
!> \param mode_damped_abs_avg average absolute spectral curvature correction
!> \param mode_eval_min minimum Projector-Hessian delta eigenvalue
!> \param mode_eval_max maximum Projector-Hessian delta eigenvalue
!> \param mode_step_negative_fraction fraction of the rotation step in negative eigenmodes
!> \param mode_response_negative_fraction fraction of response mismatch in negative eigenmodes
!> \param mode_response_drop total mode-decomposed response-mismatch drop
!> \param mode_response_drop_ratio response-mismatch drop relative to candidate drop
!> \param mode_trust_quality conservative quality factor for candidate expected drop
! **************************************************************************************************
      SUBROUTINE audit_kpoint_ot_projector_modes(rot_hessian, rot_hessian_projector, step_rot, &
                                                 response_actual, response_model, curv, candidate_drop, projector_weight, &
                                                 history_quality, residual_quality, mode_quality, &
                                                 mode_negative_fraction, mode_damped_abs_avg, &
                                                 mode_eval_min, mode_eval_max, mode_step_negative_fraction, &
                                                 mode_response_negative_fraction, mode_response_drop, &
                                                 mode_response_drop_ratio, mode_trust_quality)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rot_hessian, rot_hessian_projector
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step_rot
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: response_actual, response_model
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: curv
      REAL(KIND=dp), INTENT(IN)                          :: candidate_drop, projector_weight, &
                                                            history_quality, residual_quality
      REAL(KIND=dp), INTENT(OUT) :: mode_quality, mode_negative_fraction, mode_damped_abs_avg, &
         mode_eval_min, mode_eval_max, mode_step_negative_fraction, &
         mode_response_negative_fraction, mode_response_drop, mode_response_drop_ratio, &
         mode_trust_quality

      INTEGER                                            :: imode, nrot_local
      REAL(KIND=dp) :: damped_abs_sum, filtered_eval, mode_response_norm, mode_risk, &
         mode_soft_shift, negative_count, response_negative_sum, response_total_sum, &
         step_negative_sum, step_total_sum
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: mode_coeff, mode_eval, mode_rx
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: mode_vec

         mode_quality = 0.0_dp
         mode_negative_fraction = 0.0_dp
         mode_damped_abs_avg = 0.0_dp
         mode_eval_min = 0.0_dp
         mode_eval_max = 0.0_dp
         mode_step_negative_fraction = 0.0_dp
         mode_response_negative_fraction = 0.0_dp
         mode_response_drop = 0.0_dp
         mode_response_drop_ratio = 0.0_dp
         mode_trust_quality = 1.0_dp
         IF (projector_weight <= EPSILON(projector_weight)) RETURN

         nrot_local = SIZE(rot_hessian, 1)
         IF (nrot_local <= 0) RETURN

         ALLOCATE (mode_coeff(nrot_local), mode_eval(nrot_local), mode_rx(SIZE(curv)), &
                   mode_vec(nrot_local, nrot_local))
         mode_vec(:, :) = 0.5_dp*((rot_hessian_projector(:, :) - rot_hessian(:, :)) + &
                                  TRANSPOSE(rot_hessian_projector(:, :) - rot_hessian(:, :)))
         CALL diamat_all(mode_vec, mode_eval)
         mode_eval_min = MINVAL(mode_eval)
         mode_eval_max = MAXVAL(mode_eval)

         mode_quality = MIN(1.0_dp, MAX(0.0_dp, history_quality))* &
                        MIN(1.0_dp, MAX(0.0_dp, residual_quality))
         mode_soft_shift = MAX(0.0_dp, -SUM(mode_eval)/REAL(nrot_local, KIND=dp))
         negative_count = 0.0_dp
         damped_abs_sum = 0.0_dp
         response_negative_sum = 0.0_dp
         response_total_sum = 0.0_dp
         step_negative_sum = 0.0_dp
         mode_coeff(:) = MATMUL(TRANSPOSE(mode_vec), step_rot)
         step_total_sum = DOT_PRODUCT(mode_coeff, mode_coeff)
         DO imode = 1, nrot_local
            filtered_eval = mode_eval(imode) + mode_soft_shift
            IF (filtered_eval < 0.0_dp) THEN
               negative_count = negative_count + 1.0_dp
               step_negative_sum = step_negative_sum + mode_coeff(imode)*mode_coeff(imode)
            END IF
            damped_abs_sum = damped_abs_sum + ABS(mode_eval(imode) - filtered_eval)
            mode_rx(:) = mode_coeff(imode)*MATMUL(response_model - response_actual, mode_vec(:, imode))
            mode_response_norm = DOT_PRODUCT(curv(:)*mode_rx(:), mode_rx(:))
            CALL para_env_inter_kp%sum(mode_response_norm)
            response_total_sum = response_total_sum + mode_response_norm
            IF (filtered_eval < 0.0_dp) response_negative_sum = response_negative_sum + mode_response_norm
         END DO

         mode_negative_fraction = negative_count/REAL(MAX(1, nrot_local), KIND=dp)
         mode_damped_abs_avg = projector_weight*damped_abs_sum/REAL(MAX(1, nrot_local), KIND=dp)
         IF (step_total_sum > EPSILON(step_total_sum)) &
            mode_step_negative_fraction = step_negative_sum/step_total_sum
         IF (response_total_sum > EPSILON(response_total_sum)) &
            mode_response_negative_fraction = response_negative_sum/response_total_sum
         mode_response_drop = 0.5_dp*MAX(0.0_dp, response_total_sum)
         IF (candidate_drop > EPSILON(candidate_drop)) &
            mode_response_drop_ratio = mode_response_drop/candidate_drop
         mode_risk = MAX(mode_response_negative_fraction, &
                         mode_step_negative_fraction*MIN(1.0_dp, mode_response_drop_ratio)) - mode_quality
         mode_trust_quality = 1.0_dp - ot_kp_schur_projector_mode_trust_max_penalty* &
                              projector_weight*MAX(0.0_dp, mode_risk)
         mode_trust_quality = MAX(1.0_dp - ot_kp_schur_projector_mode_trust_max_penalty*projector_weight, &
                                  MIN(1.0_dp, mode_trust_quality))
         DEALLOCATE (mode_coeff, mode_eval, mode_rx, mode_vec)

      END SUBROUTINE audit_kpoint_ot_projector_modes

!> \brief audit an accepted Schur step in a shadow Hessian-delta eigenbasis
!> \param hessian_delta symmetric shadow Hessian contribution
!> \param step_rot accepted, line-search-normalized rotation step
!> \param candidate_drop calibrated Mermin drop predicted for the accepted step
!> \param mode_negative_fraction fraction of negative shadow-Hessian eigenmodes
!> \param mode_eval_min minimum shadow-Hessian eigenvalue
!> \param mode_eval_max maximum shadow-Hessian eigenvalue
!> \param mode_step_negative_fraction fraction of the accepted step in negative modes
!> \param mode_quad signed quadratic shadow-Hessian contribution along the step
!> \param mode_abs_quad absolute quadratic shadow-Hessian contribution along the step
!> \param mode_positive_quad positive-mode quadratic contribution
!> \param mode_negative_quad absolute negative-mode quadratic contribution
!> \param mode_quad_signed_ratio signed half-quadratic over candidate_drop
!> \param mode_quad_abs_ratio absolute half-quadratic over candidate_drop
! **************************************************************************************************
      SUBROUTINE audit_kpoint_ot_hessian_delta_modes(hessian_delta, step_rot, candidate_drop, &
                                                     mode_negative_fraction, mode_eval_min, mode_eval_max, &
                                                     mode_step_negative_fraction, mode_quad, mode_abs_quad, &
                                                     mode_positive_quad, mode_negative_quad, &
                                                     mode_quad_signed_ratio, mode_quad_abs_ratio)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian_delta
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step_rot
      REAL(KIND=dp), INTENT(IN)                          :: candidate_drop
      REAL(KIND=dp), INTENT(OUT) :: mode_negative_fraction, mode_eval_min, mode_eval_max, &
         mode_step_negative_fraction, mode_quad, mode_abs_quad, mode_positive_quad, &
         mode_negative_quad, mode_quad_signed_ratio, mode_quad_abs_ratio

      INTEGER                                            :: imode, nrot_local
      REAL(KIND=dp)                                      :: coeff2, negative_count, &
                                                            step_negative_sum, step_total_sum
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: mode_coeff, mode_eval
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: mode_vec

         mode_abs_quad = 0.0_dp
         mode_eval_max = 0.0_dp
         mode_eval_min = 0.0_dp
         mode_negative_fraction = 0.0_dp
         mode_negative_quad = 0.0_dp
         mode_positive_quad = 0.0_dp
         mode_quad = 0.0_dp
         mode_quad_abs_ratio = 0.0_dp
         mode_quad_signed_ratio = 0.0_dp
         mode_step_negative_fraction = 0.0_dp

         nrot_local = SIZE(hessian_delta, 1)
         IF (nrot_local <= 0) RETURN
         IF (SIZE(hessian_delta, 2) /= nrot_local) RETURN
         IF (SIZE(step_rot) /= nrot_local) RETURN

         ALLOCATE (mode_coeff(nrot_local), mode_eval(nrot_local), mode_vec(nrot_local, nrot_local))
         mode_vec(:, :) = 0.5_dp*(hessian_delta(:, :) + TRANSPOSE(hessian_delta(:, :)))
         CALL diamat_all(mode_vec, mode_eval)
         mode_eval_min = MINVAL(mode_eval)
         mode_eval_max = MAXVAL(mode_eval)
         mode_coeff(:) = MATMUL(TRANSPOSE(mode_vec), step_rot)
         step_total_sum = DOT_PRODUCT(mode_coeff, mode_coeff)
         step_negative_sum = 0.0_dp
         negative_count = 0.0_dp
         DO imode = 1, nrot_local
            coeff2 = mode_coeff(imode)*mode_coeff(imode)
            IF (mode_eval(imode) < 0.0_dp) THEN
               negative_count = negative_count + 1.0_dp
               step_negative_sum = step_negative_sum + coeff2
               mode_negative_quad = mode_negative_quad - mode_eval(imode)*coeff2
            ELSE
               mode_positive_quad = mode_positive_quad + mode_eval(imode)*coeff2
            END IF
         END DO
         mode_quad = mode_positive_quad - mode_negative_quad
         mode_abs_quad = mode_positive_quad + mode_negative_quad
         mode_negative_fraction = negative_count/REAL(MAX(1, nrot_local), KIND=dp)
         IF (step_total_sum > EPSILON(step_total_sum)) &
            mode_step_negative_fraction = step_negative_sum/step_total_sum
         IF (candidate_drop > EPSILON(candidate_drop)) THEN
            mode_quad_signed_ratio = 0.5_dp*mode_quad/candidate_drop
            mode_quad_abs_ratio = 0.5_dp*mode_abs_quad/candidate_drop
         END IF
         DEALLOCATE (mode_coeff, mode_eval, mode_vec)

      END SUBROUTINE audit_kpoint_ot_hessian_delta_modes

! **************************************************************************************************
!> \brief ...
!> \param response_actual ...
!> \param response_model ...
!> \param curv ...
!> \param scale ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_response_mismatch_drop(response_actual, response_model, curv, scale) RESULT(drop)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: response_actual, response_model, curv
      REAL(KIND=dp), INTENT(IN)                          :: scale
      REAL(KIND=dp)                                      :: drop

         drop = SUM(curv(:)*(response_model(:) - response_actual(:))**2)
         CALL para_env_inter_kp%sum(drop)
         drop = 0.5_dp*scale*scale*MAX(0.0_dp, drop)

      END FUNCTION kpoint_ot_response_mismatch_drop

! **************************************************************************************************
!> \brief ...
!> \param hessian ...
!> \param step_vec ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_symmetric_quad(hessian, step_vec) RESULT(quad)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step_vec
      REAL(KIND=dp)                                      :: quad

      INTEGER                                            :: i, j, nrot_local

         quad = 0.0_dp
         nrot_local = SIZE(hessian, 1)
         IF (nrot_local <= 0) RETURN
         IF (SIZE(hessian, 2) /= nrot_local) RETURN
         IF (SIZE(step_vec) /= nrot_local) RETURN

         DO j = 1, nrot_local
            DO i = 1, nrot_local
               quad = quad + 0.5_dp*(hessian(i, j) + hessian(j, i))*step_vec(i)*step_vec(j)
            END DO
         END DO

      END FUNCTION kpoint_ot_symmetric_quad

! **************************************************************************************************
!> \brief ...
!> \param hessian ...
!> \param step_vec ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_symmetric_abs_quad(hessian, step_vec) RESULT(abs_quad)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step_vec
      REAL(KIND=dp)                                      :: abs_quad

      INTEGER                                            :: imode, nrot_local
      REAL(KIND=dp)                                      :: coeff
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: mode_eval
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: mode_vec

         abs_quad = 0.0_dp
         nrot_local = SIZE(hessian, 1)
         IF (nrot_local <= 0) RETURN
         IF (SIZE(hessian, 2) /= nrot_local) RETURN
         IF (SIZE(step_vec) /= nrot_local) RETURN

         ALLOCATE (mode_eval(nrot_local), mode_vec(nrot_local, nrot_local))
         mode_vec(:, :) = 0.5_dp*(hessian(:, :) + TRANSPOSE(hessian(:, :)))
         CALL diamat_all(mode_vec, mode_eval)
         DO imode = 1, nrot_local
            coeff = DOT_PRODUCT(mode_vec(:, imode), step_vec)
            abs_quad = abs_quad + ABS(mode_eval(imode))*coeff*coeff
         END DO
         DEALLOCATE (mode_eval, mode_vec)

      END FUNCTION kpoint_ot_symmetric_abs_quad

! **************************************************************************************************
!> \brief ...
!> \param mode_vec ...
!> \param mode_eval ...
!> \param step_vec ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_modal_abs_quad(mode_vec, mode_eval, step_vec) RESULT(abs_quad)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: mode_vec
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: mode_eval, step_vec
      REAL(KIND=dp)                                      :: abs_quad

      INTEGER                                            :: imode, nrot_local
      REAL(KIND=dp)                                      :: coeff

         abs_quad = 0.0_dp
         nrot_local = SIZE(mode_eval)
         IF (nrot_local <= 0) RETURN
         IF (SIZE(mode_vec, 1) /= nrot_local) RETURN
         IF (SIZE(mode_vec, 2) /= nrot_local) RETURN
         IF (SIZE(step_vec) /= nrot_local) RETURN

         DO imode = 1, nrot_local
            coeff = DOT_PRODUCT(mode_vec(:, imode), step_vec)
            abs_quad = abs_quad + ABS(mode_eval(imode))*coeff*coeff
         END DO

      END FUNCTION kpoint_ot_modal_abs_quad

! **************************************************************************************************
!> \brief ...
!> \param local_channel ...
!> \param nmo ...
!> \param first_var ...
!> \param last_var ...
!> \param first_energy ...
!> \param chc_re ...
!> \param chc_im ...
!> \param occupation_numbers ...
!> \param kpoint_weight ...
!> \param projector_window_gap ...
!> \param occ_curv_channel ...
!> \param var_i ...
!> \param var_j ...
!> \param var_kind ...
!> \param compute_projector_shadow ...
!> \param compute_density_full_audit ...
!> \param compute_projector_plateau_audit ...
!> \param step_gauge_quality ...
!> \param rot_hessian ...
!> \param rot_hessian_coupled ...
!> \param rot_hessian_projector ...
!> \param rot_hessian_projector_physical ...
!> \param rot_hessian_projector_physical_offdiag ...
!> \param rot_hessian_projector_physical_offdiag_plateau ...
!> \param response ...
!> \param response_occ ...
!> \param response_occ_physical ...
!> \param response_density_physical ...
!> \param response_density_floor_audit ...
!> \param response_density_full ...
!> \param response_density_full_audit ...
!> \param response_density_plateau ...
!> \param projector_fd_cluster_derivatives ...
!> \param projector_fd_cluster_replacements ...
!> \param failed ...
! **************************************************************************************************
      SUBROUTINE build_finite_ref_rotation_model(local_channel, nmo, first_var, last_var, first_energy, &
                                                 chc_re, chc_im, occupation_numbers, kpoint_weight, &
                                                 projector_window_gap, occ_curv_channel, var_i, var_j, var_kind, &
                                                 compute_projector_shadow, &
                                                 compute_density_full_audit, compute_projector_plateau_audit, &
                                                 step_gauge_quality, &
                                                 rot_hessian, rot_hessian_coupled, rot_hessian_projector, &
                                                 rot_hessian_projector_physical, &
                                                 rot_hessian_projector_physical_offdiag, &
                                                 rot_hessian_projector_physical_offdiag_plateau, response, &
                                                 response_occ, response_occ_physical, response_density_physical, &
                                                 response_density_floor_audit, response_density_full, &
                                                 response_density_full_audit, &
                                                 response_density_plateau, projector_fd_cluster_derivatives, &
                                                 projector_fd_cluster_replacements, failed)
      INTEGER, INTENT(IN)                                :: local_channel, nmo, first_var, last_var, &
                                                            first_energy
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: chc_re, chc_im
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_numbers
      REAL(KIND=dp), INTENT(IN)                          :: kpoint_weight, projector_window_gap
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv_channel
      INTEGER, DIMENSION(:), INTENT(IN)                  :: var_i, var_j, var_kind
      LOGICAL, INTENT(IN) :: compute_projector_shadow, compute_density_full_audit, &
         compute_projector_plateau_audit
      REAL(KIND=dp), INTENT(IN)                          :: step_gauge_quality
      REAL(KIND=dp), DIMENSION(:, :), INTENT(INOUT) :: rot_hessian, rot_hessian_coupled, &
         rot_hessian_projector, rot_hessian_projector_physical, &
         rot_hessian_projector_physical_offdiag, rot_hessian_projector_physical_offdiag_plateau, &
         response, response_occ, response_occ_physical, response_density_physical, &
         response_density_floor_audit, response_density_full, response_density_full_audit, &
         response_density_plateau
      INTEGER, INTENT(INOUT) :: projector_fd_cluster_derivatives, projector_fd_cluster_replacements
      LOGICAL, INTENT(INOUT)                             :: failed

      REAL(KIND=dp), PARAMETER                           :: fd_step = 1.0E-4_dp

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: base, chc, chc_m, chc_p, dchc, docc_mat, &
         docc_plateau, occ_basis, occ_mat, occ_mat_coupled, occ_mat_m, occ_mat_p, projector_evec, u
      INTEGER                                            :: ie, imo, jmo, r, s
      LOGICAL                                            :: fd_cluster_used
      REAL(KIND=dp) :: channel_occ_curv_max, density_plateau_full_response, &
         density_plateau_response, density_response, density_response_alignment, &
         projector_centered_shift, projector_response, projector_response_norm, &
         projector_safe_response_dot, projector_weight, raw_response, safe_centered_shift, &
         safe_response_norm, weighted_curv_sum
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: density_floor_audit_column, &
         density_full_centered_column, density_full_column, density_mixed_column, &
         density_plateau_centered_column, density_plateau_column, density_projector_column, eps_m, &
         eps_p, projector_evals, projector_evals_m, projector_evals_p
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: grad_m_im, grad_m_re, grad_p_im, &
                                                            grad_p_re, u_im, u_re, x_im, x_m_im, &
                                                            x_m_re, x_p_im, x_p_re, x_re

         IF (failed) RETURN
         IF (first_var > last_var) RETURN

         ALLOCATE (x_re(nmo, nmo), x_im(nmo, nmo), u_re(nmo, nmo), u_im(nmo, nmo))
         CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_x, x_re)
         CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_x_im, x_im)
         CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_u, u_re)
         CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_u_im, u_im)
         CALL local_ot_env(local_channel)%para_env%sum(x_re)
         CALL local_ot_env(local_channel)%para_env%sum(x_im)
         CALL local_ot_env(local_channel)%para_env%sum(u_re)
         CALL local_ot_env(local_channel)%para_env%sum(u_im)

         ALLOCATE (chc(nmo, nmo), u(nmo, nmo), base(nmo, nmo), &
                   chc_p(nmo, nmo), chc_m(nmo, nmo), dchc(nmo, nmo), docc_mat(nmo, nmo), &
                   docc_plateau(nmo, nmo), &
                   occ_mat(nmo, nmo), occ_mat_p(nmo, nmo), occ_mat_m(nmo, nmo), &
                   occ_mat_coupled(nmo, nmo), occ_basis(nmo, nmo), projector_evec(nmo, nmo))
         ALLOCATE (density_floor_audit_column(nmo), density_full_centered_column(nmo), &
                   density_full_column(nmo), density_mixed_column(nmo), &
                   density_plateau_centered_column(nmo), density_plateau_column(nmo), &
                   density_projector_column(nmo))
         chc = CMPLX(chc_re, chc_im, KIND=dp)
         u = CMPLX(u_re, u_im, KIND=dp)
         base = MATMUL(u, MATMUL(chc, CONJG(TRANSPOSE(u))))
         CALL dense_history_safe_occ_projector(chc, occupation_numbers, kpoint_weight, &
                                               local_ot_env(local_channel)%delta, occ_mat, &
                                               occ_curv_channel, ot_kp_projector_occupation_gauge_gap, &
                                               projector_window_gap)
         occ_mat_coupled(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         DO imo = 1, nmo
            occ_mat_coupled(imo, imo) = CMPLX(2.0_dp*kpoint_weight*occupation_numbers(imo), 0.0_dp, KIND=dp)
         END DO
         channel_occ_curv_max = MAXVAL(occ_curv_channel)
         projector_weight = kpoint_ot_canonical_projector_weight(local_ot_env(local_channel)%delta, &
                                                                 ot_kp_canonical_projector_max_weight)
         IF (projector_weight > 0.0_dp) THEN
            ALLOCATE (projector_evals(nmo))
            CALL diag_complex(chc, projector_evec, projector_evals)
            DEALLOCATE (projector_evals)
         END IF

         ALLOCATE (x_p_re(nmo, nmo), x_p_im(nmo, nmo), x_m_re(nmo, nmo), x_m_im(nmo, nmo))
         ALLOCATE (grad_p_re(nmo, nmo), grad_p_im(nmo, nmo), grad_m_re(nmo, nmo), grad_m_im(nmo, nmo))
         ALLOCATE (eps_p(nmo), eps_m(nmo), projector_evals_p(nmo), projector_evals_m(nmo))

         DO ie = 1, nmo
            CALL dense_history_safe_occ_projector_basis(projector_evec, projector_weight, ie, occ_basis)
            CALL dense_ref_rotation_gradient(x_re, x_im, base, occ_basis, grad_p_re, grad_p_im, eps_p)
            DO r = first_var, last_var
               imo = var_i(r)
               jmo = var_j(r)
               SELECT CASE (var_kind(r))
               CASE (1)
                  response_occ(first_energy + ie - 1, r) = 2.0_dp*grad_p_re(imo, jmo)
               CASE (2)
                  response_occ(first_energy + ie - 1, r) = 2.0_dp*grad_p_im(imo, jmo)
               END SELECT
            END DO
         END DO

         DO s = first_var, last_var
            x_p_re(:, :) = x_re(:, :)
            x_p_im(:, :) = x_im(:, :)
            x_m_re(:, :) = x_re(:, :)
            x_m_im(:, :) = x_im(:, :)
            imo = var_i(s)
            jmo = var_j(s)
            SELECT CASE (var_kind(s))
            CASE (1)
               x_p_re(imo, jmo) = x_p_re(imo, jmo) + fd_step
               x_p_re(jmo, imo) = x_p_re(jmo, imo) - fd_step
               x_m_re(imo, jmo) = x_m_re(imo, jmo) - fd_step
               x_m_re(jmo, imo) = x_m_re(jmo, imo) + fd_step
            CASE (2)
               x_p_im(imo, jmo) = x_p_im(imo, jmo) + fd_step
               x_p_im(jmo, imo) = x_p_im(jmo, imo) + fd_step
               x_m_im(imo, jmo) = x_m_im(imo, jmo) - fd_step
               x_m_im(jmo, imo) = x_m_im(jmo, imo) - fd_step
            END SELECT

            CALL dense_ref_rotation_gradient(x_p_re, x_p_im, base, occ_mat, grad_p_re, grad_p_im, eps_p)
            CALL dense_ref_rotation_gradient(x_m_re, x_m_im, base, occ_mat, grad_m_re, grad_m_im, eps_m)

            DO r = first_var, last_var
               imo = var_i(r)
               jmo = var_j(r)
               SELECT CASE (var_kind(r))
               CASE (1)
                  rot_hessian(r, s) = 2.0_dp*(grad_p_re(imo, jmo) - grad_m_re(imo, jmo))/(2.0_dp*fd_step)
               CASE (2)
                  rot_hessian(r, s) = 2.0_dp*(grad_p_im(imo, jmo) - grad_m_im(imo, jmo))/(2.0_dp*fd_step)
               END SELECT
            END DO
            CALL dense_rotated_chc(x_p_re, x_p_im, base, chc_p)
            CALL dense_rotated_chc(x_m_re, x_m_im, base, chc_m)
            IF (compute_projector_shadow .AND. projector_weight > 0.0_dp) THEN
               CALL diag_complex(chc_p, projector_evec, projector_evals_p)
               CALL diag_complex(chc_m, projector_evec, projector_evals_m)
            END IF
            density_projector_column(:) = 0.0_dp
            DO ie = 1, nmo
               raw_response = (REAL(chc_p(ie, ie), KIND=dp) - REAL(chc_m(ie, ie), KIND=dp))/(2.0_dp*fd_step)
               projector_response = raw_response
               IF (compute_projector_shadow .AND. projector_weight > 0.0_dp) &
                  projector_response = (projector_evals_p(ie) - projector_evals_m(ie))/(2.0_dp*fd_step)
               response_occ_physical(first_energy + ie - 1, s) = &
                  (1.0_dp - projector_weight)*raw_response + projector_weight*projector_response
               density_projector_column(ie) = -projector_weight*projector_response
            END DO
            CALL dense_history_safe_occ_projector(chc_p, occupation_numbers, kpoint_weight, &
                                                  local_ot_env(local_channel)%delta, occ_mat_p, &
                                                  occ_curv_channel, ot_kp_projector_occupation_gauge_gap, &
                                                  projector_window_gap)
            CALL dense_history_safe_occ_projector(chc_m, occupation_numbers, kpoint_weight, &
                                                  local_ot_env(local_channel)%delta, occ_mat_m, &
                                                  occ_curv_channel, ot_kp_projector_occupation_gauge_gap, &
                                                  projector_window_gap)
            CALL dense_ref_rotation_gradient(x_p_re, x_p_im, base, occ_mat_p, grad_p_re, grad_p_im, eps_p)
            CALL dense_ref_rotation_gradient(x_m_re, x_m_im, base, occ_mat_m, grad_m_re, grad_m_im, eps_m)
            DO r = first_var, last_var
               imo = var_i(r)
               jmo = var_j(r)
               SELECT CASE (var_kind(r))
               CASE (1)
                  rot_hessian_projector(r, s) = &
                     2.0_dp*(grad_p_re(imo, jmo) - grad_m_re(imo, jmo))/(2.0_dp*fd_step)
               CASE (2)
                  rot_hessian_projector(r, s) = &
                     2.0_dp*(grad_p_im(imo, jmo) - grad_m_im(imo, jmo))/(2.0_dp*fd_step)
               END SELECT
            END DO
            IF (compute_projector_shadow .OR. compute_density_full_audit) THEN
               dchc(:, :) = (chc_p(:, :) - chc_m(:, :))/(2.0_dp*fd_step)
               CALL dense_history_safe_occ_projector_derivative(chc, dchc, occupation_numbers, kpoint_weight, &
                                                                local_ot_env(local_channel)%delta, docc_mat)
               fd_cluster_used = .FALSE.
               CALL dense_history_safe_occ_projector_derivative(chc, dchc, occupation_numbers, kpoint_weight, &
                                                                local_ot_env(local_channel)%delta, docc_plateau, &
                                                                occ_curv_channel, &
                                                                ot_kp_projector_occupation_gauge_gap, &
                                                                fd_cluster_used, projector_window_gap)
               projector_fd_cluster_derivatives = projector_fd_cluster_derivatives + 1
               IF (fd_cluster_used) &
                  projector_fd_cluster_replacements = projector_fd_cluster_replacements + 1
               ! The diagonal density response is consumed by the auxiliary-energy
               ! channel below.  The remaining spectral Projector motion is the
               ! history-safe off-diagonal occupation response.  Use the
               ! gauge-filtered derivative for the physical rotation Hessian so
               ! near-degenerate projector-gauge motion does not enter the
               ! finite complex Mermin curvature.
               density_full_column(:) = 0.0_dp
               density_floor_audit_column(:) = 0.0_dp
               density_mixed_column(:) = 0.0_dp
               density_plateau_column(:) = 0.0_dp
               density_plateau_centered_column(:) = 0.0_dp
               density_full_centered_column(:) = 0.0_dp
               DO ie = 1, nmo
                  IF (ABS(occ_curv_channel(ie)) > EPSILON(occ_curv_channel(ie))) THEN
                     ! The physical density-response channel follows the finite
                     ! projector eigenvalue response, with only a sign-consistent
                     ! bounded contribution from the gauge-safe dP derivative.
                     ! The raw derivative remains exposed through the audit
                     ! channels below.
                     density_plateau_column(ie) = density_projector_column(ie)
                     density_full_column(ie) = 0.5_dp*REAL(docc_plateau(ie, ie), KIND=dp)/ &
                                               occ_curv_channel(ie)
                  END IF
               END DO
               density_plateau_centered_column(:) = density_plateau_column(:)
               density_full_centered_column(:) = density_full_column(:)
               weighted_curv_sum = SUM(MAX(0.0_dp, occ_curv_channel(:)))
               IF (weighted_curv_sum > EPSILON(weighted_curv_sum)) THEN
                  projector_centered_shift = DOT_PRODUCT(MAX(0.0_dp, occ_curv_channel(:)), &
                                                         density_plateau_centered_column(:))/ &
                                             weighted_curv_sum
                  safe_centered_shift = DOT_PRODUCT(MAX(0.0_dp, occ_curv_channel(:)), &
                                                    density_full_centered_column(:))/ &
                                        weighted_curv_sum
                  density_plateau_centered_column(:) = density_plateau_centered_column(:) - &
                                                       projector_centered_shift
                  density_full_centered_column(:) = density_full_centered_column(:) - &
                                                    safe_centered_shift
               END IF
               projector_safe_response_dot = 0.0_dp
               projector_response_norm = 0.0_dp
               safe_response_norm = 0.0_dp
               DO ie = 1, nmo
                  IF (ABS(occ_curv_channel(ie)) > EPSILON(occ_curv_channel(ie))) THEN
                     projector_safe_response_dot = projector_safe_response_dot + &
                                                   MAX(0.0_dp, occ_curv_channel(ie))* &
                                                   density_plateau_centered_column(ie)* &
                                                   density_full_centered_column(ie)
                     projector_response_norm = projector_response_norm + &
                                               MAX(0.0_dp, occ_curv_channel(ie))* &
                                               density_plateau_centered_column(ie)**2
                     safe_response_norm = safe_response_norm + &
                                          MAX(0.0_dp, occ_curv_channel(ie))* &
                                          density_full_centered_column(ie)**2
                  END IF
               END DO
               density_response_alignment = 0.0_dp
               IF (projector_response_norm > EPSILON(projector_response_norm) .AND. &
                   safe_response_norm > EPSILON(safe_response_norm)) &
                  density_response_alignment = projector_safe_response_dot/ &
                                               SQRT(projector_response_norm*safe_response_norm)
               DO ie = 1, nmo
                  IF (ABS(occ_curv_channel(ie)) > EPSILON(occ_curv_channel(ie))) THEN
                     density_mixed_column(ie) = &
                        kpoint_ot_physical_density_response(density_plateau_column(ie), &
                                                            density_full_column(ie), &
                                                            occ_curv_channel(ie), channel_occ_curv_max, &
                                                            density_plateau_centered_column(ie), &
                                                            density_full_centered_column(ie), &
                                                            density_response_alignment)
                     density_mixed_column(ie) = &
                        kpoint_ot_residual_gauge_density_response(density_mixed_column(ie), &
                                                                  density_plateau_column(ie), &
                                                                  density_full_column(ie), &
                                                                  occ_curv_channel(ie), channel_occ_curv_max, &
                                                                  step_gauge_quality, &
                                                                  density_plateau_centered_column(ie), &
                                                                  density_full_centered_column(ie), &
                                                                  density_response_alignment)
                     density_floor_audit_column(ie) = &
                        kpoint_ot_physical_density_floor_audit_response(density_plateau_column(ie), &
                                                                        density_full_column(ie), &
                                                                        occ_curv_channel(ie), &
                                                                        channel_occ_curv_max)
                  END IF
               END DO
               DO ie = 1, nmo
                  IF (ABS(occ_curv_channel(ie)) > EPSILON(occ_curv_channel(ie))) THEN
                     ! Keep the production density response tied to finite
                     ! spectral density motion plus the bounded physical
                     ! occupation-response component.  The raw diagonal
                     ! derivative is still exposed through the audit channel.
                     density_plateau_response = density_mixed_column(ie)
                     ! The full density response below keeps channel-uniform
                     ! components for the global fixed-N Mermin projector.  The
                     ! plateau-gap model is only a local trust/audit source, so
                     ! feed it the local fixed-N centered shape and do not let
                     ! channel gauge shifts inflate the response trust.
                     density_plateau_full_response = density_projector_column(ie)
                     density_response = 0.5_dp*REAL(docc_mat(ie, ie), KIND=dp)/ &
                                        occ_curv_channel(ie)
                     IF (compute_density_full_audit) &
                        response_density_full_audit(first_energy + ie - 1, s) = density_response
                     IF (compute_density_full_audit) &
                        response_density_floor_audit(first_energy + ie - 1, s) = &
                        density_floor_audit_column(ie)
                     IF (compute_projector_shadow) THEN
                        response_density_full(first_energy + ie - 1, s) = &
                           density_plateau_full_response
                        response_density_physical(first_energy + ie - 1, s) = &
                           density_plateau_response
                        response_density_plateau(first_energy + ie - 1, s) = &
                           density_plateau_centered_column(ie)
                        response_occ_physical(first_energy + ie - 1, s) = &
                           response_occ_physical(first_energy + ie - 1, s) - &
                           response_density_physical(first_energy + ie - 1, s)
                        ! The diagonal projector response is represented by the
                        ! energy-response channel above.  Keeping it in the
                        ! rotation Hessian as well double-counts the same density
                        ! response and creates an artificial physical row floor.
                        docc_mat(ie, ie) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
                        docc_plateau(ie, ie) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
                     END IF
                  END IF
               END DO
               IF (compute_projector_shadow) THEN
                  CALL dense_ref_rotation_gradient(x_re, x_im, base, docc_plateau, &
                                                   grad_p_re, grad_p_im, eps_p)
                  DO r = first_var, last_var
                     imo = var_i(r)
                     jmo = var_j(r)
                     SELECT CASE (var_kind(r))
                     CASE (1)
                        rot_hessian_projector_physical_offdiag(r, s) = 2.0_dp*grad_p_re(imo, jmo)
                     CASE (2)
                        rot_hessian_projector_physical_offdiag(r, s) = 2.0_dp*grad_p_im(imo, jmo)
                     END SELECT
                  END DO
                  IF (compute_projector_plateau_audit) THEN
                     ! Keep the active Hessian plateau-filtered, but expose the
                     ! raw off-diagonal projector response as an audit/candidate
                     ! gap against that filtered physical model.
                     CALL dense_ref_rotation_gradient(x_re, x_im, base, docc_mat, &
                                                      grad_p_re, grad_p_im, eps_p)
                     DO r = first_var, last_var
                        imo = var_i(r)
                        jmo = var_j(r)
                        SELECT CASE (var_kind(r))
                        CASE (1)
                           rot_hessian_projector_physical_offdiag_plateau(r, s) = 2.0_dp*grad_p_re(imo, jmo)
                        CASE (2)
                           rot_hessian_projector_physical_offdiag_plateau(r, s) = 2.0_dp*grad_p_im(imo, jmo)
                        END SELECT
                     END DO
                  ELSE
                     DO r = first_var, last_var
                        rot_hessian_projector_physical_offdiag_plateau(r, s) = &
                           rot_hessian_projector_physical_offdiag(r, s)
                     END DO
                  END IF
                  DO r = first_var, last_var
                     rot_hessian_projector_physical(r, s) = (1.0_dp - projector_weight)*rot_hessian(r, s)
                  END DO
               ELSE
                  DO r = first_var, last_var
                     rot_hessian_projector_physical(r, s) = rot_hessian_projector(r, s)
                  END DO
               END IF
            ELSE
               DO r = first_var, last_var
                  rot_hessian_projector_physical(r, s) = rot_hessian_projector(r, s)
               END DO
            END IF
            CALL dense_ref_rotation_gradient(x_p_re, x_p_im, base, occ_mat_coupled, grad_p_re, &
                                             grad_p_im, eps_p)
            CALL dense_ref_rotation_gradient(x_m_re, x_m_im, base, occ_mat_coupled, grad_m_re, &
                                             grad_m_im, eps_m)
            DO r = first_var, last_var
               imo = var_i(r)
               jmo = var_j(r)
               SELECT CASE (var_kind(r))
               CASE (1)
                  rot_hessian_coupled(r, s) = &
                     2.0_dp*(grad_p_re(imo, jmo) - grad_m_re(imo, jmo))/(2.0_dp*fd_step)
               CASE (2)
                  rot_hessian_coupled(r, s) = &
                     2.0_dp*(grad_p_im(imo, jmo) - grad_m_im(imo, jmo))/(2.0_dp*fd_step)
               END SELECT
            END DO
            DO ie = 1, nmo
               raw_response = (eps_p(ie) - eps_m(ie))/(2.0_dp*fd_step)
               response(first_energy + ie - 1, s) = raw_response
            END DO
         END DO

         DEALLOCATE (x_re, x_im, u_re, u_im, chc, u, base, chc_p, chc_m, dchc, docc_mat, docc_plateau, &
                     occ_basis, occ_mat, occ_mat_p, occ_mat_m, occ_mat_coupled, projector_evec)
         DEALLOCATE (density_floor_audit_column, density_full_centered_column, density_full_column, &
                     density_mixed_column, density_plateau_centered_column, density_plateau_column, &
                     density_projector_column)
         DEALLOCATE (x_p_re, x_p_im, x_m_re, x_m_im, grad_p_re, grad_p_im, grad_m_re, grad_m_im)
         DEALLOCATE (eps_p, eps_m, projector_evals_p, projector_evals_m)
      END SUBROUTINE build_finite_ref_rotation_model

! **************************************************************************************************
!> \brief ...
!> \param evec ...
!> \param projector_weight ...
!> \param iband ...
!> \param occ_mat ...
! **************************************************************************************************
      SUBROUTINE dense_history_safe_occ_projector_basis(evec, projector_weight, iband, occ_mat)
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: evec
      REAL(KIND=dp), INTENT(IN)                          :: projector_weight
      INTEGER, INTENT(IN)                                :: iband
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(OUT)     :: occ_mat

      INTEGER                                            :: i, j, n

         n = SIZE(evec, 1)
         occ_mat(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)

         IF (projector_weight > 0.0_dp) THEN
            DO j = 1, n
               DO i = 1, n
                  occ_mat(i, j) = projector_weight*evec(i, iband)*CONJG(evec(j, iband))
               END DO
            END DO
         END IF

         occ_mat(iband, iband) = occ_mat(iband, iband) + &
                                 CMPLX(1.0_dp - projector_weight, 0.0_dp, KIND=dp)

      END SUBROUTINE dense_history_safe_occ_projector_basis

! **************************************************************************************************
!> \brief ...
!> \param x_re ...
!> \param x_im ...
!> \param base ...
!> \param chc ...
! **************************************************************************************************
      SUBROUTINE dense_rotated_chc(x_re, x_im, base, chc)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: x_re, x_im
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: base
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(OUT)     :: chc

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: evec, generator, u
      INTEGER                                            :: j, n
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: evals

         n = SIZE(x_re, 1)
         ALLOCATE (generator(n, n), evec(n, n), u(n, n), evals(n))

         generator(:, :) = CMPLX(-x_im(:, :), x_re(:, :), KIND=dp)
         CALL diag_complex(generator, evec, evals)

         u(:, :) = evec(:, :)
         DO j = 1, n
            u(:, j) = EXP(CMPLX(0.0_dp, -evals(j), KIND=dp))*u(:, j)
         END DO
         u(:, :) = MATMUL(u, CONJG(TRANSPOSE(evec)))

         chc(:, :) = MATMUL(CONJG(TRANSPOSE(u)), MATMUL(base, u))

         DEALLOCATE (generator, evec, u, evals)
      END SUBROUTINE dense_rotated_chc

! **************************************************************************************************
!> \brief ...
!> \param chc ...
!> \param occupation_numbers ...
!> \param kpoint_weight ...
!> \param delta ...
!> \param occ_mat ...
!> \param occ_curv_channel ...
!> \param gauge_gap ...
!> \param projector_window_gap ...
! **************************************************************************************************
      SUBROUTINE dense_history_safe_occ_projector(chc, occupation_numbers, kpoint_weight, delta, occ_mat, &
                                                  occ_curv_channel, gauge_gap, projector_window_gap)
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: chc
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_numbers
      REAL(KIND=dp), INTENT(IN)                          :: kpoint_weight, delta
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(OUT)     :: occ_mat
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: occ_curv_channel
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: gauge_gap
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_window_gap

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: evec, weighted_evec
      INTEGER                                            :: i, n
      REAL(KIND=dp)                                      :: occ_tol, projector_weight
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: evals, occ_scale, occ_work

         n = SIZE(chc, 1)
         ALLOCATE (evec(n, n), weighted_evec(n, n), evals(n), occ_scale(n), occ_work(n))

         occ_scale(:) = 2.0_dp*kpoint_weight*occupation_numbers(1:n)
         CALL diag_complex(chc, evec, evals)
         occ_work(:) = occ_scale(:)
         IF (PRESENT(occ_curv_channel) .AND. PRESENT(gauge_gap)) THEN
            occ_tol = SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, MAXVAL(ABS(occ_work(:))))
            CALL monotone_occupation_slopes(occ_scale, occ_tol, occ_work)
            CALL near_degenerate_occupation_plateau(evals, occ_curv_channel, gauge_gap, occ_tol, occ_work, &
                                                    projector_window_gap)
         END IF
         weighted_evec(:, :) = evec(:, :)
         DO i = 1, n
            weighted_evec(:, i) = occ_work(i)*weighted_evec(:, i)
         END DO
         occ_mat(:, :) = MATMUL(weighted_evec, CONJG(TRANSPOSE(evec)))

         projector_weight = kpoint_ot_canonical_projector_weight(delta, ot_kp_canonical_projector_max_weight)
         occ_mat(:, :) = projector_weight*occ_mat(:, :)
         DO i = 1, n
            occ_mat(i, i) = CMPLX(REAL(occ_mat(i, i), KIND=dp) + &
                                  (1.0_dp - projector_weight)*occ_scale(i), 0.0_dp, KIND=dp)
         END DO

         DEALLOCATE (evec, weighted_evec, evals, occ_scale, occ_work)
      END SUBROUTINE dense_history_safe_occ_projector

! **************************************************************************************************
!> \brief ...
!> \param chc ...
!> \param dchc ...
!> \param occupation_numbers ...
!> \param kpoint_weight ...
!> \param delta ...
!> \param docc_mat ...
!> \param occ_curv_channel ...
!> \param gauge_gap ...
!> \param fd_cluster_used ...
!> \param projector_window_gap ...
! **************************************************************************************************
      SUBROUTINE dense_history_safe_occ_projector_derivative(chc, dchc, occupation_numbers, kpoint_weight, &
                                                             delta, docc_mat, occ_curv_channel, gauge_gap, &
                                                             fd_cluster_used, projector_window_gap)
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: chc, dchc
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_numbers
      REAL(KIND=dp), INTENT(IN)                          :: kpoint_weight, delta
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(OUT)     :: docc_mat
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: occ_curv_channel
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: gauge_gap
      LOGICAL, INTENT(OUT), OPTIONAL                     :: fd_cluster_used
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_window_gap

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: evec, kernel, occ_mat_m, occ_mat_p, work
      INTEGER                                            :: i, idx, j, n
      LOGICAL                                            :: same_gauge_cluster, use_projector_fd
      REAL(KIND=dp) :: allowed_jump, coeff, denom, diag_response_shift, gap_tol, local_gap, &
         occ_curv_max, occ_curv_sum, occ_jump, occ_tol, physical_slope, projector_fd_step, &
         projector_weight, scale, slope_cap, work_norm, work_tol
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: evals, occ_scale, occ_slope

         n = SIZE(chc, 1)
         docc_mat(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         IF (PRESENT(fd_cluster_used)) fd_cluster_used = .FALSE.

         projector_weight = kpoint_ot_canonical_projector_weight(delta, ot_kp_canonical_projector_max_weight)
         IF (projector_weight <= 0.0_dp) RETURN

         ALLOCATE (evec(n, n), kernel(n, n), work(n, n), evals(n), occ_scale(n), occ_slope(n))

         occ_scale(:) = 2.0_dp*kpoint_weight*occupation_numbers(1:n)
         CALL diag_complex(chc, evec, evals)
         work(:, :) = MATMUL(CONJG(TRANSPOSE(evec)), MATMUL(dchc, evec))

         scale = MAX(1.0_dp, MAXVAL(ABS(evals(:))))
         gap_tol = SQRT(EPSILON(1.0_dp))*scale
         occ_tol = SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, MAXVAL(ABS(occ_scale(:))))
         occ_curv_max = 0.0_dp
         IF (PRESENT(occ_curv_channel)) occ_curv_max = MAXVAL(MAX(0.0_dp, occ_curv_channel(:)))
         CALL monotone_occupation_slopes(occ_scale, occ_tol, occ_slope)
         IF (PRESENT(occ_curv_channel) .AND. PRESENT(gauge_gap)) &
            CALL near_degenerate_occupation_plateau(evals, occ_curv_channel, gauge_gap, occ_tol, &
                                                    occ_slope, projector_window_gap)
         use_projector_fd = .FALSE.
         IF (PRESENT(occ_curv_channel) .AND. PRESENT(gauge_gap)) THEN
            work_norm = MAXVAL(ABS(work(:, :)))
            work_tol = SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, work_norm)
            DO j = 1, n
               DO i = 1, n
                  same_gauge_cluster = i /= j
                  IF (same_gauge_cluster) THEN
                     DO idx = MIN(i, j), MAX(i, j) - 1
                        local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, &
                                                                            occ_curv_channel(idx), &
                                                                            occ_curv_channel(idx + 1), &
                                                                            occ_curv_max, &
                                                                            projector_window_gap)
                        IF (ABS(evals(idx + 1) - evals(idx)) > local_gap) &
                           same_gauge_cluster = .FALSE.
                     END DO
                  END IF
                  IF (same_gauge_cluster .AND. &
                      (ABS(work(i, j)) > work_tol .OR. &
                       ABS(REAL(work(i, i), KIND=dp) - REAL(work(j, j), KIND=dp)) > work_tol)) &
                     use_projector_fd = .TRUE.
               END DO
            END DO
            IF (use_projector_fd) THEN
               IF (PRESENT(fd_cluster_used)) fd_cluster_used = .TRUE.
               projector_fd_step = 1.0E-7_dp
               IF (work_norm > EPSILON(work_norm)) THEN
                  projector_fd_step = MIN(projector_fd_step, 1.0E-2_dp*gauge_gap/work_norm)
                  projector_fd_step = MAX(projector_fd_step, &
                                          10.0_dp*EPSILON(1.0_dp)*MAX(1.0_dp, scale)/work_norm)
               END IF
               ALLOCATE (occ_mat_p(n, n), occ_mat_m(n, n))
               CALL dense_history_safe_occ_projector(chc + projector_fd_step*dchc, occupation_numbers, &
                                                     kpoint_weight, delta, occ_mat_p, occ_curv_channel, &
                                                     gauge_gap, projector_window_gap)
               CALL dense_history_safe_occ_projector(chc - projector_fd_step*dchc, occupation_numbers, &
                                                     kpoint_weight, delta, occ_mat_m, occ_curv_channel, &
                                                     gauge_gap, projector_window_gap)
               docc_mat(:, :) = (occ_mat_p(:, :) - occ_mat_m(:, :))/(2.0_dp*projector_fd_step)
               kernel(:, :) = MATMUL(CONJG(TRANSPOSE(evec)), MATMUL(docc_mat, evec))
               ! The finite-difference projector value still contains arbitrary
               ! eigenvector gauge inside a near-degenerate cluster.  Replace
               ! those whole cluster blocks by the fixed-N Mermin response to
               ! the Hermitian perturbation projected into the cluster.  This is
               ! covariant under REF-basis rotations and keeps true level
               ! splitting response without feeding projector-basis noise into
               ! the physical Schur curvature.
               CALL near_degenerate_occupation_plateau(evals, occ_curv_channel, gauge_gap, occ_tol, &
                                                       occ_slope, projector_window_gap)
               CALL dense_fixed_n_projector_cluster_kernel(evals, work, occ_curv_channel, occ_slope, gauge_gap, &
                                                           projector_weight, kernel, projector_window_gap)
               docc_mat(:, :) = MATMUL(evec, MATMUL(kernel, CONJG(TRANSPOSE(evec))))
               docc_mat(:, :) = 0.5_dp*(docc_mat(:, :) + CONJG(TRANSPOSE(docc_mat(:, :))))
               DEALLOCATE (occ_mat_p, occ_mat_m)
               DEALLOCATE (evec, kernel, work, evals, occ_scale, occ_slope)
               RETURN
            END IF
         END IF
         diag_response_shift = 0.0_dp
         IF (PRESENT(occ_curv_channel) .AND. PRESENT(gauge_gap)) &
            CALL near_degenerate_occupation_plateau(evals, occ_curv_channel, gauge_gap, occ_tol, &
                                                    occ_slope, projector_window_gap)
         IF (PRESENT(occ_curv_channel)) THEN
            occ_curv_sum = SUM(MAX(0.0_dp, occ_curv_channel(:)))
            IF (occ_curv_sum > EPSILON(occ_curv_sum)) THEN
               DO i = 1, n
                  diag_response_shift = diag_response_shift + &
                                        MAX(0.0_dp, occ_curv_channel(i))*REAL(work(i, i), KIND=dp)
               END DO
               diag_response_shift = diag_response_shift/occ_curv_sum
            END IF
         END IF
         kernel(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         DO j = 1, n
            DO i = 1, n
               IF (i == j) THEN
                  IF (PRESENT(occ_curv_channel)) THEN
                     coeff = -2.0_dp*MAX(0.0_dp, occ_curv_channel(i))
                     IF (ABS(coeff) > EPSILON(coeff)) &
                        kernel(i, i) = CMPLX(coeff*(REAL(work(i, i), KIND=dp) - diag_response_shift), &
                                             0.0_dp, KIND=dp)
                  END IF
                  CYCLE
               END IF
               denom = evals(i) - evals(j)
               physical_slope = 0.0_dp
               IF (PRESENT(occ_curv_channel) .AND. PRESENT(gauge_gap)) THEN
                  IF (ABS(denom) <= gauge_gap) THEN
                     physical_slope = kpoint_ot_shared_occ_slope(occ_curv_channel(i), occ_curv_channel(j))
                     allowed_jump = 4.0_dp*physical_slope*MAX(ABS(denom), EPSILON(1.0_dp)) + occ_tol
                     occ_jump = ABS(occ_slope(i) - occ_slope(j))
                     IF (occ_jump > allowed_jump) CYCLE
                  END IF
               END IF
               IF (ABS(denom) > gap_tol) THEN
                  coeff = (occ_slope(i) - occ_slope(j))/denom
               ELSE IF (ABS(occ_slope(i) - occ_slope(j)) <= occ_tol) THEN
                  coeff = 0.0_dp
               ELSE
                  coeff = (occ_slope(i) - occ_slope(j))/SIGN(gap_tol, denom)
               END IF
               coeff = MIN(0.0_dp, coeff)
               IF (PRESENT(occ_curv_channel)) THEN
                  IF (PRESENT(gauge_gap)) THEN
                     IF (PRESENT(projector_window_gap)) THEN
                        slope_cap = kpoint_ot_projector_pair_slope_cap(denom, gauge_gap, &
                                                                       occ_curv_channel(i), &
                                                                       occ_curv_channel(j), &
                                                                       occ_curv_max, projector_window_gap)
                     ELSE
                        slope_cap = kpoint_ot_projector_pair_slope_cap(denom, gauge_gap, &
                                                                       occ_curv_channel(i), &
                                                                       occ_curv_channel(j), occ_curv_max)
                     END IF
                  ELSE
                     slope_cap = 2.0_dp*MAX(0.0_dp, MAX(occ_curv_channel(i), occ_curv_channel(j)))
                  END IF
                  IF (slope_cap > EPSILON(slope_cap)) THEN
                     coeff = MAX(coeff, -slope_cap)
                  ELSE
                     coeff = 0.0_dp
                  END IF
               END IF
               kernel(i, j) = coeff*work(i, j)
            END DO
         END DO

         IF (PRESENT(occ_curv_channel) .AND. PRESENT(gauge_gap)) &
            CALL dense_fixed_n_projector_cluster_kernel(evals, work, occ_curv_channel, occ_slope, gauge_gap, &
                                                        1.0_dp, kernel, projector_window_gap)

         docc_mat(:, :) = projector_weight*MATMUL(evec, MATMUL(kernel, CONJG(TRANSPOSE(evec))))
         docc_mat(:, :) = 0.5_dp*(docc_mat(:, :) + CONJG(TRANSPOSE(docc_mat(:, :))))

         DEALLOCATE (evec, kernel, work, evals, occ_scale, occ_slope)

      END SUBROUTINE dense_history_safe_occ_projector_derivative

! **************************************************************************************************
!> \brief fixed-N physical occupations for finite Projector cluster modes
!> \param evals near-degenerate eigenvalue cluster
!> \param occ_curv_channel fixed-N occupation curvatures in the cluster
!> \param occ_slope gauge-filtered occupation values in the cluster
!> \param modal_energy expectation values of the unperturbed energies in split modes
!> \param modal_occ physical modal occupations with preserved cluster charge
!> \param modal_curv optional fixed-N Mermin curvatures of the split modes
! **************************************************************************************************
      SUBROUTINE kpoint_ot_projector_cluster_modal_occupation(evals, occ_curv_channel, occ_slope, &
                                                              modal_energy, modal_occ, modal_curv)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: evals, occ_curv_channel, occ_slope, &
                                                            modal_energy
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: modal_occ
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: modal_curv

      INTEGER                                            :: i, m
      REAL(KIND=dp)                                      :: curv, curv_sum, delta_e, eval_center, fit_den, &
                                                            fit_num, mu_shift, occ_mean, physical_slope, &
                                                            slope_cap

         m = SIZE(evals)
         modal_occ(:) = 0.0_dp
         IF (m <= 0) RETURN

         IF (PRESENT(modal_curv)) THEN
            curv_sum = 0.0_dp
            mu_shift = 0.0_dp
            DO i = 1, m
               curv = MAX(0.0_dp, modal_curv(i))
               curv_sum = curv_sum + curv
               mu_shift = mu_shift + curv*modal_energy(i)
            END DO
            IF (curv_sum > EPSILON(curv_sum)) THEN
               mu_shift = mu_shift/curv_sum
               occ_mean = SUM(occ_slope(1:m))/REAL(m, KIND=dp)
               DO i = 1, m
                  modal_occ(i) = occ_mean - 2.0_dp*MAX(0.0_dp, modal_curv(i))* &
                                 (modal_energy(i) - mu_shift)
               END DO
               RETURN
            END IF
         END IF

         occ_mean = SUM(occ_slope(1:m))/REAL(m, KIND=dp)
         eval_center = SUM(evals(1:m))/REAL(m, KIND=dp)
         fit_den = 0.0_dp
         fit_num = 0.0_dp
         DO i = 1, m
            delta_e = evals(i) - eval_center
            fit_den = fit_den + delta_e*delta_e
            fit_num = fit_num + delta_e*(occ_slope(i) - occ_mean)
         END DO
         physical_slope = 0.0_dp
         IF (fit_den > EPSILON(fit_den)) physical_slope = fit_num/fit_den
         physical_slope = MIN(0.0_dp, physical_slope)

         slope_cap = HUGE(1.0_dp)
         DO i = 1, m - 1
            slope_cap = MIN(slope_cap, kpoint_ot_shared_occ_slope(occ_curv_channel(i), occ_curv_channel(i + 1)))
         END DO
         IF (slope_cap < HUGE(1.0_dp)/2.0_dp) THEN
            physical_slope = MAX(physical_slope, -MAX(0.0_dp, slope_cap))
         ELSE
            physical_slope = 0.0_dp
         END IF

         DO i = 1, SIZE(modal_occ)
            modal_occ(i) = occ_mean + physical_slope*(modal_energy(i) - eval_center)
         END DO

      END SUBROUTINE kpoint_ot_projector_cluster_modal_occupation

! **************************************************************************************************
!> \brief Replace near-degenerate projector-gauge blocks by a fixed-N physical response.
!> \param evals ...
!> \param work ...
!> \param occ_curv_channel ...
!> \param occ_slope ...
!> \param gauge_gap ...
!> \param projector_weight ...
!> \param kernel ...
!> \param projector_window_gap ...
! **************************************************************************************************
      SUBROUTINE dense_fixed_n_projector_cluster_kernel(evals, work, occ_curv_channel, occ_slope, gauge_gap, &
                                                        projector_weight, kernel, projector_window_gap)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: evals
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: work
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv_channel, occ_slope
      REAL(KIND=dp), INTENT(IN)                          :: gauge_gap, projector_weight
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(INOUT)   :: kernel
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_window_gap

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:)        :: cluster_col, modal_col, response_col
      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: cluster_evec, cluster_evec_b, &
                                                            cluster_kernel, cluster_work, &
                                                            cluster_work_b, modal_block, &
                                                            response_block
      INTEGER                                            :: a, b, first, first_b, j, last, last_b, &
                                                            m, m_b, n
      LOGICAL                                            :: outside_gauge_cluster
      REAL(KIND=dp)                                      :: component_weight, curv, denom, gap_tol, &
                                                            local_gap, mu_den, mu_num, mu_shift, &
                                                            occ_curv_max, offdiag_coeff, slope_cap
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: cluster_eval, cluster_eval_b, &
                                                            modal_curv, modal_curv_b, &
                                                            modal_energy, modal_energy_b, &
                                                            modal_occ, modal_occ_b

         n = SIZE(evals)
         IF (n <= 0) RETURN
         IF (projector_weight <= 0.0_dp) RETURN
         gap_tol = SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, MAXVAL(ABS(evals(:))))
         occ_curv_max = MAXVAL(MAX(0.0_dp, occ_curv_channel(:)))

         mu_num = 0.0_dp
         mu_den = 0.0_dp
         first = 1
         DO WHILE (first <= n)
            last = first
            DO WHILE (last < n)
               local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_channel(last), &
                                                                   occ_curv_channel(last + 1), occ_curv_max, &
                                                                   projector_window_gap)
               IF (ABS(evals(last + 1) - evals(last)) > local_gap) EXIT
               last = last + 1
            END DO
            m = last - first + 1
            IF (m > 1) THEN
               ALLOCATE (cluster_work(m, m), cluster_evec(m, m), cluster_eval(m), modal_curv(m))
               cluster_work(:, :) = 0.5_dp*(work(first:last, first:last) + &
                                            CONJG(TRANSPOSE(work(first:last, first:last))))
               CALL diag_complex(cluster_work, cluster_evec, cluster_eval)
               CALL dense_fixed_n_projector_modal_curvature(cluster_evec, occ_curv_channel(first:last), &
                                                            modal_curv, split_response=.TRUE.)
               DO a = 1, m
                  mu_num = mu_num + modal_curv(a)*cluster_eval(a)
                  mu_den = mu_den + modal_curv(a)
               END DO
               DEALLOCATE (cluster_work, cluster_evec, cluster_eval, modal_curv)
            ELSE
               curv = MAX(0.0_dp, occ_curv_channel(first))
               IF (curv > EPSILON(curv)) THEN
                  mu_num = mu_num + curv*REAL(work(first, first), KIND=dp)
                  mu_den = mu_den + curv
               END IF
            END IF
            first = last + 1
         END DO
         mu_shift = 0.0_dp
         IF (mu_den > EPSILON(mu_den)) mu_shift = mu_num/mu_den

         first = 1
         DO WHILE (first <= n)
            last = first
            DO WHILE (last < n)
               local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_channel(last), &
                                                                   occ_curv_channel(last + 1), occ_curv_max, &
                                                                   projector_window_gap)
               IF (ABS(evals(last + 1) - evals(last)) > local_gap) EXIT
               last = last + 1
            END DO
            m = last - first + 1
            IF (m > 1) THEN
               kernel(first:last, first:last) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
               ALLOCATE (cluster_col(m), cluster_work(m, m), cluster_evec(m, m), cluster_kernel(m, m), &
                         modal_col(m), modal_energy(m), modal_occ(m), response_block(m, m), &
                         response_col(m), cluster_eval(m), modal_curv(m))
               cluster_work(:, :) = 0.5_dp*(work(first:last, first:last) + &
                                            CONJG(TRANSPOSE(work(first:last, first:last))))
               CALL diag_complex(cluster_work, cluster_evec, cluster_eval)
               CALL dense_fixed_n_projector_modal_curvature(cluster_evec, occ_curv_channel(first:last), &
                                                            modal_curv, split_response=.TRUE.)
               modal_energy(:) = 0.0_dp
               DO a = 1, m
                  DO b = 1, m
                     component_weight = ABS(cluster_evec(b, a))**2
                     modal_energy(a) = modal_energy(a) + component_weight*evals(first + b - 1)
                  END DO
               END DO
               CALL kpoint_ot_projector_cluster_modal_occupation(evals(first:last), occ_curv_channel(first:last), &
                                                                 occ_slope(first:last), modal_energy, modal_occ, &
                                                                 modal_curv)
               cluster_kernel(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
               DO a = 1, m
                  cluster_kernel(a, a) = CMPLX(-2.0_dp*projector_weight*modal_curv(a)* &
                                               (cluster_eval(a) - mu_shift), 0.0_dp, KIND=dp)
               END DO
               response_block(:, :) = MATMUL(cluster_evec, &
                                             MATMUL(cluster_kernel, CONJG(TRANSPOSE(cluster_evec))))
               DO b = 1, m
                  DO a = 1, m
                     kernel(first + a - 1, first + b - 1) = response_block(a, b)
                  END DO
               END DO
               DO j = 1, n
                  IF (j >= first .AND. j <= last) CYCLE
                  outside_gauge_cluster = .FALSE.
                  IF (j > 1) outside_gauge_cluster = &
                     outside_gauge_cluster .OR. &
                     ABS(evals(j) - evals(j - 1)) <= &
                     kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_channel(j - 1), &
                                                             occ_curv_channel(j), occ_curv_max, &
                                                             projector_window_gap)
                  IF (j < n) outside_gauge_cluster = &
                     outside_gauge_cluster .OR. &
                     ABS(evals(j + 1) - evals(j)) <= &
                     kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_channel(j), &
                                                             occ_curv_channel(j + 1), occ_curv_max, &
                                                             projector_window_gap)
                  IF (outside_gauge_cluster) CYCLE
                  cluster_col(:) = work(first:last, j)
                  modal_col(:) = MATMUL(CONJG(TRANSPOSE(cluster_evec)), cluster_col)
                  DO a = 1, m
                     denom = modal_energy(a) - evals(j)
                     IF (ABS(denom) > gap_tol) THEN
                        offdiag_coeff = (modal_occ(a) - occ_slope(j))/denom
                     ELSE
                        offdiag_coeff = 0.0_dp
                     END IF
                     offdiag_coeff = MIN(0.0_dp, offdiag_coeff)
                     IF (PRESENT(projector_window_gap)) THEN
                        slope_cap = kpoint_ot_projector_pair_slope_cap(denom, gauge_gap, modal_curv(a), &
                                                                       occ_curv_channel(j), occ_curv_max, &
                                                                       projector_window_gap)
                     ELSE
                        slope_cap = kpoint_ot_projector_pair_slope_cap(denom, gauge_gap, modal_curv(a), &
                                                                       occ_curv_channel(j), occ_curv_max)
                     END IF
                     IF (slope_cap > EPSILON(slope_cap)) THEN
                        offdiag_coeff = MAX(offdiag_coeff, -slope_cap)
                     ELSE
                        offdiag_coeff = 0.0_dp
                     END IF
                     modal_col(a) = offdiag_coeff*modal_col(a)
                  END DO
                  response_col(:) = projector_weight*MATMUL(cluster_evec, modal_col)
                  DO a = 1, m
                     kernel(first + a - 1, j) = response_col(a)
                     kernel(j, first + a - 1) = CONJG(kernel(first + a - 1, j))
                  END DO
               END DO
               DEALLOCATE (cluster_col, cluster_work, cluster_evec, cluster_kernel, modal_col, modal_energy, &
                           modal_occ, response_block, response_col, cluster_eval, modal_curv)
            ELSE
               curv = MAX(0.0_dp, occ_curv_channel(first))
               kernel(first, first) = CMPLX(-2.0_dp*projector_weight*curv* &
                                            (REAL(work(first, first), KIND=dp) - mu_shift), &
                                            0.0_dp, KIND=dp)
            END IF
            first = last + 1
         END DO

         first = 1
         DO WHILE (first <= n)
            last = first
            DO WHILE (last < n)
               local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_channel(last), &
                                                                   occ_curv_channel(last + 1), occ_curv_max, &
                                                                   projector_window_gap)
               IF (ABS(evals(last + 1) - evals(last)) > local_gap) EXIT
               last = last + 1
            END DO
            m = last - first + 1
            IF (m > 1) THEN
               ALLOCATE (cluster_work(m, m), cluster_evec(m, m), cluster_eval(m), modal_curv(m), &
                         modal_energy(m), modal_occ(m))
               cluster_work(:, :) = 0.5_dp*(work(first:last, first:last) + &
                                            CONJG(TRANSPOSE(work(first:last, first:last))))
               CALL diag_complex(cluster_work, cluster_evec, cluster_eval)
               CALL dense_fixed_n_projector_modal_curvature(cluster_evec, occ_curv_channel(first:last), &
                                                            modal_curv, split_response=.TRUE.)
               modal_energy(:) = 0.0_dp
               DO a = 1, m
                  DO b = 1, m
                     component_weight = ABS(cluster_evec(b, a))**2
                     modal_energy(a) = modal_energy(a) + component_weight*evals(first + b - 1)
                  END DO
               END DO
               CALL kpoint_ot_projector_cluster_modal_occupation(evals(first:last), occ_curv_channel(first:last), &
                                                                 occ_slope(first:last), modal_energy, modal_occ, &
                                                                 modal_curv)
               first_b = last + 1
               DO WHILE (first_b <= n)
                  last_b = first_b
                  DO WHILE (last_b < n)
                     local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, &
                                                                         occ_curv_channel(last_b), &
                                                                         occ_curv_channel(last_b + 1), &
                                                                         occ_curv_max, projector_window_gap)
                     IF (ABS(evals(last_b + 1) - evals(last_b)) > local_gap) EXIT
                     last_b = last_b + 1
                  END DO
                  m_b = last_b - first_b + 1
                  IF (m_b > 1) THEN
                     ALLOCATE (cluster_work_b(m_b, m_b), cluster_evec_b(m_b, m_b), &
                               cluster_eval_b(m_b), modal_curv_b(m_b), modal_energy_b(m_b), &
                               modal_occ_b(m_b), modal_block(m, m_b), response_block(m, m_b))
                     cluster_work_b(:, :) = 0.5_dp*(work(first_b:last_b, first_b:last_b) + &
                                                    CONJG(TRANSPOSE(work(first_b:last_b, first_b:last_b))))
                     CALL diag_complex(cluster_work_b, cluster_evec_b, cluster_eval_b)
                     CALL dense_fixed_n_projector_modal_curvature(cluster_evec_b, &
                                                                  occ_curv_channel(first_b:last_b), &
                                                                  modal_curv_b, split_response=.TRUE.)
                     modal_energy_b(:) = 0.0_dp
                     DO a = 1, m_b
                        DO b = 1, m_b
                           component_weight = ABS(cluster_evec_b(b, a))**2
                           modal_energy_b(a) = modal_energy_b(a) + &
                                               component_weight*evals(first_b + b - 1)
                        END DO
                     END DO
                     CALL kpoint_ot_projector_cluster_modal_occupation(evals(first_b:last_b), &
                                                                       occ_curv_channel(first_b:last_b), &
                                                                       occ_slope(first_b:last_b), &
                                                                       modal_energy_b, modal_occ_b, modal_curv_b)
                     modal_block(:, :) = MATMUL(CONJG(TRANSPOSE(cluster_evec)), &
                                                MATMUL(work(first:last, first_b:last_b), cluster_evec_b))
                     DO b = 1, m_b
                        DO a = 1, m
                           denom = modal_energy(a) - modal_energy_b(b)
                           IF (ABS(denom) > gap_tol) THEN
                              offdiag_coeff = (modal_occ(a) - modal_occ_b(b))/denom
                           ELSE
                              offdiag_coeff = 0.0_dp
                           END IF
                           offdiag_coeff = MIN(0.0_dp, offdiag_coeff)
                           IF (PRESENT(projector_window_gap)) THEN
                              slope_cap = kpoint_ot_projector_pair_slope_cap(denom, gauge_gap, modal_curv(a), &
                                                                             modal_curv_b(b), occ_curv_max, &
                                                                             projector_window_gap)
                           ELSE
                              slope_cap = kpoint_ot_projector_pair_slope_cap(denom, gauge_gap, modal_curv(a), &
                                                                             modal_curv_b(b), occ_curv_max)
                           END IF
                           IF (slope_cap > EPSILON(slope_cap)) THEN
                              offdiag_coeff = MAX(offdiag_coeff, -slope_cap)
                           ELSE
                              offdiag_coeff = 0.0_dp
                           END IF
                           modal_block(a, b) = offdiag_coeff*modal_block(a, b)
                        END DO
                     END DO
                     response_block(:, :) = projector_weight*MATMUL(cluster_evec, &
                                                                    MATMUL(modal_block, CONJG(TRANSPOSE(cluster_evec_b))))
                     DO b = 1, m_b
                        DO a = 1, m
                           kernel(first + a - 1, first_b + b - 1) = response_block(a, b)
                           kernel(first_b + b - 1, first + a - 1) = CONJG(response_block(a, b))
                        END DO
                     END DO
                     DEALLOCATE (cluster_work_b, cluster_evec_b, cluster_eval_b, modal_curv_b, &
                                 modal_energy_b, modal_occ_b, modal_block, response_block)
                  END IF
                  first_b = last_b + 1
               END DO
               DEALLOCATE (cluster_work, cluster_evec, cluster_eval, modal_curv, modal_energy, modal_occ)
            END IF
            first = last + 1
         END DO

      END SUBROUTINE dense_fixed_n_projector_cluster_kernel

! **************************************************************************************************
!> \brief Active-selective modal curvature in one near-degenerate Projector cluster.
!> \param cluster_evec ...
!> \param occ_curv ...
!> \param modal_curv ...
!> \param split_response ...
! **************************************************************************************************
      SUBROUTINE dense_fixed_n_projector_modal_curvature(cluster_evec, occ_curv, modal_curv, &
                                                         split_response)
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: cluster_evec
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: modal_curv
      LOGICAL, INTENT(IN), OPTIONAL                      :: split_response

      REAL(KIND=dp), PARAMETER :: active_component_fraction_min = 0.60_dp, &
         active_component_majority_min = 0.50_dp, active_component_transition_min = 0.50_dp, &
         active_curvature_fraction = 0.25_dp, significant_component_fraction = 0.5_dp

      INTEGER                                            :: a, b, m
      LOGICAL                                            :: use_split_response
      REAL(KIND=dp) :: active_blend, active_component_fraction, component_weight, curv, &
         curv_floor, curv_max, max_component_weight, modal_damped, modal_floor, modal_raw

         m = SIZE(occ_curv)
         modal_curv(:) = 0.0_dp
         IF (m <= 0) RETURN
         use_split_response = .FALSE.
         IF (PRESENT(split_response)) use_split_response = split_response

         curv_floor = HUGE(1.0_dp)
         curv_max = 0.0_dp
         DO b = 1, m
            curv = MAX(0.0_dp, occ_curv(b))
            IF (curv > EPSILON(curv)) curv_floor = MIN(curv_floor, curv)
            curv_max = MAX(curv_max, curv)
         END DO
         IF (curv_floor >= HUGE(1.0_dp)/2.0_dp) RETURN

         DO a = 1, m
            modal_raw = 0.0_dp
            active_component_fraction = 0.0_dp
            max_component_weight = 0.0_dp
            DO b = 1, m
               component_weight = ABS(cluster_evec(b, a))**2
               curv = MAX(0.0_dp, occ_curv(b))
               max_component_weight = MAX(max_component_weight, component_weight)
               modal_raw = modal_raw + component_weight*curv
               IF (curv >= active_curvature_fraction*curv_max) &
                  active_component_fraction = active_component_fraction + component_weight
            END DO
            IF (modal_raw > EPSILON(modal_raw)) THEN
               IF (use_split_response .AND. active_component_fraction >= active_component_transition_min) THEN
                  modal_curv(a) = modal_raw
                  CYCLE
               END IF
               modal_floor = HUGE(1.0_dp)
               DO b = 1, m
                  component_weight = ABS(cluster_evec(b, a))**2
                  curv = MAX(0.0_dp, occ_curv(b))
                  IF (curv > EPSILON(curv) .AND. &
                      component_weight >= significant_component_fraction*max_component_weight) &
                     modal_floor = MIN(modal_floor, curv)
               END DO
               IF (modal_floor >= HUGE(1.0_dp)/2.0_dp) modal_floor = curv_floor
               IF (modal_raw < 0.25_dp*curv_max) modal_floor = MIN(modal_floor, curv_floor)
               modal_damped = MIN(modal_raw, SQRT(modal_floor*modal_raw))
               IF (active_component_fraction > active_component_majority_min) &
                  modal_damped = MAX(modal_damped, active_component_fraction*modal_raw)
               IF (active_component_fraction >= active_component_fraction_min) THEN
                  modal_curv(a) = modal_raw
               ELSE IF (active_component_fraction > active_component_transition_min .AND. &
                        active_component_fraction < active_component_fraction_min) THEN
                  active_blend = (active_component_fraction - active_component_transition_min)/ &
                                 (active_component_fraction_min - active_component_transition_min)
                  active_blend = MIN(1.0_dp, MAX(0.0_dp, active_blend))
                  modal_curv(a) = (1.0_dp - active_blend)*modal_damped + active_blend*modal_raw
               ELSE
                  modal_curv(a) = modal_damped
               END IF
            END IF
         END DO

      END SUBROUTINE dense_fixed_n_projector_modal_curvature

! **************************************************************************************************
!> \brief ...
!> \param evals ...
!> \param occ_curv_channel ...
!> \param gauge_gap ...
!> \param occ_tol ...
!> \param occ_mono ...
!> \param projector_window_gap ...
! **************************************************************************************************
      SUBROUTINE near_degenerate_occupation_plateau(evals, occ_curv_channel, gauge_gap, occ_tol, occ_mono, &
                                                    projector_window_gap)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: evals, occ_curv_channel
      REAL(KIND=dp), INTENT(IN)                          :: gauge_gap, occ_tol
      REAL(KIND=dp), DIMENSION(:), INTENT(INOUT)         :: occ_mono
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_window_gap

      INTEGER                                            :: first, idx, last, n
      LOGICAL                                            :: needs_filter
      REAL(KIND=dp) :: allowed_jump, cluster_sum, eval_center, fit_den, fit_num, gap, local_gap, &
         occ_curv_max, occ_curv_sum, occ_jump, pair_slope, pair_weight, physical_slope, plateau, &
         shape_sum, slope_cap, slope_pair

         n = SIZE(evals)
         IF (n <= 1) RETURN
         IF (gauge_gap <= EPSILON(gauge_gap)) RETURN

         occ_curv_max = MAXVAL(MAX(0.0_dp, occ_curv_channel(:)))
         first = 1
         DO WHILE (first < n)
            last = first
            needs_filter = .FALSE.
            DO WHILE (last < n)
               gap = ABS(evals(last + 1) - evals(last))
               local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, &
                                                                   occ_curv_channel(last), &
                                                                   occ_curv_channel(last + 1), &
                                                                   occ_curv_max, projector_window_gap)
               IF (gap > local_gap) EXIT
               slope_cap = kpoint_ot_shared_occ_slope(occ_curv_channel(last), occ_curv_channel(last + 1))
               allowed_jump = slope_cap*MAX(gap, EPSILON(1.0_dp)) + occ_tol
               occ_jump = ABS(occ_mono(last + 1) - occ_mono(last))
               IF (occ_jump > allowed_jump) needs_filter = .TRUE.
               last = last + 1
            END DO
            IF (last > first .AND. needs_filter) THEN
               cluster_sum = SUM(occ_mono(first:last))
               plateau = cluster_sum/REAL(last - first + 1, KIND=dp)
               eval_center = SUM(evals(first:last))/REAL(last - first + 1, KIND=dp)
               slope_cap = HUGE(1.0_dp)
               fit_num = 0.0_dp
               fit_den = 0.0_dp
               DO idx = first, last - 1
                  gap = ABS(evals(idx + 1) - evals(idx))
                  slope_pair = kpoint_ot_shared_occ_slope(occ_curv_channel(idx), occ_curv_channel(idx + 1))
                  slope_cap = MIN(slope_cap, slope_pair)
                  allowed_jump = slope_pair*MAX(gap, EPSILON(1.0_dp)) + occ_tol
                  occ_jump = ABS(occ_mono(idx + 1) - occ_mono(idx))
                  IF (gap <= EPSILON(gap)) CYCLE
                  IF (occ_jump > allowed_jump) CYCLE
                  pair_slope = (occ_mono(idx + 1) - occ_mono(idx))/(evals(idx + 1) - evals(idx))
                  pair_slope = MIN(0.0_dp, pair_slope)
                  pair_slope = MAX(pair_slope, -MAX(0.0_dp, slope_pair))
                  pair_weight = gap*gap
                  fit_num = fit_num + pair_weight*pair_slope
                  fit_den = fit_den + pair_weight
               END DO
               physical_slope = 0.0_dp
               IF (fit_den > EPSILON(fit_den)) physical_slope = fit_num/fit_den
               physical_slope = MAX(physical_slope, -MAX(0.0_dp, slope_cap))
               IF (fit_den > EPSILON(fit_den) .OR. slope_cap <= EPSILON(slope_cap)) THEN
                  DO idx = first, last
                     occ_mono(idx) = plateau + physical_slope*(evals(idx) - eval_center)
                  END DO
               ELSE
                  ! With no clean pair slope inside a noisy near-degenerate
                  ! component, build the fixed-N Mermin shape from adjacent
                  ! shared Fermi slopes.  This keeps pure gauge jumps out while
                  ! retaining a physical off-diagonal occupation response in the
                  ! whole connected cluster.
                  occ_curv_sum = 0.0_dp
                  DO idx = first, last
                     occ_curv_sum = occ_curv_sum + MAX(0.0_dp, occ_curv_channel(idx))
                  END DO
                  IF (occ_curv_sum > EPSILON(occ_curv_sum)) THEN
                     occ_mono(first) = 0.0_dp
                     DO idx = first + 1, last
                        slope_pair = kpoint_ot_shared_occ_slope(occ_curv_channel(idx - 1), &
                                                                occ_curv_channel(idx))
                        occ_mono(idx) = occ_mono(idx - 1) - &
                                        slope_pair*(evals(idx) - evals(idx - 1))
                     END DO
                     shape_sum = SUM(occ_mono(first:last))
                     occ_mono(first:last) = occ_mono(first:last) + &
                                            (cluster_sum - shape_sum)/REAL(last - first + 1, KIND=dp)
                  ELSE
                     DO idx = first, last
                        occ_mono(idx) = plateau + physical_slope*(evals(idx) - eval_center)
                     END DO
                  END IF
               END IF
            END IF
            first = last + 1
         END DO

      END SUBROUTINE near_degenerate_occupation_plateau

! **************************************************************************************************
!> \brief ...
!> \param occ_scale ...
!> \param occ_tol ...
!> \param occ_mono ...
! **************************************************************************************************
      SUBROUTINE monotone_occupation_slopes(occ_scale, occ_tol, occ_mono)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_scale
      REAL(KIND=dp), INTENT(IN)                          :: occ_tol
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: occ_mono

      INTEGER                                            :: i, iblock, idx, n, nblock
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: block_end, block_start
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: block_level, block_weight

         n = SIZE(occ_scale)
         IF (n <= 0) RETURN

         ALLOCATE (block_end(n), block_level(n), block_start(n), block_weight(n))
         nblock = 0
         DO i = 1, n
            nblock = nblock + 1
            block_start(nblock) = i
            block_end(nblock) = i
            block_level(nblock) = occ_scale(i)
            block_weight(nblock) = 1.0_dp
            DO WHILE (nblock > 1 .AND. &
                      block_level(nblock - 1) + occ_tol < block_level(nblock))
               block_level(nblock - 1) = &
                  (block_weight(nblock - 1)*block_level(nblock - 1) + &
                   block_weight(nblock)*block_level(nblock))/ &
                  (block_weight(nblock - 1) + block_weight(nblock))
               block_weight(nblock - 1) = block_weight(nblock - 1) + block_weight(nblock)
               block_end(nblock - 1) = block_end(nblock)
               nblock = nblock - 1
            END DO
         END DO

         DO iblock = 1, nblock
            DO idx = block_start(iblock), block_end(iblock)
               occ_mono(idx) = block_level(iblock)
            END DO
         END DO
         DEALLOCATE (block_end, block_level, block_start, block_weight)

      END SUBROUTINE monotone_occupation_slopes

! **************************************************************************************************
!> \brief ...
!> \param x_re ...
!> \param x_im ...
!> \param base ...
!> \param occ_mat ...
!> \param grad_re ...
!> \param grad_im ...
!> \param eps_diag ...
! **************************************************************************************************
      SUBROUTINE dense_ref_rotation_gradient(x_re, x_im, base, occ_mat, grad_re, grad_im, eps_diag)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: x_re, x_im
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: base, occ_mat
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: grad_re, grad_im
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: eps_diag

      COMPLEX(KIND=dp)                                   :: kernel
      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: dedu, evec, frechet, generator, inner, &
                                                            outer, u, work
      INTEGER                                            :: i, j, n
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: evals

         n = SIZE(x_re, 1)
         ALLOCATE (generator(n, n), evec(n, n), u(n, n), work(n, n), dedu(n, n))
         ALLOCATE (inner(n, n), outer(n, n), frechet(n, n), evals(n))

         generator(:, :) = CMPLX(-x_im(:, :), x_re(:, :), KIND=dp)
         CALL diag_complex(generator, evec, evals)

         u(:, :) = evec(:, :)
         DO j = 1, n
            u(:, j) = EXP(CMPLX(0.0_dp, -evals(j), KIND=dp))*u(:, j)
         END DO
         u(:, :) = MATMUL(u, CONJG(TRANSPOSE(evec)))

         dedu(:, :) = MATMUL(base, MATMUL(u, occ_mat))

         work(:, :) = MATMUL(CONJG(TRANSPOSE(u)), MATMUL(base, u))
         DO i = 1, n
            eps_diag(i) = REAL(work(i, i), KIND=dp)
         END DO

         inner(:, :) = MATMUL(CONJG(TRANSPOSE(evec)), MATMUL(dedu, evec))
         DO j = 1, n
            DO i = 1, n
               kernel = CONJG(qs_ot_complex_exp_frechet_kernel(evals(i), evals(j)))
               outer(i, j) = inner(i, j)*kernel
            END DO
         END DO
         frechet(:, :) = MATMUL(evec, MATMUL(outer, CONJG(TRANSPOSE(evec))))

         grad_re(:, :) = REAL(frechet, KIND=dp) - TRANSPOSE(REAL(frechet, KIND=dp))
         grad_im(:, :) = AIMAG(frechet) + TRANSPOSE(AIMAG(frechet))

         DEALLOCATE (generator, evec, u, work, dedu, inner, outer, frechet, evals)
      END SUBROUTINE dense_ref_rotation_gradient

! **************************************************************************************************
!> \brief ...
!> \param matrix ...
!> \param dense ...
! **************************************************************************************************
      SUBROUTINE dbcsr_square_to_dense(matrix, dense)
      TYPE(dbcsr_type), POINTER                          :: matrix
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: dense

      INTEGER                                            :: bcol, brow, i, ig, j, jg
      INTEGER, DIMENSION(:), POINTER                     :: col_blk_size, row_blk_size
      REAL(KIND=dp), DIMENSION(:, :), POINTER            :: block
      TYPE(dbcsr_iterator_type)                          :: iter

         dense(:, :) = 0.0_dp
         NULLIFY (row_blk_size, col_blk_size)
         CALL dbcsr_get_info(matrix, row_blk_size=row_blk_size, col_blk_size=col_blk_size)
         CALL dbcsr_iterator_start(iter, matrix)
         DO WHILE (dbcsr_iterator_blocks_left(iter))
            CALL dbcsr_iterator_next_block(iter, brow, bcol, block)
            DO j = 1, SIZE(block, 2)
               jg = dbcsr_block_offset(col_blk_size, bcol) + j - 1
               IF (jg < 1 .OR. jg > SIZE(dense, 2)) CYCLE
               DO i = 1, SIZE(block, 1)
                  ig = dbcsr_block_offset(row_blk_size, brow) + i - 1
                  IF (ig >= 1 .AND. ig <= SIZE(dense, 1)) dense(ig, jg) = block(i, j)
               END DO
            END DO
         END DO
         CALL dbcsr_iterator_stop(iter)
      END SUBROUTINE dbcsr_square_to_dense

! **************************************************************************************************
!> \brief ...
!> \param matrix ...
!> \param dense ...
! **************************************************************************************************
      SUBROUTINE dense_to_dbcsr_square(matrix, dense)
      TYPE(dbcsr_type), POINTER                          :: matrix
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: dense

      INTEGER                                            :: bcol, brow, i, ig, j, jg
      INTEGER, DIMENSION(:), POINTER                     :: col_blk_size, row_blk_size
      REAL(KIND=dp), DIMENSION(:, :), POINTER            :: block
      TYPE(dbcsr_iterator_type)                          :: iter

         NULLIFY (row_blk_size, col_blk_size)
         CALL dbcsr_get_info(matrix, row_blk_size=row_blk_size, col_blk_size=col_blk_size)
         CALL dbcsr_iterator_start(iter, matrix)
         DO WHILE (dbcsr_iterator_blocks_left(iter))
            CALL dbcsr_iterator_next_block(iter, brow, bcol, block)
            DO j = 1, SIZE(block, 2)
               jg = dbcsr_block_offset(col_blk_size, bcol) + j - 1
               DO i = 1, SIZE(block, 1)
                  ig = dbcsr_block_offset(row_blk_size, brow) + i - 1
                  IF (ig >= 1 .AND. ig <= SIZE(dense, 1) .AND. jg >= 1 .AND. jg <= SIZE(dense, 2)) &
                     block(i, j) = dense(ig, jg)
               END DO
            END DO
         END DO
         CALL dbcsr_iterator_stop(iter)
      END SUBROUTINE dense_to_dbcsr_square

! **************************************************************************************************
!> \brief ...
!> \param block_size ...
!> \param block_index ...
!> \return ...
! **************************************************************************************************
      FUNCTION dbcsr_block_offset(block_size, block_index) RESULT(offset)
      INTEGER, DIMENSION(:), POINTER                     :: block_size
      INTEGER, INTENT(IN)                                :: block_index
      INTEGER                                            :: offset

         offset = 1
         IF (block_index > 1) offset = offset + SUM(block_size(1:block_index - 1))
      END FUNCTION dbcsr_block_offset

! **************************************************************************************************
!> \brief ...
!> \param occupation ...
!> \param eigenvalue ...
!> \param mu ...
!> \param sigma ...
!> \param maxocc ...
!> \param method ...
!> \return ...
! **************************************************************************************************
      FUNCTION kpoint_ot_smearing_g(occupation, eigenvalue, mu, sigma, maxocc, method) RESULT(gvalue)
      REAL(KIND=dp), INTENT(IN)                          :: occupation, eigenvalue, mu, sigma, maxocc
      INTEGER, INTENT(IN)                                :: method
      REAL(KIND=dp)                                      :: gvalue

      REAL(KIND=dp)                                      :: expu2, expx2, fi_norm, u, x

         IF (sigma <= 1.0E-14_dp .OR. maxocc <= EPSILON(maxocc)) THEN
            gvalue = 0.0_dp
            RETURN
         END IF

         x = (eigenvalue - mu)/sigma
         SELECT CASE (method)
         CASE (smear_fermi_dirac)
            fi_norm = occupation/maxocc
            gvalue = maxocc*fi_norm*(1.0_dp - fi_norm)/sigma
         CASE (smear_gaussian)
            expx2 = EXP(-x*x)
            gvalue = maxocc/(sigma*rootpi)*expx2
         CASE (smear_mp)
            expx2 = EXP(-x*x)
            gvalue = maxocc*(3.0_dp - 2.0_dp*x*x)/(2.0_dp*sigma*rootpi)*expx2
         CASE (smear_mv)
            u = x + sqrthalf
            expu2 = EXP(-u*u)
            gvalue = maxocc*(2.0_dp + sqrt2*x)/(sigma*rootpi)*expu2
         CASE DEFAULT
            gvalue = 0.0_dp
         END SELECT
      END FUNCTION kpoint_ot_smearing_g

   END SUBROUTINE qs_scf_loop_prepare_ot_kp_energy_gradient

! **************************************************************************************************
!> \brief the inner loop of scf, specific to using to the orbital transformation method
!>       basically, in goes the ks matrix out goes a new p matrix
!> \param qs_env ...
!> \param scf_env ...
!> \param smear ...
!> \param mos ...
!> \param rho ...
!> \param mo_derivs ...
!> \param total_energy ...
!> \param matrix_s ...
!> \param energy_only ...
!> \param has_unit_metric ...
!> \param added_mos_auto_grow ...
!> \par History
!>      03.2006 created [Joost VandeVondele]
!>      2013    moved from qs_scf [Florian Schiffmann]
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_do_ot(qs_env, scf_env, smear, mos, rho, mo_derivs, total_energy, &
                                matrix_s, energy_only, has_unit_metric, added_mos_auto_grow)

      TYPE(qs_environment_type), POINTER                 :: qs_env
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(smear_type), POINTER                          :: smear
      TYPE(mo_set_type), DIMENSION(:), INTENT(INOUT)     :: mos
      TYPE(qs_rho_type), POINTER                         :: rho
      TYPE(dbcsr_p_type), DIMENSION(:), POINTER          :: mo_derivs
      REAL(KIND=dp), INTENT(IN)                          :: total_energy
      TYPE(dbcsr_p_type), DIMENSION(:), POINTER          :: matrix_s
      LOGICAL, INTENT(INOUT)                             :: energy_only
      LOGICAL, INTENT(IN)                                :: has_unit_metric
      LOGICAL, INTENT(OUT), OPTIONAL                     :: added_mos_auto_grow

      CHARACTER(LEN=*), PARAMETER                        :: routineN = 'qs_scf_loop_do_ot'

      INTEGER                                            :: handle, ispin
      LOGICAL                                            :: my_added_mos_auto_grow
      TYPE(dbcsr_p_type), DIMENSION(:), POINTER          :: rho_ao
      TYPE(dbcsr_type), POINTER                          :: orthogonality_metric
      TYPE(scf_control_type), POINTER                    :: scf_control

      CALL timeset(routineN, handle)
      NULLIFY (rho_ao)
      NULLIFY (scf_control)
      my_added_mos_auto_grow = .FALSE.
      IF (PRESENT(added_mos_auto_grow)) added_mos_auto_grow = .FALSE.

      CALL qs_rho_get(rho, rho_ao=rho_ao)
      CALL get_qs_env(qs_env=qs_env, scf_control=scf_control)

      IF (has_unit_metric) THEN
         NULLIFY (orthogonality_metric)
      ELSE
         orthogonality_metric => matrix_s(1)%matrix
      END IF

      ! in case of LSD the first spin qs_ot_env will drive the minimization
      ! in the case of a restricted calculation, it will make sure the spin orbitals are equal

      CALL ot_scf_mini(mos, mo_derivs, smear, orthogonality_metric, &
                       total_energy, energy_only, scf_env%iter_delta, &
                       scf_env%qs_ot_env)

      DO ispin = 1, SIZE(mos)
         CALL set_mo_occupation(mo_set=mos(ispin), smear=smear, &
                                emit_warnings=(.NOT. energy_only .AND. &
                                               .NOT. scf_env%qs_ot_env(1)%settings%do_ener))
      END DO
      IF (.NOT. energy_only) &
         CALL check_added_mos_auto_occupation(mos, scf_control, smear, my_added_mos_auto_grow)
      IF (my_added_mos_auto_grow) THEN
         IF (PRESENT(added_mos_auto_grow)) added_mos_auto_grow = .TRUE.
         CALL timestop(handle)
         RETURN
      END IF

      DO ispin = 1, SIZE(mos)
         CALL calculate_density_matrix(mos(ispin), &
                                       rho_ao(ispin)%matrix, &
                                       use_dbcsr=.TRUE.)
      END DO

      scf_env%iter_method = scf_env%qs_ot_env(1)%OT_METHOD_FULL
      scf_env%iter_param = scf_env%qs_ot_env(1)%ds_min
      qs_env%broyden_adaptive_sigma = scf_env%qs_ot_env(1)%broyden_adaptive_sigma

      CALL timestop(handle)

   END SUBROUTINE qs_scf_loop_do_ot

! **************************************************************************************************
!> \brief checks whether an automatic smearing virtual-space buffer is still sufficient
!> \param mos ...
!> \param scf_control ...
!> \param smear ...
!> \param added_mos_auto_grow ...
! **************************************************************************************************
   SUBROUTINE check_added_mos_auto_occupation(mos, scf_control, smear, added_mos_auto_grow)

      TYPE(mo_set_type), DIMENSION(:), INTENT(IN)        :: mos
      TYPE(scf_control_type), POINTER                    :: scf_control
      TYPE(smear_type), POINTER                          :: smear
      LOGICAL, INTENT(OUT)                               :: added_mos_auto_grow

      INTEGER                                            :: ispin, nmo
      REAL(KIND=dp)                                      :: last_occ, threshold

      added_mos_auto_grow = .FALSE.
      IF (.NOT. ASSOCIATED(scf_control)) RETURN
      IF (.NOT. ANY(scf_control%added_mos_auto)) RETURN
      IF (.NOT. ASSOCIATED(smear)) RETURN
      IF (.NOT. smear%do_smear) RETURN

      threshold = MAX(smear%eps_fermi_dirac, 10.0_dp*EPSILON(1.0_dp))
      DO ispin = 1, MIN(SIZE(mos), SIZE(scf_control%added_mos_auto))
         IF (.NOT. scf_control%added_mos_auto(ispin)) CYCLE
         IF (.NOT. ASSOCIATED(mos(ispin)%occupation_numbers)) CYCLE

         nmo = mos(ispin)%nmo
         IF (nmo < 1) CYCLE
         last_occ = ABS(mos(ispin)%occupation_numbers(nmo))
         IF (last_occ > threshold) THEN
            IF (nmo >= mos(ispin)%nao) THEN
               CALL cp_abort(__LOCATION__, &
                             "ADDED_MOS AUTO exhausted the AO basis but the highest MO is still occupied. "// &
                             "Use a larger basis or a lower electronic temperature.")
            ELSE
               added_mos_auto_grow = .TRUE.
               RETURN
            END IF
         END IF
      END DO

   END SUBROUTINE check_added_mos_auto_occupation

! **************************************************************************************************
!> \brief Performs the requested density mixing if any needed
!> \param scf_env   Holds SCF environment information
!> \param rho       All data for the electron density
!> \param para_env  Parallel environment
!> \param diis_step Did we do a DIIS step?
! **************************************************************************************************
   SUBROUTINE qs_scf_density_mixing(scf_env, rho, para_env, diis_step)
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(qs_rho_type), POINTER                         :: rho
      TYPE(mp_para_env_type), POINTER                    :: para_env
      LOGICAL                                            :: diis_step

      TYPE(dbcsr_p_type), DIMENSION(:, :), POINTER       :: rho_ao_kp

      NULLIFY (rho_ao_kp)

      CALL qs_rho_get(rho, rho_ao_kp=rho_ao_kp)

      SELECT CASE (scf_env%mixing_method)
      CASE (direct_mixing_nr)
         CALL scf_env_density_mixing(scf_env%p_mix_new, &
                                     scf_env%mixing_store, rho_ao_kp, para_env, scf_env%iter_delta, scf_env%iter_count, &
                                     diis=diis_step)
      CASE (gspace_mixing_nr, pulay_mixing_nr, broyden_mixing_nr, modified_broyden_mixing_nr, &
            multisecant_mixing_nr)
         ! Compute the difference p_out-p_in
         CALL self_consistency_check(rho_ao_kp, scf_env%p_delta, para_env, scf_env%p_mix_new, &
                                     delta=scf_env%iter_delta)
      CASE (no_mixing_nr)
      CASE DEFAULT
         CALL cp_abort(__LOCATION__, &
                       "unknown scf mixing method: "// &
                       cp_to_string(scf_env%mixing_method))
      END SELECT

   END SUBROUTINE qs_scf_density_mixing

! **************************************************************************************************
!> \brief checks whether exit conditions for outer loop are satisfied
!> \param qs_env ...
!> \param scf_env ...
!> \param scf_control ...
!> \param should_stop ...
!> \param outer_loop_converged ...
!> \param exit_outer_loop ...
! **************************************************************************************************
   SUBROUTINE qs_scf_check_outer_exit(qs_env, scf_env, scf_control, should_stop, &
                                      outer_loop_converged, exit_outer_loop)
      TYPE(qs_environment_type), POINTER                 :: qs_env
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(scf_control_type), POINTER                    :: scf_control
      LOGICAL                                            :: should_stop, outer_loop_converged, &
                                                            exit_outer_loop

      REAL(KIND=dp)                                      :: outer_loop_eps

      outer_loop_converged = .TRUE.
      IF (scf_control%outer_scf%have_scf) THEN
         ! We have an outer SCF loop...
         scf_env%outer_scf%iter_count = scf_env%outer_scf%iter_count + 1
         outer_loop_converged = .FALSE.

         CALL outer_loop_gradient(qs_env, scf_env)
         ! Multiple constraints: get largest deviation
         outer_loop_eps = SQRT(MAXVAL(scf_env%outer_scf%gradient(:, scf_env%outer_scf%iter_count)**2))

         IF (outer_loop_eps < scf_control%outer_scf%eps_scf) outer_loop_converged = .TRUE.
      END IF

      exit_outer_loop = should_stop .OR. outer_loop_converged .OR. &
                        scf_env%outer_scf%iter_count > scf_control%outer_scf%max_scf

   END SUBROUTINE qs_scf_check_outer_exit

! **************************************************************************************************
!> \brief checks whether exit conditions for inner loop are satisfied
!> \param qs_env ...
!> \param scf_env ...
!> \param scf_control ...
!> \param should_stop ...
!> \param just_energy ...
!> \param exit_inner_loop ...
!> \param inner_loop_converged ...
!> \param output_unit ...
! **************************************************************************************************
   SUBROUTINE qs_scf_check_inner_exit(qs_env, scf_env, scf_control, should_stop, just_energy, &
                                      exit_inner_loop, inner_loop_converged, output_unit)
      TYPE(qs_environment_type), POINTER                 :: qs_env
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(scf_control_type), POINTER                    :: scf_control
      LOGICAL                                            :: should_stop, just_energy, &
                                                            exit_inner_loop, inner_loop_converged
      INTEGER                                            :: output_unit

      inner_loop_converged = .FALSE.
      exit_inner_loop = .FALSE.

      CALL external_control(should_stop, "SCF", target_time=qs_env%target_time, &
                            start_time=qs_env%start_time)
      IF (scf_env%iter_delta < scf_control%eps_scf) THEN
         IF (output_unit > 0) THEN
            WRITE (UNIT=output_unit, FMT="(/,T3,A,I5,A/)") &
               "*** SCF run converged in ", scf_env%iter_count, " steps ***"
         END IF
         inner_loop_converged = .TRUE.
         exit_inner_loop = .TRUE.
      ELSE IF (should_stop .OR. scf_env%iter_count >= scf_control%max_scf) THEN
         inner_loop_converged = .FALSE.
         IF (just_energy) THEN
            exit_inner_loop = .FALSE.
         ELSE
            exit_inner_loop = .TRUE.
            IF (output_unit > 0) THEN
               WRITE (UNIT=output_unit, FMT="(/,T3,A,I5,A/)") &
                  "Leaving inner SCF loop after reaching ", scf_env%iter_count, " steps."
            END IF
         END IF
      END IF

   END SUBROUTINE qs_scf_check_inner_exit

! **************************************************************************************************
!> \brief undoing density mixing. Important upon convergence
!> \param scf_env ...
!> \param rho ...
!> \param dft_control ...
!> \param para_env ...
!> \param diis_step ...
! **************************************************************************************************
   SUBROUTINE qs_scf_undo_mixing(scf_env, rho, dft_control, para_env, diis_step)
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(qs_rho_type), POINTER                         :: rho
      TYPE(dft_control_type), POINTER                    :: dft_control
      TYPE(mp_para_env_type), POINTER                    :: para_env
      LOGICAL                                            :: diis_step

      CHARACTER(len=default_string_length)               :: name
      INTEGER                                            :: ic, ispin, nc
      TYPE(dbcsr_p_type), DIMENSION(:, :), POINTER       :: rho_ao_kp

      NULLIFY (rho_ao_kp)

      IF (scf_env%mixing_method > 0) THEN
         CALL qs_rho_get(rho, rho_ao_kp=rho_ao_kp)
         nc = SIZE(scf_env%p_mix_new, 2)
         SELECT CASE (scf_env%mixing_method)
         CASE (direct_mixing_nr)
            CALL scf_env_density_mixing(scf_env%p_mix_new, scf_env%mixing_store, &
                                        rho_ao_kp, para_env, scf_env%iter_delta, &
                                        scf_env%iter_count, diis=diis_step, &
                                        invert=.TRUE.)
            DO ic = 1, nc
               DO ispin = 1, dft_control%nspins
                  CALL dbcsr_get_info(rho_ao_kp(ispin, ic)%matrix, name=name) ! keep the name
                  CALL dbcsr_copy(rho_ao_kp(ispin, ic)%matrix, scf_env%p_mix_new(ispin, ic)%matrix, name=name)
               END DO
            END DO
         CASE (gspace_mixing_nr, pulay_mixing_nr, broyden_mixing_nr, modified_broyden_mixing_nr, &
               multisecant_mixing_nr)
            DO ic = 1, nc
               DO ispin = 1, dft_control%nspins
                  CALL dbcsr_get_info(rho_ao_kp(ispin, ic)%matrix, name=name) ! keep the name
                  CALL dbcsr_copy(rho_ao_kp(ispin, ic)%matrix, scf_env%p_mix_new(ispin, ic)%matrix, name=name)
               END DO
            END DO
         END SELECT
      END IF
   END SUBROUTINE qs_scf_undo_mixing

! **************************************************************************************************
!> \brief Performs the updates rho (takes care of mixing as well)
!> \param rho ...
!> \param qs_env ...
!> \param scf_env ...
!> \param ks_env ...
!> \param mix_rho ...
! **************************************************************************************************
   SUBROUTINE qs_scf_rho_update(rho, qs_env, scf_env, ks_env, mix_rho)
      TYPE(qs_rho_type), POINTER                         :: rho
      TYPE(qs_environment_type), POINTER                 :: qs_env
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(qs_ks_env_type), POINTER                      :: ks_env
      LOGICAL, INTENT(IN)                                :: mix_rho

      TYPE(mp_para_env_type), POINTER                    :: para_env

      NULLIFY (para_env)
      CALL get_qs_env(qs_env, para_env=para_env)
      ! ** update qs_env%rho
      CALL qs_rho_update_rho(rho, qs_env=qs_env)
      ! ** Density mixing through density matrix or on the reciprocal space grid (exclusive)
      IF (mix_rho) THEN
         CALL gspace_mixing(qs_env, scf_env%mixing_method, scf_env%mixing_store, rho, &
                            para_env, scf_env%iter_count)

      END IF
      CALL qs_ks_did_change(ks_env, rho_changed=.TRUE.)

   END SUBROUTINE qs_scf_rho_update

! **************************************************************************************************
!> \brief Performs the necessary steps before leaving innner scf loop
!> \param scf_env ...
!> \param qs_env ...
!> \param diis_step ...
!> \param output_unit ...
! **************************************************************************************************
   SUBROUTINE qs_scf_inner_finalize(scf_env, qs_env, diis_step, output_unit)
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(qs_environment_type), POINTER                 :: qs_env
      LOGICAL                                            :: diis_step
      INTEGER, INTENT(IN)                                :: output_unit

      LOGICAL                                            :: do_kpoints
      TYPE(dft_control_type), POINTER                    :: dft_control
      TYPE(mp_para_env_type), POINTER                    :: para_env
      TYPE(qs_energy_type), POINTER                      :: energy
      TYPE(qs_ks_env_type), POINTER                      :: ks_env
      TYPE(qs_rho_type), POINTER                         :: rho

      NULLIFY (energy, rho, dft_control, ks_env)

      CALL get_qs_env(qs_env=qs_env, energy=energy, ks_env=ks_env, &
                      rho=rho, dft_control=dft_control, para_env=para_env, &
                      do_kpoints=do_kpoints)

      CALL cleanup_scf_loop(scf_env)

      ! now, print out energies and charges corresponding to the obtained wfn
      ! (this actually is not 100% consistent at this point)!
      CALL qs_scf_print_summary(output_unit, qs_env)

      CALL qs_scf_undo_mixing(scf_env, rho, dft_control, para_env, diis_step)

      !   *** update rspace rho since the mo changed
      !   *** this might not always be needed (i.e. no post calculation / no forces )
      !   *** but guarantees that rho and wfn are consistent at this point
      CALL qs_scf_rho_update(rho, qs_env, scf_env, ks_env, mix_rho=.FALSE.)

   END SUBROUTINE qs_scf_inner_finalize

! **************************************************************************************************
!> \brief perform cleanup operations at the end of an scf loop
!> \param scf_env ...
!> \par History
!>      03.2006 created [Joost VandeVondele]
! **************************************************************************************************
   SUBROUTINE cleanup_scf_loop(scf_env)
      TYPE(qs_scf_env_type), INTENT(INOUT)               :: scf_env

      CHARACTER(len=*), PARAMETER                        :: routineN = 'cleanup_scf_loop'

      INTEGER                                            :: handle, ispin
      LOGICAL                                            :: keep_kpoint_ot_for_restart

      CALL timeset(routineN, handle)

      SELECT CASE (scf_env%method)
      CASE (ot_method_nr)
         keep_kpoint_ot_for_restart = ANY(scf_env%qs_ot_env(:)%kpoint_index > 0)
         IF (.NOT. keep_kpoint_ot_for_restart) THEN
            DO ispin = 1, SIZE(scf_env%qs_ot_env)
               CALL ot_scf_destroy(scf_env%qs_ot_env(ispin))
            END DO
            DEALLOCATE (scf_env%qs_ot_env)
         END IF
      CASE (ot_diag_method_nr)
         !
      CASE (general_diag_method_nr)
         !
      CASE (special_diag_method_nr)
         !
      CASE (block_krylov_diag_method_nr, block_davidson_diag_method_nr)
         !
      CASE (filter_matrix_diag_method_nr)
         !
      CASE (smeagol_method_nr)
         !
      CASE DEFAULT
         CALL cp_abort(__LOCATION__, &
                       "unknown scf method method:"// &
                       cp_to_string(scf_env%method))
      END SELECT

      CALL timestop(handle)

   END SUBROUTINE cleanup_scf_loop

END MODULE qs_scf_loop_utils
